"use client";

import type { CSSProperties } from "react";
import type { DocumentIdentity, DocumentKind, DocumentNavigatorProps } from "@/lib/workspaceTypes";

export type DocumentGroup = { groupId: string; title: string; documents: DocumentIdentity[] };

const shell: CSSProperties = { border: "1px solid var(--line)", borderRadius: "var(--radius)", background: "var(--raised)", padding: 14, minWidth: 0, maxWidth: "100%", boxSizing: "border-box" };
const list: CSSProperties = { display: "grid", gap: 7, listStyle: "none", margin: "8px 0 0", padding: 0, minWidth: 0 };
const row: CSSProperties = { display: "flex", alignItems: "center", justifyContent: "space-between", gap: 9, flexWrap: "wrap", minWidth: 0 };
const copy: CSSProperties = { color: "var(--ink-3)", font: "400 13px/1.45 var(--sans)", overflowWrap: "anywhere" };
const button: CSSProperties = { minWidth: 0, maxWidth: "100%", whiteSpace: "normal", overflowWrap: "anywhere", textAlign: "left" };

export function groupDocuments(documents: readonly DocumentIdentity[], kind: DocumentKind): DocumentGroup[] {
  const groups = new Map<string, DocumentGroup>();
  for (const document of documents) {
    if (document.kind !== kind) continue;
    const identity = document.work_product_id?.trim() || document.document_id;
    const groupId = `${kind}:${identity}`;
    const group = groups.get(groupId);
    if (group) group.documents.push(document);
    else groups.set(groupId, { groupId, title: document.title, documents: [document] });
  }
  return [...groups.values()];
}

export function documentType(document: DocumentIdentity): string {
  const name = document.path.split("/").at(-1) || document.path;
  const extension = name.includes(".") ? name.split(".").at(-1) : "file";
  return (extension || "file").toUpperCase();
}

export function lifecycleLabel(document: DocumentIdentity): string {
  if (document.lifecycle_state === "editing_draft") return "Editing draft";
  if (document.lifecycle_state === "reading_source") return "Reading source";
  if (document.lifecycle_state === "final") return "Final";
  if (document.lifecycle_state === "approved") return "Approved";
  return "Matter record";
}

export function documentPickerValue(document: DocumentIdentity): string {
  return JSON.stringify([document.document_id, document.path, document.revision]);
}

function DocumentGroupList({ groups, duplicateTitles, activeDocumentId, activePickerValue, onOpen, onCreateWorkingCopy }: { groups: DocumentGroup[]; duplicateTitles: ReadonlySet<string>; activeDocumentId: string | null; activePickerValue?: string; onOpen: DocumentNavigatorProps["onOpen"]; onCreateWorkingCopy: DocumentNavigatorProps["onCreateWorkingCopy"] }) {
  return <ul style={list}>{groups.map((group) => {
    const current = group.documents[0];
    const versions = group.documents.slice(1);
    return <li key={group.groupId} style={{ borderTop: "1px solid var(--line-faint)", paddingTop: 7, minWidth: 0 }}>
      <div style={row}>
        <button aria-current={current.document_id === activeDocumentId && (!activePickerValue || documentPickerValue(current) === activePickerValue) ? "page" : undefined} className="btn quiet tiny" style={button} type="button" onClick={() => onOpen(current)}>{group.title}</button>
        <span style={copy}>{documentType(current)} · {lifecycleLabel(current)} · Saved</span>
      </div>
      {duplicateTitles.has(current.title) ? <div style={copy}>{current.path}</div> : null}
      {current.kind === "source" && !current.editable ? <button className="btn quiet tiny" style={{ ...button, marginTop: 6 }} type="button" onClick={() => onCreateWorkingCopy(current)}>Create working copy</button> : null}
      {versions.length ? <details style={{ marginTop: 6 }}><summary>Earlier versions ({versions.length})</summary><ul style={list}>{versions.map((version) => <li key={`${version.document_id}:${version.revision}`} style={row}><button aria-current={activePickerValue === documentPickerValue(version) ? "page" : undefined} className="btn quiet tiny" style={button} type="button" onClick={() => onOpen(version)}>{version.version_id || version.revision}</button><span style={copy}>{documentType(version)} · {lifecycleLabel(version)} · Saved</span></li>)}</ul></details> : null}
    </li>;
  })}</ul>;
}

export default function DocumentNavigator({ documents, activeDocumentId, activeDocumentPath, activeDocumentRevision, matterRecordsExpanded = false, onOpen, onCreateWorkingCopy }: DocumentNavigatorProps) {
  const workProducts = groupDocuments(documents, "work_product");
  const sources = groupDocuments(documents, "source");
  const matterRecords = groupDocuments(documents, "matter_record");
  const activeDocument = documents.find((document) => document.document_id === activeDocumentId
    && (!activeDocumentPath || document.path === activeDocumentPath)
    && (!activeDocumentRevision || document.revision === activeDocumentRevision));
  const activeValue = activeDocument ? documentPickerValue(activeDocument) : "";
  const titleCounts = new Map<string, number>();
  for (const document of documents) titleCounts.set(document.title, (titleCounts.get(document.title) ?? 0) + 1);
  const duplicateTitles = new Set([...titleCounts].filter(([, count]) => count > 1).map(([title]) => title));

  return <nav aria-label="Documents" style={shell}>
    <h2 className="section-heading" style={{ margin: "0 0 10px" }}>Documents</h2>
    <label className="field-block"><span className="field-label">Document picker · Work products ({workProducts.length}) · Sources ({sources.length})</span><select className="text-input" value={activeValue} onChange={(event) => { const selected = documents.find((document) => documentPickerValue(document) === event.target.value); if (selected) onOpen(selected); }}><option value="">Choose a document</option>{documents.map((document) => <option key={documentPickerValue(document)} value={documentPickerValue(document)}>{document.title} · {lifecycleLabel(document)}{duplicateTitles.has(document.title) ? ` · ${document.path}` : ""}</option>)}</select></label>
    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(min(100%, 320px), 1fr))", gap: 16, minWidth: 0 }}>
    <section aria-labelledby="work-products-heading" style={{ marginTop: 14 }}><h3 className="section-heading" id="work-products-heading" style={{ margin: 0 }}>Work products ({workProducts.length})</h3><DocumentGroupList activeDocumentId={activeDocumentId} activePickerValue={activeValue} duplicateTitles={duplicateTitles} groups={workProducts} onCreateWorkingCopy={onCreateWorkingCopy} onOpen={onOpen} /></section>
    <section aria-labelledby="sources-heading" style={{ marginTop: 14 }}><h3 className="section-heading" id="sources-heading" style={{ margin: 0 }}>Sources ({sources.length})</h3><DocumentGroupList activeDocumentId={activeDocumentId} activePickerValue={activeValue} duplicateTitles={duplicateTitles} groups={sources} onCreateWorkingCopy={onCreateWorkingCopy} onOpen={onOpen} /></section>
    </div>
    <details open={matterRecordsExpanded} style={{ marginTop: 14 }}><summary>Matter records ({matterRecords.length})</summary><DocumentGroupList activeDocumentId={activeDocumentId} activePickerValue={activeValue} duplicateTitles={duplicateTitles} groups={matterRecords} onCreateWorkingCopy={onCreateWorkingCopy} onOpen={onOpen} /></details>
  </nav>;
}

