"use client";

import type { CSSProperties } from "react";
import type { DocumentIdentity, DocumentTabsProps, LocalEditorSnapshot } from "@/lib/workspaceTypes";
import { lifecycleLabel } from "./DocumentNavigator";

const VISIBLE_TAB_LIMIT = 4;
const shell: CSSProperties = { display: "flex", alignItems: "stretch", gap: 6, flexWrap: "wrap", minWidth: 0, maxWidth: "100%" };
const tab: CSSProperties = { display: "grid", gridTemplateColumns: "minmax(0, 1fr) auto", alignItems: "center", gap: 5, border: "1px solid var(--line)", borderRadius: 7, padding: 5, minWidth: 0, maxWidth: "100%", background: "var(--raised)" };
const tabButton: CSSProperties = { minWidth: 0, maxWidth: "100%", whiteSpace: "normal", overflowWrap: "anywhere", textAlign: "left" };
const detail: CSSProperties = { color: "var(--ink-3)", font: "400 12px/1.4 var(--sans)", overflowWrap: "anywhere" };

export function visibleDocumentTabs(documents: readonly DocumentIdentity[], activeDocumentId: string | null, limit = VISIBLE_TAB_LIMIT): { visible: DocumentIdentity[]; overflow: DocumentIdentity[] } {
  if (documents.length <= limit) return { visible: [...documents], overflow: [] };
  const visible = documents.slice(0, limit);
  const active = documents.find((document) => document.document_id === activeDocumentId);
  if (active && !visible.some((document) => document.document_id === active.document_id)) visible[limit - 1] = active;
  const visibleIds = new Set(visible.map((document) => document.document_id));
  return { visible, overflow: documents.filter((document) => !visibleIds.has(document.document_id)) };
}

function hasDirtyEdit(document: DocumentIdentity, localEdits: Record<string, LocalEditorSnapshot>): boolean {
  return Boolean(localEdits[document.document_id]?.dirty);
}

function OpenTab({ document, activeDocumentId, localEdits, onSelect, onClose, onDiscardLocalEdit }: { document: DocumentIdentity; activeDocumentId: string | null; localEdits: Record<string, LocalEditorSnapshot>; onSelect: DocumentTabsProps["onSelect"]; onClose: DocumentTabsProps["onClose"]; onDiscardLocalEdit: DocumentTabsProps["onDiscardLocalEdit"] }) {
  const dirty = hasDirtyEdit(document, localEdits);
  return <div style={tab}>
    <button aria-current={document.document_id === activeDocumentId ? "page" : undefined} className="btn quiet tiny" style={tabButton} type="button" onClick={() => onSelect(document.document_id)}><strong>{document.title}</strong><span style={{ ...detail, display: "block" }}>{lifecycleLabel(document)}{dirty ? " · Local edits retained" : " · Saved"}</span></button>
    <button aria-label={`Close ${document.title}. ${dirty ? "Local edits will be retained." : ""}`} className="btn quiet tiny" type="button" onClick={() => onClose(document.document_id)}>Close</button>
    {dirty ? <button className="btn quiet tiny" style={{ ...tabButton, gridColumn: "1 / -1" }} type="button" onClick={() => onDiscardLocalEdit(document.document_id)}>Discard local edits</button> : null}
  </div>;
}

export default function DocumentTabs({ documents, activeDocumentId, localEdits, onSelect, onClose, onDiscardLocalEdit }: DocumentTabsProps) {
  const { visible, overflow } = visibleDocumentTabs(documents, activeDocumentId);
  if (!documents.length) return <p style={detail}>No documents are open.</p>;
  return <nav aria-label="Open documents" style={shell}>
    {visible.map((document) => <OpenTab activeDocumentId={activeDocumentId} document={document} key={document.document_id} localEdits={localEdits} onClose={onClose} onDiscardLocalEdit={onDiscardLocalEdit} onSelect={onSelect} />)}
    {overflow.length ? <details><summary className="btn quiet tiny">More open documents ({overflow.length})</summary><div style={{ display: "grid", gap: 6, marginTop: 6 }}>{overflow.map((document) => <OpenTab activeDocumentId={activeDocumentId} document={document} key={document.document_id} localEdits={localEdits} onClose={onClose} onDiscardLocalEdit={onDiscardLocalEdit} onSelect={onSelect} />)}</div></details> : null}
  </nav>;
}

frontend/components/workspace/ReferenceP:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties, ReactNode, RefObject } from "react";
import { getFile } from "@/lib/api";
import { exactPassageRange, isSafeDocumentPath, returnReferenceOrigin } from "@/lib/documentNavigation";
import { isSafeVaultPath } from "@/lib/research";
import type { ReferencePreviewProps } from "@/lib/workspaceTypes";
import type { VaultDocument } from "@/lib/types";

const shell: CSSProperties = { minWidth: 0, maxWidth: "100%", border: "1px solid var(--line)", borderRadius: "var(--radius)", background: "var(--raised)", overflow: "hidden" };
const header: CSSProperties = { display: "flex", justifyContent: "space-between", alignItems: "start", gap: 12, padding: 14, borderBottom: "1px solid var(--line-soft)", background: "var(--rail)", flexWrap: "wrap" };
const reading: CSSProperties = { position: "relative", margin: 0, padding: "18px 20px", maxHeight: "min(66vh, 760px)", overflow: "auto", whiteSpace: "pre-wrap", overflowWrap: "anywhere", font: "400 15px/1.65 var(--serif)", color: "var(--ink-2)" };

function passage(content: string, range: { start: number; end: number } | null, passageMark: RefObject<HTMLElement | null>): ReactNode {
  if (!range) return content;
  return <>{content.slice(0, range.start)}<mark ref={passageMark}>{content.slice(range.start, range.end)}</mark>{content.slice(range.end)}</>;
}

export default function ReferencePreview({
  target,
  document,
  loading = false,
  error,
  onBack,
  onOpenOriginal,
  onUseInRequest,
  onCreateWorkingCopy,
}: ReferencePreviewProps) {
  const [loaded, setLoaded] = useState<VaultDocument | null>(null);
  const [loadError, setLoadError] = useState("");
  const backButton = useRef<HTMLButtonElement>(null);
  const readingArea = useRef<HTMLPreElement>(null);
  const passageMark = useRef<HTMLElement>(null);

  useEffect(() => {
    const path = document?.path;
    setLoaded(null);
    setLoadError("");
    if (!target || !document || !path) return;
    if (!isSafeDocumentPath(path)) {
      setLoadError("Unsafe reference path blocked.");
      return;
    }
    let current = true;
    void getFile(path).then((result) => {
      if (current) setLoaded(result);
    }).catch((cause) => {
      if (current) setLoadError(cause instanceof Error ? cause.message : "The referenced document is unavailable.");
    });
    return () => { current = false; };
  }, [document?.document_id, document?.path, document?.revision, target?.document_id, target?.path, target?.revision]);

  useEffect(() => { if (target) backButton.current?.focus(); }, [target]);

  const range = useMemo(() => loaded && target ? exactPassageRange(loaded.content, target) : null, [loaded, target]);
  useEffect(() => {
    const area = readingArea.current;
    if (!area || !loaded) return;
    area.scrollTop = 0;
    const mark = passageMark.current;
    if (!range || !mark) return;
    const centeredTop = mark.offsetTop - Math.max(0, (area.clientHeight - mark.offsetHeight) / 2);
    area.scrollTop = Math.max(0, centeredTop);
  }, [loaded, range]);

  if (!target) return null;
  const passageUnavailable = Boolean(loaded && (!range || !target.exact_passage_available));
  const originalAvailable = Boolean(document && (
    (document.original_path && isSafeVaultPath(document.original_path))
    || (document.kind === "source" && isSafeDocumentPath(document.path))
  ));
  const missing = !document && !loading;
  const actualPath = document?.path ?? target.path;
  const actualRevision = document?.revision || null;
  const requestedRevisionDiffers = Boolean(document && target.revision && target.revision !== actualRevision);
  const unavailableMessage = error || loadError || "Referenced document or version is unavailable.";

  return <aside aria-label="Reference preview" style={shell}>
    <header style={header}>
      <div style={{ minWidth: 0 }}>
        <span className="record-meta">Reading source{actualRevision ? ` · Version ${actualRevision}` : target.revision ? ` · Requested version ${target.revision}` : ""}</span>
        <h2 className="section-heading" style={{ margin: "3px 0 0", overflowWrap: "anywhere" }}>{document?.title || "Reference unavailable"}</h2>
        <p className="muted small" style={{ margin: "5px 0 0", overflowWrap: "anywhere" }}>{actualPath}{actualRevision ? ` · Revision ${actualRevision}` : target.revision ? ` · Requested revision ${target.revision}` : ""}</p>
        {requestedRevisionDiffers ? <p className="muted small" style={{ margin: "3px 0 0" }}>Requested revision: {target.revision}</p> : null}
      </div>
      <button className="btn quiet tiny" ref={backButton} type="button" onClick={() => onBack(returnReferenceOrigin(target.origin))}>Back to {target.origin?.document_id ? "document" : "where you were"}</button>
    </header>
    <div style={{ padding: "10px 14px", borderBottom: "1px solid var(--line-faint)" }}>
      <span className={`state-label ${passageUnavailable || missing || loadError || error ? "state-attention" : "state-healthy"}`}>{passageUnavailable ? "Exact passage unavailable" : missing || loadError || error ? "Source unavailable" : loading || !loaded ? "Loading source" : "Exact passage"}</span>
      {target.locator ? <span className="muted small" style={{ marginLeft: 8 }}>Saved locator: {target.locator}</span> : null}
      <p className="muted small" style={{ margin: "7px 0 0" }}>Reading this source does not add it to the agent request.</p>
    </div>
    {error || loadError || missing ? <div className="warning-callout" role="status" style={{ margin: 14 }}>{unavailableMessage}{!document && target.revision ? ` Requested revision: ${target.revision}.` : ""}</div> : null}
    {loading || (document && !loaded && !loadError && !error) ? <div className="loading">Loading referenced document…</div> : null}
    {loaded ? <>
      {document?.extracted_path === target.path || loaded.path.endsWith(".extracted.md") ? <p className="chat-history-status" style={{ margin: 0 }}>Extracted text · The original document layout is not shown.</p> : null}
      <pre data-passage-state={range ? "exact" : "document_only"} ref={readingArea} style={reading}>{passage(loaded.content, range, passageMark)}</pre>
    </> : null}
    {document ? <footer className="btn-row" style={{ padding: 14, borderTop: "1px solid var(--line-soft)" }}>
      <button className="btn agent compact" type="button" onClick={() => onUseInRequest(document)}>Use in this request</button>
      {originalAvailable ? <button className="btn compact" type="button" onClick={() => onOpenOriginal(document)}>Open original</button> : null}
      {document.immutable || !document.editable ? <button className="btn compact" type="button" onClick={() => onCreateWorkingCopy(document)}>Create working copy</button> : null}
    </footer> : null}
  </aside>;
}

