"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties } from "react";
import type { EvidenceDrawerProps } from "@/lib/workspaceTypes";
import { isSafeSourceUrl, isSafeVaultPath } from "@/lib/research";

const panel: CSSProperties = { position: "fixed", inset: "0 0 0 auto", zIndex: 80, width: "min(390px, 100vw)", overflowY: "auto", background: "var(--raised)", borderLeft: "1px solid var(--line)", boxShadow: "var(--shadow-modal)", padding: 18, font: "400 15px/1.55 var(--sans)" };
const card: CSSProperties = { border: "1px solid var(--line)", borderRadius: "var(--radius)", padding: 13, background: "var(--paper)", minWidth: 0 };
const reading: CSSProperties = { font: "400 15px/1.62 var(--serif)", whiteSpace: "pre-wrap", overflowWrap: "anywhere", margin: "7px 0 0" };

function supportLabel(state: NonNullable<NonNullable<EvidenceDrawerProps["evidence"]>["support_state"]>) {
  return ({ supplied: "Supplied", retrieved: "Retrieved", verified: "Verified support", unverified_lead: "Unverified lead", unknown: "Status unknown" })[state];
}

export default function EvidenceDrawer({ evidence, open, onClose, onOpenArtifact }: EvidenceDrawerProps) {
  const drawer = useRef<HTMLElement>(null);
  const returnFocus = useRef<HTMLElement | null>(null);
  const closeRef = useRef(onClose);
  useEffect(() => { closeRef.current = onClose; }, [onClose]);
  useEffect(() => {
    if (!open) return;
    returnFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const node = drawer.current;
    const focusable = () => Array.from(node?.querySelectorAll<HTMLElement>('button:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])') ?? []);
    focusable()[0]?.focus();
    const keydown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); closeRef.current(); return; }
      if (event.key !== "Tab") return;
      const items = focusable(); if (!items.length) return;
      const first = items[0]; const last = items.at(-1)!;
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("keydown", keydown); returnFocus.current?.focus(); };
  }, [open]);
  if (!open) return null;

  const state = evidence?.support_state ?? "unknown";
  const safeUrl = evidence?.url && isSafeSourceUrl(evidence.url) ? evidence.url : null;
  const safePath = evidence?.path && isSafeVaultPath(evidence.path) ? evidence.path : null;
  return <>
    <button aria-label="Close evidence" onClick={onClose} style={{ position: "fixed", inset: 0, zIndex: 79, border: 0, background: "var(--ink)", opacity: 0.24 }} type="button" />
    <aside aria-label="Claim evidence" aria-modal="true" ref={drawer} role="dialog" style={panel}>
      <header style={{ display: "flex", alignItems: "start", justifyContent: "space-between", gap: 12 }}>
        <div><span className="record-meta">Evidence for claim</span><h2 style={{ font: "600 21px/1.3 var(--serif)", margin: "3px 0 0" }}>{evidence?.source_label || "Source unavailable"}</h2></div>
        <button aria-label="Close evidence drawer" className="btn quiet tiny" onClick={onClose} type="button">Close</button>
      </header>
      {!evidence ? <div className="warning-callout" role="status" style={{ marginTop: 16 }}><strong>Evidence unavailable.</strong> The saved answer remains visible.</div> : <div style={{ display: "grid", gap: 12, marginTop: 16 }}>
        <section style={card}><span className={`state-label ${state === "verified" ? "state-healthy" : state === "unverified_lead" || state === "unknown" ? "state-attention" : "state-agent"}`}>{supportLabel(state)}</span><dl style={{ display: "grid", gridTemplateColumns: "max-content minmax(0, 1fr)", gap: "5px 10px", margin: "10px 0 0", fontSize: 13 }}><dt>Claim ID</dt><dd style={{ margin: 0, overflowWrap: "anywhere" }}>{evidence.claim_id || "Unknown"}</dd><dt>Claim revision</dt><dd style={{ margin: 0, overflowWrap: "anywhere" }}>{evidence.claim_revision || "Legacy or unavailable"}</dd><dt>Output revision</dt><dd style={{ margin: 0, overflowWrap: "anywhere" }}>{evidence.output_revision || "Legacy or unavailable"}</dd><dt>Source ID</dt><dd style={{ margin: 0, overflowWrap: "anywhere" }}>{evidence.source_id || "Unknown"}</dd><dt>Location</dt><dd style={{ margin: 0 }}>{evidence.locator || "Exact location unavailable"}</dd><dt>Retrieved</dt><dd style={{ margin: 0 }}>{evidence.retrieved_at || "Unknown"}</dd><dt>Version</dt><dd style={{ margin: 0, overflowWrap: "anywhere" }}>{evidence.source_version || evidence.source_hash || "Unknown"}</dd></dl><p className="faint" style={{ marginBottom: 0 }}>Source support and legal applicability are separate. Supplied or Retrieved does not mean Verified, and no source status proves that the rule applies to this matter.</p></section>
        <section style={card}><span className="record-meta">Exact available passage</span>{evidence.available_excerpt ? <blockquote style={{ ...reading, borderLeft: "3px solid var(--line)", paddingLeft: 12 }}>{evidence.available_excerpt}</blockquote> : <p style={reading}>No exact passage is available. Retrieval may have failed or the saved source reference may be missing.</p>}</section>
        {evidence.explanation ? <section className="wash-agent" style={card}><span className="record-meta">Generated explanation · How this source supports this claim</span><p style={reading}>{evidence.explanation}</p></section> : <section className="warning-callout" role="status"><strong>Claim explanation unavailable.</strong> The source record remains available, but its support for this claim is not explained.</section>}
        <section style={card}><span className="record-meta">Open source</span><div className="btn-row" style={{ marginTop: 8 }}>{safeUrl ? <a className="btn quiet tiny" href={safeUrl} rel="noopener noreferrer" target="_blank">Open public source</a> : null}{safePath ? <button className="btn quiet tiny" onClick={() => onOpenArtifact(safePath)} type="button">Open saved source</button> : null}{!safeUrl && !safePath ? <span className="faint">No safe source link is available.</span> : null}</div>{(evidence.url && !safeUrl) || (evidence.path && !safePath) ? <p className="warning-callout" role="status" style={{ marginBottom: 0 }}>An unsafe source location was blocked.</p> : null}<p className="faint" style={{ marginBottom: 0 }}>Opening a link does not verify the source.</p></section>
      </div>}
    </aside>
  </>;
}

