"use client";

import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import type { MouseEvent, ReactNode } from "react";
import type { ClaimEvidence, DocumentIdentity, DocumentReferenceTarget, ReferenceOrigin, WorkspaceClaim } from "@/lib/workspaceTypes";
import { isSafeDocumentPath } from "@/lib/documentNavigation";

const SOURCE_MARKER = /\[source:([^\]|;\s]+)(?:\|([^\]]+))?\]/g;
const TRANSPORT = /```claim-support[ \t]*\n([\s\S]*?)\n```[ \t]*(?:\n|$)/g;

export function visibleClaimProse(text: string): string {
  const visible = text.replace(TRANSPORT, (block, payload: string) => {
    try {
      const parsed = JSON.parse(payload);
      return parsed && typeof parsed === "object" && Array.isArray(parsed.claims) ? "" : block;
    } catch { return block; }
  }).trimEnd();
  return visible.trim() ? visible : text.trimEnd();
}

export function evidenceForSourceMarker(claims: WorkspaceClaim[], sourceId: string, locator?: string | null): ClaimEvidence | null {
  const normalizedLocator = locator?.trim() || null;
  const matches = claims.flatMap((claim) => claim.evidence.map((evidence) => ({ claim, evidence }))).filter(({ claim, evidence }) =>
    evidence.source_id === sourceId
    && (!normalizedLocator || evidence.locator?.trim() === normalizedLocator)
    && (!evidence.output_revision || !claim.output_revision || evidence.output_revision === claim.output_revision)
    && (!evidence.claim_revision || !claim.claim_revision || evidence.claim_revision === claim.claim_revision));
  return matches.length === 1 ? matches[0].evidence : null;
}

export function claimsForRenderedText(claims: WorkspaceClaim[], text: string): WorkspaceClaim[] {
  const prose = visibleClaimProse(text);
  return claims.filter((claim) => {
    const statement = claim.text?.trim();
    return Boolean(statement && prose.includes(statement));
  });
}

export function sourceForMarker(claims: WorkspaceClaim[], sourceId: string): ClaimEvidence | null {
  const matches = claims.flatMap((claim) => claim.evidence.map((evidence) => ({ claim, evidence }))).filter(({ claim, evidence }) =>
    evidence.source_id === sourceId
    && (!evidence.output_revision || !claim.output_revision || evidence.output_revision === claim.output_revision)
    && (!evidence.claim_revision || !claim.claim_revision || evidence.claim_revision === claim.claim_revision));
  const sources = new Map<string, ClaimEvidence[]>();
  for (const { evidence } of matches) {
    const key = `${evidence.source_id}\u0000${evidence.path ?? ""}\u0000${evidence.url ?? ""}`;
    sources.set(key, [...(sources.get(key) ?? []), evidence]);
  }
  if (sources.size !== 1) return null;
  const sourceEvidence = [...sources.values()][0];
  const evidence = sourceEvidence[0];
  const versions = new Set(sourceEvidence.map((item) => item.source_version).filter(Boolean));
  return {
      claim_id: `source:${evidence.source_id}`,
      source_id: evidence.source_id,
      source_label: evidence.source_label,
      path: evidence.path,
      url: evidence.url,
      source_version: versions.size === 1 ? evidence.source_version : null,
      support_state: evidence.support_state,
  };
}

function safeDecodePath(href: string): string | null {
  try { return decodeURIComponent(href.replace(/^\.\//, "")); }
  catch { return null; }
}

function safePublicUrl(value: string): boolean {
  try { return ["http:", "https:", "mailto:"].includes(new URL(value).protocol); }
  catch { return false; }
}

function origin(surface: ReferenceOrigin["surface"], recordId?: string | null): ReferenceOrigin {
  return { surface, record_id: recordId ?? null, focus_id: typeof document === "undefined" ? null : document.activeElement instanceof HTMLElement ? document.activeElement.id || null : null, scroll_offset: typeof window === "undefined" ? null : window.scrollY };
}

export interface ClaimMarkdownProps {
  text: string;
  claims?: WorkspaceClaim[];
  documents?: DocumentIdentity[];
  surface?: ReferenceOrigin["surface"];
  recordId?: string | null;
  className?: string;
  onOpenEvidence?: (evidence: ClaimEvidence) => void;
  onOpenDocument?: (target: DocumentReferenceTarget) => void;
}

/** Render saved prose and resolve each source marker by source, locator, and claim revision. */
export default function ClaimMarkdown({ text, claims = [], documents = [], surface = "document", recordId, className, onOpenEvidence, onOpenDocument }: ClaimMarkdownProps) {
  const markers: Array<{ label: string; evidence: ClaimEvidence | null; exact: boolean }> = [];
  const renderedClaims = claimsForRenderedText(claims, text);
  const markdown = visibleClaimProse(text).replace(SOURCE_MARKER, (_marker, sourceId: string, locator?: string) => {
    const normalizedLocator = locator?.trim() || null;
    const exact = evidenceForSourceMarker(renderedClaims, sourceId, normalizedLocator);
    const evidence = exact ?? sourceForMarker(claims, sourceId);
    const index = markers.push({ label: normalizedLocator ? `${sourceId} · ${normalizedLocator}` : sourceId, evidence, exact: Boolean(exact) }) - 1;
    return `[${normalizedLocator ? `Source: ${sourceId} · ${normalizedLocator}` : `Source: ${sourceId}`}](#themis-source-${index})`;
  });

  function openInternal(event: MouseEvent<HTMLAnchorElement>, href: string) {
    const decoded = safeDecodePath(href);
    if (!decoded) return;
    const match = documents.find((item) => item.path === decoded);
    if (!match || !onOpenDocument || !isSafeDocumentPath(match.path)) return;
    event.preventDefault();
    onOpenDocument({ document_id: match.document_id, path: match.path, revision: match.revision, origin: origin(surface, recordId) });
  }

  return <div className={className}><ReactMarkdown remarkPlugins={[remarkGfm]} components={{
    a: ({ href = "", children }) => {
      const marker = href.match(/^#themis-source-(\d+)$/);
      if (marker) {
        const item = markers[Number(marker[1])];
        return <button className="claim-source-link" disabled={!item?.evidence || !onOpenEvidence} onClick={() => item?.evidence && onOpenEvidence?.(item.evidence)} title={item?.exact ? "Review this saved passage" : item?.evidence ? "Open the saved source; no unique passage is selected" : "The saved source is unavailable"} type="button">{children}{item?.exact ? null : item?.evidence ? " · source" : " · unavailable"}</button>;
      }
      if (safePublicUrl(href)) return <a href={href} rel="noreferrer" target="_blank">{children}</a>;
      const decoded = safeDecodePath(href);
      const internal = decoded !== null && documents.some((item) => item.path === decoded);
      if (internal) return <a href={href} onClick={(event) => openInternal(event, href)}>{children}</a>;
      return <span title="Unsafe or unavailable link">{children}</span>;
    },
    table: ({ children }: { children?: ReactNode }) => <div className="claim-table-scroll"><table>{children}</table></div>,
  }}>{markdown}</ReactMarkdown></div>;
}

frontend/components/DocumentPanel.tsx:
"use client";

import { DragEvent, useEffect, useRef, useState } from "react";
import DocumentReview from "@/components/DocumentReview";
import LinkifiedText from "@/components/LinkifiedText";
import MarkdownRichEditor from "@/components/MarkdownRichEditor";
import { exportFileUrl, getDocumentReview, getFile, rawFileUrl, saveFile, updateDocumentReview } from "@/lib/api";
import { discardLocalEditorSnapshot, documentVersionKey, freezeDocumentTarget, mutationBasisForSnapshot, readLocalEditorSnapshot, recoverableLocalEditorSnapshot, sameDocumentTarget, snapshotForDocument, writeLocalEditorSnapshot } from "@/lib/documentNavigation";
import { parseMemo } from "@/lib/research";
import type { DocumentIdentity, DocumentPanelProps, LocalEditorSnapshot, SelectedRange } from "@/lib/workspaceTypes";
import type { DocumentReview as ReviewState, DocumentReviewAction, VaultDocument } from "@/lib/types";
import { authorId, GENERATED_REVIEW_AUTHOR, REVIEW_AUTHOR_PALETTE } from "@/lib/reviewAuthor";
import { savedMarkdownMatches } from "@/lib/documentSave";

type SaveState = "clean" | "saving" | "conflict" | "error";
type MutationBasis = { base_revision: string; review_revision?: string };
type ReferenceAwareDocumentPanelProps = DocumentPanelProps & { documents?: DocumentIdentity[] };

/**
 * Canvas 4c — the work surface. A what-you-see editor over a file that stays
 * plain Markdown on disk. Agent-written files remain clearly labelled.
 */
export default function DocumentPanel({
  activeDocument,
  activePath,
  contextKey,
  humanActor,
  refreshSignal = 0,
  localEdit,
  actionTargetDocumentId,
  referenceTarget,
  documents = [],
  onSnapshot,
  onSaved,
  onUpload,
  onAskAgent,
  onOpenReference,
  onClose,
  onCollapse,
  activeReviewAuthor,
  lawyerAuthor,
  onReviewAuthorChange,
}: ReferenceAwareDocumentPanelProps) {
  const [document, setDocument] = useState<VaultDocument | null>(null);
  const [review, setReview] = useState<ReviewState | null>(null);
  const [mode, setMode] = useState<"editing" | "markdown" | "review" | "sources">("editing");
  const [exportMode, setExportMode] = useState<"markup" | "accepted_text">("markup");
  const [dirty, setDirty] = useState(false);
  const [saveState, setSaveState] = useState<SaveState>("clean");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [editorVersion, setEditorVersion] = useState(0);
  const cachedEdits = useRef(new Map<string, { document: VaultDocument; review: ReviewState | null; dirty: boolean; range: SelectedRange | null }>());
  const mutationBases = useRef(new Map<string, MutationBasis>());
  const loadVersion = useRef(0);
  const reviewRef = useRef<ReviewState | null>(null);
  reviewRef.current = review;
  const [savedChangesAvailable, setSavedChangesAvailable] = useState(false);
  const [selectedRange, setSelectedRange] = useState<SelectedRange | null>(null);
  const defaultedHumanAuthor = useRef(false);
  const documentRef = useRef<VaultDocument | null>(null);
  documentRef.current = document;
  const activeIdentity: DocumentIdentity | null = activeDocument ?? (activePath ? {
    document_id: activePath,
    path: activePath,
    title: activePath.split("/").at(-1) || activePath,
    kind: "work_product",
    revision: "",
    lifecycle_state: "editing_draft",
    editable: true,
    immutable: false,
  } : null);
  const activeIdentityRef = useRef<DocumentIdentity | null>(activeIdentity);
  activeIdentityRef.current = activeIdentity;

  const editingAuthorId = humanActor?.person_id ?? authorId(activeReviewAuthor);
  const editingAuthorName = humanActor?.display_name ?? activeReviewAuthor;
  const lawyerAuthorId = humanActor?.person_id ?? authorId(lawyerAuthor);

  function basisFor(identity: DocumentIdentity, savedReview: ReviewState | null): MutationBasis {
    return mutationBases.current.get(documentVersionKey(identity)) ?? {
      base_revision: savedReview?.artifact_revision || identity.revision,
      review_revision: savedReview?.revision ?? undefined,
    };
  }

  useEffect(() => {
    const lawyer = lawyerAuthor.trim();
    if (defaultedHumanAuthor.current || !lawyer) return;
    defaultedHumanAuthor.current = true;
    if (!activeReviewAuthor.trim() || ["Themis", GENERATED_REVIEW_AUTHOR].includes(activeReviewAuthor)) {
      onReviewAuthorChange(lawyer);
    }
  }, [activeReviewAuthor, lawyerAuthor, onReviewAuthorChange]);

  function rememberDocument(savedDocument: VaultDocument, savedReview: ReviewState | null, isDirty: boolean, range: SelectedRange | null, recoverable = false, frozenIdentity = activeIdentityRef.current) {
    const identity = frozenIdentity;
    const cacheKey = identity ? documentVersionKey(identity) : savedDocument.path;
    cachedEdits.current.set(cacheKey, { document: savedDocument, review: savedReview, dirty: isDirty, range });
    if (identity && !isDirty) mutationBases.current.set(cacheKey, { base_revision: savedReview?.artifact_revision || identity.revision, review_revision: savedReview?.revision ?? undefined });
    if (!contextKey || !identity || identity.path !== savedDocument.path) return;
    const basis = basisFor(identity, savedReview);
    const snapshot: LocalEditorSnapshot = { document_id: identity.document_id, path: identity.path, content: savedDocument.content, base_revision: basis.base_revision, review_revision: basis.review_revision, dirty: isDirty, selected_range: range, recoverable, updated_at: new Date().toISOString() };
    if (isDirty) writeLocalEditorSnapshot(localStorage, contextKey, snapshot);
    else {
      const stored = readLocalEditorSnapshot(localStorage, contextKey, identity.document_id);
      if (stored?.path === identity.path) discardLocalEditorSnapshot(localStorage, contextKey, identity.document_id);
    }
  }

  useEffect(() => {
    if (!document) return;
    const identity = activeIdentityRef.current;
    if (!identity || identity.path !== document.path) return;
    rememberDocument(document, review, dirty, selectedRange);
    const basis = basisFor(identity, review);
    onSnapshot?.({ document_id: identity.document_id, path: identity.path, content: document.content, base_revision: basis.base_revision, review_revision: basis.review_revision, dirty, selected_range: selectedRange, recoverable: false, updated_at: new Date().toISOString() });
  }, [document, review, dirty, selectedRange, onSnapshot, activeDocument?.document_id, activeDocument?.path, activeDocument?.revision]);

  useEffect(() => {
    let current = true;
    const version = ++loadVersion.current;
    setSavedChangesAvailable(false);
    if (!activePath) { setDocument(null); return; }
    const identity = activeIdentityRef.current;
    const cacheKey = identity ? documentVersionKey(identity) : activePath;
    const recoveredSnapshot = snapshotForDocument(identity, localEdit)
      ?? (contextKey && identity ? snapshotForDocument(identity, readLocalEditorSnapshot(localStorage, contextKey, identity.document_id)) : null);
    const cached = cachedEdits.current.get(cacheKey);
    if (cached?.dirty) {
      setDocument(cached.document); setReview(cached.review); setDirty(true); setSelectedRange(cached.range);
    }
    if (!cached?.dirty && recoveredSnapshot) {
      setDocument(null);
      setDirty(true);
      setSelectedRange(recoveredSnapshot.selected_range);
    }
    if (!cached?.dirty) { setDocument(null); setReview(null); setBusy(true); }
    setError("");
    void loadDocument(activePath).then(({ result, reviewState }) => {
      if (!current || version !== loadVersion.current) return;
      const latestIdentity = activeIdentityRef.current;
      const newer = cachedEdits.current.get(cacheKey) || cached;
      if (newer?.dirty) {
        const localBasis = latestIdentity ? basisFor(latestIdentity, newer.review) : { base_revision: newer.review?.artifact_revision ?? "", review_revision: newer.review?.revision };
        setSavedChangesAvailable(localBasis.base_revision !== (reviewState?.artifact_revision || latestIdentity?.revision || "") || localBasis.review_revision !== reviewState?.revision);
        return;
      }
      const restored = snapshotForDocument(latestIdentity, recoveredSnapshot);
      if (restored) {
        const localDocument = { ...result, content: restored.content };
        const restoredBasis = mutationBasisForSnapshot(restored);
        mutationBases.current.set(cacheKey, { base_revision: restoredBasis.expected_revision, review_revision: restoredBasis.expected_review_revision });
        cachedEdits.current.set(cacheKey, { document: localDocument, review: reviewState, dirty: true, range: restored.selected_range });
        setDocument(localDocument); setReview(reviewState); setDirty(true); setSelectedRange(restored.selected_range);
        setSavedChangesAvailable(Boolean(restored.base_revision && restored.base_revision !== (reviewState?.artifact_revision || latestIdentity?.revision)) || Boolean(restored.review_revision && restored.review_revision !== reviewState?.revision));
        setSaveState("clean"); setMode("editing"); setEditorVersion(value => value + 1);
        return;
      }
      rememberDocument(result, reviewState, false, null);
      setDocument(result); setReview(reviewState); setDirty(false); setSelectedRange(null);
      setSaveState("clean"); setMode("editing"); setEditorVersion(value => value + 1);
    }).catch(cause => { if (current && version === loadVersion.current) setError(cause instanceof Error ? cause.message : "Could not load the file."); })
      .finally(() => { if (current && version === loadVersion.current) setBusy(false); });
    return () => { current = false; ++loadVersion.current; };
  }, [activePath, activeDocument?.document_id, activeDocument?.path, activeDocument?.revision, refreshSignal, contextKey, localEdit?.document_id, localEdit?.path]);

  async function loadDocument(path: string): Promise<{ result: VaultDocument; reviewState: ReviewState | null }> {
    let result = await getFile(path);
    if (result.kind !== "markdown" || (path.includes("/documents/") && result.metadata.record_type !== "work_product" && !path.endsWith(".extracted.md"))) {
      try {
        const companion = await getFile(`${path}.extracted.md`);
        const reviewState = await getDocumentReview(companion.path);
        return { result: { ...result, editable: false }, reviewState };
      } catch {
        // Original bytes stay visible even when no editable companion is available.
      }
    }
    const reviewState = result.kind === "markdown" && result.editable
      ? await getDocumentReview(result.path)
      : null;
    if (reviewState && !savedMarkdownMatches(result.content, reviewState.segments.filter(segment => segment.kind !== "delete").map(segment => segment.text).join(""))) {
      throw new Error("The saved file changed while it loaded. Reload to get its latest text and review together.");
    }
    return { result, reviewState };
  }

  async function save(): Promise<boolean> {
    const submittedIdentity = activeIdentityRef.current;
    if (!document || !document.editable || submittedIdentity?.immutable || submittedIdentity?.editable === false) return false;
    const frozenTarget = submittedIdentity ? freezeDocumentTarget(submittedIdentity) : null;
    const targetIsActive = () => frozenTarget ? sameDocumentTarget(frozenTarget, activeIdentityRef.current) : documentRef.current?.path === document.path;
    const submitted = { ...document, metadata: { ...document.metadata } };
    const frozenBasis = submittedIdentity ? basisFor(submittedIdentity, review) : { base_revision: review?.artifact_revision ?? "", review_revision: review?.revision };
    const latestBaseRevision = review?.artifact_revision || submittedIdentity?.revision || "";
    if (frozenBasis.base_revision !== latestBaseRevision || frozenBasis.review_revision !== review?.revision) {
      setSaveState("conflict");
      setDirty(true);
      setError("The saved file changed after this local edit began. Your local text is still here. Reload the saved file only when you are ready to discard or reapply it.");
      return false;
    }
    const basis = { expected_revision: frozenBasis.base_revision, expected_review_revision: frozenBasis.review_revision };
    ++loadVersion.current;
    setBusy(true);
    setSaveState("saving");
    setError("");
    try {
      let nextReview: ReviewState | null = null;
      if (review?.tracking) {
        const existing = review.authors.find((item) => item.author_id === editingAuthorId);
        nextReview = await updateDocumentReview(submitted.path, { ...basis, action: "save_revision", content: submitted.content, author_id: editingAuthorId, author_name: editingAuthorName, author_color: existing?.color ?? REVIEW_AUTHOR_PALETTE[review.authors.length % REVIEW_AUTHOR_PALETTE.length] });
      } else if (review) nextReview = await updateDocumentReview(submitted.path, { ...basis, action: "save_untracked", content: submitted.content });
      else await saveFile(submitted);
      let canonical: VaultDocument;
      try {
        canonical = await getFile(submitted.path);
      } catch {
        if (targetIsActive()) {
          setSaveState("conflict");
          setDirty(true);
          setError("The save response returned, but Themis.ai could not verify the saved file. Your local text is still here.");
        }
        return false;
      }
      if (!savedMarkdownMatches(submitted.content, canonical.content)) {
        if (targetIsActive()) {
          setSaveState("conflict");
          setDirty(true);
          setError("The saved file differs from this edit. Your local text is still here.");
        }
        return false;
      }
      const current = documentRef.current;
      if (!current || current.path !== submitted.path) {
        const cacheKey = submittedIdentity ? documentVersionKey(submittedIdentity) : submitted.path;
        const cached = cachedEdits.current.get(cacheKey);
        if (cached?.document.content === submitted.content) rememberDocument(canonical, nextReview, false, null, false, submittedIdentity);
        return false;
      }
      if (current?.path === submitted.path && nextReview) {
        reviewRef.current = nextReview;
        setReview(nextReview);
      }
      if (current.content !== submitted.content) {
        if (current?.path === submitted.path) rememberDocument(current, nextReview, true, selectedRange, false, submittedIdentity);
        setSaveState("clean");
        setDirty(true);
        return false;
      }
      rememberDocument(canonical, nextReview, false, null, false, submittedIdentity);
      documentRef.current = canonical;
      setDocument(canonical);
      setDirty(false);
      setSelectedRange(null);
      setSavedChangesAvailable(false);
      setSaveState("clean");
      if (canonical.kind === "markdown" && nextReview) setReview(nextReview);
      setEditorVersion((current) => current + 1);
      const savedRevision = nextReview?.artifact_revision || (typeof canonical.metadata.revision === "string" ? canonical.metadata.revision : submittedIdentity?.revision);
      if (submittedIdentity && savedRevision && savedRevision !== submittedIdentity.revision) onSaved?.({ ...submittedIdentity, revision: savedRevision });
      else onSaved?.();
      return true;
    } catch (caught) {
      if (targetIsActive()) {
        setSaveState("error");
        setDirty(true);
        setError(caught instanceof Error ? caught.message : "Could not save the file.");
      }
      return false;
    }
    finally { setBusy(false); }
  }

  async function reloadCanonical() {
    if (!document) return;
    if (dirty && !window.confirm("Discard your local changes and load the latest saved file? Copy any text you want to keep before you continue.")) return;
    const submitted = documentRef.current;
    const version = ++loadVersion.current;
    setBusy(true);
    setError("");
    try {
      const loaded = await loadDocument(document.path);
      if (version !== loadVersion.current) return;
      if (documentRef.current !== submitted) {
        setError("Your local text changed while the saved file loaded. It is still here. Reload again when you are ready.");
        return;
      }
      rememberDocument(loaded.result, loaded.reviewState, false, null);
      documentRef.current = loaded.result;
      reviewRef.current = loaded.reviewState;
      setSavedChangesAvailable(false);
      setSelectedRange(null);
      setMode("editing");
      setDocument(loaded.result);
      setReview(loaded.reviewState);
      setDirty(false);
      setSaveState("clean");
      setEditorVersion((current) => current + 1);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not reload the saved file.");
    } finally {
      setBusy(false);
    }
  }

  function requestClose() {
    if (!onClose) return;
    if (dirty) {
      const identity = activeIdentityRef.current;
      if (document && identity) {
        rememberDocument(document, review, true, selectedRange, true, identity);
        const basis = basisFor(identity, review);
        onSnapshot?.(recoverableLocalEditorSnapshot({ document_id: identity.document_id, path: identity.path, content: document.content, base_revision: basis.base_revision, review_revision: basis.review_revision, dirty: true, selected_range: selectedRange }));
      }
      setDocument(null);
      onClose();
      return;
    }
    onClose();
  }

  async function reviewAction(action: DocumentReviewAction) {
    if (!document) return;
    const requestedDocument = documentRef.current;
    const requestedIdentity = activeIdentityRef.current;
    if (dirty && !await save()) return;
    const submitted = documentRef.current?.path === requestedDocument?.path ? documentRef.current : null;
    const submittedIdentity = requestedIdentity;
    const frozenTarget = submittedIdentity ? freezeDocumentTarget(submittedIdentity) : null;
    if (!submitted) return;
    ++loadVersion.current;
    setBusy(true);
    setError("");
    try {
      const actorName = ["edit_comment", "delete_comment_entry", "resolve_comment", "reopen_comment", "delete_comment_thread", "delete_resolved_comments"].includes(action.action) ? lawyerAuthor : activeReviewAuthor;
      const actorId = humanActor?.person_id ?? authorId(actorName);
      const actor = review?.authors.find((item) => item.author_id === actorId);
      const frozenBasis = submittedIdentity ? basisFor(submittedIdentity, reviewRef.current) : { base_revision: reviewRef.current?.artifact_revision ?? "", review_revision: reviewRef.current?.revision };
      const basis = reviewRef.current;
      const nextReview = await updateDocumentReview(submitted.path, { ...action, expected_revision: frozenBasis.base_revision, expected_review_revision: frozenBasis.review_revision, author_id: action.author_id ?? actorId, author_name: humanActor?.display_name ?? action.author_name ?? actorName, author_color: action.author_color ?? actor?.color ?? REVIEW_AUTHOR_PALETTE[(review?.authors.length ?? 0) % REVIEW_AUTHOR_PALETTE.length] });
      const nextDocument = await getFile(submitted.path);
      const current = documentRef.current;
      if (!current || current.path !== submitted.path) return;
      if (current.content !== submitted.content) {
        // These edits started against the prior review. Keep that base so a
        // later save cannot silently overwrite the completed review action.
        const cacheKey = submittedIdentity ? documentVersionKey(submittedIdentity) : current.path;
        rememberDocument(current, basis, true, cachedEdits.current.get(cacheKey)?.range ?? null, false, submittedIdentity);
        setDirty(true);
        setSavedChangesAvailable(true);
        setError("Your review action was saved. Your newer local text is still here. Reload the saved file when you are ready to review it.");
        return;
      }
      rememberDocument(nextDocument, nextReview, false, null, false, submittedIdentity);
      documentRef.current = nextDocument;
      reviewRef.current = nextReview;
      setSavedChangesAvailable(false);
      setSelectedRange(null);
      setDocument(nextDocument);
      setReview(nextReview);
      setDirty(false);
      setEditorVersion((current) => current + 1);
    } catch (caught) {
      if (!frozenTarget || sameDocumentTarget(frozenTarget, activeIdentityRef.current)) {
        setError(caught instanceof Error ? caught.message : "Could not update document review.");
      }
    } finally {
      setBusy(false);
    }
  }

  async function exportDocument(format: "docx" | "pdf") {
    if (!document) return;
    const submitted = { path: document.path, document_id: activeIdentityRef.current?.document_id };
    if (dirty && !await save()) return;
    const link = window.document.createElement("a");
    const savedReview = await getDocumentReview(submitted.path);
    link.href = exportFileUrl(submitted.path, format, { mode: exportMode, expected_revision: savedReview.artifact_revision, expected_review_revision: savedReview.revision });
    link.download = "";
    window.document.body.appendChild(link);
    link.click();
    link.remove();
  }

  async function drop(event: DragEvent<HTMLDivElement>) {
    event.preventDefault();
    const file = event.dataTransfer.files?.[0];
    if (!file) return;
    if (document?.editable && activeIdentityRef.current?.editable !== false && !activeIdentityRef.current?.immutable && /\.(md|txt)$/i.test(file.name)) {
      const text = await file.text();
      setDocument({ ...document, content: `${document.content.trimEnd()}\n\n${text}\n` });
      setDirty(true);
      return;
    }
    await onUpload(file);
  }

  if (!activePath) return null;
  if (busy && !document) return <div className="doc-pane"><div className="loading">Loading document…</div></div>;
  if (error && !document) return <div className="doc-pane"><div className="doc-scroll"><p className="error">{error}</p></div></div>;
  if (!document) return null;

  const isMarkdown = document.kind === "markdown" || /\.md$/i.test(document.name);
  const canEdit = document.editable && activeIdentity?.editable !== false && !activeIdentity?.immutable;
  const isResearch = isMarkdown && document.path.includes("/research/") && document.name !== "annotations.md";
  const citations = isResearch ? parseMemo(document).citations : [];
  const agentWritten = /^(research|drafts)\//.test(document.path.split("/").slice(2).join("/"))
    || String(document.metadata.author ?? "").toLowerCase().includes("agent");
  const sourcePath = typeof document.metadata.source_path === "string" ? document.metadata.source_path : null;
  const saveLabel = saveState === "saving"
    ? "Saving…"
    : saveState === "conflict"
      ? "Save conflict — review"
      : dirty ? "Unsaved changes" : "Saved";

  return (
    <div className="doc-pane" onDragOver={(event) => event.preventDefault()} onDrop={drop}>
      <label className="workspace-export-mode">Export version <select value={exportMode} onChange={event => setExportMode(event.target.value as "markup" | "accepted_text")}><option value="markup">Saved changes as markup</option><option value="accepted_text">Accepted text only</option></select></label>
      <div className="doc-bar">
        <div style={{ minWidth: 0 }}>
          <span className="doc-name">{document.name}</span>
          <span className={`doc-status ${agentWritten ? "agent" : ""}`}>
            {activeIdentity?.lifecycle_state === "reading_source" ? "Reading source · Read-only"
              : activeIdentity?.lifecycle_state === "approved" ? "Approved · Read-only"
                : activeIdentity?.lifecycle_state === "final" ? "Final · Read-only"
                  : agentWritten ? `Editing draft · Agent work · ${saveLabel.toLowerCase()}`
                    : canEdit ? `Editing draft · ${saveLabel.toLowerCase()}` : saveLabel}
          </span>
        </div>
        <div className="doc-mode">
          {isMarkdown && canEdit ? (
            <>
              <button className={mode === "editing" ? "active" : ""} onClick={() => setMode("editing")} title="Edit the document with formatting controls.">Editing</button>
              <button className={mode === "markdown" ? "active" : ""} onClick={() => setMode("markdown")} title="Edit the Markdown source text directly.">Markdown</button>
              {isResearch ? (
                <button className={mode === "sources" ? "active" : ""} onClick={() => setMode("sources")} title="Review the sources cited in this research document.">Sources</button>
              ) : null}
            </>
          ) : null}
          {onClose ? <button aria-label="Close document" className="pane-close" onClick={requestClose} title="Close document" type="button">×</button> : null}
          {onCollapse ? <button aria-label="Collapse document" className="pane-collapse" onClick={onCollapse} title="Collapse document">›</button> : null}
        </div>
      </div>

      {!isMarkdown && review ? <p className="chat-history-status">Original supplied file. Drafting uses its saved extracted text. The original remains unchanged.</p> : null}
      {referenceTarget && onOpenReference ? <div className="chat-history-status"><button className="btn quiet tiny" type="button" onClick={() => onOpenReference(referenceTarget)}>Open referenced passage</button> The source opens separately and does not change this document&apos;s action target.</div> : null}
      {isResearch && mode === "sources" ? (
        <div className="doc-scroll research-sources">
          {citations.length ? citations.map((citation) => (
            <article className="research-source-card" key={citation.id}>
              <div className="research-source-heading">
                <span>{citation.n}</span>
                <strong>{citation.name}</strong>
              </div>
              <div className="research-source-kind"><LinkifiedText text={citation.kind} /></div>
              <div className="source-quote"><LinkifiedText text={citation.quote} /></div>
              <p><LinkifiedText text={citation.note} /></p>
            </article>
          )) : (
            <div className="empty-state">
              <h3>No sources are cited in this research yet.</h3>
              <p className="muted">The research remains editable. Add citations before relying on it as sourced analysis.</p>
            </div>
          )}
        </div>
      ) : isMarkdown && (mode === "editing" || !document.editable) ? review ? (
        <DocumentReview
          author={review.authors.find((item) => item.author_id === editingAuthorId) ?? { author_id: editingAuthorId, name: editingAuthorName, color: REVIEW_AUTHOR_PALETTE[review.authors.length % REVIEW_AUTHOR_PALETTE.length] }}
          busy={busy}
          key={document.path}
          lawyerAuthor={lawyerAuthor}
          lawyerAuthorId={lawyerAuthorId}
          onAction={reviewAction}
          onAuthorChange={onReviewAuthorChange}
          readOnly={!canEdit}
          review={review}
        >{({ mode: reviewMode, reviewers, onAddComment, onOpenThread, onSelectionContext }) => <MarkdownRichEditor
          key={`${document.path}-${editorVersion}`}
          markdown={document.content}
          onAddComment={onAddComment}
          onAskAgent={canEdit && onAskAgent ? () => onAskAgent(actionTargetDocumentId ?? activeIdentity?.document_id) : undefined}
          onOpenCommentThread={onOpenThread}
          onSelectionContext={selection => {
            onSelectionContext(selection);
            if (selection.anchorStart !== undefined && selection.anchorEnd !== undefined) {
              const start = Array.from(document.content.slice(0, selection.anchorStart)).length;
              const end = Array.from(document.content.slice(0, selection.anchorEnd)).length;
              setSelectedRange({ start, end, text: document.content.slice(selection.anchorStart, selection.anchorEnd) });
            } else setSelectedRange(null);
          }}
          documents={documents}
          onOpenDocument={onOpenReference}
          readOnly={!canEdit}
          reviewComments={review.comments}
          reviewMode={reviewMode}
          reviewReviewers={reviewers}
          reviewSegments={review.segments}
          reviewTracking={review.tracking}
          reviewAuthor={review.authors.find((item) => item.author_id === editingAuthorId) ?? { author_id: editingAuthorId, name: editingAuthorName, color: REVIEW_AUTHOR_PALETTE[review.authors.length % REVIEW_AUTHOR_PALETTE.length] }}
          onChange={(content) => {
            if (savedMarkdownMatches(content, document.content)) return;
            setDocument((current) => (current ? { ...current, content } : current));
            setDirty(true);
          }}
        />}</DocumentReview>
      ) : <MarkdownRichEditor key={document.path} markdown={document.content} readOnly documents={documents} onOpenDocument={onOpenReference} />
      : isMarkdown || document.editable ? (
        <div className="doc-scroll">
          <textarea
            aria-label="Raw Markdown"
            className="markdown-source"
            onChange={(event) => { setDocument({ ...document, content: event.target.value }); setDirty(true); }}
            readOnly={!canEdit}
            spellCheck
            value={document.content}
          />
        </div>
      ) : (
        <div className="doc-scroll">
          <div className="empty-state">
            <h3>{document.name}</h3>
            <p className="muted" style={{ maxWidth: "48ch", margin: "8px auto 14px" }}>
              The original file is read-only. Open it directly, or select its extracted Markdown companion.
            </p>
            <a className="btn" href={rawFileUrl(document.path)} target="_blank" rel="noreferrer">Open the original</a>
          </div>
        </div>
      )}

      {savedChangesAvailable ? (
        <div className="notice-card wash-attention" style={{ margin: "0 34px 12px" }}>
          <strong>New saved version available</strong>
          <p>Your local text is still here. Copy any edits you want to keep, then reload the saved file to review its latest changes.</p>
        </div>
      ) : null}
      {error ? <p className="error" style={{ margin: "0 34px 12px" }}>{error}</p> : null}
      {saveState === "conflict" ? (
        <div className="notice-card wash-attention" style={{ margin: "0 34px 12px" }}>
          <strong>Save conflict — review</strong>
          <p>Your local text is still available. Check the saved file before you retry.</p>
          <div className="btn-row">
            <button className="btn compact" disabled={busy} onClick={() => void save()} type="button">Retry save</button>
            <button className="btn compact" disabled={busy} onClick={() => void reloadCanonical()} type="button">Reload saved file</button>
          </div>
        </div>
      ) : null}

      <div className="doc-bar" style={{ position: "static", borderBottom: 0, borderTop: "1px solid var(--line-soft)" }}>
        <div className="review-footer-status">
          <span>{saveLabel}</span>
          {isMarkdown && review ? (
            <span className="track-toggle">Redline {review.tracking ? "on" : "off"}</span>
          ) : null}
        </div>
        <div className="btn-row">
          {isMarkdown ? (
            <>
              {sourcePath ? <a className="btn compact" href={rawFileUrl(sourcePath)} rel="noreferrer" target="_blank">Original</a> : null}
              <button className="btn compact" disabled={busy} onClick={() => void exportDocument("docx")} type="button">Word</button>
              <button className="btn compact" disabled={busy} onClick={() => void exportDocument("pdf")} type="button">PDF</button>
            </>
          ) : null}
          {saveState !== "conflict" ? <button className="btn compact" disabled={busy} onClick={() => void reloadCanonical()} type="button">Reload saved file</button> : null}
          <button className="btn primary compact" disabled={!dirty || busy || !canEdit} onClick={() => void save()}>
            {busy ? "Saving…" : dirty && review?.tracking ? "Save redline" : "Save"}
          </button>
        </div>
      </div>
    </div>
  );
}

frontend/components/ChatPanel.tsx:
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { KeyboardEvent, useCallback, useEffect, useRef, useState } from "react";
import AttachmentPicker from "@/components/AttachmentPicker";
import ChatCards, { WorkspaceReceiptCards } from "@/components/ChatCards";
import SkillCommandMenu from "@/components/SkillCommandMenu";
import LinkifiedText from "@/components/LinkifiedText";
import UploadIntentCard from "@/components/UploadIntentCard";
import { cancelChatRun, getChatRun, getChatRuns, getConversation, getConversations, getSkills, recoverIntakeQuestion, retryChatRun, saveWorkProductDraft, startChatRun, uploadDocuments } from "@/lib/api";
import { chatAgentId, chatDraftStorageKey, chatFailureGuidance, chatProgressLabel, chatRunStateLabel, chatRunStorageKey, chatSuggestions, conversationChatDraftStorageKey, durableChatProgress, historicalQuestionStates, intakeRecoveryKey, legacyChatDraftStorageKey, legacyChatRunStorageKey, mergeChatMessages, needsIntakeQuestionRecovery, pendingChatRunId, promoteConversationComposer, rememberChatRun, remainingComposerValue, safeChatFailureDetail, shouldCompactIntakeTurn, shouldShowChatRunStatus, storeConversationComposer } from "@/lib/chatRunLogic";
import { legacyQuestionModeStorageKey, questionModeStorageKey } from "@/lib/chatCardLogic";
import { skillBuilderGoal } from "@/lib/skills";
import type { AppliedSkillSummary, AttachmentReference, CardAction, ChatCard, ChatRun, IntakeAnswer, OperationResult, QuestionMode, SkillDefinition, ToolTrace } from "@/lib/types";
import ClaimMarkdown from "@/components/workspace/ClaimMarkdown";
import type { DocumentIdentity, DocumentReferenceTarget, WorkspaceClaim } from "@/lib/workspaceTypes";

type ChatOperationResult = OperationResult & { proposal?: Record<string, unknown> };
type Message = { message_id?: string; run_id?: string; workspace_action?: string | null; role: "user" | "assistant"; content: string; trace?: ToolTrace[]; cards?: ChatCard[]; attachments?: AttachmentReference[]; applied_skills?: AppliedSkillSummary[]; card_action?: CardAction | null; operation_results?: ChatOperationResult[] };

function terminalRunToken(run: ChatRun): string | null {
  return ["completed", "failed", "interrupted"].includes(run.state) && run.finished_at && Number.isFinite(Date.parse(run.finished_at))
    ? JSON.stringify([run.run_id, run.state, run.finished_at]) : null;
}

function reconciliationHint(contextKey: string | undefined, matterId: string, conversationId?: string | null, value?: string | null): string | null {
  if (!contextKey) return null;
  const key = JSON.stringify(["themis.ai:chat-run-reconciled:v1", contextKey, matterId, conversationId ?? "new"]);
  try {
    if (value === null) window.localStorage.removeItem(key);
    else if (value !== undefined) window.localStorage.setItem(key, value);
    return window.localStorage.getItem(key);
  } catch { return null; } // Optional refresh hint; storage failure must not hide saved work.
}

function shouldRefreshReconnectedRun(run: ChatRun, messages: Message[], conversationId: string | null, pendingRunId: string | null, hint: string | null = null): boolean {
  const token = terminalRunToken(run);
  // A retained failed-run retry key is not new work after this exact result was reconciled.
  return !token || (Boolean(pendingRunId) && hint !== token)
    || !conversationId || (run.response?.conversation_id ?? run.conversation_id) !== conversationId
    || !run.response?.reply || !messages.some(message => message.message_id && message.role === "assistant"
      && message.run_id === run.run_id && message.content === run.response?.reply);
}

const SHOW_AGENT_TRACES = process.env.NEXT_PUBLIC_SHOW_AGENT_TRACES === "true";

/**
 * Canvas 2b — the copilot is a thread at the foot of the matter, not a pane of
 * its own. Its last line never moves: it can research, draft and move the
 * matter; it records a decision only on explicit instruction.
 */
import type { ConversationTarget, InteractionReceipt } from "@/lib/workspaceTypes";

export default function ChatPanel({
  matterId,
  contextKey,
  externalRun,
  contextSelections,
  onFilesAttached,
  onFilesRemoved,
  selectedTemplateId,
  onRunComplete,
  onBeforeSubmit,
  onRunStarted,
  target,
  expectedQuestionRevision,
  workspaceReceipts,
  onClearTarget,
  matterTitle,
  activeFile,
  activeAgentId,
  initialConversationId,
  initialRunId,
  intakeActive = false,
  onRefresh,
  conversationSeed,
  onConversationChange,
  onOpenDocument,
  onOpenReference,
  onOpenEvidence,
  workspaceClaims = [],
  workspaceDocuments = [],
  seed,
  reviewAuthor,
  lawyerAuthor,
  onReviewAuthorChange,
  currentWorkProductDraftPath,
  decisionOptions = [],
  intakeAnswers = [],
}: {
  matterId: string;
  contextKey?: string;
  externalRun?: ChatRun | null;
  contextSelections?: import("@/lib/workspaceTypes").ContextSelection[];
  onFilesAttached?: (files: AttachmentReference[]) => Promise<void>;
  onFilesRemoved?: (files: AttachmentReference[]) => Promise<void>;
  selectedTemplateId?: string | null;
  onRunComplete?: (run: ChatRun) => void;
  onBeforeSubmit?: () => void;
  onRunStarted?: (run: ChatRun) => void;
  target?: ConversationTarget;
  expectedQuestionRevision?: string;
  workspaceReceipts?: InteractionReceipt[];
  onClearTarget?: () => void;
  matterTitle: string;
  activeFile: string | null;
  activeAgentId?: string | null;
  initialConversationId?: string | null;
  initialRunId?: string | null;
  intakeActive?: boolean;
  onRefresh: () => Promise<void>;
  conversationSeed?: { conversationId: string; revision: number };
  onConversationChange?: (conversationId: string | null) => void;
  onOpenDocument?: (path: string) => void;
  onOpenReference?: (target: DocumentReferenceTarget) => void;
  onOpenEvidence?: (evidence: import("@/lib/workspaceTypes").ClaimEvidence) => void;
  workspaceClaims?: WorkspaceClaim[];
  workspaceDocuments?: DocumentIdentity[];
  seed?: { text: string; revision: number };
  reviewAuthor: string;
  lawyerAuthor: string;
  onReviewAuthorChange: (name: string) => void;
  currentWorkProductDraftPath?: string | null;
  decisionOptions?: string[];
  intakeAnswers?: IntakeAnswer[];
}) {
  const router = useRouter();
  const legacyInputStorageKey = contextKey ? `${contextKey}:composer` : chatDraftStorageKey(matterId);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [loadingHistory, setLoadingHistory] = useState(true);
  const [input, setInput] = useState("");
  const composerValue = useRef(input); composerValue.current = input;
  const draftConversationId = conversationId ?? (loadingHistory ? initialConversationId : null);
  const inputStorageKey = conversationChatDraftStorageKey(matterId, draftConversationId);
  const activeInputStorageKey = useRef<string | null>(null);
  const activeDraftConversationId = useRef<string | null>(draftConversationId);
  const skipInputPersistence = useRef(false);
  const [preparedRequest, setPreparedRequest] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [historyError, setHistoryError] = useState("");
  const [attachments, setAttachments] = useState<AttachmentReference[]>([]);
  useEffect(() => {
    const excluded = new Set((contextSelections ?? []).filter(item => !item.selected).map(item => item.path).filter(Boolean));
    setAttachments(current => current.some(item => excluded.has(item.path)) ? current.filter(item => !excluded.has(item.path)) : current);
  }, [contextSelections]);
  const [uploading, setUploading] = useState(false);
  const [composerUploads, setComposerUploads] = useState<Array<{ id: string; file: File; state: string; detail?: string }>>([]);
  const [skills, setSkills] = useState<SkillDefinition[]>([]);
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const [activeRun, setActiveRun] = useState<ChatRun | null>(null);
  const threadElement = useRef<HTMLDivElement>(null);
  const followLatest = useRef(true);
  useEffect(() => { if (followLatest.current) { const frame = requestAnimationFrame(() => { const node = threadElement.current; if (node) node.scrollTop = node.scrollHeight; }); return () => cancelAnimationFrame(frame); } }, [messages, busy]);
  useEffect(() => { if (externalRun?.run_id) { setActiveRun(externalRun); setBusy(["queued", "running"].includes(externalRun.state)); setWaiting(["queued", "running"].includes(externalRun.state)); } }, [externalRun]);
  const [waiting, setWaiting] = useState(false);
  const [refreshingRun, setRefreshingRun] = useState(false);
  const [questionMode, setQuestionMode] = useState<QuestionMode>("guided");
  const [savingAnswerKey, setSavingAnswerKey] = useState<string | null>(null);
  const [savedAnswerPaths, setSavedAnswerPaths] = useState<Record<string, string>>({});
  const [savedAnswerNotices, setSavedAnswerNotices] = useState<Record<string, string>>({});
  const [saveAnswerErrors, setSaveAnswerErrors] = useState<Record<string, string>>({});
  const [intakeRecoveryNotice, setIntakeRecoveryNotice] = useState("");
  const [intakeRecoveryRevision, setIntakeRecoveryRevision] = useState(0);
  const [pendingCardAction, setPendingCardAction] = useState<CardAction | null>(null);
  const terminalRuns = useRef(new Set<string>());
  const intakeRecoveryAttempts = useRef(new Set<string>());

  useEffect(() => {
    if (!busy) { setElapsedSeconds(0); return; }
    const parsed = Date.parse(activeRun?.started_at || activeRun?.created_at || "");
    const started = Number.isFinite(parsed) ? parsed : Date.now();
    const update = () => setElapsedSeconds(Math.max(0, Math.floor((Date.now() - started) / 1000)));
    update();
    const timer = window.setInterval(update, 1000);
    return () => window.clearInterval(timer);
  }, [activeRun?.created_at, activeRun?.started_at, busy]);

  useEffect(() => { void getSkills().then(({ skills: saved }) => setSkills(saved)).catch(() => setSkills([])); }, []);

  useEffect(() => {
    let saved = window.localStorage.getItem(inputStorageKey);
    if (saved === null) {
      saved = window.localStorage.getItem(legacyInputStorageKey)
        ?? window.localStorage.getItem(legacyChatDraftStorageKey(matterId));
      if (saved !== null) {
        window.localStorage.setItem(inputStorageKey, saved);
        window.localStorage.removeItem(legacyInputStorageKey);
        window.localStorage.removeItem(legacyChatDraftStorageKey(matterId));
      }
    }
    activeInputStorageKey.current = inputStorageKey;
    activeDraftConversationId.current = draftConversationId;
    skipInputPersistence.current = true;
    setInput(saved ?? "");
  }, [draftConversationId, inputStorageKey, legacyInputStorageKey, matterId]);

  useEffect(() => {
    if (skipInputPersistence.current) {
      skipInputPersistence.current = false;
      return;
    }
    if (activeInputStorageKey.current !== inputStorageKey) return;
    if (input) window.localStorage.setItem(inputStorageKey, input);
    else window.localStorage.removeItem(inputStorageKey);
    window.localStorage.removeItem(legacyInputStorageKey);
    window.localStorage.removeItem(legacyChatDraftStorageKey(matterId));
  }, [input, matterId, inputStorageKey, legacyInputStorageKey]);

  useEffect(() => {
    const saved = window.localStorage.getItem(questionModeStorageKey(matterId))
      ?? window.localStorage.getItem(legacyQuestionModeStorageKey(matterId));
    if (saved) window.localStorage.setItem(questionModeStorageKey(matterId), saved);
    setQuestionMode(saved === "set" ? "set" : "guided");
  }, [matterId]);

  function changeQuestionMode(mode: QuestionMode) {
    setQuestionMode(mode);
    window.localStorage.setItem(questionModeStorageKey(matterId), mode);
    window.localStorage.removeItem(legacyQuestionModeStorageKey(matterId));
  }

  function saveOutgoingComposer() {
    storeConversationComposer(
      window.localStorage,
      matterId,
      activeDraftConversationId.current,
      composerValue.current,
    );
  }

  function promoteNewComposer(conversation: string, value = composerValue.current) {
    if (activeDraftConversationId.current !== null) return;
    promoteConversationComposer(
      window.localStorage,
      matterId,
      null,
      conversation,
      value,
    );
  }

  useEffect(() => {
    let cancelled = false;
    setLoadingHistory(true);
    setHistoryError("");
    void getConversations(matterId)
      .then(async ({ conversations: saved }) => {
        if (cancelled) return;
        const targetConversationId = initialConversationId || saved[0]?.conversation_id;
        if (!targetConversationId) {
          setConversationId(null);
          setMessages([]);
          return;
        }
        const conversation = await getConversation(matterId, targetConversationId);
        if (!cancelled) {
          promoteNewComposer(conversation.conversation_id);
          setConversationId(conversation.conversation_id);
          setMessages(conversation.messages);
          onConversationChange?.(conversation.conversation_id);
        }
      })
      .catch((caught) => {
        if (!cancelled) setHistoryError(caught instanceof Error ? caught.message : "Could not load saved chat.");
      })
      .finally(() => { if (!cancelled) setLoadingHistory(false); });
    return () => { cancelled = true; };
  }, [initialConversationId, matterId]);

  const finishRun = useCallback(async (run: ChatRun, refreshMatter = true) => {
    setActiveRun(run);
    setWaiting(false);
    if (terminalRuns.current.has(run.run_id)) {
      setBusy(false);
      return;
    }
    terminalRuns.current.add(run.run_id);
    setBusy(false);
    setRefreshingRun(true);
    if (run.response?.review_author) onReviewAuthorChange(run.response.review_author);
    const nextConversationId = run.response?.conversation_id ?? run.conversation_id;
    if (nextConversationId) {
      try {
        const saved = await getConversation(matterId, nextConversationId);
        promoteNewComposer(saved.conversation_id);
        setConversationId(saved.conversation_id);
        setMessages((current) => {
          const merged = mergeChatMessages(current, saved.messages);
          return run.response?.reply && !merged.some(item => item.role === "assistant" && item.content === run.response?.reply)
            ? [...merged, { role: "assistant", workspace_action: "unreconciled_run", content: run.response.reply, trace: run.response.trace, cards: run.response.cards, operation_results: run.response.operation_results }]
            : merged;
        });
        onConversationChange?.(saved.conversation_id);
      } catch {
        if (run.response) setMessages((current) => current.some((item) => item.role === "assistant" && item.content === run.response?.reply)
          ? current
          : [...current, { role: "assistant", workspace_action: "unreconciled_run", content: run.response!.reply, trace: run.response!.trace, cards: run.response!.cards, applied_skills: run.response!.applied_skills, operation_results: run.response!.operation_results }]);
      }
    } else if (run.response) {
      setMessages((current) => current.some((item) => item.role === "assistant" && item.content === run.response?.reply)
        ? current
        : [...current, { role: "assistant", workspace_action: "unreconciled_run", content: run.response!.reply, trace: run.response!.trace, cards: run.response!.cards, applied_skills: run.response!.applied_skills, operation_results: run.response!.operation_results }]);
    }
    if (["failed", "interrupted"].includes(run.state)) rememberChatRun(window.localStorage, matterId, run);
    else window.localStorage.removeItem(chatRunStorageKey(matterId, run.conversation_id));
    window.localStorage.removeItem(chatRunStorageKey(matterId));
    window.localStorage.removeItem(legacyChatRunStorageKey(matterId, run.conversation_id));
    window.localStorage.removeItem(legacyChatRunStorageKey(matterId));
    try {
      if (refreshMatter) {
        await onRefresh();
        onRunComplete?.(run);
      }
      const token = terminalRunToken(run);
      if (token) reconciliationHint(contextKey, matterId, nextConversationId, token);
    } catch {
      setHistoryError("The request finished, but the matter did not refresh. Reload the page to see current state.");
    } finally {
      setRefreshingRun(false);
      setBusy(false);
    }
  }, [matterId, contextKey, onConversationChange, onRefresh, onReviewAuthorChange]);

  useEffect(() => {
    if (!activeRun || !["queued", "running"].includes(activeRun.state)) return;
    reconciliationHint(contextKey, matterId, activeRun.conversation_id, null);
    let cancelled = false;
    const check = async () => {
      try {
        const next = await getChatRun(matterId, activeRun.run_id);
        if (cancelled) return;
        setActiveRun(next);
        if (!["queued", "running"].includes(next.state)) await finishRun(next);
      } catch {
        if (!cancelled) setHistoryError("Themis.ai could not finish this request.");
        setWaiting(false);
      }
    };
    void check();
    const timer = window.setInterval(() => void check(), 2000);
    return () => { cancelled = true; window.clearInterval(timer); };
  }, [activeRun?.run_id, activeRun?.state, contextKey, finishRun, matterId]);

  useEffect(() => {
    if (!seed?.text) return;
    const saved = window.localStorage.getItem(inputStorageKey);
    if (saved?.trim()) {
      if (saved !== seed.text) setPreparedRequest(seed.text);
      return;
    }
    if (composerValue.current.trim() && composerValue.current !== seed.text) setPreparedRequest(seed.text);
    else { setInput(seed.text); setPreparedRequest(null); }
    requestAnimationFrame(() => inputRef.current?.focus());
  }, [inputStorageKey, seed]);

  function appendPreparedRequest() {
    if (!preparedRequest) return;
    setInput(current => current.trim() ? `${current}\n\n${preparedRequest}` : preparedRequest);
    setPreparedRequest(null);
    requestAnimationFrame(() => inputRef.current?.focus());
  }

  useEffect(() => {
    if (conversationSeed?.revision) void openConversation(conversationSeed.conversationId);
  }, [conversationSeed]);

  useEffect(() => {
    if (loadingHistory || activeRun) return;
    const pendingRunId = pendingChatRunId(window.localStorage, matterId, conversationId);
    if (!pendingRunId && !conversationId && !initialRunId) return;
    setBusy(true);
    setWaiting(true);
    let cancelled = false;
    let timer: number | undefined;
    const readSavedRun = async () => {
      if (pendingRunId) return getChatRun(matterId, pendingRunId);
      const latest = conversationId ? (await getChatRuns(matterId, conversationId))[0] : undefined;
      if (latest) return latest;
      return initialRunId ? getChatRun(matterId, initialRunId) : null;
    };
    const reconnectSavedRun = () => void readSavedRun().then(async (run) => {
      if (cancelled) return;
      setHistoryError("");
      if (!run) { setBusy(false); setWaiting(false); return; }
      rememberChatRun(window.localStorage, matterId, run);
      setActiveRun(run);
      if (!["queued", "running"].includes(run.state)) {
        await finishRun(run, shouldRefreshReconnectedRun(run, messages, conversationId, pendingRunId, reconciliationHint(contextKey, matterId, conversationId)));
      } else reconciliationHint(contextKey, matterId, run.conversation_id, null);
    }).catch(() => {
      if (cancelled) return;
      setHistoryError("Themis.ai could not reconnect to the saved request. The server may still be working, so sending another request is blocked.");
      timer = window.setTimeout(reconnectSavedRun, 2000);
    });
    reconnectSavedRun();
    return () => { cancelled = true; window.clearTimeout(timer); };
  }, [activeRun?.run_id, contextKey, conversationId, finishRun, initialRunId, loadingHistory, matterId, messages]);

  useEffect(() => {
    if (
      loadingHistory || busy || refreshingRun || !conversationId
      || (initialConversationId && conversationId !== initialConversationId)
      || !needsIntakeQuestionRecovery(intakeActive, messages)
    ) return;
    const recoveryKey = intakeRecoveryKey(conversationId, messages);
    if (!recoveryKey) return;
    if (intakeRecoveryAttempts.current.has(recoveryKey)) {
      setIntakeRecoveryNotice(
        "The next intake question could not be restored automatically. Send a message to continue.",
      );
      return;
    }
    intakeRecoveryAttempts.current.add(recoveryKey);
    setIntakeRecoveryNotice("");
    setBusy(true);
    setWaiting(true);
    setHistoryError("");
    void recoverIntakeQuestion(matterId, conversationId).then(async (run) => {
      setActiveRun(run);
      setWaiting(["queued", "running"].includes(run.state));
      rememberChatRun(window.localStorage, matterId, run);
      if (!["queued", "running"].includes(run.state)) await finishRun(run);
    }).catch(() => {
      setHistoryError("Themis.ai could not restore the next intake question.");
      setIntakeRecoveryNotice(
        "The next intake question could not be restored automatically. Send a message to continue.",
      );
      setBusy(false);
      setWaiting(false);
    });
  }, [busy, conversationId, finishRun, initialConversationId, intakeActive, intakeRecoveryRevision, loadingHistory, matterId, messages, refreshingRun]);

  function retryIntakeQuestion() {
    if (!conversationId) return;
    const recoveryKey = intakeRecoveryKey(conversationId, messages);
    if (recoveryKey) intakeRecoveryAttempts.current.delete(recoveryKey);
    setIntakeRecoveryNotice("");
    setIntakeRecoveryRevision((value) => value + 1);
  }

  async function submit(
    text: string,
    cardAction?: CardAction,
    actionAttachments: AttachmentReference[] = attachments,
    consumeInput = false,
    consumeAttachments = actionAttachments === attachments,
  ) {
    const trimmed = text.trim();
    if ((!trimmed && !cardAction && !actionAttachments.length) || busy) return;
    const builderGoal = !cardAction ? skillBuilderGoal(text) : null;
    if (builderGoal) {
      router.push(`/skills?goal=${encodeURIComponent(builderGoal)}`);
      return;
    }
    const visibleText = trimmed || cardActionText(cardAction) || `Attached ${actionAttachments.map((item) => item.name).join(", ")}`;
    const previousInput = input;
    const previousAttachments = attachments;
    setMessages((current) => [...current, { role: "user", content: visibleText, attachments: actionAttachments, card_action: cardAction }]);
    setBusy(true);
    try {
      onBeforeSubmit?.();
      const run = await startChatRun(matterId, {
        message: trimmed,
        target,
        expected_question_revision: expectedQuestionRevision,
        context_selections: contextSelections,
        template_id: selectedTemplateId,
        source_action_key: `chat:${crypto.randomUUID()}`,
        matter_id: matterId,
        active_file: activeFile,
        agent_id: chatAgentId(intakeActive, activeAgentId),
        conversation_id: conversationId,
        history: messages.slice(-8).map(({ role, content }) => ({ role, content })),
        card_action: cardAction,
        attachments: actionAttachments,
        review_author: reviewAuthor,
        lawyer_author: lawyerAuthor,
      });
      onRunStarted?.(run);
      setPendingCardAction(cardAction ?? null);
      setActiveRun(run);
      setInput((current) => remainingComposerValue(current, previousInput, consumeInput, ""));
      setAttachments((current) => remainingComposerValue(current, previousAttachments, consumeAttachments, []));
      setWaiting(["queued", "running"].includes(run.state));
      rememberChatRun(window.localStorage, matterId, run);
      if (run.conversation_id) {
        const saved = await getConversation(matterId, run.conversation_id);
        const promotedValue = remainingComposerValue(
          composerValue.current,
          previousInput,
          consumeInput,
          "",
        );
        promoteNewComposer(saved.conversation_id, promotedValue);
        setConversationId(saved.conversation_id);
        setMessages((current) => mergeChatMessages(current, saved.messages));
        onConversationChange?.(saved.conversation_id);
      }
      if (!["queued", "running"].includes(run.state)) await finishRun(run);
    } catch (caught) {
      setBusy(false);
      setWaiting(false);
      setHistoryError("Themis.ai could not finish this request.");
    }
  }

  async function handleCardAction(action: CardAction, answerText?: string) {
    await submit(answerText ?? "", action, [], false, false);
  }

  async function addFiles(files: File[]) {
    if (!files.length || uploading) return;
    setUploading(true);
    setHistoryError("");
    try {
      const result = await uploadDocuments(matterId, files);
      const refs = attachmentsFromUploadResult(result);
      const outcomes = Array.isArray(result.results) ? result.results as Array<{ state?: string; failure_detail?: string }> : [];
      setComposerUploads(current => [...current.filter(item => !files.includes(item.file)), ...files.map((file, index) => ({ id: crypto.randomUUID(), file, state: outcomes[index]?.state ?? "saved", detail: outcomes[index]?.failure_detail }))]);
      try { await onFilesAttached?.(refs); }
      catch { setHistoryError("Files are saved, but their inquiry selection could not be saved. Add them from Files & context."); return; }
      setAttachments(current => [...current, ...refs.filter(ref => !current.some(item => item.path === ref.path))]);
      try { await onRefresh(); } catch { setHistoryError("Upload results are saved. The file list could not refresh."); }
    } catch (caught) {
      setComposerUploads(current => [...current.filter(item => !files.includes(item.file)), ...files.map(file => ({ id: crypto.randomUUID(), file, state: "failed", detail: caught instanceof Error ? caught.message : "Upload did not finish." }))]);
      setHistoryError(caught instanceof Error ? caught.message : "Could not upload the selected files.");
    } finally { setUploading(false); }
  }

  async function openConversation(nextId: string) {
    saveOutgoingComposer();
    if (!nextId)
      storeConversationComposer(window.localStorage, matterId, null, "");
    setActiveRun(null);
    setWaiting(false);
    setBusy(false);
    if (!nextId) {
      setConversationId(null);
      setMessages([]);
      setInput("");
      setAttachments([]);
      setHistoryError("");
      onConversationChange?.(null);
      return;
    }
    setLoadingHistory(true);
    setHistoryError("");
    try {
      const conversation = await getConversation(matterId, nextId);
      setConversationId(conversation.conversation_id);
      setMessages(conversation.messages);
      onConversationChange?.(conversation.conversation_id);
    } catch (caught) {
      setHistoryError(caught instanceof Error ? caught.message : "Could not load saved chat.");
    } finally {
      setLoadingHistory(false);
    }
  }

  async function retryRun() {
    if (!activeRun || !["failed", "interrupted"].includes(activeRun.state)) return;
    setBusy(true); setWaiting(true); setHistoryError("");
    try {
      reconciliationHint(contextKey, matterId, activeRun.conversation_id, null);
      const next = await retryChatRun(matterId, activeRun.run_id);
      terminalRuns.current.delete(next.run_id);
      setActiveRun(next);
      setWaiting(["queued", "running"].includes(next.state));
      rememberChatRun(window.localStorage, matterId, next);
      if (!["queued", "running"].includes(next.state)) await finishRun(next);
    } catch {
      setBusy(false); setWaiting(false); setHistoryError("Themis.ai could not finish this request.");
    }
  }

  async function saveAssistantAnswer(content: string, key: string) {
    setSavingAnswerKey(key);
    setSaveAnswerErrors((current) => ({ ...current, [key]: "" }));
    try {
      const saved = await saveWorkProductDraft(matterId, `${matterTitle} response`, content, `chat-save:${matterId}:${key}`);
      setSavedAnswerPaths((current) => ({ ...current, [key]: saved.vault_path }));
      setSavedAnswerNotices((current) => ({
        ...current,
        [key]: saved.changed_paths.length
          ? "Current draft saved."
          : "This current draft already exists. No new save was made.",
      }));
      try {
        await onRefresh();
      } catch {
        setSaveAnswerErrors((current) => ({
          ...current,
          [key]: "Draft saved, but the matter did not refresh. Open the saved draft or reload the page.",
        }));
      }
      onOpenDocument?.(saved.vault_path);
    } catch (caught) {
      setSaveAnswerErrors((current) => ({
        ...current,
        [key]: caught instanceof Error ? caught.message : "Could not save this answer as work product.",
      }));
    } finally {
      setSavingAnswerKey(null);
    }
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      void submit(input, undefined, attachments, true, true);
    }
  }

  const readingInitialRequest = Boolean(
    initialRunId
      && activeRun?.run_id === initialRunId
      && ["queued", "running"].includes(activeRun.state),
  );
  const latestOperationResults = new Map<string, ChatOperationResult>();
  for (const message of messages) {
    for (const result of message.operation_results ?? []) {
      latestOperationResults.set(result.source_action_key ?? result.action, result);
    }
  }
  const currentEligibleAssistantIndex = intakeActive
    ? -1
    : messages.reduce(
      (latest, message, index) => isEligibleWorkProductResponse(message) ? index : latest,
      -1,
    );
  const activeRunHasSavedWork = Boolean(
    activeRun?.response?.changed_paths.length
    || activeRun?.response?.operation_results.some((result) => result.status === "changed"),
  );
  const activeRunHasSavedIntakeAnswer = Boolean(activeRun?.operation_results?.some((result) => (
    ["record_intake_answer", "update_matter_intake"].includes(result.operation)
    && ["changed", "no_change"].includes(result.status)
  )));

  return (
    <div className="chat-panel">
      <div className="chat-history-status">Target: {target?.scenario_id ? "Saved scenario" : target?.artifact_path ? target.artifact_path.split("/").at(-1) : target?.issue_id ? "Selected issue" : matterTitle}{target?.issue_id || target?.artifact_path || target?.scenario_id ? <button className="btn tiny quiet" type="button" onClick={onClearTarget}>Clear target</button> : null}</div>
      <WorkspaceReceiptCards receipts={workspaceReceipts} onOpenDocument={onOpenDocument} />
      {historyError ? <p className="error chat-history-status">{historyError}</p> : null}
      {intakeRecoveryNotice ? <div className="chat-history-status" role="status">{intakeRecoveryNotice} <button className="btn tiny quiet" disabled={busy} onClick={retryIntakeQuestion} type="button">Retry intake question</button></div> : null}
      {loadingHistory ? <p className="chat-history-status">Loading saved chat…</p> : null}
      {activeRun && (shouldShowChatRunStatus(activeRun.state) || activeRun.finished_at) ? (
        <section className={`chat-card ${activeRun.state === "failed" || activeRun.state === "interrupted" ? "wash-failure" : activeRun.state === "completed" ? "wash-healthy" : "wash-agent"}`} role="status">
          <div className="chat-card-kicker">Themis.ai · {chatRunStateLabel(activeRun.state)}</div>
          {activeRun.state === "failed" || activeRun.state === "interrupted" ? (
            <>
              <div className="chat-card-summary">{activeRunHasSavedWork ? "Partial work was saved. Review it, then continue with the next matter action." : "Themis.ai could not finish this request."}</div>
              <div className="chat-card-detail">{chatFailureGuidance(activeRun.failure_class)}</div>
              {safeChatFailureDetail(activeRun.failure_detail) ? <div className="chat-card-detail">{safeChatFailureDetail(activeRun.failure_detail)}</div> : null}
              {activeRun.response?.reply ? <div className="chat-card-detail"><strong>Saved response</strong><ClaimMarkdown claims={workspaceClaims} documents={workspaceDocuments} onOpenDocument={onOpenReference} onOpenEvidence={onOpenEvidence} recordId={activeRun.run_id} surface="conversation" text={activeRun.response.reply} /></div> : null}
            </>
          ) : activeRun.state === "completed" ? <div className="chat-card-summary">{activeRun.status} Review the saved result below.</div>
            : <div className="chat-card-summary">{activeRunHasSavedIntakeAnswer ? "Answer saved · Preparing the next question" : readingInitialRequest ? "Themis.ai is reading your request…" : durableChatProgress(activeRun)}</div>}
          <div className="chat-card-actions">
            {["queued", "running"].includes(activeRun.state) ? <button className="btn tiny quiet" onClick={() => void cancelChatRun(matterId, activeRun.run_id).then(finishRun).catch(cause => setHistoryError(cause instanceof Error ? cause.message : "Could not stop this request."))} type="button">Stop and keep saved work</button> : null}
            {["failed", "interrupted"].includes(activeRun.state) ? <button className="btn tiny quiet" disabled={busy} onClick={() => void retryRun()}>Retry</button> : null}
            {waiting && ["queued", "running"].includes(activeRun.state) ? <button className="btn tiny quiet" onClick={() => setWaiting(false)} type="button">Continue in background</button> : null}
            {!waiting && ["queued", "running"].includes(activeRun.state) ? <button className="btn tiny quiet" onClick={() => setWaiting(true)} type="button">Show progress</button> : null}
          </div>
          {!waiting && ["queued", "running"].includes(activeRun.state) ? <div className="chat-card-detail">Progress is hidden on this page. Server work continues.</div> : null}
          {waiting && elapsedSeconds >= 15 && ["queued", "running"].includes(activeRun.state) ? <div className="chat-card-detail">Last durable step: {activeRunHasSavedIntakeAnswer ? "Answer saved · Preparing the next question." : durableChatProgress(activeRun)} You can leave this page. Server work continues.</div> : null}
        </section>
      ) : null}
      {messages.length ? (
        <div className="thread" ref={threadElement} onScroll={() => { const node = threadElement.current; if (node) followLatest.current = node.scrollHeight - node.scrollTop - node.clientHeight < 100; }}>
          {messages.map((message, index) => {
            const messageKey = message.message_id ?? String(index);
            const questionIds = message.cards?.flatMap((card) => card.type === "question" ? [card.question_id] : []) ?? [];
            const questionStates = historicalQuestionStates(
              messages,
              index,
              questionIds,
              intakeActive,
              intakeAnswers,
              Object.fromEntries((message.cards ?? []).filter((card) => card.type === "question").map((card) => [card.question_id, card.text])),
            );
            const currentOperationResults = message.operation_results?.filter(
              (result) => latestOperationResults.get(result.source_action_key ?? result.action) === result,
            );
            const questionCards = message.cards?.filter((card) => card.type === "question") ?? [];
            const compactIntakeTurn = message.role === "assistant" && shouldCompactIntakeTurn(
              questionCards,
              questionStates,
              message.content,
              Boolean(currentOperationResults?.some((result) => ![
                "record_intake_answer", "update_matter_intake",
              ].includes(result.operation))),
            );
            return message.role === "user" ? (
              <UserMessage
                appliedSkill={messages[index + 1]?.role === "assistant" ? messages[index + 1].applied_skills?.[0] : undefined}
                content={message.content}
                cardAction={message.card_action}
                key={messageKey}
              />
            ) : (
              <div className="assistant-message" key={messageKey}>
                {message.applied_skills?.map((skill) => <div className="applied-skill-label" key={skill.skill_id}>Applied skill: {skill.name}</div>)}
                <div className="agent-label">Themis.ai</div>
                {compactIntakeTurn ? (
                  <details className="intake-turn-history">
                    <summary>
                      <span className="intake-history-label">Earlier intake update</span>
                      {questionCards.map((card) => {
                        const state = questionStates[card.question_id];
                        const label = state.state === "answered" ? "Answered" : state.state === "stopped" ? "Stopped" : state.state === "superseded" ? "Superseded" : "Earlier question";
                        const savedValues = state.values.map((value) => (
                          card.choices.find((choice) => choice.value === value)?.label ?? value
                        ));
                        const answer = savedValues.length
                          ? ` — ${savedValues.join(" · ")}`
                          : state.state === "stopped" ? " — Intake stopped" : "";
                        return <span key={card.question_id}>{label} · {card.text}{answer}</span>;
                      })}
                      <span className="text-button">Expand</span>
                    </summary>
                    <div className="bubble-agent">
                      <div className="intake-history-context">This response shows what was known at that point. The latest turn shows the current status.</div>
                      <ClaimMarkdown claims={workspaceClaims} documents={workspaceDocuments} onOpenDocument={onOpenReference} onOpenEvidence={onOpenEvidence} recordId={message.message_id} surface="conversation" text={message.content} />
                      <ChatCards cards={message.cards} currentWorkProductDraftPath={currentWorkProductDraftPath} disabled matterId={matterId} onAction={handleCardAction} onOpenDocument={onOpenDocument} onRefresh={onRefresh} operationResults={currentOperationResults} questionStates={questionStates} questionsDisabled />
                    </div>
                  </details>
                ) : <div className="bubble-agent">
                  <ClaimMarkdown claims={workspaceClaims} documents={workspaceDocuments} onOpenDocument={onOpenReference} onOpenEvidence={onOpenEvidence} recordId={message.message_id} surface="conversation" text={message.content} />
                  <ChatCards cards={message.cards} currentWorkProductDraftPath={currentWorkProductDraftPath} disabled={busy} matterId={matterId} onAction={handleCardAction} onOpenDocument={onOpenDocument} onQuestionModeChange={changeQuestionMode} onRefresh={onRefresh} operationResults={currentOperationResults} questionMode={questionMode} questionStates={questionStates} showQuestionMode={intakeActive} />
                  {SHOW_AGENT_TRACES && message.trace?.length ? (
                    <details className="chat-actions">
                      <summary>Actions taken ({message.trace.length})</summary>
                      <div className="trace-list">
                        {message.trace.map((item, traceIndex) => (
                          <div className="trace-item" key={traceIndex}>
                            <span style={{ flex: "none", color: item.status === "success" ? "var(--healthy)" : "var(--failure)" }}>
                              {item.status === "success" ? "✓" : "!"}
                            </span>
                            <span style={{ flex: 1 }}><LinkifiedText text={item.summary} /></span>
                          </div>
                        ))}
                      </div>
                    </details>
                  ) : null}
                  {saveAnswerErrors[messageKey] ? <div className="error chat-card-detail" role="alert">{saveAnswerErrors[messageKey]}</div> : null}
                  {savedAnswerPaths[messageKey] ? (
                    <div className="mutation-status recorded">
                      {savedAnswerNotices[messageKey]} <button className="text-button" onClick={() => onOpenDocument?.(savedAnswerPaths[messageKey])} type="button">Open draft</button>
                    </div>
                  ) : index === currentEligibleAssistantIndex ? (
                    <button
                      className="btn primary compact"
                      disabled={busy || savingAnswerKey !== null}
                      onClick={() => void saveAssistantAnswer(message.content, messageKey)}
                      type="button"
                    >
                      {savingAnswerKey === messageKey ? "Saving…" : "Save current work product"}
                    </button>
                  ) : null}
                </div>}
              </div>
            );
          })}
          {busy && waiting ? (
            <div className="agent-label" role="status">
              <span className="agent-mark" style={{ width: 12, height: 12 }} />
              {readingInitialRequest ? "Themis.ai is reading your request…" : pendingCardAction ? chatProgressLabel(pendingCardAction) : durableChatProgress(activeRun ?? { state: "running", status: "Model is working." })} {elapsedSeconds}s
            </div>
          ) : null}
        </div>
      ) : null}

      <div className="composer"
        onDragOver={event => { if (Array.from(event.dataTransfer.types).includes("Files")) { event.preventDefault(); event.dataTransfer.dropEffect = "copy"; } }}
        onDrop={event => { if (event.dataTransfer.files.length) { event.preventDefault(); event.stopPropagation(); void addFiles(Array.from(event.dataTransfer.files)); } }}
      >
        {preparedRequest ? <div className="composer-note" role="status"><strong>Prepared request · Not sent.</strong><p>Your current message is unchanged.</p><p>{preparedRequest}</p><button className="btn quiet compact" type="button" onClick={appendPreparedRequest}>Append prepared request</button><button className="btn quiet compact" type="button" onClick={() => setPreparedRequest(null)}>Keep current message</button></div> : null}
        {seed?.text && input === seed.text ? (
          <div className="composer-note" role="status"><strong>Prepared request · Not sent.</strong> Review it, then select Send.</div>
        ) : null}
        {composerUploads.length ? <div className="composer-note" role="status">{composerUploads.map(item => <div key={item.id}>
          <strong>{item.file.name}</strong> · {item.state === "failed" ? "Not saved" : item.state === "partial" ? "Saved · Partial text" : "Saved"}
          {item.detail ? <span> · {item.detail}</span> : null}
          {item.state === "failed" ? <button className="btn tiny quiet" type="button" disabled={uploading} onClick={() => void addFiles([item.file])}>Retry {item.file.name}</button> : null}
        </div>)}</div> : null}
        <UploadIntentCard attachments={attachments} busy={busy} onClear={() => { const removing = attachments; setAttachments([]); void onFilesRemoved?.(removing).catch(() => setHistoryError("Files were removed from this message, but their saved context selection could not be cleared. Check Files & context.")); }} onSend={(intent) => submit(intent, undefined, attachments, false, true)} />
        <div className="composer-suggestions">
          {chatSuggestions(decisionOptions).map((suggestion) => (
            <button className="suggestion" disabled={busy} key={suggestion} onClick={() => void submit(suggestion)}>
              {suggestion}
            </button>
          ))}
        </div>
        <SkillCommandMenu input={input} skills={skills} onSelect={(skill) => { setInput(`/${skill.skill_id} `); requestAnimationFrame(() => inputRef.current?.focus()); }} />
        <div className="composer-field">
          <AttachmentPicker disabled={busy || uploading} onSelect={addFiles} />
          <textarea
            ref={inputRef}
            onChange={(event) => setInput(event.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={`Ask Themis.ai about ${matterTitle}…`}
            rows={1}
            value={input}
          />
          <button className="btn primary compact" disabled={busy || !input.trim()} onClick={() => void submit(input, undefined, attachments, true, true)}>
            {uploading ? "Uploading…" : "Send"}
          </button>
        </div>
        <div className="composer-note">
          Themis.ai can research, draft and move this matter. It records a decision only when you explicitly ask it to. <Link className="build-skill-link" href="/skills">Build a skill</Link>
        </div>
      </div>
    </div>
  );
}

function isEligibleWorkProductResponse(message: Message): boolean {
  const content = message.content.trim();
  const contentWithoutHeading = content.replace(/^#{1,6}[^\S\r\n]+/u, "").trim();
  if (message.role !== "assistant" || message.cards?.length) return false;
  if (message.operation_results?.some((result) => (
    result.operation === "finish_intake" || result.operation === "record_intake_answer"
  ))) return false;
  if (/^intake is complete\b/i.test(contentWithoutHeading) || /^(?:chat|research) (?:is |was )?(?:queued|running|complete|interrupted|stopped)\b/i.test(contentWithoutHeading)) return false;
  return content.length > 180 && (/\n\s*\n/.test(content) || /^#{1,3}\s|^\s*[-*]\s/m.test(content));
}

function UserMessage({ content, appliedSkill, cardAction }: { content: string; appliedSkill?: AppliedSkillSummary; cardAction?: CardAction | null }) {
  const answer = cardAction?.action === "answer" || cardAction?.action === "answer_set" ? (
    <div className="mutation-status recorded"><strong>Answered</strong> · {(cardAction.values ?? cardAction.answers?.flatMap((item) => item.values) ?? []).join(" · ")}</div>
  ) : null;
  if (!appliedSkill || !content.trimStart().startsWith(`/${appliedSkill.skill_id}`)) {
    return <div className="bubble-you"><LinkifiedText text={content} />{answer}</div>;
  }
  const request = content.trimStart().slice(appliedSkill.skill_id.length + 1).trim();
  return (
    <div className="bubble-you skill-invocation" data-skill-id={appliedSkill.skill_id} title={`Stored command: ${content}`}>
      <span className="human-skill-label">Used {appliedSkill.name} skill</span>
      {request ? <LinkifiedText text={request} /> : null}
    </div>
  );
}

function cardActionText(action?: CardAction): string {
  if (!action) return "";
  if (action.action === "save_draft") return "Save this Watch as a draft";
  if (action.action === "scan_now") return "Scan this Watch now without starting its schedule";
  if (action.action === "scan_again") return "Scan this Watch again";
  if (action.action === "change_something") return "Change something in this Watch";
  if (action.action === "start_watch") return "Start this Watch and activate its schedule";
  if (action.action === "skip") return "Skip";
  if (action.action === "stop") return "No more questions";
  if (action.action === "undo") return "Undo that matter update";
  if (action.action === "edit") return "Edit that matter update";
  return action.values?.join(", ") ?? action.action;
}

function attachmentsFromUploadResult(result: Record<string, unknown>): AttachmentReference[] {
  if (Array.isArray(result.attachments)) return result.attachments as AttachmentReference[];
  if (Array.isArray(result.files)) {
    return result.files.filter((item): item is AttachmentReference => Boolean(item && typeof item === "object" && "path" in item && "name" in item));
  }
  throw new Error("The upload completed without attachment references.");
}

frontend/components/workspace/Conversati:
"use client";

import type { ConversationDockProps, ConversationTarget, InteractionReceipt } from "@/lib/workspaceTypes";

function fileName(path: string): string {
  return path.split("/").filter(Boolean).at(-1) || "saved file";
}

function targetParts(target: ConversationTarget | null): Array<{ label: string; value?: string }> {
  if (!target) return [{ label: "Matter context" }];
  const parts: Array<{ label: string; value?: string }> = [{ label: "Matter context" }];
  if (target.business_question_id) parts.push({ label: "Business question" });
  if (target.issue_id) parts.push({ label: "Selected issue" });
  if (target.source_id) parts.push({ label: "Selected source" });
  if (target.scenario_id) parts.push({ label: "Saved scenario" });
  if (target.artifact_path) parts.push({ label: "Document", value: fileName(target.artifact_path) });
  if (target.selected_range?.text) parts.push({ label: "Selected passage", value: target.selected_range.text });
  if (target.local_draft_snapshot) parts.push({ label: "Local draft snapshot", value: "Not saved" });
  return parts;
}

function receiptLabel(receipt: InteractionReceipt): string {
  return receipt.operation.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function receiptState(receipt: InteractionReceipt): { label: string; className: string } {
  if (receipt.state === "applied") return { label: "Applied", className: "state-healthy" };
  if (receipt.state === "proposed") return { label: "Proposed", className: "state-agent" };
  return { label: "Not saved", className: "state-failure" };
}

function ReceiptRow({ receipt, onOpenArtifact }: { receipt: InteractionReceipt; onOpenArtifact: (path: string) => void }) {
  const state = receiptState(receipt);
  return <li className="conversation-receipt">
    <span className={`state-label ${state.className}`}>{state.label}</span>
    <span>{receiptLabel(receipt)}</span>
    {receipt.failure_detail ? <span className="conversation-receipt__detail">{receipt.failure_detail}</span> : null}
    {receipt.changed_links?.map((path) => <button className="btn tiny quiet" key={path} onClick={() => onOpenArtifact(path)} type="button">Open {fileName(path)}</button>)}
  </li>;
}

export default function ConversationDock({ matterId, target, onTargetChange, receipts, children, busy = false, onOpenArtifact }: ConversationDockProps) {
  const visibleReceipts = receipts.slice(-3).reverse();
  const parts = targetParts(target);
  return <section aria-label="Matter conversation" className="conversation-dock" data-matter-context={matterId}>
    <div className="conversation-dock__target" role="status">
      <span className="record-meta">Conversation scope</span>
      <div className="conversation-dock__target-parts">
        {parts.map((part) => <span className="conversation-target" key={`${part.label}:${part.value ?? ""}`}><strong>{part.label}</strong>{part.value ? <span title={part.value}>{part.value}</span> : null}</span>)}
      </div>
      {target ? <button className="btn tiny quiet" disabled={busy} onClick={() => onTargetChange(null)} type="button">Clear scope</button> : null}
    </div>
    {visibleReceipts.length ? <details className="conversation-dock__receipts"><summary>Recent saved actions</summary><ul>{visibleReceipts.map((receipt) => <ReceiptRow key={receipt.receipt_id} onOpenArtifact={onOpenArtifact} receipt={receipt} />)}</ul></details> : null}
    <div className="conversation-dock__panel">{children}</div>
    <style jsx>{`
      .conversation-dock { min-width: 0; border: 1px dashed var(--agent-edge); border-radius: var(--radius); background: var(--agent-wash); }
      .conversation-dock__target { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 11px 13px; border-bottom: 1px solid var(--agent-edge); }
      .conversation-dock__target-parts { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0; flex-wrap: wrap; }
      .conversation-target { display: inline-flex; max-width: 100%; gap: 4px; align-items: baseline; padding: 3px 7px; border-radius: 5px; background: var(--raised); color: var(--ink-3); font-size: 12px; }
      .conversation-target strong { color: var(--ink-2); font-weight: 600; }.conversation-target span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
      .conversation-dock__receipts { padding: 9px 13px; border-bottom: 1px solid var(--agent-edge); }.conversation-dock__receipts summary { cursor: pointer; color: var(--ink-3); font-size: 13px; }.conversation-dock__receipts ul { display: grid; gap: 8px; padding: 0; margin: 10px 0 0; list-style: none; }
      .conversation-receipt { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; color: var(--ink-3); font-size: 13px; }.conversation-receipt__detail { flex-basis: 100%; color: var(--failure); }
      .conversation-dock__panel { min-width: 0; }
      @media (max-width: 430px) { .conversation-dock__target { align-items: flex-start; }.conversation-dock__target > .btn { width: 100%; }.conversation-dock__panel { max-height: 46vh; overflow: auto; } }
      @media (prefers-reduced-motion: reduce) { .conversation-dock * { transition: none !important; animation: none !important; } }
    `}</style>
  </section>;
}

frontend/components/workspace/MatterFile:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties, DragEvent } from "react";
import ContextTray from "./ContextTray";
import type { ContextSelection, DocumentReferenceTarget, FileUploadBatch, FileUploadOutcome, MatterFileEntry, MatterFilesPanelProps } from "@/lib/workspaceTypes";
import { isSafeVaultPath } from "@/lib/research";

type UploadOutcome = Omit<FileUploadOutcome, "state"> & { state: FileUploadOutcome["state"] | "pending" | "completed" | "unknown"; input: File };
type UploadBatch = { id: string; destination: "library" | "inquiry"; outcomes: UploadOutcome[] };
type ReferenceAwareMatterFilesPanelProps = MatterFilesPanelProps & {
  onOpenReference?: (target: DocumentReferenceTarget) => void;
};
const panel: CSSProperties = { position: "fixed", inset: "0 0 0 auto", zIndex: 80, width: "min(520px, 100vw)", overflowY: "auto", background: "var(--raised)", borderLeft: "1px solid var(--line)", boxShadow: "var(--shadow-modal)", padding: 18, font: "400 15px/1.55 var(--sans)" };
const card: CSSProperties = { border: "1px solid var(--line)", borderRadius: "var(--radius)", background: "var(--paper)", padding: 12, minWidth: 0 };
const copy: CSSProperties = { font: "400 13.5px/1.5 var(--sans)", color: "var(--ink-3)", margin: "5px 0 0", overflowWrap: "anywhere" };

function extractionLabel(state: MatterFileEntry["extraction_state"]) {
  return ({ pending: "Preparing", complete: "Text ready", partial: "Partial text", failed: "Preview failed", unsupported: "Unsupported type", not_applicable: "Saved output" })[state];
}
function stateClass(state: MatterFileEntry["extraction_state"]) {
  if (state === "complete" || state === "not_applicable") return "state-healthy";
  if (state === "failed" || state === "unsupported") return "state-failure";
  return state === "partial" ? "state-attention" : "state-agent";
}
export function uploadState(outcomes: UploadOutcome[]) {
  if (outcomes.some((outcome) => outcome.state === "pending")) return { word: "Preparing", tone: "state-agent" };
  const failed = outcomes.filter((outcome) => outcome.state === "failed").length;
  const partial = outcomes.filter((outcome) => outcome.state === "partial").length;
  if (failed === outcomes.length) return { word: "Failed", tone: "state-failure" };
  if (failed || partial) return { word: "Partial", tone: "state-attention" };
  if (outcomes.every((outcome) => outcome.state === "saved")) return { word: "Saved", tone: "state-healthy" };
  return { word: "Completed", tone: "state-agent" };
}
export function normalizeUpload(result: FileUploadBatch | void, inputs: File[]): UploadOutcome[] {
  if (!result) return inputs.map((input, index) => ({ input, name: input.name, state: "completed", retry_key: `legacy-${index}`, failure_detail: "Per-file result not supplied by this upload path." }));
  return inputs.map((input, index) => {
    const outcome = result.outcomes[index];
    return outcome ? { ...outcome, input } : { input, name: input.name, state: "unknown", retry_key: `missing-${index}`, failure_detail: "No result was returned for this file." };
  });
}

export function matterFileReferenceTarget(file: MatterFileEntry, path: string): DocumentReferenceTarget {
  return {
    document_id: file.source_id?.trim() || file.reference_id,
    path,
    revision: file.revision ?? null,
    origin: { surface: "document", record_id: file.reference_id, focus_id: `matter-file-${file.reference_id}` },
  };
}

export default function MatterFilesPanel(props: ReferenceAwareMatterFilesPanelProps) {
  const { open, files, onClose, onUpload, onOpenArtifact, onOpenReference, onRetryFile, manifest, busy = false } = props;
  const [view, setView] = useState<"files" | "context">("files");
  const [query, setQuery] = useState("");
  const [selections, setSelections] = useState(props.selections);
  const [selectionSaving, setSelectionSaving] = useState(false);
  const [selectionDirty, setSelectionDirty] = useState(false);
  const [selectionError, setSelectionError] = useState("");
  const [batches, setBatches] = useState<UploadBatch[]>([]);
  const [retrying, setRetrying] = useState<string | null>(null);
  const [retryError, setRetryError] = useState<Record<string, string>>({});
  const [pickerDestination, setPickerDestination] = useState<"library" | "inquiry">("library");
  const input = useRef<HTMLInputElement>(null);
  const drawer = useRef<HTMLElement>(null);
  const returnFocus = useRef<HTMLElement | null>(null);
  const closeRef = useRef(onClose);
  useEffect(() => { closeRef.current = onClose; }, [onClose]);
  useEffect(() => { if (!selectionSaving && !selectionDirty) setSelections(props.selections); }, [props.selections, selectionSaving, selectionDirty]);
  useEffect(() => {
    if (!open) return;
    returnFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const node = drawer.current;
    const focusable = () => Array.from(node?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])') ?? []);
    focusable()[0]?.focus();
    const keydown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); closeRef.current(); return; }
      if (event.key !== "Tab") return;
      const items = focusable(); if (!items.length) return;
      const first = items[0]; const last = items.at(-1)!;
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("keydown", keydown); returnFocus.current?.focus(); };
  }, [open]);

  const filtered = useMemo(() => {
    const needle = query.trim().toLocaleLowerCase();
    return needle ? files.filter((file) => `${file.name} ${file.path}`.toLocaleLowerCase().includes(needle)) : files;
  }, [files, query]);
  if (!open) return null;

  async function saveSelections(next: ContextSelection[]) {
    setSelections(next); setSelectionDirty(true); setSelectionSaving(true); setSelectionError("");
    try { await props.onChange(next); setSelectionDirty(false); }
    catch (cause) { setSelectionError(cause instanceof Error ? cause.message : "Selection was not saved. Your choice is retained so you can retry."); throw cause; }
    finally { setSelectionSaving(false); }
  }
  async function toggleFile(file: MatterFileEntry) {
    const existing = selections.find((item) => item.reference_id === file.reference_id);
    const selected = existing ? existing.selected !== false : file.selected;
    const next = existing
      ? selections.map((item) => item.reference_id === file.reference_id ? { ...item, selected: !selected } : item)
      : [...selections, { reference_id: file.reference_id, path: file.path, role: file.kind === "work_product" ? "generated_output" : "source_file", selected: !selected, mandatory: false, revision: file.revision }];
    try { await saveSelections(next); } catch { /* local selection is intentionally retained */ }
  }
  async function upload(batchFiles: File[], destination: "library" | "inquiry") {
    if (!batchFiles.length) return;
    const id = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`;
    setBatches((current) => [...current, { id, destination, outcomes: batchFiles.map((input, index) => ({ input, name: input.name, state: "pending", retry_key: `pending-${index}` })) }]);
    try {
      const result = await onUpload(batchFiles, destination);
      setBatches((current) => current.map((batch) => batch.id === id ? { ...batch, outcomes: normalizeUpload(result, batchFiles) } : batch));
    } catch (cause) {
      const detail = cause instanceof Error ? cause.message : "Upload failed. The batch is retained for retry.";
      setBatches((current) => current.map((batch) => batch.id === id ? { ...batch, outcomes: batch.outcomes.map((outcome) => ({ ...outcome, state: "failed", failure_detail: detail })) } : batch));
    }
  }
  async function retryUpload(batchId: string, retryKey: string) {
    const batch = batches.find((item) => item.id === batchId);
    const outcome = batch?.outcomes.find((item) => item.retry_key === retryKey);
    if (!batch || !outcome) return;
    setBatches((current) => current.map((item) => item.id === batchId ? { ...item, outcomes: item.outcomes.map((candidate) => candidate.retry_key === retryKey ? { ...candidate, state: "pending", failure_detail: null } : candidate) } : item));
    try {
      const result = await onUpload([outcome.input], batch.destination);
      const next = normalizeUpload(result, [outcome.input])[0];
      setBatches((current) => current.map((item) => item.id === batchId ? { ...item, outcomes: item.outcomes.map((candidate) => candidate.retry_key === retryKey ? next : candidate) } : item));
    } catch (cause) {
      const detail = cause instanceof Error ? cause.message : "Upload failed. The batch is retained for retry.";
      setBatches((current) => current.map((item) => item.id === batchId ? { ...item, outcomes: item.outcomes.map((candidate) => candidate.retry_key === retryKey ? { ...candidate, state: "failed", failure_detail: detail } : candidate) } : item));
    }
  }
  function chooseFiles(destination: "library" | "inquiry") { setPickerDestination(destination); input.current?.click(); }
  function drop(event: DragEvent<HTMLElement>) { event.preventDefault(); void upload(Array.from(event.dataTransfer.files ?? []), view === "context" ? "inquiry" : "library"); }
  async function retry(file: MatterFileEntry) {
    setRetrying(file.reference_id); setRetryError((current) => ({ ...current, [file.reference_id]: "" }));
    try { await onRetryFile(file.reference_id); }
    catch (cause) { setRetryError((current) => ({ ...current, [file.reference_id]: cause instanceof Error ? cause.message : "Retry failed. The saved file remains available." })); }
    finally { setRetrying(null); }
  }
  function openSource(file: MatterFileEntry, path: string) {
    if (onOpenReference) onOpenReference(matterFileReferenceTarget(file, path));
    else onOpenArtifact(path);
  }

  return <>
    <button aria-label="Close files and context" onClick={onClose} style={{ position: "fixed", inset: 0, zIndex: 79, border: 0, background: "var(--ink)", opacity: 0.24 }} type="button" />
    <aside aria-label="Files and context" aria-modal="true" onDragOver={(event) => event.preventDefault()} onDrop={drop} ref={drawer} role="dialog" style={panel}>
      <header style={{ display: "flex", alignItems: "start", justifyContent: "space-between", gap: 12 }}><div><span className="record-meta">Matter workspace</span><h2 style={{ font: "600 21px/1.3 var(--serif)", margin: "3px 0 0" }}>Files &amp; context</h2></div><button aria-label="Close files and context panel" className="btn quiet tiny" onClick={onClose} type="button">Close</button></header>
      <div aria-label="Files and context views" className="btn-row" role="tablist" style={{ marginTop: 15 }}><button aria-selected={view === "files"} className={`btn tiny ${view === "files" ? "" : "quiet"}`} onClick={() => setView("files")} role="tab" type="button">Matter files</button><button aria-selected={view === "context"} className={`btn tiny ${view === "context" ? "" : "quiet"}`} onClick={() => setView("context")} role="tab" type="button">Inquiry context</button></div>
      <input hidden multiple onChange={(event) => { void upload(Array.from(event.target.files ?? []), pickerDestination); event.target.value = ""; }} ref={input} type="file" />

      <div className="btn-row" style={{ marginTop: 12 }}><button className="btn quiet tiny" disabled={busy} onClick={() => chooseFiles("library")} type="button">Add files to library</button><button className="btn agent tiny" disabled={busy} onClick={() => chooseFiles("inquiry")} type="button">Add files to inquiry</button></div>
      <p style={copy}>You can add several files now and add another batch while earlier files are preparing. Dropped files go to the current view.</p>
      {batches.length ? <section aria-label="Recent uploads" style={{ display: "grid", gap: 7, marginTop: 12 }}>{batches.map((batch) => {
        const summary = uploadState(batch.outcomes);
        return <div key={batch.id} style={card}><span className={`state-label ${summary.tone}`}>{summary.word}</span><strong style={{ marginLeft: 7 }}>{batch.destination === "inquiry" ? "Inquiry upload" : "Library upload"}</strong><div style={{ display: "grid", gap: 7, marginTop: 9 }}>{batch.outcomes.map((outcome, index) => <div key={`${outcome.retry_key}:${index}`} style={{ borderTop: "1px solid var(--line-faint)", paddingTop: 7 }}><div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 8 }}><span style={{ overflowWrap: "anywhere" }}>{outcome.name}</span><span className={`state-label ${outcome.state === "saved" ? "state-healthy" : outcome.state === "failed" ? "state-failure" : outcome.state === "partial" || outcome.state === "unknown" ? "state-attention" : "state-agent"}`}>{outcome.state === "saved" ? "Saved" : outcome.state === "partial" ? "Saved · Partial text" : outcome.state === "failed" ? "Not saved" : outcome.state === "pending" ? "Preparing" : outcome.state === "unknown" ? "Status unavailable" : "Completed"}</span></div>{outcome.failure_detail ? <p style={copy}>{outcome.failure_detail}</p> : null}{outcome.state === "failed" ? <button className="btn quiet tiny" onClick={() => void retryUpload(batch.id, outcome.retry_key)} type="button">Retry {outcome.name}</button> : null}</div>)}</div></div>;
      })}</section> : null}

      {view === "files" ? <section aria-label="Matter files" style={{ display: "grid", gap: 10, marginTop: 16 }}>
        <label className="field-block"><span className="field-label">Find by name or folder</span><input className="text-input" onChange={(event) => setQuery(event.target.value)} placeholder="Search matter files" type="search" value={query} /></label>
        {props.folderView ? <details><summary className="btn quiet tiny">Folder view</summary><div style={{ marginTop: 8 }}>{props.folderView}</div></details> : null}
        {selectionError ? <div className="warning-callout" role="status"><strong>Selection not saved.</strong> {selectionError} <button className="btn quiet tiny" disabled={selectionSaving} onClick={() => void saveSelections(selections).catch(() => undefined)} type="button">Retry</button></div> : null}
        {filtered.length ? filtered.map((file) => {
          const selected = selections.find((item) => item.reference_id === file.reference_id)?.selected ?? file.selected;
          const original = file.original_path && isSafeVaultPath(file.original_path) ? file.original_path : null;
          const extracted = file.extracted_path && isSafeVaultPath(file.extracted_path) ? file.extracted_path : null;
          const artifact = file.kind === "work_product" && isSafeVaultPath(file.path) ? file.path : null;
          return <article id={`matter-file-${file.reference_id}`} key={`${file.reference_id}:${file.path}`} style={card}><div style={{ display: "flex", alignItems: "start", justifyContent: "space-between", gap: 8 }}><div style={{ minWidth: 0 }}><strong style={{ overflowWrap: "anywhere" }}>{file.name}</strong><p style={copy}>{file.kind === "work_product" ? "Generated output" : file.kind === "source" ? "Supplied source" : "Matter file"} · {file.path}</p></div><span className={`state-label ${stateClass(file.extraction_state)}`}>{extractionLabel(file.extraction_state)}</span></div>
            <p style={copy}>Saved: {file.saved_at || "Unknown"}{file.source_id ? ` · Source ID: ${file.source_id}` : " · Source ID: Unknown"}</p>
            {file.failure_detail ? <p className="warning-callout" role="status">{file.failure_detail}</p> : null}
            <div className="btn-row"><button className={`btn tiny ${selected ? "" : "quiet"}`} disabled={busy || selectionSaving} onClick={() => void toggleFile(file)} type="button">{selected ? selectionDirty ? "Selected · Not saved" : "Selected for next inquiry" : selectionDirty ? "Available · Not saved" : "Add to next inquiry"}</button>{original ? <button className="btn quiet tiny" onClick={() => openSource(file, original)} type="button">Open original</button> : null}{extracted ? <button className="btn quiet tiny" onClick={() => openSource(file, extracted)} type="button">Open extracted text</button> : null}{artifact ? <button className="btn quiet tiny" onClick={() => onOpenArtifact(artifact)} type="button">Open generated output</button> : null}{["failed", "partial"].includes(file.extraction_state) ? <button className="btn quiet tiny" disabled={retrying === file.reference_id} onClick={() => void retry(file)} type="button">{retrying === file.reference_id ? "Retrying…" : "Retry preview"}</button> : null}</div>
            {retryError[file.reference_id] ? <p className="warning-callout" role="status">{retryError[file.reference_id]}</p> : null}
            {!original && file.original_path ? <p className="warning-callout" role="status">Unsafe original path blocked.</p> : null}
          </article>;
        }) : <p style={copy}>No files match this search.</p>}
      </section> : <div style={{ marginTop: 16 }}><ContextTray busy={busy || selectionSaving} manifest={manifest} onChange={saveSelections} selections={selections} /></div>}
    </aside>
  </>;
}

frontend/components/workspace/ContextTra:
"use client";

import { useEffect, useState } from "react";
import type { CSSProperties } from "react";
import type { ContextSelection, ContextTrayProps } from "@/lib/workspaceTypes";

const card: CSSProperties = { border: "1px solid var(--line)", borderRadius: "var(--radius)", background: "var(--paper)", padding: 12, minWidth: 0 };
const copy: CSSProperties = { font: "400 13.5px/1.5 var(--sans)", color: "var(--ink-3)", margin: "5px 0 0", overflowWrap: "anywhere" };

function title(item: Pick<ContextSelection, "reference_id" | "role">) {
  const known: Record<string, string> = {
    business_question: "Business question", current_facts: "Current facts", company: "Company context",
    company_context: "Company context", selected_passage: "Selected passage", applied_note: "Applied note",
    conversation_history: "Relevant conversation history", contribution: "Lawyer contribution", matter_record: "Matter record",
    tool_read: "Material read by a tool",
  };
  return known[item.role] ?? known[item.reference_id] ?? item.role.replace(/[_-]+/g, " ").replace(/^./, (letter) => letter.toUpperCase());
}

function manifestState(state: string) {
  return ({ included: "Included in this run", truncated: "Included in part", omitted: "Omitted from this run", unavailable: "Unavailable for this run" } as Record<string, string>)[state] ?? "State unknown";
}

export default function ContextTray({ selections, manifest, onChange, busy = false }: ContextTrayProps) {
  const [draft, setDraft] = useState(selections);
  const [saving, setSaving] = useState<string | null>(null);
  const [error, setError] = useState("");
  const [dirty, setDirty] = useState(false);
  useEffect(() => { if (!saving && !dirty) setDraft(selections); }, [selections, saving, dirty]);

  async function toggle(referenceId: string) {
    const next = draft.map((item) => item.reference_id === referenceId ? { ...item, selected: item.selected === false } : item);
    setDraft(next); setDirty(true); setSaving(referenceId); setError("");
    try { await onChange(next); setDirty(false); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Context selection was not saved. Your choices are retained so you can retry."); }
    finally { setSaving(null); }
  }
  async function retry() {
    setSaving("retry"); setError("");
    try { await onChange(draft); setDirty(false); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Context selection was not saved. Your choices are retained so you can retry."); }
    finally { setSaving(null); }
  }

  return <section aria-label="Inquiry context" style={{ display: "grid", gap: 14 }}>
    <div><h2 className="section-heading" style={{ margin: 0 }}>Next inquiry</h2><p style={copy}>These choices apply to the next inquiry. Removing a choice does not delete the saved file or change an earlier run.</p></div>
    {error ? <div className="warning-callout" role="status"><strong>Not saved.</strong> {error} <button className="btn quiet tiny" disabled={Boolean(saving)} onClick={() => void retry()} type="button">Retry</button></div> : null}
    <div style={{ display: "grid", gap: 8 }}>
      {draft.length ? draft.map((item) => <label key={item.reference_id} style={{ ...card, display: "grid", gridTemplateColumns: "auto minmax(0, 1fr)", gap: 10, cursor: item.mandatory ? "default" : "pointer" }}>
        <input checked={item.mandatory || item.selected !== false} disabled={busy || Boolean(saving) || item.mandatory} onChange={() => void toggle(item.reference_id)} type="checkbox" />
        <span><strong>{title(item)}</strong><span className="record-meta" style={{ marginLeft: 7 }}>{item.mandatory ? "Mandatory" : item.selected !== false ? dirty ? "Selected · Not saved" : "Selected" : dirty ? "Available · Not saved" : "Available"}</span>{item.path ? <span style={copy}>{item.path}</span> : null}<span style={copy}>{item.mandatory ? "This matter record is always supplied because the inquiry cannot be understood without it." : item.selected !== false ? "Chosen for the next inquiry." : "Saved and available. It will not be supplied directly to the next inquiry."}</span>{saving === item.reference_id ? <span className="state-label state-agent" role="status">Saving selection…</span> : null}</span>
      </label>) : <p style={copy}>No optional context is available. The current question and saved matter facts still travel with the inquiry.</p>}
    </div>

    <div><h2 className="section-heading" style={{ margin: 0 }}>{manifest ? "Submitted context" : "No submitted inquiry selected"}</h2><p style={copy}>{manifest ? "This is the saved context record for the selected inquiry. Later selection changes do not alter it." : "After an inquiry starts, its actual included, partial, omitted, unavailable, and later-read material appears here."}</p></div>
    {manifest ? <div style={{ display: "grid", gap: 8 }}>{(manifest.entries ?? []).length ? (manifest.entries ?? []).map((item, index) => <article key={`${item.reference_id}:${index}`} style={card}>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 8 }}><strong>{title(item)}</strong><span className={`state-label ${item.state === "included" ? "state-healthy" : item.state === "truncated" ? "state-attention" : item.state === "unavailable" ? "state-failure" : "state-agent"}`}>{manifestState(item.state)}</span></div>
      {item.path ? <p style={copy}>{item.path}</p> : null}<p style={copy}>{item.reason || "No reason was stored."}</p>
      {item.tool_read_evidence?.length ? <details style={{ marginTop: 7 }}><summary className="faint">Technical read record</summary><p style={copy}>{item.tool_read_evidence.join(", ")}</p></details> : item.role === "tool_read" ? <p className="warning-callout" style={{ marginBottom: 0 }}>No saved proof of this later read is available.</p> : null}
    </article>) : <p style={copy}>This run stored an empty context manifest.</p>}</div> : null}
  </section>;
}

