"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { DraftResult, OutputTemplate, OutputTemplateLibraryProps } from "@/lib/workspaceTypes";

const titleCase = (value: string) => value.replaceAll("_", " ").replaceAll("-", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const isUnavailable = (template: OutputTemplate) => template.enabled === false || ["failed", "malformed", "unavailable"].includes(template.status ?? "");
const runningPreviewStates = new Set(["queued", "running", "pending", "started"]);
function previewState(result: DraftResult) {
  if (result.artifact) return { label: "Editable preview", className: "state-agent", detail: "This preview is editable work product. It is not approval and does not record a decision." };
  const state = result.state.trim().toLowerCase();
  if (runningPreviewStates.has(state)) return { label: "Preparing", className: "state-agent", detail: `No preview artifact is ready. Current state: ${result.state}.` };
  const label = state === "not_saved" ? "Not saved" : state === "cancelled" || state === "canceled" ? "Cancelled" : state === "failed" ? "Failed" : "No artifact";
  return { label, className: "state-failure", detail: result.receipt?.failure_detail || `No editable preview was created. Current state: ${result.state}.` };
}

export default function OutputTemplateLibrary({ templates, selectedTemplateId, busy = false, onSelect, onCreate, onEdit, onDuplicate, onSetDefault, onPreview, onOpenArtifact }: OutputTemplateLibraryProps) {
  const selected = templates.find((template) => template.template_id === selectedTemplateId) ?? null;
  const outputTypes = useMemo(() => Array.from(new Set(templates.map((template) => template.output_type || "unavailable"))).sort(), [templates]);
  const [pending, setPending] = useState<"copy" | "default" | "preview" | "">("");
  const [overrides, setOverrides] = useState<Record<string, string>>({});
  const [preview, setPreview] = useState<DraftResult | null>(null);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [noticeFailed, setNoticeFailed] = useState(false);
  const selectedIdentity = selected ? `${selected.template_id}:${selected.revision}` : "";
  const latestSelection = useRef(selectedIdentity);
  const selectionGeneration = useRef(0);
  if (latestSelection.current !== selectedIdentity) { latestSelection.current = selectedIdentity; selectionGeneration.current += 1; }
  useEffect(() => { setPending(""); setPreview(null); setError(""); setNotice(""); setNoticeFailed(false); setOverrides({}); }, [selectedIdentity]);

  function choose(template: OutputTemplate) { onSelect(template); setPreview(null); setError(""); setNotice(""); setNoticeFailed(false); setOverrides({}); }
  async function act(action: "copy" | "default" | "preview") {
    if (!selected) return;
    const actionIdentity = `${selected.template_id}:${selected.revision}`;
    const actionGeneration = selectionGeneration.current;
    const stillSelected = () => latestSelection.current === actionIdentity && selectionGeneration.current === actionGeneration;
    setPending(action); setError(""); setNotice(""); setNoticeFailed(false);
    try {
      if (action === "copy") { const copy = await onDuplicate(selected); if (!stillSelected()) return; setNotice(`${copy.name} was created. Open it to rename or edit it.`); }
      if (action === "default") { await onSetDefault(selected); if (!stillSelected()) return; setNotice(`${selected.name} is now the default for ${titleCase(selected.output_type)}.`); }
      if (action === "preview") {
        const result = await onPreview(selected, overrides); if (!stillSelected()) return; setPreview(result);
        const state = previewState(result);
        setNoticeFailed(state.className === "state-failure");
        setNotice(result.artifact ? "Editable preview created from the current matter." : state.detail);
      }
    } catch (caught) { if (stillSelected()) setError(caught instanceof Error ? caught.message : `The ${action} action failed. Your selection and preview instructions are retained.`); }
    finally { if (stillSelected()) setPending(""); }
  }

  return <section aria-labelledby="template-library-title" className="template-library">
    <header className="template-library__head"><div><h2 id="template-library-title">Output templates</h2><p>Templates set reusable structure and guidance. Instructions below apply to one preview only.</p></div><button className="btn primary" disabled={busy} onClick={onCreate} type="button">Create blank template</button></header>
    {selectedTemplateId && !selected ? <div className="template-warning" role="alert"><span className="state-label state-failure">Unavailable</span><span>The selected template <span className="mono">{selectedTemplateId}</span> is missing. Choose another template.</span></div> : null}
    {templates.length === 0 ? <div className="empty-state">No output templates are available. Create one, or restore the starter templates.</div> : <div className="template-layout">
      <nav aria-label="Output template list" className="template-list">{outputTypes.map((outputType) => {
        const matching = templates.filter((template) => (template.output_type || "unavailable") === outputType);
        const defaultTemplate = matching.find((template) => template.is_default);
        return <section className="template-group" key={outputType}><div className="template-group__title"><h3>{titleCase(outputType)}</h3><span>{defaultTemplate ? `Default: ${defaultTemplate.name}` : "No selected default"}</span></div>{matching.map((template) => <button aria-pressed={template.template_id === selectedTemplateId} className={`template-row ${template.template_id === selectedTemplateId ? "selected" : ""}`} disabled={busy || !!pending} key={template.template_id} onClick={() => choose(template)} type="button"><span><strong>{template.name}</strong><small>{template.template_id} · version {template.revision || "unavailable"}</small></span><span className={`state-label ${isUnavailable(template) ? "state-failure" : template.is_default ? "state-healthy" : "state-agent"}`}>{isUnavailable(template) ? titleCase(template.status || "disabled") : template.is_default ? "Default" : "Available"}</span></button>)}</section>;
      })}</nav>
      <div className="template-detail">{selected ? <>
        <div className="template-detail__head"><div><div className="record-meta">{selected.output_type || "Output type unavailable"}</div><h3>{selected.name}</h3><p><span className="mono">{selected.template_id}</span> · version <span className="mono">{selected.revision || "unavailable"}</span></p></div><span className={`state-label ${isUnavailable(selected) ? "state-failure" : "state-healthy"}`}>{isUnavailable(selected) ? titleCase(selected.status || "unavailable") : "Available"}</span></div>
        {isUnavailable(selected) ? <p className="template-failure" role="alert">{selected.failure_detail || "This template is disabled or unavailable. Edit it before use."}</p> : null}
        <p className="reading template-summary">{selected.purpose || selected.instructions || "No purpose or instructions are saved."}</p>
        <details><summary>Current version and history</summary><p>Active file: <span className="mono">{selected.path}</span></p><p>Content hash: <span className="mono">{selected.content_hash || "unavailable"}</span></p><p>Immutable revision: <span className="mono">{selected.revision_path || "Created when this version is used or saved"}</span></p></details>
        <div className="btn-row template-actions"><button className="btn" disabled={busy} onClick={() => onEdit(selected)} type="button">Edit or rename</button><button className="btn" disabled={busy || !!pending || isUnavailable(selected)} onClick={() => void act("copy")} type="button">{pending === "copy" ? "Copying…" : "Make a copy"}</button><button className="btn" disabled={busy || !!pending || isUnavailable(selected) || selected.is_default} onClick={() => void act("default")} type="button">{pending === "default" ? "Saving default…" : selected.is_default ? "Current default" : "Set as default"}</button></div>
        <fieldset className="preview-overrides"><legend>Only for this preview</legend><p>These values do not change the reusable template.</p><div className="preview-grid">{(["audience", "purpose", "tone", "length"] as const).map((field) => <label key={field}><span>{titleCase(field)}</span><input className="text-input" onChange={(event) => setOverrides((current) => ({ ...current, [field]: event.target.value }))} value={overrides[field] ?? ""} /></label>)}</div><label><span>Extra instruction for this preview</span><textarea className="text-input prose" onChange={(event) => setOverrides((current) => ({ ...current, instruction: event.target.value }))} rows={3} value={overrides.instruction ?? ""} /></label><button className="btn agent" disabled={busy || !!pending || isUnavailable(selected)} onClick={() => void act("preview")} type="button">{pending === "preview" ? "Generating preview…" : "Preview with this matter"}</button></fieldset>
        {error ? <p className="error" role="alert">{error}</p> : null}{notice ? <p className={noticeFailed ? "template-action-failure" : "template-notice"} role="status">{notice}</p> : null}
        {preview ? (() => { const state = previewState(preview); return <div className="preview-result"><div><span className={`state-label ${state.className}`}>{state.label}</span><strong>{preview.artifact?.title || "Preview request"}</strong></div><p>Status: {preview.state}</p>{preview.artifact ? <><p>Version {preview.artifact.revision}</p>{onOpenArtifact ? <button className="btn quiet" onClick={() => onOpenArtifact(preview.artifact!.path)} type="button">Open editable preview</button> : null}</> : null}<p>{state.detail}</p></div>; })() : null}
      </> : <div className="empty-state">Select a template to inspect, copy, edit, set as a default, or preview.</div>}</div>
    </div>}
    <style jsx>{`
      .template-library { min-width: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised); padding: 18px; }
      .template-library__head { display: flex; align-items: start; justify-content: space-between; gap: 14px; }
      .template-library__head p, .template-detail__head p { margin: 7px 0 0; color: var(--ink-3); font-size: 13.5px; }
      .template-warning, .template-notice, .template-action-failure { display: flex; align-items: center; gap: 9px; margin: 14px 0 0; padding: 10px 12px; border: 1px solid var(--failure-edge); border-radius: 8px; background: var(--failure-wash); }
      .template-notice { border-color: var(--agent-edge); background: var(--agent-wash); }
      .template-action-failure { color: var(--failure); }
      .template-layout { display: grid; grid-template-columns: minmax(240px, 0.8fr) minmax(0, 1.5fr); gap: 18px; margin-top: 18px; }
      .template-list { min-width: 0; border-right: 1px solid var(--line-soft); padding-right: 18px; }
      .template-group + .template-group { margin-top: 18px; }
      .template-group__title { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; margin-bottom: 6px; }
      .template-group__title h3 { font-size: 15px; }
      .template-group__title span { color: var(--ink-4); font-size: 11px; text-align: right; }
      .template-row { width: 100%; display: flex; justify-content: space-between; align-items: center; gap: 10px; border: 1px solid transparent; border-radius: 7px; background: transparent; padding: 9px; text-align: left; cursor: pointer; }
      .template-row:hover:not(:disabled) { background: var(--hover); } .template-row.selected { border-color: var(--agent-edge); background: var(--agent-wash); } .template-row:disabled { cursor: wait; }
      .template-row > span:first-child { min-width: 0; display: grid; gap: 4px; }
      .template-row small { color: var(--ink-4); overflow-wrap: anywhere; }
      .template-detail { min-width: 0; }
      .template-detail__head { display: flex; justify-content: space-between; gap: 12px; align-items: start; }
      .template-summary { margin: 16px 0; font-size: 15px; white-space: pre-wrap; }
      .template-failure { margin: 12px 0 0; padding: 9px 11px; border: 1px solid var(--failure-edge); border-radius: 7px; background: var(--failure-wash); color: var(--failure); }
      details { border-top: 1px solid var(--line-soft); border-bottom: 1px solid var(--line-soft); padding: 10px 0; }
      details summary { cursor: pointer; font-weight: 600; } details p { margin: 8px 0 0; color: var(--ink-3); font-size: 12px; overflow-wrap: anywhere; }
      .template-actions { margin-top: 14px; }
      .preview-overrides { display: grid; gap: 12px; margin: 18px 0 0; padding: 14px; border: 1px solid var(--agent-edge); border-radius: 8px; background: var(--agent-wash); }
      .preview-overrides legend { padding: 0 5px; font: 600 16px var(--serif); } .preview-overrides p { margin: 0; color: var(--ink-3); font-size: 13.5px; }
      .preview-overrides label { display: grid; gap: 5px; color: var(--ink-3); font-size: 13px; }
      .preview-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
      .preview-result { margin-top: 14px; padding: 12px; border-left: 3px solid var(--agent); background: var(--agent-wash); }
      .preview-result > div { display: flex; align-items: center; gap: 8px; } .preview-result p { margin: 7px 0 0; overflow-wrap: anywhere; } .preview-result .btn { margin-top: 10px; }
      @media (max-width: 760px) { .template-layout { grid-template-columns: 1fr; } .template-list { border-right: 0; border-bottom: 1px solid var(--line-soft); padding: 0 0 16px; } }
      @media (max-width: 430px) { .template-library { padding: 14px; } .template-library__head { flex-direction: column; } .template-library__head .btn, .template-actions .btn { width: 100%; } .preview-grid { grid-template-columns: 1fr; } }
      @media (prefers-reduced-motion: reduce) { .template-library * { transition: none !important; animation: none !important; } }
    `}</style>
  </section>;
}

"use client";

import { useEffect, useRef, useState } from "react";
import MarkdownRichEditor from "@/components/MarkdownRichEditor";
import type { DraftResult, OutputTemplateEditable, OutputTemplateEditorProps } from "@/lib/workspaceTypes";

function editable(template: OutputTemplateEditorProps["template"]): OutputTemplateEditable {
  return { name: template.name, output_type: template.output_type, instructions: template.instructions ?? "", section_outline: template.section_outline ?? "", audience: template.audience ?? "", purpose: template.purpose ?? "", tone: template.tone ?? "", length: template.length ?? "", exclusions: template.exclusions ?? "", source_presentation: template.source_presentation ?? "", sample_wording: template.sample_wording ?? "", enabled: template.enabled !== false };
}

const runningPreviewStates = new Set(["queued", "running", "pending", "started"]);
function previewState(result: DraftResult) {
  if (result.artifact) return { label: "Editable preview", className: "state-agent", detail: "This preview is editable work product. It is not approval and does not record a decision." };
  const state = result.state.trim().toLowerCase();
  if (runningPreviewStates.has(state)) return { label: "Preparing", className: "state-agent", detail: `No preview artifact is ready. Current state: ${result.state}.` };
  const label = state === "not_saved" ? "Not saved" : state === "cancelled" || state === "canceled" ? "Cancelled" : state === "failed" ? "Failed" : "No artifact";
  return { label, className: "state-failure", detail: result.receipt?.failure_detail || `No editable preview was created. Current state: ${result.state}.` };
}

export default function OutputTemplateEditor({ template, busy = false, onSave, onCancel, onPreview, onOpenArtifact }: OutputTemplateEditorProps) {
  const [draft, setDraft] = useState<OutputTemplateEditable>(() => editable(template));
  const [baseRevision, setBaseRevision] = useState(template.revision);
  const [dirty, setDirty] = useState(false);
  const [staleRevision, setStaleRevision] = useState<string | null>(null);
  const [pending, setPending] = useState<"save" | "preview" | "">("");
  const [overrides, setOverrides] = useState<Record<string, string>>({});
  const [preview, setPreview] = useState<DraftResult | null>(null);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [noticeFailed, setNoticeFailed] = useState(false);
  const templateId = useRef(template.template_id);
  const sourceRevision = useRef(template.revision);
  const draftRef = useRef(draft);
  const [savedTemplate, setSavedTemplate] = useState(template);
  const renderedTemplateId = useRef(template.template_id);
  const editorGeneration = useRef(0);
  if (renderedTemplateId.current !== template.template_id) { renderedTemplateId.current = template.template_id; editorGeneration.current += 1; }

  useEffect(() => {
    if (template.template_id !== templateId.current) {
      templateId.current = template.template_id; sourceRevision.current = template.revision; setSavedTemplate(template); setDraft(editable(template)); draftRef.current = editable(template); setBaseRevision(template.revision); setDirty(false); setStaleRevision(null); setPending(""); setPreview(null); setOverrides({}); setError(""); setNotice(""); setNoticeFailed(false);
      return;
    }
    if (template.revision === baseRevision) { sourceRevision.current = template.revision; setSavedTemplate(template); return; }
    if (template.revision === sourceRevision.current) return;
    sourceRevision.current = template.revision;
    if (dirty) setStaleRevision(template.revision);
    else { const next = editable(template); setSavedTemplate(template); setDraft(next); draftRef.current = next; setBaseRevision(template.revision); setStaleRevision(null); }
  }, [baseRevision, dirty, template]);

  function patch(change: Partial<OutputTemplateEditable>) { setDraft((current) => { const next = { ...current, ...change }; draftRef.current = next; return next; }); setDirty(true); setNotice(""); setNoticeFailed(false); }
  async function save() {
    if (!draft.name.trim() || !draft.output_type.trim()) { setError("Add a template name and output type before saving."); return; }
    const submitted = draft;
    const actionTemplateId = template.template_id;
    const actionGeneration = editorGeneration.current;
    const stillEditingSubmittedTemplate = () => renderedTemplateId.current === actionTemplateId && editorGeneration.current === actionGeneration;
    setPending("save"); setError(""); setNotice(""); setNoticeFailed(false);
    try {
      const saved = await onSave(submitted, baseRevision); if (!stillEditingSubmittedTemplate()) return; setSavedTemplate(saved); setBaseRevision(saved.revision); setStaleRevision(null);
      if (draftRef.current === submitted) { const next = editable(saved); setDraft(next); draftRef.current = next; setDirty(false); setNotice(saved.enabled === false ? `Reusable template saved as version ${saved.revision}. It is disabled and is not available for future draft requests.` : `Reusable template saved as version ${saved.revision}. Future requests can use it.`); }
      else { setDirty(true); setNotice(`Version ${saved.revision} was saved. Edits made during the save are still here and are not saved.`); }
    }
    catch (caught) { if (stillEditingSubmittedTemplate()) setError(caught instanceof Error ? caught.message : "The reusable template was not saved. Your edits are retained."); }
    finally { if (stillEditingSubmittedTemplate()) setPending(""); }
  }
  async function previewMatter() {
    const actionTemplateId = template.template_id;
    const actionGeneration = editorGeneration.current;
    const stillEditingSubmittedTemplate = () => renderedTemplateId.current === actionTemplateId && editorGeneration.current === actionGeneration;
    setPending("preview"); setError(""); setNotice(""); setNoticeFailed(false);
    try {
      const result = await onPreview(savedTemplate, overrides); if (!stillEditingSubmittedTemplate()) return; setPreview(result);
      const state = previewState(result);
      setNoticeFailed(state.className === "state-failure");
      setNotice(result.artifact ? "Editable preview created from the saved template." : state.detail);
    }
    catch (caught) { if (stillEditingSubmittedTemplate()) setError(caught instanceof Error ? caught.message : "The preview failed. Your template edits and one-time instructions are retained."); }
    finally { if (stillEditingSubmittedTemplate()) setPending(""); }
  }

  return <section aria-labelledby="template-editor-title" className="template-editor">
    <header className="template-editor__head"><div><div className="record-meta">Output template · {template.template_id}</div><h2 id="template-editor-title">Edit {template.name}</h2><p>Version <span className="mono">{baseRevision}</span>. Saving creates a new reusable version.</p></div><span className={`state-label ${draft.enabled ? "state-healthy" : "state-failure"}`}>{draft.enabled ? "Available" : "Disabled"}</span></header>
    {staleRevision ? <div className="stale-warning" role="alert"><span className="state-label state-attention">Newer version exists</span><span>Version <span className="mono">{staleRevision}</span> arrived while you were editing. Your local text is retained. Save will check version <span className="mono">{baseRevision}</span> and report a conflict rather than replace newer content.</span></div> : null}
    <div className="template-fields"><label><span>Name</span><input className="text-input" onChange={(event) => patch({ name: event.target.value })} value={draft.name} /></label><label><span>Output type</span><input className="text-input mono" onChange={(event) => patch({ output_type: event.target.value })} value={draft.output_type} /></label></div>
    <div className="template-fields template-fields--details">{(["audience", "purpose", "tone", "length"] as const).map((field) => <label key={field}><span>{field.replace(/^./, (letter) => letter.toUpperCase())}</span><input className="text-input" onChange={(event) => patch({ [field]: event.target.value })} value={draft[field] ?? ""} /></label>)}</div>
    <section className="editor-field"><div><h3>Plain-language instructions and desired content</h3><p>State what the draft must do. These instructions are data. They cannot run code or change matter records.</p></div><MarkdownRichEditor key={`instructions:${template.template_id}:${baseRevision}`} markdown={draft.instructions ?? ""} onChange={(instructions) => patch({ instructions })} /></section>
    <section className="editor-field"><div><h3>Markdown section outline and heading order</h3><p>Put headings in the order the reader should see them.</p></div><MarkdownRichEditor key={`outline:${template.template_id}:${baseRevision}`} markdown={draft.section_outline ?? ""} onChange={(section_outline) => patch({ section_outline })} /></section>
    <div className="template-long-fields"><label><span>Exclusions</span><textarea className="text-input prose" onChange={(event) => patch({ exclusions: event.target.value })} rows={3} value={draft.exclusions ?? ""} /></label><label><span>How to present sources</span><textarea className="text-input prose" onChange={(event) => patch({ source_presentation: event.target.value })} rows={3} value={draft.source_presentation ?? ""} /></label><label><span>Optional sample wording</span><textarea className="text-input prose" onChange={(event) => patch({ sample_wording: event.target.value })} rows={4} value={draft.sample_wording ?? ""} /><small>Examples guide style only. They are not matter facts or legal authority.</small></label></div>
    <label className="checkbox-row template-enabled"><input checked={draft.enabled !== false} onChange={(event) => patch({ enabled: event.target.checked })} type="checkbox" />Available for future draft requests</label>
    <div className="save-actions"><button className="btn primary" disabled={busy || !!pending || !dirty} onClick={() => void save()} type="button">{pending === "save" ? "Saving…" : "Save reusable template"}</button><button className="btn quiet" disabled={busy || !!pending} onClick={onCancel} type="button">Cancel</button><span>{dirty ? "Edited. Not saved." : "Current saved version."}</span></div>
    <fieldset className="preview-box"><legend>Preview with this matter</legend><p>Use the real draft path. This creates a separate editable preview. It does not approve content, replace a draft, or record a decision.</p>{dirty ? <p className="preview-save-note">Save the reusable template before previewing these structure or guidance changes.</p> : null}<div className="preview-fields">{(["audience", "purpose", "tone", "length"] as const).map((field) => <label key={field}><span>One-time {field}</span><input className="text-input" onChange={(event) => setOverrides((current) => ({ ...current, [field]: event.target.value }))} value={overrides[field] ?? ""} /></label>)}</div><label><span>One-time instruction</span><textarea className="text-input prose" onChange={(event) => setOverrides((current) => ({ ...current, instruction: event.target.value }))} rows={3} value={overrides.instruction ?? ""} /></label><button className="btn agent" disabled={busy || !!pending || dirty || draft.enabled === false} onClick={() => void previewMatter()} type="button">{pending === "preview" ? "Generating preview…" : "Create editable preview"}</button></fieldset>
    {error ? <p className="error" role="alert">{error}</p> : null}{notice ? <p className={noticeFailed ? "editor-action-failure" : "editor-notice"} role="status">{notice}</p> : null}
    {preview ? (() => { const state = previewState(preview); return <div className="preview-result"><span className={`state-label ${state.className}`}>{state.label}</span><div><strong>{preview.artifact?.title || "Preview request"}</strong><p>Status: {preview.state}</p>{preview.artifact ? <><p>Version {preview.artifact.revision}</p>{onOpenArtifact ? <button className="btn quiet" onClick={() => onOpenArtifact(preview.artifact!.path)} type="button">Open editable preview</button> : null}</> : <p>{state.detail}</p>}</div></div>; })() : null}
    <details className="revision-detail"><summary>Current version record</summary><p>Active file: <span className="mono">{template.path}</span></p><p>Content hash: <span className="mono">{template.content_hash || "unavailable"}</span></p><p>Immutable revision: <span className="mono">{template.revision_path || "Created when this version is used or saved"}</span></p></details>
    <style jsx>{`
      .template-editor { min-width: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised); padding: 18px; }
      .template-editor__head { display: flex; justify-content: space-between; align-items: start; gap: 14px; }
      .template-editor__head p { margin: 7px 0 0; color: var(--ink-3); font-size: 13.5px; }
      .stale-warning { display: flex; align-items: start; gap: 9px; margin-top: 14px; padding: 10px 12px; border: 1px solid var(--attention-edge); border-radius: 8px; background: var(--attention-wash); font-size: 13.5px; }
      .template-fields { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(180px, 0.7fr); gap: 12px; margin-top: 18px; }
      .template-fields--details { grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: 12px; }
      .template-fields label, .template-long-fields label, .preview-box label { display: grid; gap: 6px; color: var(--ink-3); font: 500 13px var(--sans); }
      .editor-field { display: grid; gap: 10px; margin-top: 20px; } .editor-field p { margin: 5px 0 0; color: var(--ink-3); font-size: 13.5px; }
      .template-long-fields { display: grid; gap: 12px; margin-top: 18px; }
      .template-long-fields small { color: var(--ink-4); font-weight: 400; }
      .template-enabled { margin-top: 14px; }
      .save-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-top: 16px; } .save-actions span { color: var(--ink-3); font-size: 13px; }
      .preview-box { display: grid; gap: 12px; margin-top: 22px; padding: 14px; border: 1px solid var(--agent-edge); border-radius: 8px; background: var(--agent-wash); }
      .preview-box legend { padding: 0 5px; font: 600 17px var(--serif); } .preview-box > p { margin: 0; color: var(--ink-3); font-size: 13.5px; } .preview-box .preview-save-note { padding: 8px 10px; border: 1px solid var(--attention-edge); border-radius: 7px; background: var(--attention-wash); color: var(--attention-deep); }
      .preview-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
      .editor-notice, .editor-action-failure { margin-top: 14px; padding: 10px 12px; border: 1px solid var(--agent-edge); border-radius: 8px; background: var(--agent-wash); }
      .editor-action-failure { border-color: var(--failure-edge); background: var(--failure-wash); color: var(--failure); }
      .preview-result { display: flex; align-items: start; gap: 10px; margin-top: 14px; padding: 12px; border-left: 3px solid var(--agent); background: var(--agent-wash); }
      .preview-result p { margin: 6px 0 0; overflow-wrap: anywhere; } .preview-result .btn { margin-top: 10px; }
      .revision-detail { margin-top: 18px; padding-top: 12px; border-top: 1px solid var(--line-soft); } .revision-detail summary { cursor: pointer; font-weight: 600; } .revision-detail p { margin: 7px 0 0; color: var(--ink-3); font-size: 12px; overflow-wrap: anywhere; }
      @media (max-width: 620px) { .template-editor { padding: 14px; } .template-fields, .template-fields--details, .preview-fields { grid-template-columns: 1fr; } .template-editor__head { flex-direction: column; } .save-actions .btn { width: 100%; } }
      @media (prefers-reduced-motion: reduce) { .template-editor * { transition: none !important; animation: none !important; } }
    `}</style>
  </section>;
}

frontend/components/workspace/FactReques:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { ContinuityRunCommand, FactReply, FactRequestPanelProps, FactRequestResult } from "@/lib/continuityTypes";
import { factRequestStateLabel, newActionKey, preparationNotice, receiptNotice, recoverRetryCommand, retryDraftKey, type PresentationNotice } from "@/lib/teamPresentation";

type RetryableCommand = { source_action_key: string };

export default function FactRequestPanel(props: FactRequestPanelProps) {
  const { actor, question, requests, selectedRequestId, drafts, busy = false, error, onDraftChange } = props;
  const [pending, setPending] = useState("");
  const [notice, setNotice] = useState<PresentationNotice | null>(null);
  const [localError, setLocalError] = useState("");
  const [reassessment, setReassessment] = useState<FactRequestResult["reassessment"]>(null);
  const frozen = useRef<Record<string, string>>({});
  const activeContext = useRef(props.contextKey); activeContext.current = props.contextKey;
  useEffect(() => {
    frozen.current = {};
    setPending(""); setNotice(null); setLocalError(""); setReassessment(null);
  }, [props.contextKey]);
  const selected = useMemo(() => requests.find((request) => request.request_id === selectedRequestId) ?? null, [requests, selectedRequestId]);
  const locked = busy || Boolean(pending);
  const value = (field: string, fallback = "") => Object.hasOwn(drafts, field) ? drafts[field] : fallback;

  function commandFor<T extends RetryableCommand>(slot: string, intent: unknown, base: Omit<T, "source_action_key">): T {
    const field = retryDraftKey("fact-request", slot);
    const recovered = recoverRetryCommand<T>(frozen.current[field] ?? drafts[field], intent, base, () => newActionKey(slot));
    frozen.current[field] = recovered.serialized;
    if (!recovered.reused) onDraftChange(field, recovered.serialized);
    return recovered.command;
  }
  function clear(fields: string[], slot: string) { fields.forEach((field) => onDraftChange(field, "")); const retryField = retryDraftKey("fact-request", slot); onDraftChange(retryField, ""); delete frozen.current[retryField]; }
  function fail(cause: unknown, fallback: string) { setLocalError(cause instanceof Error ? cause.message : fallback); }
  async function perform(label: string, work: () => Promise<FactRequestResult>, success: string, clearFields: string[] = []) {
    const startedIn = props.contextKey;
    setPending(label); setLocalError(""); setNotice(null);
    try {
      const result = await work();
      if (activeContext.current !== startedIn) return;
      setNotice(receiptNotice(result.receipt, success));
      setReassessment(result.reassessment ?? null);
      if (result.receipt.state === "applied") clear(clearFields, label);
    } catch (cause) { if (activeContext.current === startedIn) fail(cause, "The action did not finish. Your input is retained for retry."); }
    finally { if (activeContext.current === startedIn) setPending(""); }
  }

  async function copyWording() {
    const wording = value("request.wording", selected?.wording ?? "").trim();
    if (!wording) { setLocalError("Add request wording before you copy it."); return; }
    try { await navigator.clipboard.writeText(wording); setNotice({ tone: "agent", word: "Copied", detail: "The request was copied. The app has not marked it as sent." }); setLocalError(""); }
    catch { setLocalError("Copy failed. Select the request text and copy it manually."); }
  }

  async function prepareWording() {
    if (!question || !props.onPrepareWording) return;
    const slot = `prepare-wording:${question.question_id}`;
    const instruction = "Draft concise, editable wording for this fact request. Do not mark it as sent.";
    const startedIn = props.contextKey;
    setPending(slot); setLocalError(""); setNotice(null);
    try {
      const result = await props.onPrepareWording(question.question_id, commandFor<ContinuityRunCommand>(slot, { question_id: question.question_id, instruction }, { instruction }));
      if (activeContext.current !== startedIn) return;
      setNotice(preparationNotice(result.state, "Request wording", "No external request was recorded."));
      if (result.state === "completed") clear([], slot);
    } catch (cause) { if (activeContext.current === startedIn) fail(cause, "Wording preparation failed. Retry will use the same saved action."); }
    finally { if (activeContext.current === startedIn) setPending(""); }
  }

  const wording = value("request.wording", selected?.wording ?? "");
  const person = value("request.person", selected?.requested_person ?? "");
  const due = value("request.due", selected?.due_at?.slice(0, 10) ?? "");

  return <section className="fact-request" aria-labelledby="fact-request-title">
    <style>{css}</style>
    <header><div><p className="eyebrow">Supporting fact</p><h2 id="fact-request-title">Request and record an answer</h2></div><span className="fact-request__actor">Entering lawyer: {actor.display_name}</span></header>
    <p className="fact-request__intro">Prepare text here, then copy it. Only “Record external request” changes its state.</p>
    {error ? <Notice tone="failure" word="Failed" detail={error} /> : null}{notice ? <Notice {...notice} /> : null}{localError ? <Notice tone="failure" word="Failed" detail={localError} alert /> : null}
    {question ? <div className="fact-request__question"><span>Linked question</span><p>{question.text}</p></div> : <p className="muted">Choose a supporting question before you prepare a request.</p>}
    {requests.length ? <label className="label" htmlFor="fact-request-select">Saved request</label> : null}
    {requests.length ? <select id="fact-request-select" className="select-input" value={selectedRequestId ?? ""} onChange={(event) => props.onSelectRequest(event.target.value || null)} disabled={locked}><option value="">Prepare a new request</option>{requests.map((request) => <option value={request.request_id} key={request.request_id}>{factRequestStateLabel(request.state)} · {request.requested_person || "Recipient not specified"}</option>)}</select> : null}
    <div className="fact-request__form">
      <label className="label" htmlFor="fact-request-wording">Editable request</label><textarea id="fact-request-wording" className="text-input prose" value={wording} disabled={locked || Boolean(selected && selected.state !== "prepared")} onChange={(event) => onDraftChange("request.wording", event.target.value)} placeholder="Could you confirm…" />
      <div className="fact-request__grid"><label><span className="label">Requested person</span><input className="text-input" value={person} disabled={locked || Boolean(selected && selected.state !== "prepared")} onChange={(event) => onDraftChange("request.person", event.target.value)} /></label><label><span className="label">Requested date (optional)</span><input className="text-input" type="date" value={due} disabled={locked || Boolean(selected && selected.state !== "prepared")} onChange={(event) => onDraftChange("request.due", event.target.value)} /></label></div>
      <div className="btn-row"><button type="button" className="btn primary" disabled={locked || !question || !wording.trim() || Boolean(selected && selected.state !== "prepared")} onClick={() => { const slot = selected ? `request-edit:${selected.request_id}` : "request-create"; const intent = selected ? { request_id: selected.request_id, wording: wording.trim(), requested_person: person.trim() || null, due_at: due || null } : { question_id: question!.question_id, wording: wording.trim(), requested_person: person.trim() || null, due_at: due || null }; void perform(slot, () => selected ? props.onEdit(selected.request_id, commandFor(slot, intent, { expected_revision: selected.revision, wording: wording.trim(), requested_person: person.trim() || null, due_at: due || null })) : props.onCreate(commandFor(slot, intent, { question_id: question!.question_id, expected_question_revision: question!.source_revision, business_question_revision: question!.business_question_revision, wording: wording.trim(), requested_person: person.trim() || null, due_at: due || null })), selected ? "Request changes saved." : "Request prepared."); }}>{pending.startsWith("request-") ? "Saving…" : selected ? "Save request changes" : "Prepare request"}</button><button className="btn quiet" type="button" disabled={locked || !wording.trim()} onClick={() => void copyWording()}>Copy</button>{props.onPrepareWording && question ? <button className="btn agent" type="button" disabled={locked} onClick={() => void prepareWording()}>{pending.startsWith("prepare-wording:") ? "Preparing…" : "Draft wording"}</button> : null}</div>
    </div>
    {selected ? <SavedRequest request={selected} {...props} locked={locked} pending={pending} value={value} setPending={setPending} setNotice={setNotice} setError={setLocalError} perform={perform} commandFor={commandFor} /> : null}
    {reassessment ? <div className="fact-request__reassess"><p><strong>Answer saved.</strong> Reassess the current matter with the recorded fact.</p><button className="btn agent" type="button" disabled={locked} onClick={() => { setPending("reassess"); setLocalError(""); void props.onReassess(reassessment).then((result) => setNotice(result.state === "completed" ? { tone: "agent", word: "Complete", detail: "Saved analysis now uses the recorded fact. Drafts and decisions stay unchanged." } : { tone: "agent", word: result.state === "queued" ? "Queued" : "Working", detail: "Reassessment uses the saved fact. Drafts and decisions stay unchanged." })).catch((cause) => fail(cause, "Reassessment failed. The saved reply and fact remain recorded.")).finally(() => setPending("")); }}>Reassess current answer</button></div> : null}
  </section>;
}

function SavedRequest({ request, actor, locked, pending, value, onDraftChange, onAction, onSaveReply, onRecordReply, onOpenTarget, perform, commandFor }: any) {
  const replyText = value("reply.text"); const speaker = value("reply.speaker"); const date = value("reply.date");
  return <div className="fact-request__saved"><div className="fact-request__saved-head"><div><span className={`fact-state state-${request.state === "answer_recorded" ? "healthy" : "attention"}`}>{factRequestStateLabel(request.state)}</span><p className="small">Requested from: {request.requested_person || "Not specified"}</p></div><button className="btn quiet tiny" type="button" onClick={() => onOpenTarget({ matter_id: request.matter_id, kind: "fact_request", target_id: request.request_id, revision: request.revision })}>Open record</button></div>
    {request.remaining_question ? <p className="fact-request__remaining"><strong>Still open:</strong> {request.remaining_question}</p> : null}
    {(request.state ?? "prepared") === "prepared" ? <div className="btn-row"><button className="btn review" type="button" disabled={locked} onClick={() => { const slot = `request-external:${request.request_id}`; void perform(slot, () => onAction(request.request_id, commandFor(slot, { request_id: request.request_id, action: "requested_externally" }, { action: "requested_externally", expected_revision: request.revision })), "External request recorded."); }}>Record external request</button><button className="btn quiet" type="button" disabled={locked} onClick={() => { const slot = `request-open:${request.request_id}`; void perform(slot, () => onAction(request.request_id, commandFor(slot, { request_id: request.request_id, action: "leave_open" }, { action: "leave_open", expected_revision: request.revision })), "Request left open."); }}>Leave open</button></div> : null}
    <div className="fact-request__reply"><h3>Paste a reply</h3><p className="small muted">The exact reply is saved as supplied text. The speaker is separate from {actor.display_name}, who enters it.</p><label className="label" htmlFor="fact-reply-text">Exact reply text</label><textarea id="fact-reply-text" className="text-input prose" value={replyText} disabled={locked} onChange={(event) => onDraftChange("reply.text", event.target.value)} /><div className="fact-request__grid"><label><span className="label">Reported speaker (optional)</span><input className="text-input" value={speaker} disabled={locked} onChange={(event) => onDraftChange("reply.speaker", event.target.value)} /></label><label><span className="label">Reported date (optional)</span><input className="text-input" type="date" value={date} disabled={locked} onChange={(event) => onDraftChange("reply.date", event.target.value)} /></label></div><button className="btn primary" type="button" disabled={locked || !replyText.trim()} onClick={() => { const slot = `reply-save:${request.request_id}`; const intent = { request_id: request.request_id, text: replyText, reported_speaker: speaker.trim() || null, reported_at: date || null }; void perform(slot, () => onSaveReply(request.request_id, commandFor(slot, intent, { expected_revision: request.revision, text: replyText, reported_speaker: speaker.trim() || null, reported_at: date || null })), "Exact reply saved.", ["reply.text", "reply.speaker", "reply.date"]); }}>{pending.startsWith("reply-save:") ? "Saving reply…" : "Save reply"}</button></div>
    {(request.replies ?? []).map((reply: FactReply) => <ReplyRecord key={reply.reply_id} request={request} reply={reply} locked={locked} value={value} onDraftChange={onDraftChange} onRecordReply={onRecordReply} perform={perform} commandFor={commandFor} />)}
  </div>;
}

function ReplyRecord({ request, reply, locked, value, onDraftChange, onRecordReply, perform, commandFor }: any) {
  const answer = value(`answer.text:${reply.reply_id}`, reply.text); const coverage = value(`answer.coverage:${reply.reply_id}`, "full"); const remaining = value(`answer.remaining:${reply.reply_id}`); const supersedes = value(`answer.supersedes:${reply.reply_id}`);
  const answerInputId = `reported-fact-${reply.reply_id}`;
  const slot = `answer-record:${request.request_id}:${reply.reply_id}`;
  const intent = { request_id: request.request_id, reply_id: reply.reply_id, answer_text: answer.trim(), coverage, remaining_question: coverage === "partial" ? remaining.trim() : null, supersedes_fact_id: supersedes.trim() || null };
  return <details className="fact-request__answer"><summary>Record answer from {reply.reported_speaker || "speaker unknown"}</summary><blockquote>{reply.text}</blockquote><label className="label" htmlFor={answerInputId}>Reported fact</label><textarea id={answerInputId} className="text-input" value={answer} disabled={locked} onChange={(event) => onDraftChange(`answer.text:${reply.reply_id}`, event.target.value)} /><fieldset><legend className="label">Coverage</legend><label><input type="radio" name={`coverage-${reply.reply_id}`} checked={coverage === "full"} onChange={() => onDraftChange(`answer.coverage:${reply.reply_id}`, "full")} /> Full answer</label><label><input type="radio" name={`coverage-${reply.reply_id}`} checked={coverage === "partial"} onChange={() => onDraftChange(`answer.coverage:${reply.reply_id}`, "partial")} /> Partial answer</label></fieldset>{coverage === "partial" ? <label><span className="label">Question that remains</span><input className="text-input" value={remaining} onChange={(event) => onDraftChange(`answer.remaining:${reply.reply_id}`, event.target.value)} /></label> : null}<label><span className="label">Superseded fact ID (optional)</span><input className="text-input" value={supersedes} onChange={(event) => onDraftChange(`answer.supersedes:${reply.reply_id}`, event.target.value)} /></label><button className="btn primary" type="button" disabled={locked || !answer.trim() || (coverage === "partial" && !remaining.trim())} onClick={() => void perform(slot, () => onRecordReply(request.request_id, reply.reply_id, commandFor(slot, intent, { expected_revision: request.revision, expected_question_revision: request.question_revision, business_question_revision: request.business_question_revision, answer_text: answer.trim(), coverage, remaining_question: coverage === "partial" ? remaining.trim() : null, supersedes_fact_id: supersedes.trim() || null })), coverage === "partial" ? "Partial answer recorded. The remaining question stays open." : "Answer recorded.")}>Record this answer</button></details>;
}

function Notice({ tone, word, detail, alert = false }: PresentationNotice & { alert?: boolean }) { return <p className={`fact-request__notice ${tone}`} role={alert ? "alert" : "status"}><strong>{word}:</strong> {detail}</p>; }

