`;

frontend/components/workspace/InquiryAct:
"use client";

import { useRef, useState } from "react";
import type { InquiryActionsProps, WorkspaceAction } from "@/lib/workspaceTypes";
import type { ContinuityInquiryActionsProps } from "@/lib/continuityTypes";

const labels: Record<WorkspaceAction, string> = {
  explain: "Explain",
  stress_test: "Stress-test",
  ask_business: "Ask the business",
  explore_question: "Explore question",
};

const descriptions: Record<WorkspaceAction, string> = {
  explain: "Explain the selected issue or source in the current matter.",
  stress_test: "Look for a material objection or condition that could change the view.",
  ask_business: "Draft a focused question for the business. It is not sent.",
  explore_question: "Explore an open question without changing facts or decisions.",
};
type Notice = { tone: "healthy" | "agent" | "attention" | "failure"; word: string; message: string };

function actionNotice(state: string): Notice {
  if (state === "saved") return { tone: "healthy", word: "Saved", message: "The inquiry was saved in the existing conversation." };
  if (state === "proposed") return { tone: "attention", word: "Proposed", message: "The inquiry is not applied." };
  if (state === "failed" || state === "not_saved") return { tone: "failure", word: "Not saved", message: `Inquiry ${state}.` };
  return { tone: "agent", word: state === "queued" ? "Queued" : "Working", message: `Inquiry ${state}.` };
}

function targetLabel(target: InquiryActionsProps["target"]) {
  if (target.scenario_id) return "Saved scenario";
  if (target.artifact_path) return target.artifact_path.split("/").at(-1) || "Selected document";
  if (target.source_id) return "Selected source";
  if (target.issue_id) return "Selected issue";
  return "This matter";
}

export default function InquiryActions({ target, busy = false, onAction, onFactRequest, onHandoff, onCompareSources }: ContinuityInquiryActionsProps) {
  const [instruction, setInstruction] = useState("");
  const [selectedAction, setSelectedAction] = useState<WorkspaceAction>("explain");
  const [pending, setPending] = useState<WorkspaceAction | null>(null);
  const [notice, setNotice] = useState<Notice | null>(null);
  const [error, setError] = useState("");
  const actionKey = useRef({ signature: "", key: "" });
  const contextualAction = [
    onFactRequest ? { label: "Request a fact", onClick: onFactRequest } : null,
    onHandoff ? { label: "Hand off work", onClick: onHandoff } : null,
    onCompareSources ? { label: "Compare a source", onClick: onCompareSources } : null,
  ].find(Boolean);

  function stableKey(action: WorkspaceAction, text: string) {
    const signature = JSON.stringify({ action, text, target });
    if (actionKey.current.signature !== signature) actionKey.current = { signature, key: `workspace-action:${crypto.randomUUID()}` };
    return actionKey.current.key;
  }

  async function run(action: WorkspaceAction) {
    setSelectedAction(action); setPending(action); setError(""); setNotice(null);
    try {
      const result = await onAction({ action, instruction: instruction.trim(), target, source_action_key: stableKey(action, instruction.trim()) });
      setNotice(actionNotice(result.state));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The inquiry did not complete. Your question is retained for retry.");
    } finally { setPending(null); }
  }

  async function copyQuestion() {
    if (!instruction.trim()) { setError("Write a question before copying it."); return; }
    try {
      await navigator.clipboard.writeText(instruction.trim());
      setNotice({ tone: "agent", word: "Copied", message: "Question copied." }); setError("");
    } catch {
      setError("The question could not be copied. Select the text and copy it manually.");
    }
  }

  return <section aria-labelledby="inquiry-actions-title" className="inquiry-actions">
    <style>{componentCss}</style>
    <div className="inquiry-actions__header"><div><p className="eyebrow">Explore</p><h2 id="inquiry-actions-title">Ask about {targetLabel(target)}</h2></div><span className="state-agent">Agent work</span></div>
    <p className="inquiry-actions__intro">These shortcuts use the same saved conversation and matter context. They do not start a separate assistant or history.</p>
    {notice ? <p className={`inquiry-actions__state inquiry-actions__state--${notice.tone}`} role="status">{notice.word}: {notice.message}</p> : null}
    {error ? <p className="inquiry-actions__state inquiry-actions__state--failure" role="alert">Failed: {error}</p> : null}
    <fieldset className="inquiry-actions__choices" disabled={busy || pending !== null}>
      <legend className="sr-only">Inquiry type</legend>
      {(Object.keys(labels) as WorkspaceAction[]).map((action) => <label key={action}><input checked={selectedAction === action} name="inquiry-action" onChange={() => setSelectedAction(action)} type="radio" value={action} />{labels[action]}</label>)}
    </fieldset>
    <label className="label" htmlFor="inquiry-question">Question or instruction</label>
    <textarea id="inquiry-question" className="text-input prose" value={instruction} onChange={(event) => setInstruction(event.target.value)} placeholder="What would change if the funds remained in the account for two days?" />
    <div className="inquiry-actions__buttons" aria-label="Inquiry actions"><button className="btn agent" type="button" title={descriptions[selectedAction]} onClick={() => void run(selectedAction)} disabled={busy || pending !== null}>{pending === selectedAction ? `${labels[selectedAction]}…` : "Start inquiry"}</button><button className="btn quiet" type="button" onClick={() => void copyQuestion()} disabled={busy || pending !== null}>Copy question</button></div>
    {contextualAction ? <div className="inquiry-actions__context"><span className="small muted">More matter actions</span><button className="btn quiet tiny" onClick={contextualAction.onClick} type="button">{contextualAction.label}</button></div> : null}
    <p className="small muted">Selected action: {labels[selectedAction]}. {descriptions[selectedAction]}</p>
  </section>;
}

const componentCss = `
.inquiry-actions { min-width: 0; display: grid; gap: 9px; padding: 18px; border: 1px dashed var(--agent-edge); border-radius: var(--radius); background: var(--agent-wash); }
.inquiry-actions__header { display: flex; justify-content: space-between; gap: 12px; align-items: start; }
.inquiry-actions__header h2 { max-width: 28ch; }
.inquiry-actions__header > span { flex: none; padding: 3px 8px; border-radius: 11px; font: 500 12px var(--sans); }
.inquiry-actions__intro { margin: 0 0 4px; font: 400 15px/1.55 var(--sans); color: var(--ink-3); }
.inquiry-actions__state { margin: 0; padding: 9px 11px; border-radius: 7px; font: 500 13.5px/1.45 var(--sans); }
.inquiry-actions__state--healthy { border: 1px solid var(--healthy); background: var(--healthy-wash); color: var(--healthy); }
.inquiry-actions__state--agent { border: 1px dashed var(--agent-edge); background: var(--agent-wash); color: var(--agent); }
.inquiry-actions__state--attention { border: 1px solid var(--attention-edge); background: var(--attention-wash); color: var(--attention-deepest); }
.inquiry-actions__state--failure { border: 1px solid var(--failure-edge); background: var(--failure-wash); color: var(--failure); }
.inquiry-actions__buttons { display: flex; gap: 8px; flex-wrap: wrap; }
.inquiry-actions__choices { display: flex; flex-wrap: wrap; gap: 8px; padding: 0; border: 0; margin: 0; }
.inquiry-actions__choices label { display: inline-flex; align-items: center; gap: 5px; font: 500 13px var(--sans); color: var(--ink-3); }
.inquiry-actions__context { display: flex; flex-wrap: wrap; gap: 7px; align-items: center; }
@media (max-width: 620px) { .inquiry-actions { padding: 14px; } .inquiry-actions__header { flex-direction: column; } .inquiry-actions__buttons .btn { width: 100%; } }
@media (prefers-reduced-motion: reduce) { .inquiry-actions * { transition: none !important; animation: none !important; } }
`;

frontend/components/workspace/BusinessFl:
"use client";

import { useEffect, useRef, useState } from "react";
import type { BusinessFlowProps, Flow, FlowActor, FlowEdge, InteractionReceipt } from "@/lib/workspaceTypes";

const newId = (prefix: string) => `${prefix}-${crypto.randomUUID()}`;
const cloneFlow = (flow: Flow): Flow => ({ ...flow, actors: [...(flow.actors ?? [])], edges: [...(flow.edges ?? [])] });
type Notice = { tone: "healthy" | "agent" | "attention" | "failure"; word: string; message: string };

function normalizeEdges(edges: FlowEdge[]) {
  return edges.map((edge, index) => ({ ...edge, order: index + 1 }));
}

function receiptNotice(receipt: InteractionReceipt): Notice {
  if (receipt.state === "applied") return { tone: "healthy", word: "Saved", message: "Selected facts were saved to the matter record." };
  if (receipt.state === "proposed") return { tone: "attention", word: "Proposed", message: "It is not applied." };
  return { tone: "failure", word: "Not saved", message: receipt.failure_detail || "The selected facts were not saved." };
}

export default function BusinessFlow({
  flow,
  busy = false,
  currentRevisions = {},
  proposedFactChanges = [],
  onAcceptFactChanges,
  onSave,
  onSelectFact,
  onRefresh,
}: BusinessFlowProps) {
  const [draft, setDraft] = useState<Flow>(() => cloneFlow(flow));
  const [baseRevision, setBaseRevision] = useState(flow.revision);
  const [dirty, setDirty] = useState(false);
  const [selectedChanges, setSelectedChanges] = useState<string[]>([]);
  const [notice, setNotice] = useState<Notice | null>(null);
  const [error, setError] = useState("");
  const [pending, setPending] = useState<"save" | "accept" | null>(null);
  const acceptanceKey = useRef({ signature: "", key: "" });
  const [conflict, setConflict] = useState(false);
  const [refreshedFlow, setRefreshedFlow] = useState<Flow | null>(null);
  const locked = busy || pending !== null;

  // A background refresh must never erase a lawyer's unsaved flow edits.
  useEffect(() => {
    if (dirty || flow.revision === baseRevision) return;
    setDraft(cloneFlow(flow));
    setBaseRevision(flow.revision);
    setSelectedChanges([]);
  }, [baseRevision, dirty, flow]);

  const update = (next: Flow) => { setDraft({ ...next, edges: normalizeEdges(next.edges ?? []) }); setDirty(true); setConflict(false); };
  const actors = draft.actors ?? [];
  const edges = draft.edges ?? [];
  const actorLabels = new Map(actors.map((actor) => [actor.actor_id, actor.label.trim() || "Unnamed actor"]));

  function addActor() {
    const actor: FlowActor = { actor_id: newId("actor"), label: "New actor" };
    update({ ...draft, actors: [...actors, actor] });
  }

  function updateActor(actorId: string, label: string) {
    update({ ...draft, actors: actors.map((actor) => actor.actor_id === actorId ? { ...actor, label } : actor) });
  }

  function removeActor(actorId: string) {
    update({ ...draft, actors: actors.filter((actor) => actor.actor_id !== actorId), edges: edges.filter((edge) => edge.from_actor_id !== actorId && edge.to_actor_id !== actorId) });
  }

  function addEdge() {
    if (actors.length < 2) { setError("Add at least two actors before adding a relationship."); return; }
    const edge: FlowEdge = {
      edge_id: newId("edge"), from_actor_id: actors[0].actor_id, to_actor_id: actors[1].actor_id,
      label: "New relationship", order: edges.length + 1, timing: "", custody: "", ownership: "", fact_ids: [], uncertainty: "",
    };
    update({ ...draft, edges: [...edges, edge] });
  }

  function updateEdge(edgeId: string, patch: Partial<FlowEdge>) {
    update({ ...draft, edges: edges.map((edge) => edge.edge_id === edgeId ? { ...edge, ...patch } : edge) });
  }

  function moveEdge(edgeId: string, direction: -1 | 1) {
    const from = edges.findIndex((edge) => edge.edge_id === edgeId);
    const to = from + direction;
    if (from < 0 || to < 0 || to >= edges.length) return;
    const next = [...edges]; [next[from], next[to]] = [next[to], next[from]];
    update({ ...draft, edges: next });
  }

  async function save() {
    const unnamedActor = actors.some((actor) => !actor.label.trim());
    const unnamedEdge = edges.some((edge) => !edge.label.trim());
    if (unnamedActor || unnamedEdge) { setError("Name each actor and relationship before saving."); return; }
    setPending("save"); setError(""); setNotice(null); setConflict(false);
    try {
      const saved = await onSave({ ...draft, revision: baseRevision, actors, edges: normalizeEdges(edges) }, baseRevision);
      setDraft(cloneFlow(saved)); setBaseRevision(saved.revision); setDirty(false);
      setNotice({ tone: "healthy", word: "Saved", message: "Business flow saved." });
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The flow was not saved. Your edits are retained so you can refresh or retry.");
      setConflict(true);
    } finally { setPending(null); }
  }

  async function acceptSelectedFacts() {
    if (!onAcceptFactChanges) { setError("Flow fact acceptance is not connected yet."); return; }
    if (!selectedChanges.length) { setError("Choose the specific proposed facts to accept."); return; }
    setPending("accept"); setError(""); setNotice(null);
    const signature = `${selectedChanges.slice().sort().join(",")}:${JSON.stringify(currentRevisions)}`;
    if (acceptanceKey.current.signature !== signature) acceptanceKey.current = { signature, key: newId("flow-accept") };
    try {
      const receipt = await onAcceptFactChanges(selectedChanges, currentRevisions, acceptanceKey.current.key);
      setNotice(receiptNotice(receipt));
      if (receipt.state === "applied") setSelectedChanges([]);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The selected facts were not accepted. Your selection is retained.");
    } finally { setPending(null); }
  }

  async function refreshCurrentFlow() {
    if (!onRefresh) return;
    setError("");
    try {
      const latest = await onRefresh();
      setRefreshedFlow(cloneFlow(latest));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The current saved flow could not be read. Your edits are retained.");
    }
  }

  function rebaseLocalEdits() {
    if (!refreshedFlow) return;
    setBaseRevision(refreshedFlow.revision);
    setConflict(false);
    setError("");
    setNotice({ tone: "attention", word: "Rebased", message: "Your local flow edits are retained against the latest saved revision. Review them before saving." });
  }

  async function copyLocalFlow() {
    try {
      await navigator.clipboard.writeText(JSON.stringify({ ...draft, revision: baseRevision }, null, 2));
      setNotice({ tone: "agent", word: "Copied", message: "Local flow edits copied." });
    } catch {
      setError("The local flow could not be copied. Your edits remain in this form.");
    }
  }

  const initialUnsaved = !flow.revision && !dirty;

  return <section aria-labelledby="business-flow-title" className="business-flow">
    <style>{componentCss}</style>
    <div className="business-flow__header"><div><p className="eyebrow">Explore</p><h2 id="business-flow-title">Business flow</h2></div><span className={dirty || initialUnsaved ? "state-attention" : "state-healthy"}>{dirty ? "Needs save" : initialUnsaved ? "Not saved" : "Saved"}</span></div>
    <p className="business-flow__intro">Map the people and ordered relationships. This sketch does not reach a legal conclusion by itself.</p>
    {notice ? <p className={`business-flow__state business-flow__state--${notice.tone}`} role="status">{notice.word}: {notice.message}</p> : null}
    {error ? <p className="business-flow__state business-flow__state--failure" role="alert">Failed: {error}</p> : null}
    <section className="business-flow__sketch" aria-labelledby="business-flow-sketch-title">
      <div className="business-flow__section-heading"><div><h3 id="business-flow-sketch-title">Flow sketch</h3><p className="small muted">This diagram mirrors the editable ordered relationship list below.</p></div></div>
      {edges.length ? <ol className="business-flow__sketch-list">{edges.map((edge, index) => {
        const edgeDetails = [
          { label: "Timing", value: edge.timing?.trim() },
          { label: "Custody", value: edge.custody?.trim() },
          { label: "Ownership", value: edge.ownership?.trim() },
          { label: "Uncertainty", value: edge.uncertainty?.trim() },
        ].filter((detail): detail is { label: string; value: string } => Boolean(detail.value));
        return <li className="business-flow__sketch-step" key={edge.edge_id}>
          <span className="business-flow__sketch-order">Step {index + 1}</span>
          <div className="business-flow__sketch-route">
            <div className="business-flow__sketch-node"><span>From</span><strong>{actorLabels.get(edge.from_actor_id) ?? "Unknown actor"}</strong></div>
            <span className="business-flow__sketch-arrow" aria-hidden="true">→</span>
            <div className="business-flow__sketch-node business-flow__sketch-node--relationship"><span>Relationship</span><strong>{edge.label.trim() || "Unnamed relationship"}</strong></div>
            <span className="business-flow__sketch-arrow" aria-hidden="true">→</span>
            <div className="business-flow__sketch-node"><span>To</span><strong>{actorLabels.get(edge.to_actor_id) ?? "Unknown actor"}</strong></div>
          </div>
          {edgeDetails.length ? <dl className="business-flow__sketch-details">{edgeDetails.map((detail) => <div key={detail.label}><dt>{detail.label}</dt><dd>{detail.value}</dd></div>)}</dl> : <p className="small muted">No timing, custody, ownership, or uncertainty recorded for this step.</p>}
        </li>;
      })}</ol> : <p className="muted small">Add an ordered relationship to see the flow sketch.</p>}
    </section>
    <div className="business-flow__actors"><div className="business-flow__section-heading"><h3>Actors</h3><button className="btn tiny" type="button" onClick={addActor} disabled={locked}>Add actor</button></div>{actors.length ? actors.map((actor) => <div className="business-flow__actor" key={actor.actor_id}><input className="text-input" aria-label="Actor name" value={actor.label} disabled={locked} onChange={(event) => updateActor(actor.actor_id, event.target.value)} /><button className="btn tiny quiet" type="button" onClick={() => removeActor(actor.actor_id)} disabled={locked}>Remove</button></div>) : <p className="muted small">Add the people or organizations in this flow.</p>}</div>
    <div className="business-flow__edges"><div className="business-flow__section-heading"><h3>Ordered relationships</h3><button className="btn tiny" type="button" onClick={addEdge} disabled={locked}>Add relationship</button></div>{edges.length ? edges.map((edge, index) => <article className="business-flow__edge" key={edge.edge_id}><div className="business-flow__edge-order"><span>Step {index + 1}</span><div className="btn-row"><button className="btn tiny quiet" type="button" onClick={() => moveEdge(edge.edge_id, -1)} disabled={index === 0 || locked}>Earlier</button><button className="btn tiny quiet" type="button" onClick={() => moveEdge(edge.edge_id, 1)} disabled={index === edges.length - 1 || locked}>Later</button><button className="btn tiny quiet" type="button" onClick={() => update({ ...draft, edges: edges.filter((item) => item.edge_id !== edge.edge_id) })} disabled={locked}>Remove</button></div></div><div className="business-flow__edge-grid"><label><span>From</span><select className="select-input" value={edge.from_actor_id} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { from_actor_id: event.target.value })}>{actors.map((actor) => <option key={actor.actor_id} value={actor.actor_id}>{actor.label || "Unnamed actor"}</option>)}</select></label><label><span>To</span><select className="select-input" value={edge.to_actor_id} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { to_actor_id: event.target.value })}>{actors.map((actor) => <option key={actor.actor_id} value={actor.actor_id}>{actor.label || "Unnamed actor"}</option>)}</select></label><label className="business-flow__wide"><span>Relationship</span><input className="text-input" value={edge.label} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { label: event.target.value })} /></label><label><span>Timing</span><input className="text-input" value={edge.timing ?? ""} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { timing: event.target.value })} /></label><label><span>Custody</span><input className="text-input" value={edge.custody ?? ""} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { custody: event.target.value })} /></label><label><span>Ownership</span><input className="text-input" value={edge.ownership ?? ""} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { ownership: event.target.value })} /></label><label className="business-flow__wide"><span>Uncertainty</span><input className="text-input" value={edge.uncertainty ?? ""} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { uncertainty: event.target.value })} /></label></div>{edge.fact_ids?.length ? <div className="business-flow__facts"><span>Linked facts</span>{edge.fact_ids.map((factId) => <button className="chip" type="button" key={factId} onClick={() => onSelectFact(factId)} disabled={locked}>{factId}</button>)}</div> : <p className="small muted">No linked facts.</p>}</article>) : <p className="muted small">Add an ordered relationship after you add actors.</p>}</div>
    <div className="btn-row"><button className="btn primary" type="button" onClick={() => void save()} disabled={locked}>{pending === "save" ? "Saving flow…" : "Save flow"}</button><span className="small muted">Saved means the flow record was written.</span></div>
    {conflict ? <div className="business-flow__conflict"><strong>Needs attention: flow changed while you were editing.</strong><p className="small">Your local edits are still here. Refresh reads the current saved flow without replacing them. Rebase uses that current revision only after you choose it.</p><div className="btn-row"><button className="btn review" type="button" onClick={() => void refreshCurrentFlow()} disabled={locked || !onRefresh}>Refresh current flow</button><button className="btn quiet" type="button" onClick={() => void copyLocalFlow()} disabled={locked}>Copy local edits</button>{refreshedFlow ? <button className="btn primary" type="button" onClick={rebaseLocalEdits} disabled={locked}>Rebase my edits</button> : null}</div></div> : null}
    <div className="business-flow__acceptance"><h3>Accept selected facts</h3><p className="small muted">A flow edit can propose facts. Choose only the facts you want to add to the matter.</p>{proposedFactChanges.filter((change) => change.state === "proposed" || !change.state).length ? proposedFactChanges.filter((change) => change.state === "proposed" || !change.state).map((change) => <label className="checkbox-row" key={change.change_id}><input type="checkbox" checked={selectedChanges.includes(change.change_id)} disabled={locked} onChange={() => setSelectedChanges((current) => current.includes(change.change_id) ? current.filter((id) => id !== change.change_id) : [...current, change.change_id])} /><span>{change.text}</span></label>) : <p className="small muted">No proposed facts are ready to accept.</p>}<button className="btn review" type="button" onClick={() => void acceptSelectedFacts()} disabled={locked || !selectedChanges.length}>{pending === "accept" ? "Accepting facts…" : "Accept selected facts"}</button></div>
  </section>;
}

const componentCss = `
.business-flow { min-width: 0; display: grid; gap: 16px; padding: 18px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised); }
.business-flow__header, .business-flow__section-heading, .business-flow__edge-order { display: flex; justify-content: space-between; align-items: start; gap: 12px; }
.business-flow__header > span { flex: none; padding: 3px 8px; border-radius: 11px; font: 500 12px var(--sans); }
.business-flow__intro { margin: -8px 0 0; color: var(--ink-3); font: 400 15px/1.55 var(--sans); }
.business-flow__state { margin: -6px 0 0; padding: 9px 11px; border-radius: 7px; font: 500 13.5px/1.45 var(--sans); }
.business-flow__state--healthy { border: 1px solid var(--healthy); background: var(--healthy-wash); color: var(--healthy); }
.business-flow__state--agent { border: 1px dashed var(--agent-edge); background: var(--agent-wash); color: var(--agent); }
.business-flow__state--attention { border: 1px solid var(--attention-edge); background: var(--attention-wash); color: var(--attention-deepest); }
.business-flow__state--failure { border: 1px solid var(--failure-edge); background: var(--failure-wash); color: var(--failure); }
.business-flow__actors, .business-flow__edges, .business-flow__acceptance, .business-flow__sketch { display: grid; gap: 9px; }
.business-flow__actor { display: flex; gap: 8px; }
.business-flow__sketch { padding: 14px; border: 1px solid var(--line-soft); border-radius: 8px; background: var(--quiet-wash); }
.business-flow__sketch .business-flow__section-heading > div { display: grid; gap: 3px; }
.business-flow__sketch .business-flow__section-heading p { margin: 0; }
.business-flow__sketch-list { display: grid; gap: 9px; margin: 0; padding: 0; list-style: none; }
