frontend/components/workspace/PriorWorkP:
"use client";

import { FormEvent, useState } from "react";
import type { PriorWorkPanelProps } from "@/lib/workspaceTypes";

const titleCase = (value: string) => value.replaceAll("_", " ").replaceAll("-", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());

export default function PriorWorkPanel({ candidates, busy = false, onSearch, onInclude, onOpenArtifact }: PriorWorkPanelProps) {
  const [query, setQuery] = useState("");
  const [searched, setSearched] = useState(false);
  const [searching, setSearching] = useState(false);
  const [pendingPath, setPendingPath] = useState<string | null>(null);
  const [includedPaths, setIncludedPaths] = useState<Set<string>>(new Set());
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  async function search(event: FormEvent) {
    event.preventDefault();
    if (!query.trim()) return;
    setSearching(true); setError(""); setNotice("");
    try {
      await onSearch(query.trim());
      setSearched(true);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Prior work could not be searched. Your query is retained.");
    } finally { setSearching(false); }
  }

  async function include(path: string) {
    const candidate = candidates.find((item) => item.path === path);
    if (!candidate) return;
    setPendingPath(path); setError(""); setNotice("");
    try {
      await onInclude(candidate);
      setIncludedPaths((current) => new Set(current).add(`${path}:${candidate.revision}`));
      setNotice(`Included ${candidate.title} in the next inquiry context.`);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Prior work was not included. You can retry.");
    } finally { setPendingPath(null); }
  }

  return <section aria-labelledby="prior-work-title" className="reuse-panel">
    <div className="reuse-panel__head"><div><h2 id="prior-work-title">Similar prior work</h2><p>Search when it is useful. A result affects the next inquiry only after you include it.</p></div></div>
    <form className="reuse-search" onSubmit={(event) => void search(event)}>
      <label className="label" htmlFor="prior-work-query">What work should match?</label>
      <div className="reuse-search__row"><input className="text-input" id="prior-work-query" onChange={(event) => setQuery(event.target.value)} placeholder="Settlement structure, custody, or a key fact" value={query} /><button className="btn" disabled={busy || searching || !query.trim()} type="submit">{searching ? "Searching…" : "Search prior work"}</button></div>
    </form>
    {error ? <p className="error" role="alert">{error}</p> : null}
    {notice ? <p className="reuse-notice" role="status"><span className="state-label state-healthy">Included</span>{notice}</p> : null}
    {searched && candidates.length === 0 ? <p className="empty-state">No matching prior work was found.</p> : null}
    {candidates.length ? <div className="reuse-list" aria-live="polite">{candidates.map((candidate) => {
      const included = includedPaths.has(`${candidate.path}:${candidate.revision}`);
      return <article className="reuse-item" key={`${candidate.path}:${candidate.revision}`}>
        <div className="reuse-item__head"><div><h3>{candidate.title}</h3><p className="reuse-source">{titleCase(candidate.kind || "prior matter")} · {candidate.date || "Date not recorded"} · {candidate.status || "Status not recorded"}</p></div><span className={`state-label ${included ? "state-healthy" : "state-attention"}`}>{included ? "Included" : "Review first"}</span></div>
        <p className="reading reuse-reading">{candidate.relevance}</p>
        {candidate.snippet ? <blockquote className="reuse-snippet">{candidate.snippet}</blockquote> : null}
        <div className="reuse-differences"><strong>Important differences</strong><ul>{candidate.differences.length ? candidate.differences.map((difference) => <li key={difference}>{difference}</li>) : <li>No difference was supplied. Inspect the source before use.</li>}</ul></div>
        <details className="reuse-source-detail"><summary>Source details</summary><p>Matter: {candidate.matter_id || "Not recorded"}</p><p>File: <span className="mono">{candidate.path}</span></p><p>Version: <span className="mono">{candidate.revision || "Not recorded"}</span></p></details>
        <div className="btn-row"><button className="btn quiet" onClick={() => onOpenArtifact(candidate.path)} type="button">Open source</button><button className="btn primary" disabled={busy || pendingPath === candidate.path || included} onClick={() => void include(candidate.path)} type="button">{pendingPath === candidate.path ? "Including…" : included ? "Included" : "Include in next inquiry"}</button></div>
      </article>;
    })}</div> : null}
    <style jsx>{`
      .reuse-panel { min-width: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised); padding: 18px; color: var(--ink); }
      .reuse-panel__head p, .reuse-source { margin: 7px 0 0; color: var(--ink-3); font: 400 13.5px/1.45 var(--sans); overflow-wrap: anywhere; }
      .reuse-search { display: grid; gap: 7px; margin-top: 16px; }
      .reuse-search__row { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; }
      .reuse-list { display: grid; gap: 12px; margin-top: 16px; }
      .reuse-item { min-width: 0; border: 1px solid var(--line-soft); border-radius: 8px; padding: 14px; background: var(--paper); }
      .reuse-item__head { display: flex; align-items: start; justify-content: space-between; gap: 12px; }
      .reuse-item h3 { margin: 0; }
      .reuse-reading { margin: 13px 0 0; font-size: 15px; }
      .reuse-snippet { margin: 12px 0 0; padding-left: 12px; border-left: 2px solid var(--line-soft); color: var(--ink-3); font: italic 400 15px/1.55 var(--serif); }
      .reuse-differences { margin-top: 12px; color: var(--ink-2); font: 400 14px/1.5 var(--sans); }
      .reuse-differences ul { margin: 6px 0 0; padding-left: 20px; }
      .reuse-source-detail { margin-top: 10px; color: var(--ink-3); font-size: 12px; } .reuse-source-detail summary { cursor: pointer; font-weight: 600; } .reuse-source-detail p { margin: 6px 0 0; overflow-wrap: anywhere; }
      .reuse-notice { display: flex; gap: 8px; align-items: center; margin: 14px 0 0; }
      .empty-state { margin-top: 16px; }
      @media (max-width: 520px) { .reuse-panel { padding: 14px; } .reuse-search__row { grid-template-columns: 1fr; } .reuse-search__row .btn { width: 100%; } .reuse-item__head { flex-direction: column; } }
      @media (prefers-reduced-motion: reduce) { .reuse-panel * { transition: none !important; animation: none !important; } }
    `}</style>
  </section>;
}

