    <style jsx>{`
      .watch-panel { min-width: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised); padding: 18px; }
      .watch-help { margin: 7px 0 0; color: var(--ink-3); font: 400 13.5px/1.5 var(--sans); }
