frontend/components/workspace/DecisionMa:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties, PointerEvent as ReactPointerEvent } from "react";
import type { ConversationTarget } from "@/lib/workspaceTypes";
import type { DecisionMapEdge, DecisionMapLayout, DecisionMapLayoutNode, DecisionMapNode, DecisionMapOutlineProps, DecisionMapProps, ScenarioLaunchIntent } from "@/lib/decisionMapTypes";
import { decisionMapFitScale, edgeStateLabel, nodeStateLabel, relationshipLabel, visibleDecisionMap } from "@/lib/decisionMapLayout";

const shell: CSSProperties = { display: "grid", gap: 14, minWidth: 0, maxWidth: "100%" };
const card: CSSProperties = { border: "1px solid var(--line)", borderRadius: "var(--radius)", background: "var(--raised)", padding: 14, minWidth: 0, maxWidth: "100%" };
const muted: CSSProperties = { margin: "4px 0 0", color: "var(--ink-3)", font: "400 13.5px/1.5 var(--sans)", overflowWrap: "anywhere" };
const outlineText: CSSProperties = { minWidth: 0, maxWidth: "100%", overflowWrap: "anywhere", wordBreak: "break-word" };
const outlineControl: CSSProperties = { ...outlineText, boxSizing: "border-box", whiteSpace: "normal" };
const MIN_MANUAL_ZOOM = 0.1;
const MAX_MANUAL_ZOOM = 2;
const MAX_CANVAS_LABEL_LENGTH = 56;
const MAX_CANVAS_EDGE_LABEL_LENGTH = 22;

function normalizedNodeState(node: DecisionMapNode): string {
  return node.state.trim().toLowerCase().replace(/[\s-]+/g, "_");
}

function canvasLabel(label: string): string {
  if (label.length <= MAX_CANVAS_LABEL_LENGTH) return label;
  return `${label.slice(0, MAX_CANVAS_LABEL_LENGTH - 1).trimEnd()}…`;
}

function edgeLabel(edge: DecisionMapEdge): string {
  return edge.label.trim() || relationshipLabel(edge.relationship);
}

function canvasEdgeLabel(edge: DecisionMapEdge): string {
  const label = edgeLabel(edge);
  if (label.length <= MAX_CANVAS_EDGE_LABEL_LENGTH) return label;
  return `${label.slice(0, MAX_CANVAS_EDGE_LABEL_LENGTH - 1).trimEnd()}…`;
}

function stateStyle(node: DecisionMapNode): CSSProperties {
  const state = normalizedNodeState(node);
  if (node.missing_reference || state === "missing" || state === "failed") return { background: "var(--failure-wash)", borderColor: "var(--failure-edge)", color: "var(--failure)" };
  if (state === "unknown") return { background: "var(--attention-wash)", borderColor: "var(--attention-edge)", color: "var(--attention-deep)" };
  if (node.hypothetical || state === "hypothetical" || state === "agent" || state === "agent_analysis" || state === "proposed") return { background: "var(--agent-wash)", borderColor: "var(--agent-edge)", color: "var(--agent)" };
  if (state === "complete" || state === "completed" || state === "done" || state === "resolved" || state === "recorded") return { background: "var(--healthy-wash)", borderColor: "var(--healthy-tint)", color: "var(--healthy)" };
  return { background: "var(--rail)", borderColor: "var(--line)", color: "var(--ink-3)" };
}

function mapConversationTarget(node: DecisionMapNode, matterId: string): ConversationTarget {
  const issueId = node.record_type === "issue" ? node.record_id : node.issue_ids?.[0] ?? null;
  return { matter_id: matterId, issue_id: issueId };
}

function scenarioIntent(node: DecisionMapNode): ScenarioLaunchIntent {
  return {
    issue_id: node.record_type === "issue" ? node.record_id : node.issue_ids?.[0] ?? null,
    question_id: node.record_type === "question" ? node.record_id : null,
    fact_id: node.record_type === "fact" ? node.record_id : null,
  };
}

function backIssueId(node: DecisionMapNode, fallback: string | null | undefined): string | null {
  return node.record_type === "issue" ? node.record_id : node.issue_ids?.[0] ?? fallback ?? null;
}

function edgeCoordinates(edge: DecisionMapEdge, nodes: readonly DecisionMapLayoutNode[]) {
  const from = nodes.find((node) => node.node_id === edge.from_node_id);
  const to = nodes.find((node) => node.node_id === edge.to_node_id);
  if (!from || !to) return null;
  const x1 = from.x + from.width;
  const y1 = from.y + from.height / 2;
  const x2 = to.x;
  const y2 = to.y + to.height / 2;
  return { x1, y1, x2, y2, labelX: (x1 + x2) / 2, labelY: (y1 + y2) / 2 };
}

function CanvasNode({ node, selected, onSelect }: { node: DecisionMapLayoutNode; selected: boolean; onSelect: (nodeId: string) => void }) {
  const state = stateStyle(node);
  return <button aria-current={selected ? "true" : undefined} aria-label={`${node.label}. ${node.record_type}. ${nodeStateLabel(node)}.`} className="btn quiet" onClick={() => onSelect(node.node_id)} style={{ position: "absolute", left: node.x, top: node.y, width: node.width, height: node.height, minHeight: 0, boxSizing: "border-box", overflow: "hidden", padding: 11, textAlign: "left", whiteSpace: "normal", overflowWrap: "anywhere", border: `2px solid ${selected ? "var(--ink)" : state.borderColor}`, background: state.background, color: "var(--ink)", boxShadow: selected ? "0 0 0 2px var(--ink)" : undefined }} title={node.label} type="button">
    <span className="record-meta" style={{ color: state.color, display: "block" }}>{node.record_type}</span>
    <strong style={{ display: "block", font: "600 15px/1.25 var(--serif)", marginTop: 4, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{canvasLabel(node.label)}</strong>
    <span style={{ color: state.color, display: "block", font: "600 12px/1.35 var(--sans)", marginTop: 7 }}>{nodeStateLabel(node)}</span>
  </button>;
}

function MapCanvas({ layout, selectedNodeId, onSelectNode, scale, offset, onPointerDown, onPointerMove, onPointerUp }: { layout: DecisionMapLayout; selectedNodeId: string | null; onSelectNode: (nodeId: string) => void; scale: number; offset: { x: number; y: number }; onPointerDown: (event: ReactPointerEvent<HTMLDivElement>) => void; onPointerMove: (event: ReactPointerEvent<HTMLDivElement>) => void; onPointerUp: () => void }) {
  const canvasWidth = Math.max(layout.width, 360);
  const canvasHeight = Math.max(layout.height, 380);
  return <div aria-label="Decision map visual" style={{ minHeight: 420, maxWidth: "100%", overflow: "hidden", position: "relative", border: "1px solid var(--line-faint)", borderRadius: 8, background: "var(--paper)", touchAction: "none" }}>
    <div onPointerCancel={onPointerUp} onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} style={{ position: "absolute", width: canvasWidth, height: canvasHeight, transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`, transformOrigin: "0 0" }}>
      <svg aria-hidden="true" height={canvasHeight} style={{ inset: 0, overflow: "visible", pointerEvents: "none", position: "absolute" }} width={canvasWidth}>
        {layout.edges.map((edge) => {
          const line = edgeCoordinates(edge, layout.nodes);
          if (!line) return null;
          const missing = edge.state === "missing";
          const unknown = edge.state === "unknown";
          return <g key={edge.edge_id}>
            <line stroke={missing ? "var(--failure)" : unknown ? "var(--attention)" : "var(--ink-5)"} strokeDasharray={unknown || edge.state === "hypothetical" || edge.state === "historical" ? "5 5" : undefined} strokeWidth="1.5" x1={line.x1} x2={line.x2} y1={line.y1} y2={line.y2} />
            <rect fill="var(--paper)" height="30" rx="4" width="120" x={line.labelX - 60} y={line.labelY - 15} />
            <text fill="var(--ink-3)" fontFamily="var(--sans)" fontSize="11" textAnchor="middle" x={line.labelX} y={line.labelY - 1}>{canvasEdgeLabel(edge)}</text>
            <text fill={missing ? "var(--failure)" : unknown ? "var(--attention-deep)" : "var(--ink-4)"} fontFamily="var(--sans)" fontSize="10" textAnchor="middle" x={line.labelX} y={line.labelY + 11}>{edgeStateLabel(edge)}</text>
          </g>;
        })}
      </svg>
      {layout.nodes.map((node) => <CanvasNode key={node.node_id} node={node} onSelect={onSelectNode} selected={node.node_id === selectedNodeId} />)}
    </div>
  </div>;
}

/** The outline deliberately receives the exact visible arrays used by the visual map. */
export function DecisionMapOutline({ nodes, edges, selectedNodeId, onSelectNode, onDiscuss, onOpenDocument, matterId }: DecisionMapOutlineProps & { matterId?: string }) {
  void onOpenDocument;
  return <section aria-label="Decision map outline" style={card}>
    <h2 className="section-heading" style={{ margin: 0 }}>Map outline</h2>
    <p style={muted}>Use this list to reach every visible record and relationship without the visual map.</p>
    {!nodes.length ? <p style={{ ...muted, ...outlineText }}>No saved records are visible in this scope.</p> : <ul style={{ display: "grid", gap: 8, listStyle: "none", margin: "12px 0 0", padding: 0, ...outlineText }}>{nodes.map((node) => <li key={node.node_id} style={{ border: "1px solid var(--line-faint)", borderRadius: 7, padding: 10, ...outlineText }}>
      <button aria-current={selectedNodeId === node.node_id ? "true" : undefined} className="btn quiet tiny" onClick={() => onSelectNode(node.node_id)} style={{ padding: 0, textAlign: "left", width: "100%", ...outlineControl }} type="button"><strong style={{ display: "block", ...outlineText }}>{node.label}</strong><span style={{ ...muted, ...outlineText, display: "block" }}>{node.record_type} · {nodeStateLabel(node)}</span></button>
      {matterId ? <button className="btn quiet tiny" onClick={() => onDiscuss(mapConversationTarget(node, matterId))} style={{ marginTop: 7, ...outlineControl }} type="button">Discuss this path</button> : null}
    </li>)}</ul>}
    <h3 className="section-heading" style={{ margin: "16px 0 0" }}>Visible relationships</h3>
    {!edges.length ? <p style={{ ...muted, ...outlineText }}>No saved relationships are visible in this scope.</p> : <ul style={{ display: "grid", gap: 6, listStyle: "none", margin: "9px 0 0", padding: 0, ...outlineText }}>{edges.map((edge) => {
      const from = nodes.find((node) => node.node_id === edge.from_node_id)?.label ?? edge.from_node_id;
      const to = nodes.find((node) => node.node_id === edge.to_node_id)?.label ?? edge.to_node_id;
      return <li key={edge.edge_id} style={{ ...muted, ...outlineText }}><strong>{from}</strong> {edgeLabel(edge)} <strong>{to}</strong> · {edgeStateLabel(edge)}</li>;
    })}</ul>}
  </section>;
}

function useNarrowScreen() {
  const [narrow, setNarrow] = useState(false);
  useEffect(() => {
    const query = window.matchMedia("(max-width: 767px)");
    const update = () => setNarrow(query.matches);
    update(); query.addEventListener("change", update); return () => query.removeEventListener("change", update);
  }, []);
  return narrow;
}

export default function DecisionMap({ snapshot, layout, selectedNodeId, scope, busy = false, error = null, onSelectNode, onScopeChange, onFit, onOpenDocument, onDiscuss, onTryDifferentAssumption, scenarioPanel, selectedNodeDetails, onBackToIssue }: DecisionMapProps) {
  // Node data has no document target. C6 supplies a resolved target through selectedNodeDetails.
  void onOpenDocument;
  const visible = useMemo(() => visibleDecisionMap(layout, snapshot, scope, selectedNodeId), [layout, selectedNodeId, scope, snapshot]);
  const selectedNode = visible.nodes.find((node) => node.node_id === selectedNodeId) ?? layout.nodes.find((node) => node.node_id === selectedNodeId) ?? null;
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const dragging = useRef<{ x: number; y: number; offsetX: number; offsetY: number } | null>(null);
  const viewport = useRef<HTMLDivElement | null>(null);
  const narrow = useNarrowScreen();
  const matterId = snapshot.matter_id;
  const select = (nodeId: string) => onSelectNode(nodeId);
  const reset = () => { setScale(1); setOffset({ x: 0, y: 0 }); };
  const fit = () => {
    const width = viewport.current?.clientWidth ?? visible.width;
    const height = viewport.current?.clientHeight ?? 420;
    setScale(decisionMapFitScale(visible, width, height));
    setOffset({ x: 12, y: 12 });
    onFit();
  };
  const startPan = (event: ReactPointerEvent<HTMLDivElement>) => {
    if ((event.target as HTMLElement).closest("button")) return;
    dragging.current = { x: event.clientX, y: event.clientY, offsetX: offset.x, offsetY: offset.y };
    event.currentTarget.setPointerCapture(event.pointerId);
  };
  const movePan = (event: ReactPointerEvent<HTMLDivElement>) => {
    const start = dragging.current;
    if (!start) return;
    setOffset({ x: start.offsetX + event.clientX - start.x, y: start.offsetY + event.clientY - start.y });
  };
  const stopPan = () => { dragging.current = null; };
  const outline = <DecisionMapOutline edges={visible.edges} matterId={matterId} nodes={visible.nodes} onDiscuss={onDiscuss} onOpenDocument={() => undefined} onSelectNode={select} selectedNodeId={selectedNodeId} />;
  const outlinePresentation = scope === "whole_matter" ? <details style={card}><summary className="btn quiet" style={outlineControl}>Map outline ({visible.nodes.length} records)</summary><div style={{ marginTop: 10, ...outlineText }}>{outline}</div></details> : outline;
  const visual = <section aria-label="Decision map controls and visual" style={card}><div style={{ alignItems: "center", display: "flex", flexWrap: "wrap", gap: 8, justifyContent: "space-between" }}><div><h2 className="section-heading" style={{ margin: 0 }}>Decision map</h2><p style={muted}>{scope === "whole_matter" ? "Whole matter" : "Local neighborhood"} · {visible.nodes.length} visible records</p></div><div className="btn-row"><button aria-pressed={scope === "neighborhood"} className="btn quiet tiny" disabled={busy} onClick={() => onScopeChange("neighborhood")} type="button">Local neighborhood</button><button aria-pressed={scope === "whole_matter"} className="btn quiet tiny" disabled={busy} onClick={() => onScopeChange("whole_matter")} type="button">Show whole matter</button></div></div><div aria-label="Map viewport controls" className="btn-row" style={{ marginTop: 10 }}><button className="btn quiet tiny" disabled={scale <= MIN_MANUAL_ZOOM} onClick={() => setScale((value) => Math.max(MIN_MANUAL_ZOOM, value - 0.1))} type="button">Zoom out</button><span aria-live="polite" className="record-meta">Zoom {Math.round(scale * 100)}%</span><button className="btn quiet tiny" disabled={scale >= MAX_MANUAL_ZOOM} onClick={() => setScale((value) => Math.min(MAX_MANUAL_ZOOM, value + 0.1))} type="button">Zoom in</button><button className="btn quiet tiny" onClick={fit} type="button">Fit map</button><button className="btn quiet tiny" onClick={reset} type="button">Reset view</button></div><p style={muted}>Select a record for details. Drag empty space to pan. The outline below has the same records and relationships.</p><div ref={viewport} style={{ marginTop: 10 }}><MapCanvas layout={visible} offset={offset} onPointerDown={startPan} onPointerMove={movePan} onPointerUp={stopPan} onSelectNode={select} scale={scale} selectedNodeId={selectedNodeId} /></div></section>;

  return <section aria-busy={busy || undefined} aria-label="Decision map" style={shell}>
    {error ? <p className="warning-callout" role="status" style={{ margin: 0 }}>{error}</p> : null}
    {narrow ? <details><summary className="btn quiet">Show visual map</summary><div style={{ marginTop: 10 }}>{visual}</div></details> : visual}
    {selectedNode ? <aside aria-label="Selected map record" style={card}><div style={{ alignItems: "start", display: "flex", flexWrap: "wrap", gap: 10, justifyContent: "space-between" }}><div><span className="record-meta">Selected {selectedNode.record_type}</span><h2 className="section-heading" style={{ margin: "4px 0 0" }}>{selectedNode.label}</h2><p style={muted}>{nodeStateLabel(selectedNode)}</p></div><button className="btn quiet tiny" onClick={() => onSelectNode(null)} type="button">Clear selection</button></div>{normalizedNodeState(selectedNode) === "unknown" ? <p style={muted}>This condition is unknown. It does not select an active path.</p> : null}{selectedNode.detail ? <p style={muted}>{selectedNode.detail}</p> : null}{selectedNode.claim_ids?.length ? <p style={muted}>Claim references: {selectedNode.claim_ids.join(", ")}. Source details are shown when a saved document target is available.</p> : null}{selectedNodeDetails}<div className="btn-row" style={{ marginTop: 12 }}><button className="btn quiet tiny" onClick={() => onDiscuss(mapConversationTarget(selectedNode, matterId))} type="button">Discuss this path</button><button className="btn agent tiny" onClick={() => onTryDifferentAssumption(scenarioIntent(selectedNode))} type="button">Try a different assumption</button>{backIssueId(selectedNode, snapshot.selected_issue_id) ? <button className="btn quiet tiny" onClick={() => onBackToIssue(backIssueId(selectedNode, snapshot.selected_issue_id)!)} type="button">Back to issue</button> : null}</div></aside> : <p style={muted}>Select a record to see its saved detail and actions.</p>}
    {scenarioPanel}
    {outlinePresentation}
  </section>;
}

frontend/app/matters/[matterId]/decision:
"use client";

import Link from "next/link";
import { useParams, useSearchParams } from "next/navigation";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import AppShell from "@/components/AppShell";
import ChatPanel from "@/components/ChatPanel";
import DecisionMap from "@/components/workspace/DecisionMap";
import ScenarioPanel from "@/components/workspace/ScenarioPanel";
import ClaimMarkdown from "@/components/workspace/ClaimMarkdown";
import EvidenceDrawer from "@/components/workspace/EvidenceDrawer";
import ReferencePreview from "@/components/workspace/ReferencePreview";
import { useContinuityIdentity, continuityKey } from "@/lib/continuityApi";
import {
  getFile,
  getConversations,
  getMatter,
  getChatRun,
  rawFileUrl,
  saveWorkProductDraft,
} from "@/lib/api";
import {
  adoptWorkspaceScenario,
  analyzeWorkspaceScenario,
  getDecisionMap,
  getWorkspace,
  documentForReferenceTarget,
  invalidateReferenceResult,
  latestReferenceResult,
  preferredConversationId,
  referenceDestination,
  resolveWorkspaceDocument,
  saveWorkspaceScenario,
  workspaceCommand,
} from "@/lib/workspaceApi";
import { layoutDecisionMap } from "@/lib/decisionMapLayout";
import type {
  DecisionMapSnapshot,
  ScenarioLaunchIntent,
} from "@/lib/decisionMapTypes";
import type { MatterDetail } from "@/lib/types";
import type {
  ConversationTarget,
  ClaimEvidence,
  ContextSelection,
  DocumentIdentity,
  DocumentReferenceTarget,
  ReferenceOrigin,
  Scenario,
  ScenarioAdoptCommand,
  ScenarioAnalyzeCommand,
  WorkspaceActionResult,
  WorkspaceSnapshot,
} from "@/lib/workspaceTypes";

const selectionKey = (matterId: string) =>
  `themis:decision-map:${matterId}:selection`;

export default function MatterDecisionMapPage() {
  const { matterId } = useParams<{ matterId: string }>();
  const query = useSearchParams();
  const { identity } = useContinuityIdentity();
  const requestedIssue = query.get("issue");
  const requestedConversation = query.get("conversation");
  const backHref =
    query.get("back") || `/matters/${encodeURIComponent(matterId)}`;
  const [detail, setDetail] = useState<MatterDetail | null>(null);
  const [workspace, setWorkspace] = useState<WorkspaceSnapshot | null>(null);
  const [snapshot, setSnapshot] = useState<DecisionMapSnapshot | null>(null);
  const [scenarios, setScenarios] = useState<Scenario[]>([]);
  const [facts, setFacts] = useState<Array<{ fact_id: string; text: string; state?: string }>>([]);
  const [selectedScenarioId, setSelectedScenarioId] = useState<string | null>(
    null,
  );
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [scope, setScope] = useState<"neighborhood" | "whole_matter">(
    "neighborhood",
  );
  const [conversationTarget, setConversationTarget] =
    useState<ConversationTarget | null>(null);
  const [initialConversationId, setInitialConversationId] = useState<
    string | null
  >(null);
  const matterReturnHref = (issueId?: string | null) => {
    let href = backHref;
    for (const [key, value] of [
      ["issue", issueId],
      ["conversation", initialConversationId],
    ] as const) {
      if (!value) continue;
      href += `${href.includes("?") ? "&" : "?"}${key}=${encodeURIComponent(value)}`;
    }
    return href;
  };
  const issueBackHref = matterReturnHref(requestedIssue);
  const [referenceTarget, setReferenceTarget] =
    useState<DocumentReferenceTarget | null>(null);
  const [referenceDocument, setReferenceDocument] =
    useState<DocumentIdentity | null>(null);
  const [referenceError, setReferenceError] = useState("");
  const [activeEvidence, setActiveEvidence] = useState<ClaimEvidence | null>(null);
  const [launchIntent, setLaunchIntent] = useState<ScenarioLaunchIntent | null>(
    null,
  );
  const [chatSeed, setChatSeed] = useState({ text: "", revision: 0 });
  const [scenarioLaunchKey, setScenarioLaunchKey] = useState(0);
  const [error, setError] = useState("");
  const referenceGeneration = useRef(0);

  const load = useCallback(async () => {
    const [matter, savedWorkspace, map, savedScenarios, reuse, conversations] = await Promise.all([
      getMatter(matterId),
      getWorkspace(matterId),
      getDecisionMap(matterId),
      workspaceCommand<Scenario[]>(matterId, "/scenarios"),
      workspaceCommand<{
        records: { facts: Array<{ fact_id: string; text: string; status?: string }> };
      }>(matterId, "/reuse"),
      getConversations(matterId),
    ]);
    setDetail(matter);
    setInitialConversationId(
      preferredConversationId(
        conversations.conversations.map((item) => item.conversation_id),
        requestedConversation,
        matter.intake_conversation_id,
      ),
    );
    setWorkspace(savedWorkspace);
    setSnapshot(map);
    setScenarios(savedScenarios);
    setFacts(
      reuse.records.facts
        .filter((fact) => fact.status !== "superseded")
        .map((fact) => ({
          fact_id: fact.fact_id,
          text: fact.text,
          state: fact.status,
        })),
    );
    const savedSelection = window.sessionStorage.getItem(
      selectionKey(matterId),
    );
    const initial = requestedIssue ? `issue:${requestedIssue}` : savedSelection;
    setSelectedNodeId(
      initial && map.nodes.some((node) => node.node_id === initial)
        ? initial
        : (map.nodes[0]?.node_id ?? null),
    );
  }, [matterId, requestedConversation, requestedIssue]);

  useEffect(() => {
    void load().catch((cause) =>
      setError(
        cause instanceof Error
          ? cause.message
          : "The decision map could not load.",
      ),
    );
  }, [load]);
  useEffect(() => {
    if (selectedNodeId)
      window.sessionStorage.setItem(selectionKey(matterId), selectedNodeId);
  }, [matterId, selectedNodeId]);

  const contextKey = identity
    ? continuityKey(
        identity.roster.vault_key,
        identity.actor.person_id,
        matterId,
        "panels",
      )
    : `decision-map:${matterId}`;
  const selectedNode =
    snapshot?.nodes.find((node) => node.node_id === selectedNodeId) ?? null;
  const selectedIssue =
    workspace?.issues?.find(
      (issue) =>
        issue.issue_id ===
        (selectedNode?.record_type === "issue"
          ? selectedNode.record_id
          : selectedNode?.issue_ids?.[0]),
    ) ?? null;
  const claims = (workspace?.claims ?? []).filter(
    (claim) =>
      selectedNode?.claim_ids?.includes(claim.claim_id) &&
      (!selectedIssue?.claim_output_revisions?.[claim.claim_id] ||
        selectedIssue.claim_output_revisions[claim.claim_id] ===
          claim.output_revision),
  );
  const layout = useMemo(
    () => (snapshot ? layoutDecisionMap(snapshot) : null),
    [snapshot],
  );

  async function openReference(target: DocumentReferenceTarget) {
    invalidateReferenceResult(referenceGeneration);
    const knownDocument = documentForReferenceTarget(
      workspace?.documents ?? [],
      target,
    );
    if (knownDocument && referenceDestination(knownDocument) === "editor") {
      setReferenceTarget(null);
      setReferenceDocument(null);
      window.location.href = `/matters/${encodeURIComponent(matterId)}?file=${encodeURIComponent(knownDocument.path)}`;
      return;
    }
    setReferenceTarget(target);
    setReferenceDocument(null);
    setReferenceError("");
    try {
      const result = await latestReferenceResult(
        referenceGeneration,
        () => resolveWorkspaceDocument(matterId, target),
      );
      if (!result) return;
      if (result.document && referenceDestination(result.document) === "editor") {
        setReferenceTarget(null);
        setReferenceDocument(null);
        window.location.href = `/matters/${encodeURIComponent(matterId)}?file=${encodeURIComponent(result.document.path)}`;
        return;
      }
      setReferenceDocument(result.document ?? null);
      setReferenceError(result.message ?? "");
    } catch (cause) {
      setReferenceDocument(null);
      setReferenceError(
        cause instanceof Error
          ? cause.message
          : "The reference is unavailable.",
      );
    }
  }

  async function useInRequest(document: DocumentIdentity) {
    const current = await workspaceCommand<{
      selections: ContextSelection[];
      revision: string;
    }>(matterId, "/context");
    await workspaceCommand(matterId, "/context", "PUT", {
      selections: [
        ...current.selections.filter(
          (item) => item.reference_id !== document.document_id,
        ),
        {
          reference_id: document.document_id,
          path: document.path,
          role: "source_file",
          selected: true,
          revision: document.revision,
        },
      ],
      expected_revision: current.revision,
    });
    setError("");
  }

  async function createWorkingCopy(document: DocumentIdentity) {
    const source = await getFile(document.path);
    const saved = await saveWorkProductDraft(
      matterId,
      `${document.title} working copy`,
      source.content,
      `map-working-copy:${document.document_id}:${document.revision}:${crypto.randomUUID()}`,
    );
    window.location.href = `/matters/${encodeURIComponent(matterId)}?view=draft&file=${encodeURIComponent(saved.vault_path)}`;
  }

  async function analyzeScenario(
    scenarioId: string,
    command: ScenarioAnalyzeCommand,
  ): Promise<WorkspaceActionResult> {
    let run = await analyzeWorkspaceScenario(matterId, scenarioId, command);
    while (["queued", "running"].includes(run.state)) {
      await new Promise((resolve) => window.setTimeout(resolve, 1000));
      run = await getChatRun(matterId, run.run_id);
    }
    const saved = await workspaceCommand<Scenario[]>(matterId, "/scenarios");
    setScenarios(saved);
    return {
      run_id: run.run_id,
      state: run.response?.operation_results.some(
        (item) =>
          item.operation === "save_scenario_analysis" &&
          item.status === "changed",
      )
        ? "saved"
        : "not_saved",
    };
  }

  function returnFromReference(origin: ReferenceOrigin) {
    invalidateReferenceResult(referenceGeneration);
    setReferenceTarget(null);
    setReferenceDocument(null);
    setReferenceError("");
    if (
      origin.record_id &&
      snapshot?.nodes.some((node) => node.node_id === origin.record_id)
    )
      setSelectedNodeId(origin.record_id);
    requestAnimationFrame(() => {
      if (origin.scroll_offset != null)
        window.scrollTo({ top: origin.scroll_offset });
      if (origin.focus_id) document.getElementById(origin.focus_id)?.focus();
    });
  }

  function tryAssumption(intent: ScenarioLaunchIntent) {
    const node = snapshot?.nodes.find(
      (item) =>
        item.record_id === intent.question_id ||
        item.record_id === intent.fact_id ||
        item.record_id === intent.issue_id,
    );
    const adjacentFactIds = snapshot
      ? snapshot.edges
          .filter(
            (edge) =>
              edge.from_node_id === node?.node_id ||
              edge.to_node_id === node?.node_id,
          )
          .map((edge) =>
            edge.from_node_id === node?.node_id
              ? edge.to_node_id
              : edge.from_node_id,
          )
          .map((nodeId) => snapshot.nodes.find((item) => item.node_id === nodeId))
          .filter((item) => item?.record_type === "fact")
          .map((item) => item!.record_id)
      : [];
    const linkedFactId =
      intent.fact_id ||
      (adjacentFactIds.length === 1 ? adjacentFactIds[0] : null);
    setSelectedScenarioId(null);
    setScenarioLaunchKey((current) => current + 1);
    setLaunchIntent({ ...intent, fact_id: linkedFactId });
    const linkedIssue = intent.issue_id || node?.issue_ids?.[0] || null;
    setConversationTarget({
      matter_id: matterId,
      issue_id: linkedIssue,
      business_question_revision: workspace?.question.revision,
    });
    if (intent.question_id)
      setChatSeed((current) => ({
        text: `Explore a different assumption for this saved question (${intent.question_id}): ${node?.label ?? "selected question"}. ${linkedFactId ? `Use its linked reported fact ${linkedFactId}.` : "No single linked reported fact is known; keep that uncertainty visible."} Keep its linked issue context.`,
        revision: current.revision + 1,
      }));
  }

  if (!detail || !workspace || !snapshot || !layout)
    return (
      <AppShell>
        <main className="page">
          <p role="status">{error || "Loading the saved decision map…"}</p>
        </main>
      </AppShell>
    );

  return (
    <AppShell>
      <main className="page decision-map-page">
        <header className="decision-map-page__head">
          <div>
            <Link href={issueBackHref}>
              Back to matter{requestedIssue ? " issue" : ""}
            </Link>
            <span className="record-meta">Saved matter records</span>
            <h1>{detail.title} · Decision map</h1>
            <p>{workspace.question.text}</p>
          </div>
          <span className="state-label state-agent">
            Agent analysis stays proposed
          </span>
        </header>
        {error ? (
          <p className="warning-callout" role="status">
            {error}
          </p>
        ) : null}
        {referenceTarget ? (
          <ReferencePreview
            target={referenceTarget}
            document={referenceDocument}
            error={referenceError}
            onBack={returnFromReference}
            onOpenOriginal={(document) =>
              window.open(
                rawFileUrl(document.original_path || document.path),
                "_blank",
                "noopener,noreferrer",
              )
            }
            onUseInRequest={(document) =>
              void useInRequest(document).catch((cause) =>
                setError(
                  cause instanceof Error
                    ? cause.message
                    : "The source could not be added.",
                ),
              )
            }
            onCreateWorkingCopy={(document) =>
              void createWorkingCopy(document).catch((cause) =>
                setError(
                  cause instanceof Error
                    ? cause.message
                    : "The working copy could not be created.",
                ),
              )
            }
          />
        ) : null}
        <EvidenceDrawer
          evidence={activeEvidence}
          open={Boolean(activeEvidence)}
          onClose={() => setActiveEvidence(null)}
          onOpenArtifact={(path) => {
            const document = workspace.documents?.find(
              (item) => item.path === path,
            );
            if (document) {
              setActiveEvidence(null);
              void openReference({
                document_id: document.document_id,
                path: document.path,
                revision: document.revision,
                locator: activeEvidence?.locator,
                available_excerpt: activeEvidence?.available_excerpt,
                exact_passage_available: Boolean(
                  activeEvidence?.available_excerpt || activeEvidence?.locator,
                ),
                origin: {
                  surface: "decision_map",
                  record_id: selectedNodeId,
                  scroll_offset: window.scrollY,
                },
              });
            } else if (/^https?:\/\//i.test(path)) {
              window.open(path, "_blank", "noopener,noreferrer");
            }
          }}
        />
        <DecisionMap
          snapshot={snapshot}
          layout={layout}
          selectedNodeId={selectedNodeId}
          scope={scope}
          onSelectNode={setSelectedNodeId}
          onScopeChange={setScope}
          onFit={() => undefined}
          onOpenDocument={(target) => void openReference(target)}
          onDiscuss={(target) => {
            setConversationTarget({
              ...target,
              business_question_revision: workspace.question.revision,
            });
            requestAnimationFrame(() => {
              const section = document.getElementById("decision-map-discussion");
              section?.scrollIntoView({ behavior: "smooth", block: "start" });
              section?.querySelector<HTMLTextAreaElement>("textarea")?.focus();
            });
          }}
          onTryDifferentAssumption={tryAssumption}
          onBackToIssue={(issueId) => {
            window.location.href = matterReturnHref(issueId);
          }}
          selectedNodeDetails={
            claims.length ? (
              <div className="decision-map-claims">
                {claims.map((claim) => (
                  <article key={`${claim.claim_id}:${claim.output_revision}`}>
                    <ClaimMarkdown
                      text={claim.text}
                      claims={[claim]}
                      documents={workspace.documents ?? []}
                      surface="decision_map"
                      recordId={selectedNodeId}
                      onOpenEvidence={setActiveEvidence}
                      onOpenDocument={(target) => void openReference(target)}
                    />
                    {claim.applicability ? (
                      <p className="record-meta">
                        Applies to {claim.applicability.regulated_actor || "the saved actor"}
                        {claim.applicability.jurisdiction
                          ? ` in ${claim.applicability.jurisdiction}`
                          : ""}
                        {claim.applicability.explanation
                          ? `. ${claim.applicability.explanation}`
                          : ""}
                      </p>
                    ) : null}
                    <div className="inline-actions">
                      {claim.evidence.map((evidence) => (
                        <button
                          className="secondary"
                          key={`${evidence.source_id}:${evidence.locator ?? "source"}`}
                          onClick={() => setActiveEvidence(evidence)}
                          type="button"
                        >
                          Review {evidence.source_label || evidence.source_id}
                          {evidence.locator ? ` · ${evidence.locator}` : ""}
                        </button>
                      ))}
                      {!claim.evidence.length ? (
                        <span className="state-label state-attention">No saved support</span>
                      ) : null}
                    </div>
                  </article>
                ))}
              </div>
            ) : undefined
          }
          scenarioPanel={
            launchIntent ? (
              <ScenarioPanel
                claims={workspace?.claims ?? []}
                key={scenarioLaunchKey}
                matterId={matterId}
                scenarios={scenarios}
                selectedScenarioId={selectedScenarioId}
                currentRevisions={workspace.source_revisions ?? {}}
                facts={facts}
                initialIssueId={
                  launchIntent.issue_id || selectedNode?.issue_ids?.[0]
                }
                initialFactId={launchIntent.fact_id}
                onSelect={setSelectedScenarioId}
                onCreate={async (command) => {
                  const saved = await workspaceCommand<Scenario>(
                    matterId,
                    "/scenarios",
                    "POST",
                    {
                      scenario: command,
                      source_action_key: command.source_action_key,
                    },
                  );
                  setScenarios((current) => [
                    ...current.filter(
                      (item) => item.scenario_id !== saved.scenario_id,
                    ),
                    saved,
                  ]);
                  return saved;
                }}
                onAnalyze={analyzeScenario}
                onAdopt={async (
                  scenarioId: string,
                  command: ScenarioAdoptCommand,
                ) => {
                  const receipt = await adoptWorkspaceScenario(
                    matterId,
                    scenarioId,
                    command,
                  );
                  await load();
                  return receipt;
                }}
                onSaveScenario={async (scenario, title, revision, key) => {
                  const saved = await saveWorkspaceScenario(
                    matterId,
                    scenario,
                    title,
                    revision,
                    key,
                  );
                  setScenarios((current) => [
                    ...current.filter(
                      (item) => item.scenario_id !== saved.scenario_id,
                    ),
                    saved,
                  ]);
                  return saved;
                }}
                onOpenClaim={(claimId) =>
                  setSelectedNodeId(
                    snapshot.nodes.find((node) =>
                      node.claim_ids?.includes(claimId),
                    )?.node_id ?? selectedNodeId,
                  )
                }
                onOpenArtifact={(path) => {
                  const document = workspace.documents?.find(
                    (item) => item.path === path,
                  );
                  if (document)
                    void openReference({
                      document_id: document.document_id,
                      path: document.path,
                      revision: document.revision,
                      origin: {
                        surface: "decision_map",
                        record_id: selectedNodeId,
                      },
                    });
                }}
              />
            ) : undefined
          }
        />
        <section className="decision-map-discussion" id="decision-map-discussion">
          <h2>Discuss the selected path</h2>
          <ChatPanel
            contextKey={contextKey}
            matterId={matterId}
            matterTitle={detail.title}
            activeFile={null}
            activeAgentId={detail.active_agent_id}
            initialConversationId={initialConversationId}
            onConversationChange={(conversationId) => {
              if (conversationId) setInitialConversationId(conversationId);
            }}
            target={
              conversationTarget ?? {
                matter_id: matterId,
                issue_id: selectedIssue?.issue_id,
                business_question_revision: workspace.question.revision,
              }
            }
            expectedQuestionRevision={workspace.question.revision}
            workspaceClaims={workspace.claims ?? []}
            workspaceDocuments={workspace.documents ?? []}
            onOpenReference={(target) => void openReference(target)}
            onOpenEvidence={(evidence) =>
              evidence.path &&
              void openReference({
                document_id: evidence.source_id,
                path: evidence.path,
                revision: evidence.source_version,
                locator: evidence.locator,
                available_excerpt: evidence.available_excerpt,
                exact_passage_available: Boolean(
                  evidence.available_excerpt || evidence.locator,
                ),
                origin: { surface: "conversation", record_id: selectedNodeId },
              })
            }
            onRefresh={load}
            onOpenDocument={(path) => {
              const document = workspace.documents?.find(
                (item) => item.path === path,
              );
              if (document)
                void openReference({
                  document_id: document.document_id,
                  path,
                  revision: document.revision,
                  origin: {
                    surface: "conversation",
                    record_id: selectedNodeId,
                  },
                });
            }}
            seed={chatSeed}
            reviewAuthor="Themis.ai"
            lawyerAuthor={identity?.actor.display_name ?? "Lawyer"}
            onReviewAuthorChange={() => undefined}
          />
        </section>
      </main>
    </AppShell>
  );
}

frontend/components/ResearchQueuePanel.t:
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { researchQueueAggregate, researchSupportLabel } from "@/lib/researchQueue";
import type { ResearchRun } from "@/lib/types";

type SavedQuestion = { id: string; text: string };

type ResearchQueuePanelProps = {
  items: ResearchRun[];
  mode?: "controls" | "summary";
  busy?: boolean;
  enteredQuestion?: string;
  savedQuestions?: SavedQuestion[];
  selectedQuestion?: string;
  packetHref?: (path: string) => string;
  onEnteredQuestion?: (value: string) => void;
  onMove?: (runId: string, direction: -1 | 1) => Promise<void>;
  onResume?: () => Promise<void>;
  onStop?: () => Promise<void>;
  onRetry?: (runId: string) => Promise<void>;
  onRun?: () => Promise<void>;
  onContinueFromPartial?: (item: ResearchRun) => void;
  onUpdateDraftFromSavedResearch?: () => void;
  onSelectedQuestion?: (value: string) => void;
  showDraftSnapshotNotice?: boolean;
};

export default function ResearchQueuePanel({
  items,
  mode = "controls",
  busy = false,
  enteredQuestion = "",
  savedQuestions = [],
  selectedQuestion = "",
  packetHref = (path) => `?file=${encodeURIComponent(path)}`,
  onEnteredQuestion,
  onMove,
  onResume,
  onStop,
  onRetry,
  onRun,
  onContinueFromPartial,
  onUpdateDraftFromSavedResearch,
  onSelectedQuestion,
  showDraftSnapshotNotice = false,
}: ResearchQueuePanelProps) {
  const pending = items.filter((item) => item.state === "queued");
  const interrupted = items.some((item) => item.state === "interrupted");
  const active = items.some((item) => item.state === "queued" || item.state === "running");
  const canControl = mode === "controls";
  const aggregate = researchQueueAggregate(items);
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!items.some((item) => item.state === "running")) return;
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(timer);
  }, [items]);

  return <section className="agent-note" aria-label="Research queue" style={{ margin: "12px 18px", padding: 14 }}>
    <div className="field-label">Research queue</div>
    <p className="setting-help" role="status">
      {aggregate.runCount} {aggregate.runCount === 1 ? "run" : "runs"} · {aggregate.activeCount} active · {aggregate.savedPacketCount} saved {aggregate.savedPacketCount === 1 ? "packet" : "packets"} · {aggregate.supportCount} saved support {aggregate.supportCount === 1 ? "source" : "sources"}
    </p>
    {showDraftSnapshotNotice ? <div className="matter-lifecycle-action">
      <span>This draft is a saved snapshot</span>
      <p>New research does not change this draft automatically.</p>
      <button className="btn quiet compact" disabled={busy || !onUpdateDraftFromSavedResearch || aggregate.savedPacketCount === 0} onClick={onUpdateDraftFromSavedResearch} type="button">Update draft from saved research</button>
    </div> : null}
    {canControl ? <div className="btn-row" style={{ marginTop: 8 }}>
      <select className="select-input" onChange={(event) => onSelectedQuestion?.(event.target.value)} value={selectedQuestion}>
        <option value="">Select a saved question</option>
        {savedQuestions.map((item) => <option key={item.id} value={item.text}>{item.text}</option>)}
      </select>
      <input className="text-input" onChange={(event) => onEnteredQuestion?.(event.target.value)} placeholder="Or enter a research question" value={enteredQuestion} />
      <button className="btn agent compact" disabled={busy || !onRun} onClick={() => void onRun?.()}>Run research</button>
      {interrupted ? <button className="btn compact" disabled={busy || !onResume} onClick={() => void onResume?.()}>Resume research</button> : null}
      {active ? <button className="btn quiet compact" disabled={busy || !onStop} onClick={() => void onStop?.()}>Stop research</button> : null}
    </div> : null}
    <div style={{ marginTop: 8 }}>
      {items.map((item) => {
        const packetPath = item.results?.[0]?.path;
        const partial = item.state === "completed" && item.status.startsWith("Partial");
        return <div className="setting-help" key={item.run_id} style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
          <span><strong>{researchQueueStateWord(item)}</strong> · order {item.queue_order ?? item.priority ?? "—"} · {item.run_id} · {item.question ?? item.questions?.[0] ?? "Research question"}</span>
          <span>Support: {researchSupportLabel(item)}</span>
          {item.state === "running" ? <span>{researchElapsed(item, now)} elapsed{packetPath ? " · saved packet available" : ""} · You can continue elsewhere while research runs.</span> : null}
          {partial ? <span>Partial research is saved. You can use the packet to continue drafting.</span> : null}
          {canControl && item.state === "queued" ? <>
            <button className="btn compact" disabled={busy || !onMove || pending[0]?.run_id === item.run_id} onClick={() => void onMove?.(item.run_id, -1)}>Up</button>
            <button className="btn compact" disabled={busy || !onMove || pending.at(-1)?.run_id === item.run_id} onClick={() => void onMove?.(item.run_id, 1)}>Down</button>
          </> : null}
          {packetPath ? <Link href={packetHref(packetPath)}>Open packet</Link> : null}
          {item.state === "failed" ? <button className="btn quiet compact" disabled={busy || !onRetry} onClick={() => void onRetry?.(item.run_id)} type="button">Retry</button> : null}
          {partial && onContinueFromPartial ? <button className="btn quiet compact" onClick={() => onContinueFromPartial(item)} type="button">Continue from saved research</button> : null}
        </div>;
      })}
    </div>
  </section>;
}

function researchElapsed(item: ResearchRun, now: number): string {
  const started = Date.parse(item.started_at || item.created_at || "");
  const seconds = Number.isFinite(started) ? Math.max(0, Math.floor((now - started) / 1000)) : 0;
  const minutes = Math.floor(seconds / 60);
  return minutes ? `${minutes}m ${seconds % 60}s` : `${seconds}s`;
}

function researchQueueStateWord(item: ResearchRun): string {
  if (item.state === "completed") return item.status.startsWith("Partial") ? "Partial" : "Complete";
  return { queued: "Queued", running: "Running", failed: "Failed", interrupted: "Stopped" }[item.state];
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { acceptRecommendation, updateRecommendation } from "@/lib/api";
import type { RecommendationState, RecommendationVersion } from "@/lib/types";

type Props = {
  matterId: string;
  recommendation: RecommendationState;
  lawyerActor: string;
  disabled?: boolean;
  onChanged?: (recommendation: RecommendationState) => void | Promise<void>;
};

/** The typed working-recommendation control; it never uses the generic file API. */
export default function RecommendationPanel({
  matterId,
  recommendation,
  lawyerActor,
  disabled = false,
  onChanged,
}: Props) {
  const [state, setState] = useState(recommendation);
  const [draft, setDraft] = useState(state.content);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const current = useMemo(
    () => state.versions?.find((version) => version.version_id === state.current_version_id),
    [state.current_version_id, state.versions],
  );
  const isLegacy = !state.current_version_id;

  useEffect(() => {
    setState(recommendation);
    setDraft(recommendation.content);
  }, [recommendation]);

  async function saveLawyerEdit() {
    if (!draft.trim()) return;
    setBusy(true);
    setError("");
    try {
      const result = await updateRecommendation(matterId, draft, lawyerActor.trim() || "Lawyer");
      setState(result.data);
      setDraft(result.data.content);
      await onChanged?.(result.data);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not save the recommendation.");
    } finally {
      setBusy(false);
    }
  }

  async function acceptProposal() {
    setBusy(true);
    setError("");
    try {
      const result = await acceptRecommendation(matterId, lawyerActor.trim() || "Lawyer");
      setState(result.data);
      setDraft(result.data.content);
      await onChanged?.(result.data);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not accept the recommendation update.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="matter-recommendation" aria-label="Working recommendation">
      <div className="matter-recommendation-label">
        {isLegacy ? "Legacy recommendation · version history starts when counsel saves" : versionLabel(current)}
      </div>
      <div className="matter-record-note">This saved recommendation is not a recorded decision.</div>
      <textarea
        aria-label="Working recommendation"
        className="text-input prose"
        disabled={disabled || busy}
        onChange={(event) => setDraft(event.target.value)}
        value={draft}
      />
      <button
        className="btn primary compact"
        disabled={disabled || busy || !draft.trim() || draft.trim() === state.content.trim()}
        onClick={() => void saveLawyerEdit()}
        type="button"
      >
        {busy ? "Saving…" : "Save lawyer edit"}
      </button>
      {state.proposal ? (
        <div className="matter-lifecycle-action">
          <span>{proposalLabel(state.proposal)}</span>
          <p>{state.proposal.content}</p>
          <button className="btn review compact" disabled={disabled || busy} onClick={() => void acceptProposal()} type="button">
            Accept recommendation update
          </button>
        </div>
      ) : null}
      {error ? <p className="error" role="alert">{error}</p> : null}
    </section>
  );
}

function versionLabel(version: RecommendationVersion | undefined): string {
  if (!version) return "Saved recommendation";
  return `Version ${version.number} · ${version.actor} · ${originLabel(version.origin)}`;
}

function proposalLabel(proposal: RecommendationVersion): string {
  return `Proposed · ${proposal.actor} · ${originLabel(proposal.origin)}`;
}

function originLabel(origin: RecommendationVersion["origin"]): string {
  return {
    initial_agent: "Initial agent draft",
    lawyer_edit: "Lawyer edit",
    agent_proposal: "Agent proposal",
  }[origin];
}

frontend/components/ReviewPacketPanel.ts:
"use client";

import { useState } from "react";
import LinkifiedText from "@/components/LinkifiedText";
import { actOnReviewPacket, createMatterMitigation } from "@/lib/watchApi";
import type { Mitigation, ReviewAction, ReviewPacket } from "@/lib/watchTypes";

const ACTIONS: Array<{ value: ReviewAction["action"]; label: string }> = [
  { value: "keep_current", label: "Keep current" }, { value: "revise_decision", label: "Revise decision" },
  { value: "create_follow_up", label: "Create follow-up work" }, { value: "not_relevant", label: "Not relevant" },
  { value: "keep_monitoring", label: "Keep monitoring" },
];

export default function ReviewPacketPanel({ packet: initialPacket, matterId, mitigations = [], onChanged }: { packet: ReviewPacket; matterId?: string | null; mitigations?: Mitigation[]; onChanged?: () => void | Promise<void> }) {
  const [packet, setPacket] = useState(initialPacket);
  const [action, setAction] = useState<ReviewAction["action"] | null>(null);
  const [note, setNote] = useState("");
  const [decisionId, setDecisionId] = useState(packet.affected_decisions[0] ?? "");
  const [targetMatterId, setTargetMatterId] = useState(matterId ?? packet.affected_matters[0] ?? "");
  const [workTitle, setWorkTitle] = useState(`Review ${packet.what_happened}`);
  const [nextReviewAt, setNextReviewAt] = useState("");
  const [mitigationOpen, setMitigationOpen] = useState(false);
  const [mitigationTitle, setMitigationTitle] = useState("");
  const [mitigationDescription, setMitigationDescription] = useState("");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  function cancel() { setAction(null); setMitigationOpen(false); setError(""); }

  async function submitOutcome() {
    if (!action) return;
    setBusy(true); setError("");
    try {
      let payload: ReviewAction;
      if (action === "keep_current") payload = { action, expected_revision: packet.revision, payload: { note, next_review_at: nextReviewAt || null } };
      else if (action === "revise_decision") payload = { action, expected_revision: packet.revision, payload: { decision_id: decisionId, matter_id: targetMatterId || null, work_item_title: workTitle } };
      else if (action === "create_follow_up") payload = { action, expected_revision: packet.revision, payload: { matter_id: targetMatterId, title: workTitle, due_at: null } };
      else payload = { action, expected_revision: packet.revision, payload: { reason: note } };
      await actOnReviewPacket(packet.packet_id, payload);
      setPacket((current) => ({ ...current, status: action === "keep_monitoring" ? "monitoring" : "resolved", attention_state: action === "keep_monitoring" ? "monitor" : "briefing_only", revision: current.revision + 1 }));
      setMessage(`${ACTIONS.find((item) => item.value === action)?.label} was recorded.`); setAction(null); await onChanged?.();
    } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not record the review outcome."); }
    finally { setBusy(false); }
  }

  async function submitMitigation() {
    if (!targetMatterId || !mitigationTitle.trim() || !mitigationDescription.trim()) return;
    setBusy(true); setError("");
    try {
      await createMatterMitigation(targetMatterId, { title: mitigationTitle.trim(), description: mitigationDescription.trim(), status: "active", decision_ids: decisionId ? [decisionId] : [], owner: "Lawyer", review_at: null });
      setMessage("The mitigation was recorded. The review packet outcome is still open."); setMitigationOpen(false); await onChanged?.();
    } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not record the mitigation."); }
    finally { setBusy(false); }
  }

  return <section className="agent-note" aria-labelledby={`packet-${packet.packet_id}`} style={{ marginTop: 16 }}>
    <div className="agent-label">{packet.status === "open" ? "Themis.ai · Not yet reviewed by an attorney" : "Themis.ai"}</div>
    <h2 id={`packet-${packet.packet_id}`} style={{ margin: "8px 0 4px" }}>Review packet</h2>
    <p><strong>{packet.status === "open" ? "Needs review" : packet.status === "monitoring" ? "Monitoring" : "Resolved"}</strong> · {packet.review_priority.replace("_", " ")} · {packet.potential_impact} potential impact</p>
    <p><LinkifiedText text={packet.what_happened} /></p><p><strong>Why it appeared:</strong> <LinkifiedText text={packet.why_surfaced} /></p>
    <PacketSection label="Prior decision basis" values={[packet.prior_decision_basis]} />
    <PacketSection label="Existing mitigations" values={packet.existing_mitigations} empty="No linked mitigation is recorded." />
    {mitigations.length ? <PacketSection label="Matter mitigations" values={mitigations.map((item) => `${item.title} — ${item.status}`)} /> : null}
    <PacketSection label="Possible tension" values={[packet.possible_tension]} /><PacketSection label="Timing" values={[packet.timing, ...packet.effective_dates]} />
    <div style={{ marginTop: 12 }}><strong>Sources</strong></div>
    {packet.sources.length ? <ul>{packet.sources.map((source, index) => <li key={`${source.canonical_url}-${index}`}><a href={source.canonical_url} rel="noreferrer" target="_blank">{source.title}</a> · {source.support_state.replaceAll("_", " ")}{source.warning ? ` · ${source.warning}` : ""}</li>)}</ul> : <p>No cited sources</p>}
    <PacketSection label="Warnings" values={packet.warnings} empty="No warnings." />
    {message ? <p role="status" style={{ color: "var(--healthy)" }}>{message}</p> : null}{error ? <p className="error" role="alert">{error}</p> : null}
    {packet.status === "open" && !action && !mitigationOpen ? <div className="btn-row" aria-label="Review packet actions">{ACTIONS.map((item) => <button className="btn review compact" key={item.value} onClick={() => { setMessage(""); setAction(item.value); }} type="button">{item.label}</button>)}{matterId || packet.affected_matters.length ? <button className="btn agent compact" onClick={() => { setMessage(""); setMitigationOpen(true); }} type="button">Record mitigation</button> : null}</div> : null}
    {action ? <div className="card" style={{ padding: 14, marginTop: 12 }}><strong>{ACTIONS.find((item) => item.value === action)?.label}</strong>
      {(action === "revise_decision" || action === "create_follow_up") ? <label>Work item title<input value={workTitle} onChange={(event) => setWorkTitle(event.target.value)} /></label> : null}
      {action === "revise_decision" ? <label>Decision ID<input required value={decisionId} onChange={(event) => setDecisionId(event.target.value)} /></label> : null}
      {(action === "revise_decision" || action === "create_follow_up") ? <label>Matter ID<input required={action === "create_follow_up"} value={targetMatterId} onChange={(event) => setTargetMatterId(event.target.value)} /></label> : null}
      {action === "keep_current" ? <label>Next review date<input type="date" value={nextReviewAt} onChange={(event) => setNextReviewAt(event.target.value)} /></label> : null}
      {action !== "revise_decision" && action !== "create_follow_up" ? <label>{action === "keep_current" ? "Note" : "Reason"}<textarea required={action !== "keep_current"} value={note} onChange={(event) => setNote(event.target.value)} /></label> : null}
      <div className="btn-row" style={{ marginTop: 10 }}><button className="btn primary" disabled={busy || (action === "revise_decision" && (!decisionId || !workTitle)) || (action === "create_follow_up" && (!targetMatterId || !workTitle)) || ((action === "not_relevant" || action === "keep_monitoring") && !note.trim())} onClick={submitOutcome} type="button">{busy ? "Recording…" : "Submit outcome"}</button><button className="btn" disabled={busy} onClick={cancel} type="button">Cancel</button></div>
    </div> : null}
    {mitigationOpen ? <div className="card" style={{ padding: 14, marginTop: 12 }}><strong>Record a separate mitigation</strong><p>This does not record a review outcome.</p><label>Title<input value={mitigationTitle} onChange={(event) => setMitigationTitle(event.target.value)} /></label><label>Description<textarea value={mitigationDescription} onChange={(event) => setMitigationDescription(event.target.value)} /></label><label>Matter ID<input value={targetMatterId} onChange={(event) => setTargetMatterId(event.target.value)} /></label><div className="btn-row" style={{ marginTop: 10 }}><button className="btn primary" disabled={busy || !targetMatterId || !mitigationTitle.trim() || !mitigationDescription.trim()} onClick={submitMitigation} type="button">{busy ? "Recording…" : "Record mitigation"}</button><button className="btn" disabled={busy} onClick={cancel} type="button">Cancel</button></div></div> : null}
  </section>;
}

function PacketSection({ label, values, empty }: { label: string; values: string[]; empty?: string }) { const present = values.filter((value) => value?.trim()); return <div style={{ marginTop: 10 }}><strong>{label}</strong>{present.length ? <ul>{present.map((value, index) => <li key={`${value}-${index}`}><LinkifiedText text={value} /></li>)}</ul> : empty ? <p>{empty}</p> : null}</div>; }

