                      </span>
                    ) : null}
                    {!finalPath ? (
                      <span className="matter-artifact-empty">
                        No final work product is saved yet.
                      </span>
                    ) : null}
                    {!detail.decisions.length ? (
                      <span className="matter-artifact-empty">
