                      </span>
                    ) : null}
                    <button
                      className="btn quiet compact matter-new-draft-toggle"
                      onClick={() => setNewDraftOpen((open) => !open)}
                      type="button"
                    >
                      {newDraftOpen ? "Cancel new draft" : "New draft"}
                    </button>
                    {newDraftOpen ? (
                      <div className="matter-new-draft">
                        <label htmlFor="new-draft-title">Draft title</label>
                        <input
                          className="text-input"
                          id="new-draft-title"
                          onChange={(event) =>
                            setNewDraftTitle(event.target.value)
                          }
                          value={newDraftTitle}
                        />
                        <label htmlFor="new-draft-content">Draft content</label>
                        <textarea
                          className="text-input prose"
                          id="new-draft-content"
                          onChange={(event) =>
                            setNewDraftContent(event.target.value)
                          }
                          placeholder="Write or paste the deliverable here."
                          value={newDraftContent}
                        />
                        <button
                          className="btn primary compact"
                          disabled={
                            busy ||
                            !newDraftTitle.trim() ||
                            !newDraftContent.trim()
                          }
                          onClick={() => void createManualDraft()}
                          type="button"
                        >
                          Save current draft
                        </button>
                      </div>
                    ) : null}
                  </div>
                </section>

                {detail.status === "closed" ? (
                  closedContext.length ? (
                    <details className="matter-open" id="remaining-work">
                      <summary>Open context at closure</summary>
                      <ul className="matter-open-list">
                        {closedContext.map((item) => (
                          <li key={item}>
                            <span className="matter-open-text">
                              <LinkifiedText text={item} />
                            </span>
                          </li>
                        ))}
                      </ul>
                    </details>
                  ) : null
                ) : (
                  <section className="matter-open" id="remaining-work">
                    <div className="matter-open-head">
                      <h2>
                        {openItems.length
                          ? "Other open items and questions"
                          : "No other open items or questions"}
                      </h2>
                      {openItems.length ? (
                        <span>
                          {requiredCount} other required work ·{" "}
                          {optionalWorkCount} optional work ·{" "}
                          {openQuestionCount} open questions
                        </span>
                      ) : null}
                    </div>
                    {openItems.length ? (
                      <ul className="matter-open-list">
                        {openItems.map((item) => (
                          <li
                            className={item.required ? "is-required" : ""}
                            key={item.key}
                          >
                            <span
                              aria-hidden="true"
                              className="matter-open-mark"
                            />
                            <span className="matter-open-text">
                              <LinkifiedText text={item.text} />
                            </span>
                            <span className="matter-open-tag">
                              {item.source === "open_question"
                                ? "Open question"
                                : item.required
                                  ? "Required work"
                                  : "Optional work"}
                            </span>
                            {item.required && item.workItemId ? (
                              <button
                                className="btn tiny quiet"
                                disabled={busy}
                                onClick={() =>
                                  void completeSavedWorkItem(item.workItemId!)
                                }
                                type="button"
                              >
                                Complete
                              </button>
                            ) : null}
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <p className="matter-open-empty">
                        No other open records are saved.
                      </p>
                    )}
                  </section>
                )}

                <ResearchQueuePanel
                  items={researchQueue}
                  mode="summary"
                  busy={busy}
                  showDraftSnapshotNotice={Boolean(
                    draftPath && activePath === draftPath,
                  )}
                  onUpdateDraftFromSavedResearch={prepareResearchDraftUpdate}
                  onResume={async () => {
                    setBusy(true);
                    try {
                      await resumeResearchQueue(detail.matter_id);
                      await loadResearchQueue();
                    } finally {
                      setBusy(false);
                    }
                  }}
                  onStop={async () => {
                    setBusy(true);
                    try {
                      await stopResearchQueue(detail.matter_id);
                      await loadResearchQueue();
                    } finally {
                      setBusy(false);
                    }
                  }}
                  onRetry={async (runId) => {
                    setBusy(true);
                    try {
                      await retryResearchItem(detail.matter_id, runId);
                      await loadResearchQueue();
                    } finally {
                      setBusy(false);
                    }
                  }}
                  onContinueFromPartial={(item) =>
                    openChatWithSeed(
                      `Draft the work product using the saved partial research packet for: ${item.question ?? item.questions?.[0] ?? detail.title}`,
                    )
                  }
                />

                {detail.status !== "closed" ? (
                  <section
                    className="matter-open"
                    aria-label="Other saved work items"
                  >
                    <div className="matter-open-head">
                      <h2>Other saved work items</h2>
                      <span>
                        {otherRequiredOpenCount} required open ·{" "}
                        {otherOptionalOpenCount} optional open
                      </span>
                    </div>
                    <div className="stack-list">
                      {otherOpenWorkItems.map((item) => (
                        <div
                          className="matter-lifecycle-action"
                          key={item.work_item_id}
                        >
                          <span>
                            {Boolean(item.required) ? "Required" : "Optional"}
                            {detail.status === "closed" &&
                            !Boolean(item.required)
                              ? " · Open after closure"
                              : ""}
                            {item.work_item_id ===
                            detail.work_state.next_work_item_id
                              ? " · Current next action"
                              : " · Open work"}{" "}
                            · {item.priority}
                          </span>
                          <p>
                            <strong>{item.title}</strong>
                          </p>
                          <p>
                            Owner:{" "}
                            <strong>
                              {ownerOverrides[item.work_item_id] ||
                                item.owner?.trim() ||
                                "Unassigned"}
                            </strong>
                          </p>
                          <div className="matter-inline-actions">
                            <select
                              aria-label={`Priority for ${item.title}`}
                              className="text-input"
                              disabled={busy}
                              onChange={(event) =>
                                void changeWorkItemPriority(
                                  item.work_item_id,
                                  event.target.value,
                                )
                              }
                              value={item.priority || "normal"}
                            >
                              <option value="low">Low</option>
                              <option value="normal">Normal</option>
                              <option value="high">High</option>
                              <option value="urgent">Urgent</option>
                            </select>
                            {[
                              ...new Set(
                                [
                                  actor.display_name,
                                  ...participants.map(
                                    (participant) => participant.name,
                                  ),
                                ].filter(Boolean),
                              ),
                            ].map((owner) => (
                              <button
                                className="btn tiny quiet"
                                disabled={pendingActions.includes(
                                  `assign_owner:${item.work_item_id}`,
                                )}
                                key={owner}
                                onClick={() =>
                                  void assignWorkItemTo(
                                    item.work_item_id,
                                    owner,
                                  )
                                }
                                type="button"
                              >
                                {pendingActions.includes(
                                  `assign_owner:${item.work_item_id}`,
                                )
                                  ? "Assigning owner…"
                                  : owner}
                              </button>
                            ))}
                            <input
                              aria-label={`Owner for ${item.title}`}
                              className="text-input"
                              defaultValue={item.owner}
                              disabled={pendingActions.includes(
                                `assign_owner:${item.work_item_id}`,
                              )}
                              onKeyDown={(event) => {
                                if (event.key === "Enter")
                                  void assignWorkItemTo(
                                    item.work_item_id,
                                    event.currentTarget.value,
                                  );
                              }}
                              placeholder="Owner name"
                            />
                            <button
                              className="btn tiny quiet"
                              disabled={busy}
                              onClick={() =>
                                void completeSavedWorkItem(item.work_item_id)
                              }
                              type="button"
                            >
                              Complete
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </section>
                ) : null}

                <details className="matter-reference">
                  <summary>
                    Materials, activity, and decision maintenance
                  </summary>
                  <div className="matter-reference-body">
                    {recommendationText ? (
                      <section>
                        <h2>Saved recommendation</h2>
                        <div className="matter-recommendation">
                          <p>
                            <LinkifiedText text={recommendationText} />
                          </p>
                          <div className="matter-record-note">
                            This saved recommendation is not a recorded
                            decision.
                          </div>
                          {recommendationPath ? (
                            <button
                              className="btn review compact"
                              onClick={() => openDocument(recommendationPath)}
                              type="button"
                            >
                              Open recommendation
                            </button>
                          ) : null}
                        </div>
                      </section>
                    ) : null}
                    <section>
                      <h2>Matter materials</h2>
                      <div className="evidence-list">
                        {evidence.length ? (
                          evidence.map((node) => (
                            <button
                              className="evidence-row"
                              key={node.path}
                              onClick={() => openDocument(node.path)}
                              type="button"
                            >
                              <span className="evidence-kind">{node.kind}</span>
                              <span style={{ flex: 1 }}>
                                <span className="evidence-name">
                                  <LinkifiedText text={node.name} />
                                </span>
                                <span className="evidence-note">
                                  <LinkifiedText text={node.note} />
                                </span>
                              </span>
                            </button>
                          ))
                        ) : (
                          <p>
                            No source documents or research are attached yet.
                          </p>
                        )}
                        {dossierPath ? (
                          <button
                            className="matter-artifact-link"
                            onClick={() => openDocument(dossierPath)}
                            type="button"
                          >
                            <span>Editable dossier</span>
                            <span>Open the full matter summary</span>
                          </button>
                        ) : null}
                        {researchPath ? (
                          <button
                            className="matter-artifact-link"
                            onClick={() => openDocument(researchPath)}
                            type="button"
                          >
                            <span>{researchTitle}</span>
                            <span>Open the research packet</span>
                          </button>
                        ) : null}
                      </div>
                    </section>

                    <section>
                      <h2>Recent activity</h2>
                      {detail.orientation.recent_changes.length ? (
                        <ul>
                          {detail.orientation.recent_changes.map(
                            (change, index) => (
                              <li key={index}>
                                <LinkifiedText text={change} />
                              </li>
                            ),
                          )}
                        </ul>
                      ) : (
                        <p>Nothing has happened on this matter yet.</p>
                      )}
                    </section>
                    {reviewPackets.length ? (
                      <section>
                        <h2>Decision maintenance</h2>
                        {reviewPackets.map((packet) => (
                          <ReviewPacketPanel
                            key={packet.packet_id}
                            packet={packet}
                            matterId={detail.matter_id}
                            mitigations={mitigations}
                            onChanged={loadAwareness}
                          />
                        ))}
                      </section>
                    ) : mitigations.length ? (
                      <section>
                        <h2>Mitigations</h2>
                        <ul>
                          {mitigations.map((item) => (
                            <li key={item.mitigation_id}>
                              {item.title} — {item.status}
                            </li>
                          ))}
                        </ul>
                      </section>
                    ) : null}
                  </div>
                </details>
              </div>
            </details>
          </>
        }
        conversation={
          <ConversationDock
            matterId={detail.matter_id}
            target={effectiveTarget}
            onTargetChange={(target) =>
              setConversationTarget(
                target ?? {
                  matter_id: detail.matter_id,
                  business_question_revision: workspace?.question.revision,
                },
              )
            }
            receipts={workspace?.receipts ?? []}
            onOpenArtifact={openDocument}
          >
            {researchIssueTitle ? (
              <div>
                <p className="matter-action-notice" role="status">
                  Research for {researchIssueTitle} is {researchQueueActive ? "running" : savedResearch.savedPacketCount ? "saved" : "starting"}.
                </p>
                <ResearchQueuePanel items={researchQueue} mode="summary" />
              </div>
            ) : null}
            <ChatPanel
              contextKey={contextKey}
              matterId={detail.matter_id}
              matterTitle={detail.title}
              activeFile={activePath}
              activeAgentId={detail.active_agent_id}
              currentWorkProductDraftPath={draftPath}
              decisionOptions={detail.orientation.options}
              initialConversationId={initialConversationId ?? detail.intake_conversation_id}
              initialRunId={detail.intake_run_id}
              intakeActive={detail.intake_state === "active"}
              intakeAnswers={detail.intake_answers}
              target={effectiveTarget ?? undefined}
              expectedQuestionRevision={workspace?.question.revision}
              contextSelections={selections}
              onFilesAttached={(refs) => setComposerFileSelection(refs, true)}
              onFilesRemoved={(refs) => setComposerFileSelection(refs, false)}
              selectedTemplateId={selectedTemplateId}
              externalRun={externalRun}
              onBeforeSubmit={() => {
                chatSubmission.current = {
                  matter: detail.matter_id,
                  runId: null,
                  scene: { ...latestScene.current },
                };
              }}
              onRunStarted={(run) => {
                if (chatSubmission.current)
                  chatSubmission.current.runId = run.run_id;
              }}
              onRunComplete={(run) => {
                void showRunContext(run);
              }}
              onClearTarget={() =>
                setConversationTarget({
                  matter_id: detail.matter_id,
                  business_question_revision: workspace?.question.revision,
                })
              }
              onRefresh={refreshAfterChatRun}
              onOpenDocument={openDocument}
              onOpenReference={(target) => void openReference(target)}
              onOpenEvidence={(evidence) => void openEvidence(evidence)}
              workspaceClaims={workspace?.claims ?? []}
              workspaceDocuments={workspace?.documents ?? []}
              conversationSeed={conversationSeed}
              onConversationChange={setCurrentConversationId}
              seed={chatSeed}
              reviewAuthor={reviewAuthor.name}
              lawyerAuthor={actor.display_name}
              onReviewAuthorChange={reviewAuthor.setName}
            />
          </ConversationDock>
        }
        editor={
          <div className="document-workspace">
            <DocumentNavigator
              documents={workspace?.documents ?? []}
              activeDocumentId={activeDocument?.document_id ?? null}
              activeDocumentPath={activeDocument?.path ?? null}
              activeDocumentRevision={activeDocument?.revision ?? null}
              onOpen={openDocumentIdentity}
              onCreateWorkingCopy={(document) =>
                void createWorkingCopy(document)
              }
            />
            <DocumentTabs
              documents={openDocuments}
              activeDocumentId={activeDocument?.document_id ?? null}
              localEdits={localEdits}
              onSelect={(documentId) => {
                const document = openDocuments.find(
                  (item) => item.document_id === documentId,
                );
                if (document) openDocumentIdentity(document, false);
              }}
              onClose={(documentId) => {
                const snapshot = localEdits[documentId];
                if (snapshot?.dirty) {
                  const recoverable = recoverableLocalEditorSnapshot(snapshot);
                  writeLocalEditorSnapshot(
                    window.localStorage,
                    detail.matter_id,
                    recoverable,
                  );
                  setLocalEdits((current) => ({
                    ...current,
                    [documentId]: recoverable,
                  }));
                }
                setOpenDocuments((current) =>
                  current.filter((item) => item.document_id !== documentId),
                );
                if (activeDocument?.document_id === documentId)
                  setActivePath(null);
              }}
              onDiscardLocalEdit={(documentId) => {
                discardLocalEditorSnapshot(
                  window.localStorage,
                  detail.matter_id,
                  documentId,
                );
                setLocalEdits((current) => {
                  const next = { ...current };
                  delete next[documentId];
                  return next;
                });
              }}
            />
            <div className={`document-editor-reference${referenceTarget ? " has-reference" : ""}`}>
              <div className="document-editor-reference__draft">
              <>
                {!recommendationSelected &&
                selectedSavedDraft &&
                researchQueue.length > 0 ? (
                  <section
                    className="agent-note"
                    aria-label="Saved research snapshot"
                    style={{ marginBottom: 12, padding: 14 }}
                  >
                    <strong>This draft is a saved snapshot</strong>
                    <p>
                      New research does not change this draft automatically.{" "}
                      {savedResearch.activeCount > 0
                        ? "Research is running. "
                        : ""}
                      {savedResearch.savedPacketCount} saved{" "}
                      {savedResearch.savedPacketCount === 1
                        ? "packet is"
                        : "packets are"}{" "}
                      available.
                    </p>
                    <button
                      className="btn quiet compact"
                      disabled={
                        busy ||
                        savedResearch.savedPacketCount === 0 ||
                        !selectedSavedDraft.review_revision
                      }
                      onClick={prepareResearchDraftUpdate}
                      type="button"
                    >
                      Update draft from saved research
                    </button>
                  </section>
                ) : null}
                {recommendationSelected ? (
                  recommendationState ? (
                    <RecommendationPanel
                      disabled={busy}
                      lawyerActor={reviewSettings.lawyer}
                      matterId={detail.matter_id}
                      onChanged={recommendationChanged}
                      recommendation={recommendationState}
                    />
                  ) : (
                    <p className="chat-history-status">
                      Loading the saved recommendation…
                    </p>
                  )
                ) : (
                  <DocumentPanel
                    humanActor={actor}
                    contextKey={contextKey}
                    activeDocument={activeDocument}
                    activePath={activePath}
                    localEdit={
                      activeDocument
                        ? (localEdits[activeDocument.document_id] ?? null)
                        : null
                    }
                    actionTargetDocumentId={activeDocument?.document_id ?? null}
                    documents={workspace?.documents ?? []}
                    refreshSignal={editorRefresh}
                    onSnapshot={handleEditorSnapshot}
                    onSaved={() => void refreshWorkspace()}
                    activeReviewAuthor={reviewAuthor.name}
                    lawyerAuthor={actor.display_name}
                    onReviewAuthorChange={reviewAuthor.setName}
                    onOpenReference={(target) => void openReference(target)}
                    onAskAgent={(targetId) => {
                      const target = workspace?.documents?.find(
                        (item) => item.document_id === targetId,
                      );
                      setConversationTarget({
                        matter_id: detail.matter_id,
                        business_question_revision:
                          workspace?.question.revision,
                        artifact_path: target?.path,
                        artifact_revision: target?.revision,
                      });
                      openChatWithSeed(
                        `Propose revised wording for ${target?.title ?? "the selected document"}. Preserve my edits.`,
                      );
                    }}
                    onClose={() => {
                      const id = activeDocument?.document_id;
                      if (id) {
                        const snapshot = localEdits[id];
                        if (snapshot?.dirty)
                          writeLocalEditorSnapshot(
                            window.localStorage,
                            detail.matter_id,
                            recoverableLocalEditorSnapshot(snapshot),
                          );
                        setOpenDocuments((current) =>
                          current.filter((item) => item.document_id !== id),
                        );
                      }
                      setActivePath(null);
                    }}
                    onUpload={upload}
                  />
                )}
              </>
              </div>
              {referenceTarget ? (
                <ReferencePreview
                  target={referenceTarget}
                  document={referenceDocument}
                  error={referenceError}
                  onBack={returnFromReference}
                  onOpenOriginal={(document) =>
                    window.open(
                      rawFileUrl(document.original_path || document.path),
                      "_blank",
                      "noopener,noreferrer",
                    )
                  }
                  onUseInRequest={(document) =>
                    void changeContext([
                      ...selections.filter(
                        (item) => item.reference_id !== document.document_id,
                      ),
                      {
                        reference_id: document.document_id,
                        path: document.path,
                        role: "source_file",
                        selected: true,
                        revision: document.revision,
                      },
                    ])
                  }
                  onCreateWorkingCopy={(document) =>
                    void createWorkingCopy(document)
                  }
                />
              ) : null}
            </div>
          </div>
        }
      />
      <MatterFilesPanel
        open={filesOpen}
        files={files}
        selections={availableContextSelections}
        manifest={manifest}
        onClose={() => setFilesOpen(false)}
        onChange={changeContext}
        onUpload={uploadWorkspaceFiles}
        onOpenArtifact={openDocument}
        onOpenReference={(target) => void openReference(target)}
        onRetryFile={retryFilePreview}
        folderView={
          <MatterTree
            activePath={treeActivePath}
            tree={detail.tree}
            onNewChat={() => {
              setWorkspaceView("discuss");
              setConversationSeed((current) => ({
                conversationId: "",
                revision: current.revision + 1,
              }));
            }}
            onSelect={selectMatterItem}
            onUpload={upload}
            uploading={uploading}
          />
        }
      />
      <EvidenceDrawer
        evidence={activeEvidence}
        open={Boolean(activeEvidence)}
        onClose={() => {
          setActiveEvidence(null);
        }}
        onOpenArtifact={() => {
          if (!activeEvidence?.path) return;
          const document = (workspace?.documents ?? []).find(
            (item) =>
              item.path === activeEvidence.path ||
              item.document_id === activeEvidence.source_id,
          );
          if (document)
            void openReference({
              document_id: document.document_id,
              path: activeEvidence.path!,
              revision: activeEvidence.source_version ?? document.revision,
              locator: activeEvidence.locator,
              available_excerpt: activeEvidence.available_excerpt,
              exact_passage_available: Boolean(
                activeEvidence.available_excerpt || activeEvidence.locator,
              ),
              origin: {
                surface: "evidence",
                record_id: activeEvidence.claim_id,
                scroll_offset: window.scrollY,
              },
            });
          else openDocument(activeEvidence.path!);
        }}
      />

      {modalOpen ? (
        <RecordDecisionModal
          basis={evidence.map((node) => node.path)}
          basisLabels={Object.fromEntries(
            evidence.map((node) => [node.path, node.name]),
          )}
          detail={detail}
          lawyerAuthor={actor.display_name}
          onClose={() => setModalOpen(false)}
          onRecorded={reload}
          suggestion={proposedPath}
        />
      ) : null}
      {mitigationIssueId ? (
        <div className="modal-scrim">
          <form
            className="modal"
            onSubmit={(event) => {
              event.preventDefault();
              void saveMitigation();
            }}
          >
            <div className="modal-head">
              <div>
                <span className="record-meta">Issue {mitigationIssueId}</span>
                <h3>Create mitigation work</h3>
              </div>
              <button
                className="btn quiet tiny"
                onClick={() => {
                  mitigationActionKey.current = null;
                  setMitigationIssueId(null);
                }}
                type="button"
              >
                Cancel
              </button>
            </div>
            <label className="field-block">
              <span className="field-label">Title</span>
              <input
                className="text-input"
                value={mitigationDraft.title}
                onChange={(event) => {
                  mitigationActionKey.current = null;
                  setMitigationDraft((current) => ({
                    ...current,
                    title: event.target.value,
                  }));
                }}
              />
            </label>
            <label className="field-block">
              <span className="field-label">What must be done</span>
              <textarea
                className="text-input prose"
                value={mitigationDraft.description}
                onChange={(event) => {
                  mitigationActionKey.current = null;
                  setMitigationDraft((current) => ({
                    ...current,
                    description: event.target.value,
                  }));
                }}
              />
            </label>
            <label className="field-block">
              <span className="field-label">Owner</span>
              <input
                className="text-input"
                value={mitigationDraft.owner}
                onChange={(event) => {
                  mitigationActionKey.current = null;
                  setMitigationDraft((current) => ({
                    ...current,
                    owner: event.target.value,
                  }));
                }}
              />
            </label>
            <p className="muted">
              Saving this work does not resolve the issue or record a decision.
            </p>
            <button
              className="btn primary"
              disabled={
                busy ||
                !mitigationDraft.title.trim() ||
                !mitigationDraft.description.trim() ||
                !mitigationDraft.owner.trim()
              }
              type="submit"
            >
              {busy ? "Saving…" : "Save mitigation work"}
            </button>
          </form>
        </div>
      ) : null}
      {manualDeliveryConfirmation ? (
        <ConfirmationDialog
          confirmLabel="Record manual delivery"
          description="This records delivery outside Themis.ai. It does not send or contact anyone."
          onCancel={() => setManualDeliveryConfirmation(null)}
          onConfirm={() => runControl(manualDeliveryConfirmation, true, true)}
          title="Record manual delivery?"
        />
      ) : null}
    </div>
  );
}

frontend/components/workspace/DraftWorks:
"use client";

import { useEffect, useRef, useState } from "react";
import { canPersistWorkspaceDraftingPreferences, matchingLocalEditorSnapshot, newWorkspaceDraftActionKey, readWorkspaceDraftingPreferences, restoredOutputTemplate, reusableWorkspaceDraftActionKey, shouldOpenCompletedDraft, WorkspaceDraftingActionTracker, workspaceDraftRequestFingerprint, writeWorkspaceDraftingPreferences } from "@/lib/workspaceDrafting";
import type { DraftRequest, DraftResult, DraftWorkspaceProps, OutputTemplate, TemplateUse, WorkProductReference, WorkspaceView } from "@/lib/workspaceTypes";

const VIEWS: Array<{ id: WorkspaceView; label: string; help: string }> = [
  { id: "understand", label: "Understand", help: "Read the current matter" },
  { id: "discuss", label: "Discuss", help: "Continue one matter conversation" },
  { id: "draft", label: "Draft", help: "Review and prepare work product" },
];

function fileName(path: string): string { return path.split("/").filter(Boolean).at(-1) || "saved file"; }
function stateClass(state: string | undefined): string { return state === "failed" || state === "interrupted" || state === "not_saved" ? "state-failure" : state === "completed" || state === "saved" ? "state-healthy" : "state-agent"; }
function previewStateLabel(result: DraftResult): string {
  if (result.artifact) return result.artifact.preview ? "Preview · Not kept" : "Saved work product";
  if (result.state === "failed" || result.state === "interrupted") return "Preview failed";
  if (result.state === "not_saved") return "Preview not saved";
  return result.state === "queued" || result.state === "running" ? "Preview preparing" : "Preview request";
}

function templateUse(template: OutputTemplate, overrides: Record<string, string>): TemplateUse {
  return {
    template_id: template.template_id,
    output_type: template.output_type,
    revision: template.revision,
    content_hash: template.content_hash,
    revision_path: template.revision_path,
    instructions_snapshot: template.instructions ?? "",
    section_outline_snapshot: template.section_outline,
    defaults_snapshot: Object.fromEntries(Object.entries({ audience: template.audience, purpose: template.purpose, tone: template.tone, length: template.length }).filter((entry): entry is [string, string] => Boolean(entry[1]))),
    overrides,
    state: template.enabled === false ? "unavailable" : "applied",
  };
}

function ArtifactState({ artifact }: { artifact: WorkProductReference }) {
  if (artifact.pending_review) return <span className="state-label state-attention">Pending attorney review</span>;
  if (artifact.preview) return <span className="state-label state-agent">Preview · Not kept</span>;
  return <span className="state-label state-healthy">Saved work product</span>;
}

export default function DraftWorkspace(props: DraftWorkspaceProps) {
  const selectedTemplate = props.templates.find((template) => template.template_id === props.selectedTemplateId) ?? null;
  const [instruction, setInstruction] = useState("");
  const [overrides, setOverrides] = useState<Record<string, string>>({});
  const [actionKey, setActionKey] = useState<string | null>(null);
  const [actionFingerprint, setActionFingerprint] = useState<string | null>(null);
  const [draftResult, setDraftResult] = useState<DraftResult | null>(null);
  const [previewResult, setPreviewResult] = useState<DraftResult | null>(null);
  const [pending, setPending] = useState<"draft" | "preview" | "keep" | "accept" | "decline" | "retain_copy" | "open_current" | "rebase" | "">("");
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");
  const [hydratedMatterId, setHydratedMatterId] = useState<string | null>(null);
  const [restoredView, setRestoredView] = useState<WorkspaceView | null>(null);
  const [restoredArtifactPath, setRestoredArtifactPath] = useState<string | null>(null);
  const [restoredTemplateId, setRestoredTemplateId] = useState<string | null>(null);
  const [conversationExpanded, setConversationExpanded] = useState(
    props.view === "discuss",
  );
  const submittedTarget = useRef<string | null>(null);
  const submittedArtifact = useRef<WorkProductReference | null>(null);
  const latestActiveArtifactPath = useRef(props.activeArtifactPath);
  const actionTracker = useRef(new WorkspaceDraftingActionTracker(props.matterId));
  actionTracker.current.setMatter(props.matterId);
  latestActiveArtifactPath.current = props.activeArtifactPath;

  useEffect(() => {
    if (hydratedMatterId === props.matterId) return;
    const next = readWorkspaceDraftingPreferences(window.localStorage, props.matterId);
    setDraftResult(null); setPreviewResult(null); setNotice(""); setError(""); setPending("");
    setInstruction(next.instruction); setOverrides(next.overrides); setActionKey(next.sourceActionKey); setActionFingerprint(next.sourceActionFingerprint);
    setRestoredView(next.view); setRestoredArtifactPath(next.activeArtifactPath); setRestoredTemplateId(next.selectedTemplateId); setHydratedMatterId(props.matterId);
    if (next.view !== props.view) props.onViewChange(next.view);
    if (next.activeArtifactPath && next.activeArtifactPath !== props.activeArtifactPath) props.onSelectArtifact(next.activeArtifactPath);
  }, [hydratedMatterId, props.activeArtifactPath, props.matterId, props.onSelectArtifact, props.onViewChange, props.view]);

  useEffect(() => {
    if (!canPersistWorkspaceDraftingPreferences(hydratedMatterId, props.matterId)) return;
    const template = restoredOutputTemplate(props.templates, restoredTemplateId);
    if (!template) return;
    if (template.template_id !== props.selectedTemplateId) props.onSelectTemplate(template);
    setRestoredTemplateId(null);
  }, [hydratedMatterId, props.matterId, props.onSelectTemplate, props.selectedTemplateId, props.templates, restoredTemplateId]);

  useEffect(() => {
    if (!canPersistWorkspaceDraftingPreferences(hydratedMatterId, props.matterId)) return;
    if (restoredView && props.view === restoredView) setRestoredView(null);
    if (restoredArtifactPath && props.activeArtifactPath === restoredArtifactPath) setRestoredArtifactPath(null);
  }, [hydratedMatterId, props.activeArtifactPath, props.matterId, props.view, restoredArtifactPath, restoredView]);

  useEffect(() => {
    if (!canPersistWorkspaceDraftingPreferences(hydratedMatterId, props.matterId)) return;
    writeWorkspaceDraftingPreferences(window.localStorage, props.matterId, {
      version: 1,
      view: restoredView ?? props.view,
      activeArtifactPath: restoredArtifactPath ?? props.activeArtifactPath,
      selectedTemplateId: restoredTemplateId ?? props.selectedTemplateId,
      instruction,
      overrides,
      sourceActionKey: actionKey,
      sourceActionFingerprint: actionFingerprint,
    });
  }, [actionFingerprint, actionKey, hydratedMatterId, instruction, overrides, props.activeArtifactPath, props.matterId, props.selectedTemplateId, props.view, restoredArtifactPath, restoredTemplateId, restoredView]);

  useEffect(() => {
    if (!previewResult?.artifact) return;
    const refreshed = props.artifacts.find((artifact) => artifact.path === previewResult.artifact?.path);
    if (refreshed && !refreshed.preview && previewResult.artifact.preview) {
      setPreviewResult((current) => current?.artifact?.path === refreshed.path ? { ...current, artifact: refreshed } : current);
    }
  }, [previewResult, props.artifacts]);

  useEffect(() => {
    setConversationExpanded(props.view === "discuss");
  }, [props.view]);

  const localSnapshot = matchingLocalEditorSnapshot(props.target?.artifact_path, props.editorSnapshot ?? null);
  const hasScope = Boolean(props.target && props.businessQuestionRevision);
  const targetLabel = props.target?.artifact_path ? fileName(props.target.artifact_path) : "the current matter";
  const isDraftableTemplate = !selectedTemplate || selectedTemplate.enabled !== false;

  function changeInstruction(value: string) {
    setInstruction(value);
    setActionKey(null); setActionFingerprint(null);
    setDraftResult(null);
  }

  function beginAction() {
    return actionTracker.current.begin();
  }

  function isCurrentAction(token: ReturnType<WorkspaceDraftingActionTracker["begin"]>) {
    return actionTracker.current.isCurrent(token);
  }

  async function requestDraft() {
    if (!props.target || !props.businessQuestionRevision) { setError("Choose a saved conversation scope before requesting a draft."); return; }
    if (!instruction.trim()) { setError("Describe the work product you need."); return; }
    if (!isDraftableTemplate) { setError("Choose an available output template before requesting a draft."); return; }
    const frozenTarget = {
      ...props.target,
      artifact_path: localSnapshot?.path ?? props.target.artifact_path,
      artifact_revision: localSnapshot?.base_revision ?? props.target.artifact_revision,
      artifact_review_revision: localSnapshot?.review_revision ?? props.target.artifact_review_revision,
      selected_range: localSnapshot?.selected_range ?? props.target.selected_range,
      local_draft_snapshot: localSnapshot?.content ?? props.target.local_draft_snapshot,
    };
    const requestBase: Omit<DraftRequest, "source_action_key"> = {
      instruction: instruction.trim(), target: frozenTarget,
      business_question_revision: props.businessQuestionRevision,
      output_type: selectedTemplate?.output_type,
      template_use: selectedTemplate ? templateUse(selectedTemplate, overrides) : null,
      audience: overrides.audience || undefined, purpose: overrides.purpose || undefined,
      output_preferences: Object.keys(overrides).length ? overrides : undefined,
    };
    const fingerprint = workspaceDraftRequestFingerprint(requestBase);
    const key = reusableWorkspaceDraftActionKey(actionKey, actionFingerprint, fingerprint, () => newWorkspaceDraftActionKey(props.matterId));
    const request: DraftRequest = { ...requestBase, source_action_key: key };
    const token = beginAction();
    setActionKey(key); setActionFingerprint(fingerprint); setPending("draft"); setError(""); setNotice("");
    submittedTarget.current = frozenTarget.artifact_path ?? null;
    submittedArtifact.current = props.artifacts.find((artifact) => artifact.path === frozenTarget.artifact_path) ?? null;
    try {
      const result = await props.onDraft(request);
      if (!isCurrentAction(token)) return;
      setDraftResult(result);
      if (result.artifact && shouldOpenCompletedDraft(latestActiveArtifactPath.current, submittedTarget.current)) {
        props.onSelectArtifact(result.artifact.path);
        setNotice(`Draft ready: ${result.artifact.title}.`);
      } else if (result.artifact) setNotice(`Draft ready for ${targetLabel}. Open it when you are ready.`);
      else setNotice(`Draft request ${result.state}.`);
    } catch (caught) { if (isCurrentAction(token)) setError(caught instanceof Error ? caught.message : "The draft request did not finish. Your instruction is retained for retry."); }
    finally { if (isCurrentAction(token)) setPending(""); }
  }

  async function previewTemplate() {
    if (!selectedTemplate) { setError("Choose an output template before creating a preview."); return; }
    const token = beginAction();
    setPending("preview"); setError(""); setNotice("");
    try { const result = await props.onPreviewTemplate(selectedTemplate, overrides); if (!isCurrentAction(token)) return; setPreviewResult(result); setNotice(result.artifact ? "Separate editable preview created. It does not replace an existing draft." : `Preview request ${result.state}.`); }
    catch (caught) { if (isCurrentAction(token)) setError(caught instanceof Error ? caught.message : "The preview did not finish. Your template choices are retained."); }
    finally { if (isCurrentAction(token)) setPending(""); }
  }

  async function actOnArtifact(artifact: WorkProductReference, action: "keep" | "accept" | "decline" | "retain_copy" | "open_current" | "rebase") {
    const callback = action === "keep" ? props.onKeepPreview : action === "accept" || action === "decline" ? props.onUpdateOfferAction : props.onResolveDraftConflict;
    if (!callback) { setError("This recovery action is not available yet."); return; }
    const token = beginAction();
    setPending(action); setError("");
    try {
      if (action === "keep") await props.onKeepPreview?.(artifact);
      else if (action === "accept" || action === "decline") await props.onUpdateOfferAction?.(artifact, action);
      else await props.onResolveDraftConflict?.(action, artifact);
      if (isCurrentAction(token)) {
        if (action === "keep") setPreviewResult((current) => current?.artifact?.path === artifact.path ? { ...current, artifact: { ...current.artifact, preview: false } } : current);
        setNotice(action === "keep" ? "Preview kept as work product." : action === "accept" ? "Update offer accepted." : action === "decline" ? "Update offer declined." : "Draft recovery action completed.");
      }
    } catch (caught) { if (isCurrentAction(token)) setError(caught instanceof Error ? caught.message : "The action did not finish. Your current editor text is retained."); }
    finally { if (isCurrentAction(token)) setPending(""); }
  }

  const viewName = `workspace-view-${props.matterId}`;
  const conversationVisible = props.view === "discuss" || conversationExpanded;
  return <section aria-label="Matter workspace" className={`draft-workspace draft-workspace--${props.view}${conversationVisible ? "" : " draft-workspace--conversation-collapsed"}`}>
    <header className="draft-workspace__head">
      <fieldset className="segmented"><legend className="sr-only">Matter workspace view</legend>{VIEWS.map((item) => <span className="segmented-option" key={item.id}><input checked={props.view === item.id} className="segmented-input" id={`${viewName}-${item.id}`} name={viewName} onChange={() => props.onViewChange(item.id)} type="radio" value={item.id} /><label htmlFor={`${viewName}-${item.id}`} title={item.help}>{item.label}</label></span>)}</fieldset>
      <div className="draft-workspace__conversation-control">
        <p>One matter conversation stays available while you read and draft.</p>
        {props.view !== "discuss" ? <button aria-expanded={conversationVisible} className="btn quiet tiny" onClick={() => setConversationExpanded((current) => !current)} type="button">{conversationVisible ? "Hide discussion" : "Show discussion"}</button> : null}
      </div>
    </header>

    <div className="draft-workspace__layout">
      <div aria-hidden={props.view !== "understand"} className="draft-workspace__understand" hidden={props.view !== "understand"}>{props.understand}</div>
      <div aria-hidden={props.view !== "draft"} className="draft-workspace__editor" hidden={props.view !== "draft"}>{props.editor}</div>
      <div aria-hidden={!conversationVisible} className="draft-workspace__conversation" hidden={!conversationVisible}>{props.conversation}</div>
    </div>

    <section className="draft-tools" aria-labelledby="draft-tools-title" hidden={props.view !== "draft"}>
      <div className="draft-tools__head"><div><span className="record-meta">Work product</span><h2 id="draft-tools-title">Draft controls</h2></div>{localSnapshot ? <span className="state-label state-attention">Local draft snapshot · Not saved</span> : null}</div>
      {localSnapshot ? <p className="draft-tools__snapshot">Changes from {fileName(localSnapshot.path)} are included only if you submit this request. Content revision: {localSnapshot.base_revision}. Review state: {localSnapshot.review_revision ?? "not available"}.{localSnapshot.selected_range ? " The selected passage is included." : ""}</p> : null}
      <div className="draft-tools__grid"><label><span>Request</span><textarea className="text-input prose" onChange={(event) => changeInstruction(event.target.value)} placeholder="For example: Draft a concise business memo for the current question." rows={3} value={instruction} /></label><div className="draft-template"><span className="field-label">Output template</span><strong>{selectedTemplate?.name ?? "No template selected"}</strong>{selectedTemplate ? <span>Version {selectedTemplate.revision}</span> : <span>A template is optional for a direct request.</span>}<div className="btn-row"><button className="btn quiet tiny" onClick={props.onOpenTemplates} type="button">Output templates</button>{selectedTemplate ? <button className="btn quiet tiny" onClick={() => props.onSelectTemplate(selectedTemplate)} type="button">Current template</button> : null}</div></div></div>
      {selectedTemplate ? <div className="draft-overrides"><span className="field-label">Only for this request</span><div>{(["audience", "purpose", "tone", "length"] as const).map((field) => <label key={field}><span>{field[0].toUpperCase() + field.slice(1)}</span><input className="text-input" onChange={(event) => { setOverrides((current) => ({ ...current, [field]: event.target.value })); setActionKey(null); }} value={overrides[field] ?? ""} /></label>)}</div><div className="btn-row"><button className="btn agent" disabled={pending !== "" || selectedTemplate.enabled === false} onClick={() => void previewTemplate()} type="button">{pending === "preview" ? "Preparing preview…" : "Preview with this matter"}</button><span>Creates a separate editable preview. It does not replace a draft, record a decision, or send work.</span></div></div> : null}
      <div className="btn-row draft-tools__actions"><button className="btn primary" disabled={pending !== "" || !hasScope || !instruction.trim() || !isDraftableTemplate} onClick={() => void requestDraft()} type="button">{pending === "draft" ? "Preparing draft…" : "Request draft"}</button>{!hasScope ? <span className="draft-tools__help">Choose a saved scope before requesting a draft.</span> : null}</div>
      {error ? <p className="error" role="alert">{error}</p> : null}{notice ? <p className="draft-tools__notice" role="status">{notice}</p> : null}
      {previewResult ? <div className="draft-result"><span className={`state-label ${stateClass(previewResult.state)}`}>{previewStateLabel(previewResult)}</span>{previewResult.artifact ? <><strong>{previewResult.artifact.title}</strong><div className="btn-row"><button className="btn quiet tiny" onClick={() => props.onSelectArtifact(previewResult.artifact!.path)} type="button">Open preview</button>{previewResult.artifact.preview ? <button className="btn tiny" disabled={pending !== "" || !props.onKeepPreview} onClick={() => void actOnArtifact(previewResult.artifact!, "keep")} type="button">{pending === "keep" ? "Keeping…" : "Keep preview"}</button> : null}</div></> : <span>State: {previewResult.state}</span>}</div> : null}
      {draftResult ? <div className="draft-result"><span className={`state-label ${stateClass(draftResult.state)}`}>{draftResult.artifact ? "Draft ready" : "Draft request"}</span>{draftResult.artifact ? <><strong>{draftResult.artifact.title}</strong><button className="btn quiet tiny" onClick={() => props.onSelectArtifact(draftResult.artifact!.path)} type="button">Open draft</button></> : null}{draftResult.proposal_path ? <><button className="btn quiet tiny" onClick={() => props.onSelectArtifact(draftResult.proposal_path!)} type="button">Open saved proposal</button>{submittedArtifact.current ? <span className="artifact-recovery"><button className="btn tiny quiet" disabled={pending !== "" || !props.onResolveDraftConflict} onClick={() => void actOnArtifact(submittedArtifact.current!, "retain_copy")} type="button">Retain copy</button><button className="btn tiny quiet" disabled={pending !== "" || !props.onResolveDraftConflict} onClick={() => void actOnArtifact(submittedArtifact.current!, "open_current")} type="button">Open current</button><button className="btn tiny quiet" disabled={pending !== "" || !props.onResolveDraftConflict} onClick={() => void actOnArtifact(submittedArtifact.current!, "rebase")} type="button">Rebase draft</button></span> : null}</> : null}</div> : null}
    </section>

    <aside aria-label="Available work product" className="artifact-list" hidden={props.view !== "draft"}><h2>Available work product</h2>{props.artifacts.length ? props.artifacts.map((artifact) => {
      const previewKeptHere = previewResult?.artifact?.path === artifact.path && previewResult.artifact.preview === false;
      const displayedArtifact = previewKeptHere ? { ...artifact, preview: false } : artifact;
      const offerState = artifact.update_offer?.state ?? "offered";
      return <article className={artifact.path === props.activeArtifactPath ? "artifact-row selected" : "artifact-row"} key={artifact.path}><div><strong>{artifact.title}</strong><p>{artifact.output_type ?? "Work product"} · version {artifact.revision}</p><ArtifactState artifact={displayedArtifact} /></div><div className="btn-row"><button className="btn tiny quiet" onClick={() => props.onSelectArtifact(artifact.path)} type="button">{artifact.path === props.activeArtifactPath ? "Open" : "Open work"}</button>{artifact.preview && !previewKeptHere ? <button className="btn tiny" disabled={pending !== "" || !props.onKeepPreview} onClick={() => void actOnArtifact(artifact, "keep")} type="button">{pending === "keep" ? "Keeping…" : "Keep preview"}</button> : null}{artifact.update_offer ? offerState === "declined" ? <><span className="state-label state-agent">Earlier facts · Draft retained</span><span className="artifact-earlier-facts">Ask in the conversation to request an update.</span></> : <><span className={`state-label ${offerState === "stale" ? "state-attention" : "state-agent"}`}>Update offer · {offerState}</span><button className="btn tiny" disabled={pending !== "" || !props.onUpdateOfferAction} onClick={() => void actOnArtifact(artifact, "accept")} type="button">Accept update</button><button className="btn tiny quiet" disabled={pending !== "" || !props.onUpdateOfferAction} onClick={() => void actOnArtifact(artifact, "decline")} type="button">Decline update</button></> : null}{artifact.proposal_paths?.map((path) => <button className="btn tiny quiet" key={path} onClick={() => props.onSelectArtifact(path)} type="button">Open saved proposal</button>)}{artifact.proposal_paths?.length ? <span className="artifact-recovery"><button className="btn tiny quiet" disabled={pending !== "" || !props.onResolveDraftConflict} onClick={() => void actOnArtifact(artifact, "retain_copy")} type="button">Retain copy</button><button className="btn tiny quiet" disabled={pending !== "" || !props.onResolveDraftConflict} onClick={() => void actOnArtifact(artifact, "open_current")} type="button">Open current</button><button className="btn tiny quiet" disabled={pending !== "" || !props.onResolveDraftConflict} onClick={() => void actOnArtifact(artifact, "rebase")} type="button">Rebase draft</button></span> : null}</div>{artifact.version_changes?.length ? <details><summary>Why this version changed</summary>{artifact.version_changes.map((change, index) => <p key={`${change.reason}:${index}`}>{change.reason}</p>)}</details> : null}</article>;
    }) : <p>No saved work product is available yet.</p>}</aside>
    <style jsx>{`
      .draft-workspace { min-width: 0; }.draft-workspace__head { display: flex; justify-content: space-between; align-items: center; gap: 14px; margin-bottom: 14px; }.draft-workspace__head p { margin: 0; color: var(--ink-3); font-size: 13px; }.draft-workspace__conversation-control { display: flex; align-items: center; justify-content: flex-end; gap: 9px; flex-wrap: wrap; }
      .draft-workspace__layout { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(330px, .9fr); gap: 16px; align-items: start; }.draft-workspace__understand, .draft-workspace__editor, .draft-workspace__conversation { min-width: 0; }.draft-workspace__understand, .draft-workspace__editor { grid-column: 1; grid-row: 1; }.draft-workspace__conversation { grid-column: 2; grid-row: 1; position: sticky; top: 76px; max-height: calc(100vh - 92px); overflow: auto; }.draft-workspace--discuss .draft-workspace__conversation { grid-column: 1 / -1; position: static; max-width: 920px; }.draft-workspace--discuss .draft-workspace__layout { grid-template-columns: 1fr; }
      .draft-workspace--conversation-collapsed .draft-workspace__layout { grid-template-columns: minmax(0, 1fr); }.draft-workspace--conversation-collapsed .draft-workspace__understand, .draft-workspace--conversation-collapsed .draft-workspace__editor { grid-column: 1; }
      .draft-tools, .artifact-list { margin-top: 16px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised); padding: 16px; }.draft-tools__head { display: flex; justify-content: space-between; align-items: start; gap: 12px; }.draft-tools__head h2, .artifact-list h2 { margin: 4px 0 0; }.draft-tools__snapshot, .draft-tools__help { color: var(--attention-deep); font-size: 13px; }.draft-tools__grid { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(220px, .7fr); gap: 14px; margin-top: 14px; }.draft-tools__grid > label, .draft-template, .draft-overrides label { display: grid; gap: 6px; color: var(--ink-3); font-size: 13px; }.draft-template { align-content: start; padding: 12px; border-left: 3px solid var(--agent); background: var(--agent-wash); }.draft-template span:not(.field-label) { color: var(--ink-3); font-size: 12px; }.draft-overrides { display: grid; gap: 9px; margin-top: 14px; padding: 12px; border: 1px dashed var(--agent-edge); background: var(--agent-wash); }.draft-overrides > div:first-of-type { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 9px; }.draft-overrides .btn-row span { color: var(--ink-3); font-size: 12px; }.draft-tools__actions { margin-top: 14px; }.draft-tools__notice { padding: 9px 11px; border-left: 3px solid var(--agent); background: var(--agent-wash); }.draft-result { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; margin-top: 12px; padding: 10px; border-left: 3px solid var(--agent); background: var(--agent-wash); }
      .artifact-list { display: grid; gap: 10px; }.artifact-row { display: grid; gap: 9px; padding: 11px; border-top: 1px solid var(--line-soft); }.artifact-row.selected { border-left: 3px solid var(--ink); background: var(--hover); }.artifact-row p { margin: 4px 0; color: var(--ink-3); font-size: 13px; }.artifact-row details { color: var(--ink-3); font-size: 13px; }.artifact-row details p { margin: 6px 0 0; }.artifact-recovery { display: flex; gap: 6px; flex-wrap: wrap; }.artifact-earlier-facts { color: var(--ink-3); font-size: 13px; }
      @media (max-width: 760px) { .draft-workspace__head { align-items: start; flex-direction: column; }.draft-workspace__layout { display: block; }.draft-workspace__conversation { position: static; top: auto; bottom: auto; z-index: auto; max-height: none; margin-top: 14px; overflow: visible; }.draft-workspace--discuss .draft-workspace__conversation { max-width: none; }.draft-tools__grid, .draft-overrides > div:first-of-type { grid-template-columns: 1fr; } }
      @media (max-width: 430px) { .draft-workspace__head .segmented { width: 100%; }.segmented label { flex: 1; text-align: center; padding-inline: 9px; }.draft-tools, .artifact-list { padding: 13px; }.draft-tools__head { flex-direction: column; }.draft-tools__actions .btn { width: 100%; }.artifact-row .btn-row .btn { width: 100%; } }
      @media (prefers-reduced-motion: reduce) { .draft-workspace * { transition: none !important; animation: none !important; } }
    `}</style>
  </section>;
}

frontend/app/globals.css:
/* Themis.ai design language — see docs/DESIGN_LANGUAGE.md */

:root {
  /* Surfaces */
  --paper: #f7f5f1;
  --raised: #fffefb;
  --sunken: #efece5;
  --rail: #f4f2ec;
  --hover: #faf8f4;

  /* Rules */
  --line: #ded9d0;
  --line-soft: #e2ded4;
  --line-faint: #eae6de;
  --line-hair: #f2efe8;
  --control: #d6d1c7;

  /* Ink */
  --ink: #1b1a17;
  --ink-lift: #33302b;
  --ink-2: #3a3733;
  --ink-3: #55524b;
  --ink-4: #5f5b54;
  --ink-5: #8a857c;
  --ink-6: #a8a298;

  /* Roles */
  --attention: #e0a008;
  --attention-tint: #fdeec0;
  --attention-wash: #fffdf4;
  --attention-deep: #8a6612;
  --attention-deepest: #6b4a02;
  --attention-edge: #f0d896;
  --healthy: #146b54;
  --healthy-tint: #e0efe9;
  --healthy-wash: #f8fcfa;
  --failure: #b33a20;
  --failure-tint: #f8e3dc;
  --failure-wash: #fffaf8;
  --failure-edge: #e9c9bd;
  --agent: #5f5ac0;
  --agent-tint: #eae8f9;
  --agent-wash: #fdfdff;
  --agent-edge: #cfcbee;
  --agent-dash: #b9b5e4;

  --serif: var(--font-serif), Georgia, "Times New Roman", serif;
  --sans: var(--font-sans), system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: var(--font-mono), "SFMono-Regular", Consolas, monospace;

  --radius: 10px;
  --content-wide: 1440px;
  --content-reading: 760px;
  --reader-sidebar: 360px;
  --space-page-inline: 40px;
  --space-page-block: 34px;
  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.06);
  --shadow-modal: 0 24px 60px rgba(27, 26, 23, 0.28);
}

/* Matter review and decision-map integration. */
.workspace-global-tools { margin: 10px 34px; border: 1px solid var(--line-soft); border-radius: var(--radius); background: var(--raised); }
.workspace-global-tools > summary { cursor: pointer; padding: 9px 12px; color: var(--ink-3); font: 600 13px/1.4 var(--sans); }
.workspace-global-tools[open] > summary { border-bottom: 1px solid var(--line-soft); }
.document-workspace { display: grid; gap: 12px; min-width: 0; }
.claim-markdown, .decision-map-claims { min-width: 0; overflow-wrap: anywhere; }
.claim-source-link { display: inline; border: 0; padding: 0; background: transparent; color: var(--agent); font: inherit; text-decoration: underline; text-underline-offset: 2px; cursor: pointer; }
.claim-source-link:disabled { color: var(--ink-4); cursor: not-allowed; text-decoration-style: dotted; }
.claim-table-scroll { max-width: 100%; overflow-x: auto; }
.decision-map-page { display: grid; gap: 16px; }
.decision-map-page__head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 18px; border: 1px solid var(--line); border-left: 5px solid var(--agent); border-radius: var(--radius); background: var(--agent-wash); }
.decision-map-page__head h1 { margin: 4px 0; }
.decision-map-page__head p { margin: 4px 0 0; color: var(--ink-3); }
.decision-map-page__head a { display: block; margin-bottom: 7px; }
.decision-map-claims { display: grid; gap: 9px; margin-top: 12px; }
.decision-map-claims article { padding: 10px; border: 1px dashed var(--agent-edge); border-radius: 7px; background: var(--agent-wash); }
.decision-map-discussion { border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised); overflow: hidden; }
.decision-map-discussion > h2 { margin: 0; padding: 12px 14px; border-bottom: 1px solid var(--line-soft); font: 600 18px/1.3 var(--serif); }
@media (max-width: 767px) {
  .workspace-global-tools { margin-inline: 14px; }
  .decision-map-page__head { padding: 14px; }
}

* { box-sizing: border-box; }
html, body { min-height: 100%; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  -webkit-font-smoothing: antialiased;
}
button, input, textarea, select { font: inherit; color: inherit; }
a { color: inherit; text-decoration: none; }
.app-shell :where(a, button, input, textarea, select, summary, [tabindex]):focus-visible {
  outline: 2px solid var(--agent) !important;
  outline-offset: 3px;
}
.app-shell :where(input, textarea, select):focus-visible { outline-offset: 1px; }
.auto-link, .rich-link { color: var(--agent); text-decoration: underline; text-underline-offset: 3px; }
h1, h2, h3, p { margin-top: 0; }

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb {
  background: #cfcabf; border-radius: 8px;
  border: 3px solid transparent; background-clip: content-box;
}

/* ── Type ─────────────────────────────────────────────────────────────── */

.serif { font-family: var(--serif); }
.mono { font-family: var(--mono); }
.record-meta {
  font: 500 10px var(--mono);
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-5);
}
.muted { color: var(--ink-3); }
.faint { color: var(--ink-5); }
.small { font-size: 13.5px; }
.label { font: 500 14px var(--sans); color: var(--ink-4); }
.section-heading { font: 600 17px var(--serif); color: var(--ink); }

h1 { font: 600 28px var(--serif); letter-spacing: -0.015em; margin-bottom: 0; }
h2 { font: 600 20px var(--serif); letter-spacing: -0.01em; margin-bottom: 0; }
h3 { font: 600 17px var(--serif); margin-bottom: 0; }

/* Long-form reading — memos, drafts, recorded decisions */
.reading { font: 400 16px/1.72 var(--serif); color: var(--ink-2); text-wrap: pretty; }
.reading h1 { font: 600 26px/1.25 var(--serif); color: var(--ink); letter-spacing: -0.01em; margin: 0; }
.reading h2 { font: 600 18px var(--serif); color: var(--ink); margin: 26px 0 0; }
.reading h3 { font: 600 17px var(--serif); color: var(--ink); margin: 22px 0 0; }
.reading p { margin: 9px 0 22px; }
.reading ul, .reading ol { margin: 9px 0 22px; padding-left: 1.5em; }
.reading li { margin: 4px 0; }
.reading blockquote {
  margin: 0 0 22px;
  padding: 2px 0 2px 16px;
  border-left: 2px solid var(--line-soft);
  font: italic 400 15.5px/1.7 var(--serif);
  color: var(--ink-3);
}
.reading strong { font-weight: 600; }
.reading code { font: 400 13.5px var(--mono); }

/* ── Shell ────────────────────────────────────────────────────────────── */

.app-shell { min-height: 100vh; display: flex; flex-direction: column; }
.topbar {
  display: flex; align-items: center; gap: 26px;
  height: 60px; padding: 0 40px;
  background: var(--raised);
  border-bottom: 1px solid var(--line-soft);
  position: sticky; top: 0; z-index: 40;
}
.brand { align-self: stretch; display: flex; align-items: center; flex: none; }
.brand-logo { display: block; width: auto; height: 100%; }
.nav { display: flex; gap: 20px; min-width: 0; }
.nav-group { display: flex; align-items: center; gap: 20px; }
.nav-primary { padding-right: 20px; border-right: 1px solid var(--line-soft); }
.nav-admin { gap: 16px; }
.nav-link { font: 400 14px var(--sans); color: var(--ink-3); padding-bottom: 2px; border-bottom: 2px solid transparent; }
.nav-link:hover { color: var(--ink); }
.nav-link.active, .nav-link[aria-current="page"] { font-weight: 600; color: var(--ink); border-bottom-color: var(--ink); }
.topbar-spacer { flex: 1; }
.topbar-search { font: 400 13.5px var(--sans); color: var(--ink-5); }
.avatar {
  width: 26px; height: 26px; border-radius: 50%; background: var(--line-soft);
  font: 500 11px var(--sans); color: var(--ink-2);
  display: flex; align-items: center; justify-content: center; flex: none;
}

.page { padding: var(--space-page-block) var(--space-page-inline) 44px; flex: 1; }
.page.narrow { width: 100%; max-width: 1120px; margin-inline: auto; }
.page.wide { width: 100%; max-width: var(--content-wide); margin-inline: auto; }
.page.reader { width: 100%; max-width: 1280px; margin-inline: auto; }
.page-header { display: flex; justify-content: space-between; align-items: flex-end; gap: 30px; }
.page-header p { margin: 6px 0 0; font: 400 15px var(--sans); color: var(--ink-3); }
.day { font: 400 14px var(--sans); color: var(--ink-4); }
.headline { font: 600 32px/1.15 var(--serif); color: var(--ink); letter-spacing: -0.015em; margin: 6px 0 0; }
.subhead { margin: 8px 0 0; font: 400 15px/1.6 var(--sans); color: var(--ink-3); max-width: 72ch; }
.eyebrow { font: 600 11px var(--mono); letter-spacing: .09em; text-transform: uppercase; color: var(--ink-4); }
.deck { margin: 8px 0 0; max-width: 72ch; font: 400 15px/1.6 var(--sans); color: var(--ink-3); text-wrap: pretty; }

/* ── Controls ─────────────────────────────────────────────────────────── */

.btn {
  font: 500 14px var(--sans);
  background: var(--raised);
  border: 1px solid var(--control);
  border-radius: 7px;
  padding: 9px 16px;
  color: var(--ink-2);
  cursor: pointer;
  white-space: nowrap;
}
.btn:hover:not(:disabled) { border-color: var(--ink-6); }
.btn:disabled { background: var(--sunken); color: var(--ink-6); border-color: var(--line); cursor: not-allowed; }
.btn.primary { background: var(--ink); border-color: var(--ink); color: var(--paper); }
.btn.primary:disabled { background: var(--sunken); border-color: var(--line); color: var(--ink-6); }
.btn.primary:hover:not(:disabled) { background: var(--ink-lift); border-color: var(--ink-lift); }
.data-load-status { display: flex; align-items: center; gap: 10px; }
.btn.review { background: var(--attention-tint); border-color: var(--attention-edge); color: var(--attention-deepest); }
.btn.review:hover:not(:disabled) { background: #fbe4a6; }
.btn.agent { background: transparent; border: 1px dashed var(--agent-edge); color: var(--agent); }
.btn.agent:hover:not(:disabled) { background: var(--agent-wash); border-color: var(--agent-dash); }
.btn.quiet { background: transparent; border-color: var(--line); }
.btn.compact { padding: 7px 13px; font-size: 13.5px; }
.btn.tiny { padding: 5px 11px; font-size: 13px; border-radius: 6px; }
.btn-row { display: flex; gap: 9px; align-items: center; flex-wrap: wrap; }

.segmented { display: flex; margin: 0; border: 0; background: var(--sunken); border-radius: 8px; padding: 3px; }
.segmented-option { display: contents; }
.segmented-input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
.segmented label {
  font: 400 13.5px var(--sans); color: var(--ink-3);
  background: transparent; border: 0; border-radius: 6px; padding: 6px 13px; cursor: pointer;
}
.segmented-input:checked + label {
  font-weight: 500; background: var(--raised); color: var(--ink);
  box-shadow: 0 1px 2px rgba(27, 26, 23, 0.06);
}
.segmented-input:focus-visible + label { outline: 2px solid var(--ink); outline-offset: 2px; }

.chip {
  font: 400 13.5px var(--sans);
  background: var(--raised);
  border: 1px solid var(--control);
  color: var(--ink-2);
  border-radius: 15px;
  padding: 5px 13px;
  cursor: pointer;
}
.chip.active { background: var(--ink); border-color: var(--ink); color: var(--paper); font-weight: 500; }

.text-input, .select-input {
  width: 100%;
  background: var(--raised);
  border: 1px solid var(--control);
  border-radius: 7px;
  padding: 9px 12px;
  font: 400 14.5px var(--sans);
  color: var(--ink);
  outline: none;
}
.text-input:focus, .select-input:focus { border-color: var(--ink); }
textarea.text-input { min-height: 90px; resize: vertical; line-height: 1.6; }
textarea.text-input.prose { font: 400 15.5px/1.7 var(--serif); padding: 14px 16px; }
.watch-question-input:focus::placeholder { color: transparent; }

.switch {
  position: relative; width: 38px; height: 22px; border-radius: 11px;
  border: 0; cursor: pointer; flex: none; margin-top: 2px; padding: 0;
}
.switch span {
  position: absolute; top: 2px; width: 18px; height: 18px; border-radius: 50%;
  background: var(--raised); box-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
  transition: left 120ms ease;
}
.checkbox-row {
  display: flex; align-items: center; gap: 11px; text-align: left;
  background: transparent; border: 0; padding: 4px 0; cursor: pointer;
  font: 400 15px var(--sans); color: var(--ink);
}
.checkbox-box {
  flex: none; width: 19px; height: 19px; border-radius: 5px; border: 1.5px solid var(--control);
  color: var(--paper); font: 600 12px var(--sans);
  display: flex; align-items: center; justify-content: center;
}
.checkbox-box.on { background: var(--ink); border-color: var(--ink); }
/* A native checkbox in a checkbox row wears the same box, not the OS blue. */
.checkbox-row > input[type="checkbox"] {
  appearance: none; -webkit-appearance: none;
  flex: none; width: 19px; height: 19px; margin: 0;
  border: 1.5px solid var(--control); border-radius: 5px; background: var(--raised);
  display: grid; place-items: center; cursor: pointer;
}
.checkbox-row > input[type="checkbox"]:checked { background: var(--ink); border-color: var(--ink); }
.checkbox-row > input[type="checkbox"]:checked::after {
  content: "✓"; color: var(--paper); font: 600 12px/1 var(--sans);
}
.checkbox-row > input[type="checkbox"]:hover:not(:disabled) { border-color: var(--ink-6); }
.checkbox-row > input[type="checkbox"]:disabled { background: var(--sunken); cursor: not-allowed; }

/* ── Signals ──────────────────────────────────────────────────────────── */

.dot { width: 8px; height: 8px; border-radius: 50%; flex: none; display: inline-block; }
.dot.sm { width: 7px; height: 7px; }
.signal { display: inline-flex; align-items: center; gap: 7px; font: 600 13.5px var(--sans); }
.agent-mark {
  width: 11px; height: 11px; border-radius: 3px;
  border: 1px dashed var(--agent-dash); display: inline-block; flex: none;
}
.agent-label { display: inline-flex; align-items: center; gap: 7px; font: 600 13.5px var(--sans); color: var(--agent); }

.agent-note {
  border: 1px dashed var(--agent-edge);
  background: var(--agent-wash);
  border-radius: 9px;
  padding: 16px 18px;
}
.agent-note p { margin: 9px 0 0; }

/* ── Cards, lists ─────────────────────────────────────────────────────── */

.card {
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.card.flat { box-shadow: none; }
.card-pad { padding: 18px 20px; }

.row-list { display: flex; flex-direction: column; }
.row {
  display: flex; gap: 20px; align-items: flex-start;
  padding: 20px 24px; border-bottom: 1px solid var(--line-hair);
  background: var(--raised);
}
.row:last-child { border-bottom: 0; }
.row:hover { background: var(--hover); }

.brief-row { position: relative; border-left: 3px solid transparent; padding-left: 21px; }
.brief-action::before { content: ""; position: absolute; inset: 0; }
.brief-row .auto-link { position: relative; z-index: 1; }
.brief-index { flex: none; width: 26px; font: 600 17px var(--serif); color: #c2bcb1; padding-top: 2px; }
.brief-title { font: 600 19px/1.35 var(--serif); color: var(--ink); margin-top: 7px; }
.brief-why { font: 400 15px/1.6 var(--sans); color: var(--ink-3); margin-top: 5px; max-width: 66ch; text-wrap: pretty; }
.brief-meta { display: flex; align-items: center; gap: 9px; font: 400 13.5px var(--sans); color: var(--ink-4); }

.quiet-list { display: flex; flex-direction: column; }
.quiet-row {
  display: flex; gap: 18px; align-items: baseline;
  padding: 9px 2px; border-bottom: 1px solid #e6e2d9;
  font: 400 15px/1.55 var(--sans); color: var(--ink-2);
}
.quiet-row span:last-child { flex: none; font-size: 14px; color: var(--ink-4); }

.stat-chips { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.stat-chip {
  display: flex; align-items: baseline; gap: 9px;
  border: 1px solid transparent; border-radius: 9px;
  padding: 11px 16px; cursor: pointer;
}
.stat-chip:hover { border-color: var(--control); }
.stat-chip.static { cursor: default; border-color: var(--line-faint); background: var(--raised); }
.stat-chip.active { border-color: var(--ink); }
.stat-chip b { font: 600 21px var(--serif); }
.stat-chip span { font: 500 14px var(--sans); white-space: nowrap; }

.legend { display: flex; align-items: baseline; gap: 20px; flex-wrap: wrap; }
.legend-item { display: flex; align-items: center; gap: 7px; font: 400 14px var(--sans); color: var(--ink-3); }

.footer-band {
  margin-top: 34px; padding: 24px 40px 30px;
  border-top: 1px solid var(--line-soft); background: #f2efe8;
  display: flex; justify-content: space-between; align-items: center; gap: 30px;
}

/* ── Matters — stage groups (5a) ──────────────────────────────────────── */

.stage-groups { display: flex; flex-direction: column; gap: 18px; }
.stage-group { display: flex; border: 1px solid var(--line-soft); border-radius: var(--radius); overflow: hidden; }
.stage-spine { flex: none; width: 5px; }
.stage-body { flex: 1; min-width: 0; background: var(--raised); }
.stage-head {
  display: flex; align-items: baseline; gap: 14px;
  padding: 11px 20px; border-bottom: 1px solid #e6e2d9;
}
.stage-toggle {
  display: flex; align-items: baseline; gap: 10px; min-width: 0;
  border: 0; padding: 0; background: transparent; color: inherit; cursor: pointer; text-align: left;
}
.stage-toggle:focus-visible { outline: 2px solid var(--agent); outline-offset: 3px; border-radius: 3px; }
.stage-toggle-icon { flex: none; color: var(--ink-5); font: 500 18px/1 var(--sans); transform: rotate(0deg); transition: transform 120ms ease; }
.stage-toggle-icon.open { transform: rotate(90deg); }
.stage-head-label { font: 600 16px var(--serif); color: var(--ink); }
.stage-head-sub { font: 400 14px var(--sans); color: var(--ink-4); }
.stage-head-note { font: 600 13.5px var(--sans); }
.stage-head-count { font: 400 14px var(--sans); color: var(--ink-5); width: 22px; text-align: right; }

.matter-row {
  display: flex; gap: 22px; align-items: center;
  padding: 14px 20px 14px 17px;
  border-bottom: 1px solid var(--line-hair);
  border-left: 3px solid transparent;
  cursor: grab;
}
.matter-row:hover { background: var(--hover); }
.matter-row-title { display: block; font: 600 17px/1.35 var(--serif); color: var(--ink); }
.matter-title-cell {
  align-self: stretch; display: flex; flex-direction: column; justify-content: center;
  margin: -14px 0 -14px -17px; padding: 14px 17px;
}
.matter-row-type { display: block; font: 400 14px/1.5 var(--sans); color: var(--ink-3); margin-top: 3px; }
.matter-row-next { display: block; font: 400 15px/1.5 var(--sans); color: var(--ink-2); }
.matter-row-owner { flex: none; width: 96px; font: 400 14px var(--sans); color: var(--ink-4); }
.matter-row-due { flex: none; width: 92px; text-align: right; font: 400 14px var(--sans); }
.stage-empty { padding: 14px 20px; font: 400 14px var(--sans); color: var(--ink-5); }

/* ── Workspace board (3b) ─────────────────────────────────────────────── */

.board { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 12px; align-items: start; }
.board-column {
  border-radius: 9px; padding: 4px;
  display: flex; flex-direction: column; gap: 8px; min-height: 150px;
}
.board-head {
  padding: 4px 6px 6px;
  display: flex; justify-content: space-between; align-items: baseline; gap: 6px;
}
.board-head span:first-child { font: 600 13.5px/1.3 var(--sans); }
.board-head span:last-child { font: 400 13px var(--sans); color: var(--ink-5); }
.board-card {
  display: block; background: var(--raised);
  border: 1px solid #e6e2d9; border-left: 3px solid transparent;
  border-radius: 8px; padding: 12px 13px; cursor: grab;
}
.board-card:hover { border-color: #c9c3b7; }
.board-card-title { display: block; font: 600 15px/1.35 var(--serif); color: var(--ink); }
.board-card-why { display: block; font: 400 13.5px/1.5 var(--sans); color: var(--ink-3); margin-top: 5px; }
.board-card-foot {
  display: flex; justify-content: space-between; align-items: baseline; gap: 8px;
  margin-top: 9px; font: 400 13px var(--sans); color: var(--ink-5);
}

.quarter-row { display: flex; gap: 14px; align-items: baseline; }
.quarter-row b { flex: none; width: 100px; font: 600 20px var(--serif); }
.quarter-row span { flex: 1; font: 400 15px var(--sans); color: var(--ink-3); }
.activity-row {
  display: flex; gap: 12px; align-items: baseline;
  padding: 9px 0; border-bottom: 1px solid #e6e2d9;
  font: 400 15px/1.55 var(--sans); color: var(--ink-2);
}

.intake-bar {
  display: flex; gap: 14px; align-items: center;
  background: var(--raised); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 16px 20px;
}
.intake-bar.dropping { border-color: var(--attention); background: #fffdf4; }

.today-start { margin-top: 24px; display: flex; flex-direction: column; gap: 12px; }
.today-chat { padding: 20px; }
.today-chat-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 24px; }
.today-chat-head p { margin: 4px 0 0; font: 400 14px/1.5 var(--sans); color: var(--ink-3); }
.today-chat-day-row {
  display: flex; align-items: center; gap: 9px; margin-top: 14px;
  font: 400 12.5px var(--sans); color: var(--ink-4);
}
.today-chat-day-row label { font-weight: 600; color: var(--ink-3); }
.today-chat-day-row select {
  border: 1px solid var(--line); border-radius: 7px; background: var(--raised);
  padding: 7px 28px 7px 9px; font: 400 13px var(--sans); color: var(--ink);
}
.today-chat-status { margin: 12px 0 0; font: 400 13px var(--sans); color: var(--ink-4); }
.today-chat-history { margin-top: 12px; }
.today-chat-history > summary { cursor: pointer; font: 600 13.5px/1.4 var(--sans); color: var(--ink-3); }
.today-chat-history-note { margin: 12px 0 0; padding: 8px 10px; border-left: 2px solid var(--agent); background: var(--agent-wash); font: 500 13px/1.45 var(--sans); color: var(--ink-3); }
.today-chat-saved-label { margin-bottom: 7px; font: 700 11px/1.3 var(--sans); letter-spacing: .06em; text-transform: uppercase; color: var(--agent); }
.today-chat-thread {
  max-height: 280px; overflow-y: auto; margin: 16px -2px 14px; padding: 14px 2px 0;
  border-top: 1px solid var(--line-faint); display: flex; flex-direction: column; gap: 16px;
}
.today-chat-suggestions { display: flex; flex-wrap: wrap; gap: 7px; margin: 16px 0 9px; }

/* ── Matter workspace (2b) ────────────────────────────────────────────── */

.matter-shell { display: flex; flex-direction: column; height: calc(100vh - 51px); position: relative; }
.matter-head {
  flex: none; background: var(--raised); border-bottom: 1px solid var(--line-soft);
  padding: 14px 40px; display: flex; justify-content: space-between; align-items: center; gap: 30px;
}
.matter-head-context { display: flex; align-items: center; gap: 10px; min-width: 0; }
.matter-status-signal {
  flex: none; display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 8px; border: 1px solid currentColor; border-radius: 999px;
  font: 600 12px var(--sans); background: var(--raised);
}
.matter-crumb { font: 400 13.5px var(--sans); color: var(--ink-4); }
.matter-title { margin: 3px 0 0; font: 600 22px/1.2 var(--serif); color: var(--ink); letter-spacing: -0.01em; }
.matter-facts { display: flex; gap: 26px; margin: 0; flex: none; }
.matter-facts > div { display: grid; gap: 3px; }
.matter-facts dt {
  font: 500 11px var(--sans);
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--ink-5);
}
.matter-facts dd {
  margin: 0;
  font: 500 13px var(--sans);
  color: var(--ink-2);
  white-space: nowrap;
}
.matter-panes {
  flex: 1; min-height: 0; display: grid;
  grid-template-columns: minmax(210px, 0.24fr) 8px minmax(360px, 1fr) 8px minmax(430px, 1.15fr);
  transition: grid-template-columns 160ms ease;
}
.matter-panes:has(.pane-resizer:active) { transition: none; cursor: col-resize; user-select: none; }
.pane-resizer {
  position: relative; z-index: 3; width: 8px; min-width: 0; height: 100%;
  border: 0; padding: 0; background: transparent; cursor: col-resize; touch-action: none;
}
.pane-resizer::after {
  content: ""; position: absolute; inset: 0 3px; background: var(--line-soft);
  transition: background 120ms ease, inset 120ms ease;
}
.pane-resizer:hover::after, .pane-resizer:active::after, .pane-resizer:focus-visible::after {
  inset: 0 2px; background: var(--ink-6);
}
.pane-resizer:focus-visible { outline: 2px solid var(--agent); outline-offset: -2px; }
.pane-resizer.hidden { width: 0; visibility: hidden; pointer-events: none; }
.matter-tree-pane {
  min-width: 0; min-height: 0; display: flex; flex-direction: column;
  border-right: 1px solid var(--line-soft); background: var(--hover);
}
.matter-tree-head {
  flex: none; display: flex; align-items: center; justify-content: space-between;
  padding: 13px 16px; border-bottom: 1px solid var(--line-faint);
  font: 600 13px var(--sans); color: var(--ink-4);
}
.matter-tree-head-actions { display: flex; align-items: center; gap: 8px; }
.matter-tree-count { font: 500 11px var(--mono); color: var(--ink-6); }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}
.matter-risk-select {
  max-width: 112px; border: 1px solid var(--control); border-radius: 6px;
  background: var(--raised); color: var(--ink); padding: 4px 7px; font: 500 12px var(--sans);
}
.matter-action-notice {
  margin: 10px 34px 0; border: 1px solid var(--healthy); border-radius: 7px;
  background: var(--healthy-tint); color: var(--healthy); padding: 9px 12px;
  font: 600 13px/1.4 var(--sans);
}
.matter-tree-scroll { flex: 1; min-height: 0; overflow-y: auto; }
.brief-pane {
  --matter-gutter: max(34px, calc((100% - 920px) / 2));
  border-right: 1px solid var(--line-soft);
  background: var(--raised);
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.pane-content { min-width: 0; min-height: 0; height: 100%; display: flex; flex-direction: column; }
.middle-section { flex: none; min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.middle-section.active { flex: 1 1 0; }
.middle-section-toggle {
  flex: none; display: flex; align-items: center; justify-content: space-between; gap: 12px;
  width: 100%; min-height: 42px; padding: 9px 18px; border: 0; border-bottom: 1px solid var(--line-faint);
  background: var(--rail); color: var(--ink-3); cursor: pointer; text-align: left;
  font: 600 13.5px var(--sans);
}
.middle-section-toggle:hover { background: var(--sunken); color: var(--ink); }
.middle-section-toggle[aria-expanded="true"] { background: var(--raised); color: var(--ink); }
.middle-section-toggle > span:last-child { color: var(--ink-5); font: 500 18px/1 var(--sans); }
.middle-section-panel { flex: 1 1 0; min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.middle-section-panel[hidden] { display: none; }
.middle-section-panel.brief-scroll { flex: 1 1 0; max-height: none; }
.pane-head {
  flex: none; display: flex; align-items: center; justify-content: space-between;
  padding: 9px 12px 9px 18px; border-bottom: 1px solid var(--line-faint);
  font: 600 12px var(--sans); color: var(--ink-4);
}
.pane-collapse {
  display: grid; place-items: center; width: 28px; height: 28px; padding: 0;
  border: 1px solid var(--control); border-radius: 7px; background: var(--raised);
  color: var(--ink-4); cursor: pointer; font: 500 20px/1 var(--sans);
}
.pane-collapse:hover, .pane-collapse:focus-visible { border-color: var(--ink-6); color: var(--ink); outline: none; }
.pane-rail {
  width: 100%; height: 100%; border: 0; border-right: 1px solid var(--line-soft);
  background: var(--hover); color: var(--ink-4); cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 12px; padding: 12px 0;
  font: 600 12px var(--sans); letter-spacing: .02em;
}
.pane-rail > span:last-child { writing-mode: vertical-rl; }
.pane-rail:hover, .pane-rail:focus-visible { background: var(--sunken); color: var(--ink); outline: none; }
.pane-rail[hidden], .pane-content[hidden], .document-pane-content[hidden] { display: none; }
.document-pane-shell, .document-pane-content { min-width: 0; min-height: 0; height: 100%; }
.document-pane-shell { overflow: hidden; }
.document-pane-content > .doc-pane { height: 100%; }
.brief-scroll {
  flex: 0 1 auto;
  min-height: 0;
  max-height: 62%;
  overflow-y: auto;
  padding: 0;
  border-bottom: 1px solid var(--line-faint);
  background: var(--raised);
}
.evidence-row { display: flex; gap: 14px; align-items: baseline; padding: 11px 12px; border-radius: 7px; }
.evidence-row:hover { background: var(--rail); }
.evidence-kind { flex: none; width: 132px; font: 400 13px var(--sans); color: var(--ink-5); }
.evidence-name { display: block; font: 500 15px var(--sans); color: var(--ink); }
.evidence-note { display: block; font: 400 14px/1.5 var(--sans); color: var(--ink-3); margin-top: 2px; }

.matter-brief { padding: 20px var(--matter-gutter) 26px; }
.matter-call {
  margin: 0 0 22px;
  border: 1px solid var(--attention-edge);
  border-left: 4px solid var(--attention);
  border-radius: 10px;
  background: var(--attention-wash);
  padding: 18px 22px 20px;
}
.matter-call.is-complete {
  border-color: var(--line-soft);
  border-left-color: var(--ink-6);
  background: var(--rail);
}
.matter-call-kicker {
  display: block;
  margin-bottom: 10px;
  font: 600 12px var(--sans);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--attention-deepest);
}
.matter-call.is-complete .matter-call-kicker { color: var(--ink-4); }
.matter-call-task {
  margin: 0;
  font: 600 21px/1.4 var(--serif);
  color: var(--ink);
  text-wrap: pretty;
}
.matter-recommendation, .matter-orientation {
  margin-top: 17px;
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  background: var(--raised);
  padding: 13px 15px;
}
.matter-recommendation-label, .matter-orientation-label {
  font: 600 11.5px/1.4 var(--sans);
  color: var(--ink-4);
}
.matter-recommendation p, .matter-orientation p {
  margin: 8px 0 0;
  font: 400 15px/1.6 var(--serif);
  color: var(--ink-2);
}
.matter-orientation-question { margin-top: 14px; }
.matter-original-request {
  margin-top: 12px;
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  background: var(--raised);
}
.matter-original-request > summary {
  cursor: pointer;
  padding: 12px 15px;
  font: 600 13.5px var(--sans);
  color: var(--ink-3);
}
.matter-original-request > summary:hover { color: var(--ink); }
.matter-original-request-text {
  border-top: 1px solid var(--line-faint);
  padding: 13px 15px 15px;
  white-space: pre-wrap;
  font: 400 15px/1.6 var(--serif);
  color: var(--ink-2);
}
.matter-call-do {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--attention-edge);
}
.matter-call-do > span {
  font: 600 12px var(--sans);
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--attention-deepest);
}
.matter-call-button { flex: none; }
.matter-open { margin: 0 0 20px; }
.matter-open-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 10px;
}
.matter-open-head h2 { margin: 0; font: 600 15px var(--sans); color: var(--ink-3); }
.matter-open-head > span { flex: none; font: 500 12.5px var(--sans); color: var(--ink-4); }
.matter-open-list { margin: 0; padding: 0; list-style: none; display: grid; gap: 2px; }
.matter-open-list li {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 7px;
  font: 400 14.5px/1.5 var(--sans);
  color: var(--ink-2);
}
.matter-open-list li.is-required { background: var(--attention-wash); }
.matter-open-text { flex: 1; min-width: 0; }
.matter-open-mark {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ink-6);
  transform: translateY(-1px);
}
.matter-open-list li.is-required .matter-open-mark { background: var(--attention); }
.matter-open-tag {
  flex: none;
  font: 600 11px var(--sans);
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--attention-deep);
}
.matter-open-empty { margin: 0; font: 400 14.5px/1.5 var(--sans); color: var(--ink-4); }
.matter-reference-body h2 { margin: 0 0 8px; font: 600 15px var(--sans); color: var(--ink-3); }
.matter-reference-body p { margin: 0; font: 400 15.5px/1.6 var(--serif); color: var(--ink-2); }
.matter-reference-body ul { margin: 0; padding-left: 20px; }
.matter-reference-body li { margin: 6px 0; font: 400 14.5px/1.5 var(--sans); color: var(--ink-2); }
.matter-reference { margin-top: 24px; border-top: 1px solid var(--line-faint); padding-top: 15px; }
.matter-reference > summary { cursor: pointer; font: 600 13.5px var(--sans); color: var(--ink-3); }
.matter-reference > summary:hover { color: var(--ink); }
.matter-reference-body { display: grid; gap: 24px; padding-top: 20px; }
.matter-reference-body section { margin: 0; }
.matter-record-note { margin-top: 10px; font: 400 13px/1.5 var(--sans); color: var(--ink-4); }
.evidence-list { display: flex; flex-direction: column; gap: 5px; }
.evidence-list .evidence-row { width: 100%; border: 0; background: transparent; cursor: pointer; text-align: left; }
.evidence-list .matter-artifact-link { margin: 8px 12px 0; }

.trace-list { margin-top: 12px; border: 1px solid var(--line-faint); border-radius: 8px; overflow: hidden; }
.trace-item {
  display: flex; gap: 12px; align-items: baseline;
  padding: 9px 13px; border-bottom: 1px solid var(--line-hair);
  font: 400 13.5px/1.5 var(--sans); color: var(--ink-3);
}
.trace-item:last-child { border-bottom: 0; }

.chat-history-status { flex: none; margin: 0; padding: 7px 34px; font: 400 13px var(--sans); color: var(--ink-4); }
.chat-panel { flex: 1; min-height: 260px; display: flex; flex-direction: column; }
.thread {
  flex: 1; min-height: 0; overflow-y: auto;
  padding: 14px var(--matter-gutter) 18px; border-top: 1px solid var(--line-faint);
  display: flex; flex-direction: column; gap: 18px;
}
.bubble-you {
  align-self: flex-end; max-width: 82%; background: var(--sunken);
  border-radius: 10px 10px 3px 10px; padding: 11px 14px;
  font: 400 15px/1.55 var(--sans); color: var(--ink); white-space: pre-wrap;
}
.assistant-message {
  border: 1px dashed var(--agent-dash); border-radius: 10px; background: var(--agent-wash);
  padding: 13px 15px 14px;
}
.assistant-message > .agent-label { margin-bottom: 9px; color: var(--agent); }
.intake-turn-history { border: 1px solid var(--line-soft); border-radius: 8px; background: var(--rail); }
.intake-turn-history > summary { display: flex; flex-direction: column; gap: 5px; padding: 10px 12px; cursor: pointer; font: 500 13px/1.45 var(--sans); color: var(--ink-3); }
.intake-turn-history > summary::marker { color: var(--agent); }
.intake-turn-history[open] > summary { border-bottom: 1px solid var(--line-soft); }
.intake-turn-history > .bubble-agent { padding: 12px; }
.intake-history-label { font: 700 11px/1.3 var(--sans); letter-spacing: .08em; text-transform: uppercase; color: var(--agent); }
.intake-history-context { margin-bottom: 10px; padding: 8px 10px; border-left: 2px solid var(--agent); background: var(--agent-wash); font: 500 13px/1.45 var(--sans); color: var(--ink-3); }
.bubble-agent { min-width: 0; }
.bubble-agent p { margin: 0 0 9px; font: 400 15px/1.6 var(--sans); color: var(--ink-2); text-wrap: pretty; }
.bubble-agent > :last-child { margin-bottom: 0; }
.bubble-agent h1, .bubble-agent h2, .bubble-agent h3 {
  color: var(--ink); margin: 18px 0 7px;
}
.bubble-agent h1:first-child, .bubble-agent h2:first-child, .bubble-agent h3:first-child { margin-top: 0; }
.bubble-agent h1 { font: 600 21px/1.3 var(--serif); }
.bubble-agent h2 { font: 600 18px/1.35 var(--serif); }
.bubble-agent h3 { font: 600 16px/1.4 var(--serif); }
.bubble-agent ul, .bubble-agent ol {
  margin: 4px 0 12px; padding-left: 1.5em;
  font: 400 15px/1.6 var(--sans); color: var(--ink-2);
}
.bubble-agent li { margin: 3px 0; }
.bubble-agent li > p { margin: 0; }
.bubble-agent blockquote {
  margin: 10px 0 12px; padding: 2px 0 2px 13px;
  border-left: 2px solid var(--line-soft); color: var(--ink-3);
}
.bubble-agent blockquote p { color: inherit; font-style: italic; }
.bubble-agent a { color: var(--agent); text-decoration: underline; text-underline-offset: 2px; }
.bubble-agent code {
  border-radius: 4px; background: var(--sunken); padding: 1px 4px;
  font: 400 13.5px/1.55 var(--mono); color: var(--ink-lift);
}
.bubble-agent pre {
  max-width: 100%; overflow-x: auto; margin: 10px 0 12px;
  border: 1px solid var(--line-faint); border-radius: 7px; background: var(--sunken); padding: 11px 13px;
}
.bubble-agent pre code { background: transparent; padding: 0; }
.bubble-agent hr { margin: 14px 0; border: 0; border-top: 1px solid var(--line-soft); }
.bubble-agent table { width: 100%; margin: 10px 0 12px; border-collapse: collapse; font: 400 15px/1.5 var(--sans); }
.bubble-agent th, .bubble-agent td { border: 1px solid var(--line-soft); padding: 7px 9px; text-align: left; }
.bubble-agent th { background: var(--rail); font-weight: 600; }
.bubble-agent img { max-width: 100%; height: auto; }

.composer {
  flex: none;
  border-top: 1px solid var(--line-faint);
  background: var(--raised);
  padding: 12px var(--matter-gutter) 16px;
}
.composer-suggestions { display: flex; gap: 7px; flex-wrap: wrap; margin-bottom: 9px; }
.suggestion {
  font: 400 13.5px var(--sans); background: transparent;
  border: 1px dashed var(--control); border-radius: 15px;
  padding: 5px 12px; color: var(--ink-3); cursor: pointer;
}
.suggestion:hover { border-color: var(--agent-dash); color: var(--agent); }
.composer-field {
  display: flex; align-items: flex-end; gap: 9px;
  border: 1px solid var(--line); border-radius: 9px; padding: 10px 12px;
}
.composer-field textarea {
  flex: 1; border: 0; outline: none; resize: none; background: transparent;
  min-height: 24px; max-height: 140px;
  font: 400 15px/1.5 var(--sans); color: var(--ink);
}
.composer-field textarea::placeholder { color: var(--ink-5); }
.composer-note { margin-top: 7px; font: 400 13px var(--sans); color: var(--ink-5); }
.build-skill-link { color: var(--agent); text-decoration: underline; text-underline-offset: 2px; }
.applied-skill-label { margin-bottom: 6px; font: 600 11.5px var(--sans); color: var(--agent); }
.human-skill-label { display: block; margin-bottom: 4px; font: 600 12px var(--sans); color: var(--agent); }
.skill-invocation { border: 1px solid var(--agent-dash); background: var(--agent-wash); }
.chat-actions { margin-top: 12px; font: 500 13px var(--sans); color: var(--ink-4); }
.chat-actions summary { width: fit-content; cursor: pointer; }
.chat-actions .trace-list { margin-top: 8px; }
.skill-command-menu { margin: 0 0 8px 39px; border: 1px solid var(--line-soft); border-radius: 8px; background: var(--raised); box-shadow: var(--shadow-card); overflow: hidden; }
.skill-command-menu button { width: 100%; display: grid; grid-template-columns: minmax(150px, .7fr) 1.3fr; gap: 12px; border: 0; border-bottom: 1px solid var(--line-faint); background: transparent; padding: 9px 11px; text-align: left; cursor: pointer; }
.skill-command-menu button:last-child { border-bottom: 0; }
.skill-command-menu button:hover, .skill-command-menu button:focus-visible { background: var(--agent-wash); outline: none; }
.skill-command-menu button > span:last-child { display: flex; flex-direction: column; gap: 2px; font: 400 12.5px/1.4 var(--sans); color: var(--ink-4); }
.skill-command-menu b { color: var(--ink); font-size: 13.5px; }

/* Persisted chat cards and attachment controls extend the existing chat flow. */
.chat-cards { display: flex; flex-direction: column; gap: 9px; margin-top: 12px; }
.chat-card, .upload-intent-card {
  border: 1px solid var(--line-soft); border-radius: 9px; background: var(--raised);
  padding: 13px 14px; font-family: var(--sans);
}
.chat-card-kicker { font: 600 11px var(--mono); letter-spacing: .07em; text-transform: uppercase; color: var(--ink-5); }
.chat-card-summary { margin-top: 4px; font: 600 14.5px/1.45 var(--sans); color: var(--ink); }
.chat-card-detail { margin-top: 5px; font: 400 13px/1.5 var(--sans); color: var(--ink-4); }
.chat-card-actions { display: flex; gap: 7px; align-items: center; flex-wrap: wrap; margin-top: 11px; }
.question-sequence { display: flex; flex-direction: column; gap: 8px; }
.question-mode-control {
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  border: 1px solid var(--line-soft); border-radius: 9px; background: var(--sunken); padding: 9px 10px;
}
.question-mode-control > div:first-child { display: flex; flex-direction: column; gap: 2px; }
.question-mode-control strong { font: 600 12px var(--sans); color: var(--ink-2); }
.question-mode-control span { font: 400 11.5px/1.4 var(--sans); color: var(--ink-5); }
.question-mode-options { display: flex; flex: none; border: 1px solid var(--control); border-radius: 7px; overflow: hidden; }
.question-mode-options button {
  border: 0; border-right: 1px solid var(--control); background: var(--raised); color: var(--ink-4);
  padding: 6px 9px; cursor: pointer; font: 500 12px var(--sans);
}
.question-mode-options button:last-child { border-right: 0; }
.question-mode-options button.active { background: var(--agent-wash); color: var(--agent); }
.question-mode-options button:focus-visible { outline: 2px solid var(--agent-dash); outline-offset: -2px; }
.question-mode-options button:disabled { cursor: default; opacity: .55; }
@media (max-width: 720px) {
  .question-mode-control { align-items: stretch; flex-direction: column; }
  .question-mode-options { align-self: flex-start; }
}
.question-card.conflict { border-color: var(--attention-edge); background: var(--attention-tint); }
.question-meta { display: flex; gap: 10px; justify-content: space-between; font: 500 11.5px var(--sans); color: var(--ink-5); }
.question-title-row { display: flex; align-items: flex-start; gap: 9px; }
.question-title-row .chat-card-summary { flex: 1; }
.question-choices { display: grid; gap: 6px; margin-top: 11px; }
.question-choice {
  display: flex; justify-content: flex-start; align-items: center; gap: 10px; width: 100%;
  border: 1px solid var(--control); border-radius: 7px; background: transparent; color: var(--ink-2);
  padding: 8px 10px; text-align: left; font: 400 13.5px var(--sans); cursor: pointer;
}
.question-choice .suggested-label { margin-left: auto; }
.question-choice:hover, .question-choice:focus-visible { border-color: var(--agent-dash); outline: none; }
.question-choice.active { border-color: var(--ink); background: var(--sunken); }
.suggested-label { flex: none; border-radius: 10px; background: var(--agent-wash); color: var(--agent); padding: 2px 7px; font-size: 11px; }
.question-free-text { display: flex; gap: 7px; align-items: center; margin-top: 11px; }
.reason-control { position: relative; flex: none; margin-top: 2px; }
.reason-control summary {
  display: grid; place-items: center; width: 20px; height: 20px; border: 1px solid var(--control);
  border-radius: 50%; color: var(--ink-4); cursor: pointer; font: 600 12px var(--serif); list-style: none;
}
.reason-control summary::-webkit-details-marker { display: none; }
.reason-control summary:focus-visible { outline: 2px solid var(--agent-dash); outline-offset: 2px; }
.reason-control > div {
  display: none; position: absolute; z-index: 4; right: 0; top: 25px; width: min(260px, 70vw);
  border: 1px solid var(--line-soft); border-radius: 7px; background: var(--raised); box-shadow: var(--shadow-card);
  padding: 9px 10px; font: 400 12.5px/1.45 var(--sans); color: var(--ink-3);
}
.reason-control[open] > div, .reason-control:hover > div, .reason-control:focus-within > div { display: block; }
.research-card { padding: 0; }
.research-card summary { display: flex; align-items: center; gap: 10px; padding: 12px 14px; cursor: pointer; list-style: none; }
.research-card summary::-webkit-details-marker { display: none; }
.research-card summary > span:nth-child(2) { flex: 1; }
.research-card .chat-card-summary { display: block; }
.research-card > .chat-card-detail { padding: 0 14px 13px 38px; margin: 0; }
.research-progress { font: 500 11px var(--mono); color: var(--ink-5); }
.research-indicator { width: 10px; height: 10px; border-radius: 50%; background: var(--healthy); flex: none; }
.research-indicator.active { background: var(--agent); animation: research-pulse 1.5s ease-in-out infinite; }
@keyframes research-pulse { 0%, 100% { opacity: .35; transform: scale(.85); } 50% { opacity: 1; transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .research-indicator.active { animation: none; opacity: 1; } }
.work-product-link, .matter-artifact-link {
  border: 0; background: transparent; padding: 0; color: var(--agent); text-align: left; cursor: pointer;
  font: 600 14.5px/1.45 var(--sans); text-decoration: underline; text-underline-offset: 2px;
}
.attachment-picker { display: flex; align-items: center; gap: 5px; flex: none; }
.composer-plus {
  display: grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 1px solid var(--control);
  border-radius: 50%; background: transparent; color: var(--ink-3); cursor: pointer; font: 400 20px/1 var(--sans);
}
.composer-plus:hover:not(:disabled), .composer-plus:focus-visible { border-color: var(--ink-6); color: var(--ink); }
.attachment-picker button:disabled { cursor: not-allowed; opacity: .5; }
.upload-intent-card { margin-bottom: 10px; background: var(--agent-wash); border-style: dashed; border-color: var(--agent-edge); }
.upload-file-list { margin-top: 4px; font: 400 12.5px/1.45 var(--sans); color: var(--ink-4); overflow-wrap: anywhere; }
.upload-intent-card label { display: block; margin-top: 10px; font: 500 13px var(--sans); color: var(--ink-2); }
.matter-artifacts { margin-top: 24px; border-top: 1px solid var(--line-faint); padding-top: 17px; display: flex; flex-direction: column; gap: 10px; }
.matter-artifacts.compact { margin-top: 16px; padding-top: 14px; }
.matter-artifacts > strong { font: 600 13px var(--sans); color: var(--ink-3); }
.matter-artifact-empty { font: 400 13px/1.5 var(--sans); color: var(--ink-4); }
.matter-artifact-link { display: flex; flex-direction: column; gap: 2px; text-decoration: none; }
.matter-artifact-link span:last-child { color: var(--ink-4); font-weight: 400; font-size: 13px; }
.matter-lifecycle-action { margin-top: 14px; padding: 12px; border: 1px solid var(--line-soft); border-radius: 8px; background: var(--raised); }
.matter-lifecycle-action > span { font: 600 11px var(--mono); letter-spacing: .06em; text-transform: uppercase; color: var(--ink-4); }
.matter-lifecycle-action p { margin: 5px 0 10px; font: 400 13.5px/1.45 var(--sans); color: var(--ink-3); }
.matter-inline-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.matter-new-draft-toggle { align-self: flex-start; margin-top: 4px; }
.matter-new-draft {
  display: grid; gap: 8px; padding: 12px; border: 1px dashed var(--agent-edge);
  border-radius: 8px; background: var(--agent-wash);
}
.matter-new-draft label { font: 600 12px var(--sans); color: var(--ink-3); }
.text-button {
  border: 0; background: transparent; color: inherit; padding: 0; cursor: pointer;
  font: inherit; text-decoration: underline; text-underline-offset: 2px;
}
.mutation-status { width: fit-content; margin-top: 10px; border-radius: 12px; padding: 4px 9px; font: 600 12px var(--sans); }
.mutation-status.recorded { background: var(--healthy-tint); color: var(--healthy); }
.mutation-status.no-change { background: var(--failure-tint); color: var(--failure); }

/* ── Document pane / editor (4c) ──────────────────────────────────────── */

.doc-pane {
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--rail); min-height: 0;
}
.doc-bar {
  flex: none; background: var(--rail);
  border-bottom: 1px solid var(--line-soft); padding: 12px 34px;
  display: flex; justify-content: space-between; align-items: center; gap: 16px;
}
.doc-name { font: 500 15px var(--sans); color: var(--ink); }
.doc-status { font: 400 13.5px var(--sans); color: var(--ink-4); margin-left: 10px; }
.doc-status.agent { color: var(--agent); }
.doc-sheet {
  background: var(--raised); border: 1px solid var(--line-soft);
  border-radius: 9px; padding: 34px 38px 30px; max-width: 64ch;
}
.doc-scroll { flex: 1; min-height: 0; overflow-y: auto; padding: 28px 34px 60px; }
.doc-mode { display: flex; gap: 6px; }
.doc-mode button {
  font: 500 13.5px var(--sans); background: var(--raised);
  border: 1px solid var(--control); border-radius: 7px;
  padding: 7px 13px; color: var(--ink-3); cursor: pointer;
}
.doc-mode button.active { background: var(--sunken); color: var(--ink); }
.doc-mode .pane-collapse { width: 28px; height: 32px; padding: 0; font-size: 20px; }
.doc-mode .pane-close { width: 28px; height: 32px; padding: 0; font-size: 18px; }
.research-sources { padding: 28px 34px; }
.research-source-card {
  max-width: 68ch; margin: 0 auto 16px; padding: 18px 20px;
  border: 1px solid var(--line-soft); border-radius: 9px; background: var(--raised);
}
.research-source-heading { display: flex; align-items: baseline; gap: 10px; }
.research-source-heading > span {
  border-radius: 4px; background: var(--agent); color: var(--paper); padding: 2px 7px;
  font: 600 11px var(--sans);
}
.research-source-heading strong { font: 600 17px/1.3 var(--serif); color: var(--ink); }
.research-source-kind { margin-top: 6px; font: 400 13.5px/1.5 var(--sans); color: var(--ink-4); overflow-wrap: anywhere; }
.research-source-card p { margin: 14px 0 0; font: 400 14.5px/1.6 var(--sans); color: var(--ink-3); }

.rich-editor-shell { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.rich-toolbar {
  flex: none;
  display: flex; flex-wrap: wrap; gap: 6px; align-items: center;
  padding: 7px 34px; background: var(--rail); border-bottom: 1px solid var(--line-soft);
}
.rich-toolbar-button {
  height: 26px; padding: 0 9px; border: 1px solid transparent; border-radius: 6px;
  background: transparent; color: var(--ink-2); font: 400 13.5px var(--sans); cursor: pointer;
}
.rich-toolbar-button.glyph { width: 28px; padding: 0; font: 400 15px var(--serif); }
.rich-toolbar-button.glyph.b { font-weight: 700; }
.rich-toolbar-button.glyph.i { font-style: italic; }
.rich-toolbar-button.glyph.u { text-decoration: underline; }
.rich-toolbar-button:hover, .rich-toolbar-button:focus-visible { background: #e9e5dc; outline: none; }
.rich-toolbar-separator { width: 1px; height: 20px; margin: 0 3px; background: var(--line); }
.rich-toolbar-spacer { flex: 1; }
.rich-editor-surface { position: relative; flex: 1; min-height: 0; overflow: auto; padding: 28px 34px 60px; }
.rich-content {
  outline: none; background: var(--raised);
  border: 1px solid var(--line-soft); border-radius: 9px;
  box-sizing: border-box; width: 100%; min-height: 100%;
  padding: 34px 38px 30px;
  font: 400 16px/1.72 var(--serif); color: var(--ink-2);
}
.rich-content > * { max-width: 82ch; }
.rich-placeholder { position: absolute; top: 62px; left: 72px; color: var(--ink-5); pointer-events: none; }
.rich-paragraph { margin: 9px 0 22px; }
.rich-heading { color: var(--ink); font-family: var(--serif); }
.rich-heading-h1 { font-size: 26px; font-weight: 600; line-height: 1.25; letter-spacing: -0.01em; margin: 0 0 14px; }
.rich-heading-h2 { font-size: 18px; font-weight: 600; margin: 22px 0 0; }
.rich-heading-h3 { font-size: 17px; font-weight: 600; margin: 20px 0 0; }
.rich-bold { font-weight: 600; }
.rich-italic { font-style: italic; }
.rich-quote {
  margin: 0 0 22px; padding: 2px 0 2px 16px;
  border-left: 2px solid var(--line-soft);
  font: italic 400 15.5px/1.7 var(--serif); color: var(--ink-3);
}
.rich-list-unordered, .rich-list-ordered { margin: 9px 0 22px; padding-left: 1.6em; }
.rich-list-item { margin: 4px 0; }
.rich-list-item-nested { list-style-type: none; }
.markdown-source {
  width: 100%; min-height: 60vh; background: var(--raised);
  border: 1px solid var(--line-soft); border-radius: 9px;
  padding: 26px 30px; font: 400 13.5px/1.7 var(--mono); color: var(--ink-2);
  outline: none; resize: vertical;
}
.review-list { max-width: 760px; margin: 24px auto 0; }
.review-list h3 { margin: 0 0 9px; font: 600 14px var(--sans); color: var(--ink-3); }
.review-card {
  display: flex; align-items: center; justify-content: space-between; gap: 18px;
  margin-top: 8px; padding: 12px 14px; background: var(--raised);
  border: 1px solid var(--line-soft); border-radius: 8px;
}
.review-change-text { min-width: 0; white-space: pre-wrap; overflow-wrap: anywhere; font: 400 14px/1.5 var(--mono); }
.review-change-text del, .review-change-text ins { display: block; width: fit-content; }
.review-footer-status { display: flex; align-items: center; gap: 16px; font: 400 14px var(--sans); color: var(--ink-3); }
.review-footer-status .mono { font-size: 13px; color: var(--ink-4); }
.track-toggle { display: inline-flex; align-items: center; gap: 6px; color: var(--ink-2); font-weight: 500; white-space: nowrap; }
.track-toggle input { accent-color: var(--attention); }

/* ── Research reading (6a) ────────────────────────────────────────────── */

.research-shell { display: flex; flex-direction: column; height: calc(100vh - 51px); }
.research-head {
  flex: none; display: flex; justify-content: space-between; align-items: center; gap: 24px;
  padding: 13px 34px; background: var(--raised); border-bottom: 1px solid var(--line-soft);
}
.research-panes { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr); }
.memo-scroll { overflow-y: auto; padding: 34px 0 60px; background: var(--rail); }
.memo-sheet {
  width: 640px; max-width: calc(100% - 48px); margin: 0 auto;
  background: var(--raised); border: 1px solid var(--line-soft);
  border-radius: 9px; padding: 40px 46px 46px;
}
.memo-sheet h1 { font: 600 25px/1.25 var(--serif); color: var(--ink); letter-spacing: -0.01em; margin: 0; }
.memo-byline { margin: 10px 0 24px; font: 400 14px var(--sans); color: var(--ink-4); }
.memo-body p { margin: 0 0 18px; font: 400 16.5px/1.75 var(--serif); color: var(--ink-2); text-wrap: pretty; }
.citation {
  display: inline-block; transform: translateY(-2px); margin: 0 2px;
  font: 600 11px var(--sans); border-radius: 4px; padding: 1px 5px;
  border: 0; cursor: pointer; vertical-align: baseline;
}
.mark-you { background: var(--attention-tint); border-bottom: 2px solid var(--attention); padding: 1px 0; }

.rail-tabs {
  flex: none; display: flex; gap: 3px; padding: 9px 20px 0;
  background: var(--rail); border-bottom: 1px solid var(--line-soft);
}
.rail-tabs button {
  border: 1px solid var(--line-soft); border-bottom: 0; border-radius: 8px 8px 0 0;
  padding: 9px 16px; cursor: pointer; background: transparent;
  font: 400 14px var(--sans); color: var(--ink-3);
}
.rail-tabs button.active { background: var(--raised); color: var(--ink); font-weight: 600; }
.rail-pane { border-left: 1px solid var(--line-soft); background: var(--raised); display: flex; flex-direction: column; min-height: 0; }
.rail-scroll { flex: 1; min-height: 0; overflow-y: auto; padding: 24px 26px 30px; }
.source-quote {
  margin-top: 18px; padding: 16px 18px; background: var(--rail);
  border-left: 3px solid var(--agent); border-radius: 0 8px 8px 0;
  font: 400 16px/1.7 var(--serif); color: var(--ink);
}
.note-card { border: 1px solid var(--line-soft); border-radius: 9px; overflow: hidden; }
.note-quote { padding: 12px 15px; background: #fffdf4; border-left: 3px solid var(--attention); }
.note-quote > div:first-child { font: italic 400 15px/1.6 var(--serif); color: var(--ink-3); }
.note-answer { padding: 13px 15px; background: var(--raised); border-top: 1px solid var(--line-faint); }
.note-answer .reading { font-size: 15.5px; line-height: 1.65; }
.note-empty { border: 1px dashed var(--control); border-radius: 9px; padding: 13px 15px; font: 400 15px var(--sans); color: var(--ink-5); }

/* ── Settings (4a) / Agents (4b) ──────────────────────────────────────── */

.admin-shell { display: flex; height: calc(100vh - 51px); }
.admin-rail {
  flex: none; width: 238px; border-right: 1px solid var(--line-soft);
  padding: 24px 14px; background: var(--rail);
  display: flex; flex-direction: column;
}
.admin-rail-wide { width: 280px; }
.admin-rail-title { font: 600 15px var(--serif); color: var(--ink); padding: 0 10px 12px; }
.admin-rail-link {
  text-align: left; border: 0; cursor: pointer; background: transparent;
  border-radius: 7px; padding: 9px 10px;
  font: 400 14.5px var(--sans); color: var(--ink-3);
}
.admin-rail-link:hover { background: #e9e5dc; }
.admin-rail-link.active { background: var(--line-soft); color: var(--ink); font-weight: 600; }
.admin-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.admin-scroll { flex: 1; overflow-y: auto; padding: 30px 40px 40px; }
.admin-body { max-width: 780px; }
.admin-foot {
  flex: none; border-top: 1px solid var(--line-soft); background: var(--raised);
  padding: 14px 40px; display: flex; justify-content: space-between; align-items: center; gap: 20px;
}
.setting-heading {
  font: 600 15px var(--serif); color: var(--ink);
  margin: 26px 0 4px; padding-bottom: 6px; border-bottom: 1px solid var(--line);
}
.setting-row {
  display: flex; gap: 24px; align-items: flex-start;
  padding: 14px 0; border-bottom: 1px solid var(--line-faint);
}
.setting-row > div:first-child { flex: 1; }
.setting-label { font: 500 15px var(--sans); color: var(--ink); }
.setting-help { font: 400 14px/1.5 var(--sans); color: var(--ink-3); margin-top: 2px; }
.setting-control { flex: none; width: 270px; }

.agent-rail-item {
  text-align: left; border: 0; cursor: pointer; background: transparent;
  border-radius: 8px; padding: 11px 10px; width: 100%;
}
.agent-rail-item:hover { background: #e9e5dc; }
.agent-rail-item.active { background: var(--line-soft); }
.agent-rail-name { display: block; font: 600 15px var(--serif); color: var(--ink); }
.agent-rail-role { display: block; font: 400 13.5px/1.45 var(--sans); color: var(--ink-3); margin-top: 2px; }
.field-block { margin-top: 26px; }
.field-block > p { margin: 4px 0 10px; font: 400 14px var(--sans); color: var(--ink-3); }
.skill-rail-list { margin-top: 20px; padding-top: 14px; border-top: 1px solid var(--line-soft); display: flex; flex-direction: column; gap: 2px; }
.skill-command { display: block; margin-top: 6px; font-size: 11.5px; color: var(--ink-5); }
.skill-intro { max-width: 58ch; margin: 8px 0 22px; font: 400 16px/1.6 var(--sans); color: var(--ink-3); }
.skill-question-panel:focus { outline: none; }
.skill-question-panel h1 { margin-top: 7px; max-width: 26ch; }
.skill-choices { margin: 22px 0 12px; max-width: 600px; }
.skill-question-actions { margin-top: 16px; }
.skill-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 24px; }
.skill-warning { margin: 14px 0; border: 1px solid var(--attention-edge); border-radius: 8px; background: var(--attention-tint); padding: 10px 12px; color: var(--attention-deepest); }
.skill-suggestion { margin-top: 10px; }
.skill-suggestion blockquote { margin: 10px 0; padding-left: 12px; border-left: 2px solid var(--line); color: var(--ink-3); font: 400 14px/1.5 var(--sans); }

/* ── Decision register (1f) ───────────────────────────────────────────── */

.recommendation-band {
  border: 1px dashed var(--agent-edge); background: var(--agent-wash);
  border-radius: 9px; padding: 12px 16px; margin-bottom: 20px;
}
.recommendation-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.recommendation-card {
  background: var(--raised); border: 1px dashed var(--agent-edge); border-radius: 7px;
  padding: 12px 14px; display: flex; justify-content: space-between; align-items: center; gap: 14px;
}
.recommendation-text { font: 400 15px/1.5 var(--sans); color: var(--ink-2); text-wrap: pretty; }
.recommendation-source { margin-top: 5px; font: 400 13px/1.45 var(--sans); color: var(--ink-4); }
.register { background: var(--raised); border: 1px solid var(--line); border-radius: 9px; overflow: hidden; }
.register-grid {
  display: grid;
  grid-template-columns: var(--register-columns, 112px minmax(0, 2fr) minmax(0, 1.35fr) 122px minmax(0, 1.25fr) minmax(160px, 1fr));
  align-items: center;
}
.register-head { padding: 9px 16px; border-bottom: 1px solid var(--line-soft); background: var(--rail); }
.register-row { padding: 11px 16px; border-bottom: 1px solid var(--line-hair); }
.register-row:last-child { border-bottom: 0; }
.register-row:hover { background: var(--hover); }
.register-date { font: 400 13px/1.5 var(--mono); color: #666158; }
.register-title { font: 600 15px/1.5 var(--serif); color: var(--ink); }
.register-matter-cell {
  align-self: stretch; display: flex; flex-direction: column; justify-content: center;
  margin: -11px 0 -11px -16px; padding: 11px 16px;
}
.register-cell { font: 400 15px/1.5 var(--sans); color: var(--ink-2); padding-right: 18px; }
.register-basis { font: 400 15px/1.5 var(--sans); color: var(--ink-3); padding-right: 14px; }
.register-review { display: flex; justify-content: flex-end; }
.register-packets { grid-column: 2 / -1; font: 400 14px var(--sans); }

/* ── Automations (2d) ─────────────────────────────────────────────────── */

.automation-card { background: var(--raised); border: 1px solid var(--line-soft); border-radius: 9px; padding: 18px 20px; }
.automation-card.failing { border-color: var(--failure-edge); }
.automation-effect { margin: 8px 0 0; font: 400 16px/1.6 var(--serif); color: var(--ink-2); max-width: 62ch; text-wrap: pretty; }
.automation-plain { font: 400 14px/1.55 var(--sans); color: var(--ink-3); max-width: 62ch; }

/* ── Modal ────────────────────────────────────────────────────────────── */

.modal-scrim {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  background: rgba(27, 26, 23, 0.34); z-index: 30; padding: 24px;
}
.modal {
  width: 580px; max-width: 100%; max-height: 100%; overflow-y: auto;
  background: var(--raised); border: 1px solid var(--line);
  border-radius: 11px; box-shadow: var(--shadow-modal);
}
.modal-head { padding: 22px 26px 18px; border-bottom: 1px solid var(--line-hair); }
.modal-head h3 { font: 600 21px/1.3 var(--serif); color: var(--ink); margin: 0; }
.modal-head p { margin: 8px 0 0; font: 400 14.5px/1.55 var(--sans); color: var(--ink-3); }
.modal-body { padding: 20px 26px 8px; display: flex; flex-direction: column; gap: 18px; }
.modal-foot {
  display: flex; justify-content: space-between; align-items: center; gap: 20px;
  padding: 18px 26px 20px; margin-top: 14px;
  border-top: 1px solid var(--line-hair); background: var(--hover);
}
.modal-foot > span { flex: 1; min-width: 0; }
.modal-foot .btn-row { flex: none; flex-wrap: nowrap; }
.field-label { display: block; font: 600 13.5px var(--sans); color: var(--ink-4); margin-bottom: 7px; }
label.field-block, .skill-form-grid > label { display: block; }
.basis-tag { font: 400 13.5px var(--sans); color: var(--ink-2); background: var(--line-hair); border-radius: 6px; padding: 5px 11px; }
.basis-tag.agent {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--agent); background: var(--agent-wash);
  border: 1px dashed var(--agent-edge); padding: 4px 11px;
}

/* ── States ───────────────────────────────────────────────────────────── */

.loading { padding: 40px; font: 400 15px var(--sans); color: var(--ink-3); }
.error {
  padding: 14px 18px; border-radius: 9px; margin: 16px 0;
  background: var(--failure-tint); border: 1px solid var(--failure-edge);
  color: #8f2c17; font: 400 15px/1.55 var(--sans);
}
.empty-state {
  padding: 40px; text-align: center;
  font: 400 15px var(--sans); color: var(--ink-5);
  border: 1px dashed var(--control); border-radius: 9px;
}
.stub-note {
  display: inline-flex; align-items: center; gap: 7px;
  font: 400 13px var(--sans); color: var(--ink-5);
}

/* Shared awareness layouts. Surface components provide the content. */
.filter-bar {
  display: flex; align-items: end; gap: 10px; flex-wrap: wrap;
  padding: 12px; border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--raised);
}
.filter-bar > label { display: grid; gap: 5px; min-width: 150px; font: 500 12.5px var(--sans); color: var(--ink-4); }
.filter-bar-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-left: auto; }
/*
 * Work-and-rail: the thing being read or worked leads and takes the width;
 * the rail carries actions and context. Used by Briefing and the reader.
 */
.work-rail-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, var(--rail-width, 340px));
  gap: 24px; min-width: 0; align-items: start;
}
/* A rail that carries a conversation needs room to be read in. */
.work-rail-layout.rail-roomy { --rail-width: 440px; }
.work-main, .work-rail { min-width: 0; }
.work-rail {
  position: sticky; top: 72px; max-height: calc(100vh - 92px); overflow-y: auto;
  /* The explicit track stops a wide child from blowing the rail past its column. */
  display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; align-content: start;
}
.reading-column { width: 100%; max-width: var(--content-reading); margin-inline: auto; }
.stack-list { display: grid; gap: 10px; min-width: 0; }
.responsive-card { min-width: 0; overflow-wrap: anywhere; }
.responsive-card > :first-child { min-width: 0; }

/* Semantic state helpers always include a visible state word in the markup. */
.state-label {
  display: inline-flex; align-items: center; gap: 7px; width: fit-content;
  border: 1px solid transparent; border-radius: 999px; padding: 4px 9px;
  font: 600 12.5px var(--sans);
}
.state-label::before { content: ""; width: 7px; height: 7px; flex: none; border-radius: 50%; background: currentColor; }
.state-attention { color: var(--attention-deepest); background: var(--attention-tint); border-color: var(--attention-edge); }
.state-healthy { color: var(--healthy); background: var(--healthy-tint); }
.state-failure { color: var(--failure); background: var(--failure-tint); border-color: var(--failure-edge); }
.state-agent { color: var(--agent); background: var(--agent-tint); border: 1px dashed var(--agent-edge); }
.wash-attention { background: var(--attention-wash); }
.wash-healthy { background: var(--healthy-wash); }
.wash-failure { background: var(--failure-wash); }
.wash-agent { background: var(--agent-wash); }
.warning-callout {
  padding: 14px 16px; border: 1px solid var(--attention-edge); border-radius: var(--radius);
  background: var(--attention-wash); color: var(--ink-2); font: 400 14.5px/1.55 var(--sans);
}
.warning-callout > :first-child { margin-top: 0; }
.warning-callout > :last-child { margin-bottom: 0; }
.warning-callout + .warning-callout { margin-top: 8px; }

/* Review packets contain compact forms inside generated-analysis cards. */
.agent-note > .card label {
  display: grid; gap: 6px; margin-top: 12px;
  font: 500 13px var(--sans); color: var(--ink-4);
}
.agent-note > .card :where(input, textarea, select) {
  width: 100%; min-width: 0; border: 1px solid var(--control); border-radius: 7px;
  padding: 9px 11px; background: var(--raised); font: 400 14.5px var(--sans); color: var(--ink);
}
.agent-note > .card textarea { min-height: 84px; resize: vertical; line-height: 1.5; }

@media (max-width: 1280px) {
  .board { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .register-grid { --register-columns: 100px minmax(0, 1.8fr) minmax(0, 1.2fr) 104px minmax(0, 1.1fr) minmax(140px, 1fr); }
}
@media (max-width: 1024px) {
  :root { --space-page-inline: 20px; --space-page-block: 24px; }
  .topbar { padding: 0 20px; gap: 16px; }
  .topbar-search { display: none; }
  /* The nav scrolls rather than pushing the page wider. */
  .nav { min-width: 0; overflow-x: auto; scrollbar-width: none; }
  .nav::-webkit-scrollbar { display: none; }
  .nav-link { white-space: nowrap; }
  .page { padding: 24px 20px 34px; }
  .matter-panes, .research-panes { grid-template-columns: 1fr !important; }
  .pane-resizer { display: none; }
  .matter-shell, .research-shell, .admin-shell { height: auto; }
  .brief-scroll { min-height: 0; max-height: none; overflow: visible; }
  .middle-section.active { min-height: min(640px, calc(100vh - 140px)); }
  .middle-section-panel { overflow: hidden; }
  .middle-section-panel.brief-scroll { overflow-y: auto; }
  .brief-pane, .rail-pane { border-right: 0; border-left: 0; border-bottom: 1px solid var(--line-soft); }
  .matter-tree-pane { max-height: 360px; border-right: 0; border-bottom: 1px solid var(--line-soft); }
  .pane-rail { height: 44px; flex-direction: row; justify-content: center; border-right: 0; border-bottom: 1px solid var(--line-soft); padding: 0 14px; }
  .pane-rail > span:last-child { writing-mode: horizontal-tb; }
  .recommendation-grid { grid-template-columns: 1fr; }
  .admin-shell { display: block; }
  .admin-rail, .admin-rail-wide { width: auto; border-right: 0; border-bottom: 1px solid var(--line-soft); }
  .work-rail-layout { --rail-width: 300px; gap: 16px; }
  .work-rail-layout.rail-roomy { --rail-width: 340px; }
  .admin-scroll { padding: 24px 20px 34px; }
}
@media (prefers-reduced-motion: reduce) {
  .matter-panes { transition: none; }
}
@media (max-width: 820px) {
  :root { --space-page-inline: 16px; --space-page-block: 20px; }
  .board { grid-template-columns: 1fr; }
  .topbar { height: 54px; gap: 12px; padding: 0 16px; }
  .topbar-spacer, .avatar { display: none; }
  .nav { gap: 14px; overflow-x: auto; scrollbar-width: none; }
  .nav-group { gap: 14px; }
  .nav-primary { padding-right: 14px; }
  .nav::-webkit-scrollbar { display: none; }
  .nav-link { min-height: 32px; display: inline-flex; align-items: center; white-space: nowrap; }
  .page { padding: 20px 16px 32px; }
  .page-header { flex-direction: column; align-items: flex-start; gap: 14px; }
  .headline { font-size: 26px; }
  .filter-bar { align-items: stretch; }
  .filter-bar > label, .filter-bar-actions { width: 100%; min-width: 0; margin-left: 0; }
  .filter-bar-actions > * { flex: 1 1 auto; }
  .work-rail-layout { display: block; }
  .work-rail { position: static; max-height: none; margin-top: 18px; overflow: visible; }
  .responsive-card > :first-child { flex-wrap: wrap; }
  .state-label { white-space: normal; }
  .warning-callout { padding: 12px 14px; }

  .automation-card { padding: 16px; }
  .automation-card > div:first-child,
  .automation-card > div:last-child { flex-wrap: wrap; align-items: flex-start !important; }
  .automation-card > div:last-child > div { flex-wrap: wrap; }
  .automation-plain { overflow-wrap: anywhere; }

  .today-chat { padding: 16px; }
  .today-chat-head, .today-chat-day-row { flex-wrap: wrap; }
  .today-chat-day-row select { width: 100%; max-width: 100%; }
  .today-chat-day-row > span { width: 100%; }
  .today-chat-thread { max-height: none; }
  .chat-card, .bubble-agent, .bubble-you { overflow-wrap: anywhere; }
  .bubble-agent pre, .bubble-agent table { display: block; max-width: 100%; overflow-x: auto; }
  .question-choice { width: 100%; }

  /* Rows become stacked cards rather than squeezed columns. */
  .matter-row { flex-direction: column; align-items: stretch; gap: 8px; padding: 14px 16px; }
  .matter-row > * { flex: none !important; width: auto !important; }
  .matter-title-cell { margin: -14px -16px 0; padding: 14px 16px; }
  .matter-row-due { text-align: left; }
  .stage-head { flex-wrap: wrap; gap: 6px 12px; }
  .stage-head-sub { display: none; }
  .stage-head-count { width: auto; }

  .brief-row { flex-wrap: wrap; padding: 18px 18px 18px 15px; }
  .brief-row > div:last-child { padding-top: 0 !important; width: 100%; }
  .brief-index { display: none; }

  .stat-chips { gap: 8px; }
  .stat-chip { flex: 1 1 calc(50% - 8px); }

  .register-grid { grid-template-columns: 1fr; gap: 4px; }
  .register-head { display: none; }
  .register-matter-cell { margin: -11px -16px 4px; padding: 11px 16px; }
  .register-cell, .register-basis { padding-right: 0; }
  /* One column means one column: no cell may claim a second track. */
  .register-review { justify-content: flex-start; margin-top: 6px; }
  .register-packets { grid-column: 1 / -1; }

  .setting-row { flex-direction: column; gap: 10px; }
  .setting-row .signal { align-self: flex-start; white-space: normal; }
  .setting-control { width: 100%; }
  .admin-foot, .footer-band { flex-direction: column; align-items: flex-start; gap: 12px; }
  .footer-band { padding: 20px 16px 24px; }
  .intake-bar { flex-wrap: wrap; }
  .doc-bar, .research-head, .matter-head { padding-left: 16px; padding-right: 16px; flex-wrap: wrap; }
  .matter-facts { flex-wrap: wrap; gap: 10px 22px; }
  .matter-brief { padding: 22px 18px 24px; }
  .matter-call-do { align-items: stretch; flex-direction: column; gap: 12px; }
  .matter-call-button { align-self: flex-start; }
  .composer { padding-left: 18px; padding-right: 18px; }
  .question-free-text { align-items: stretch; flex-direction: column; }
  .rich-toolbar, .doc-scroll, .rich-editor-surface { padding-left: 16px; padding-right: 16px; }
  .rich-content, .memo-sheet { padding: 24px 20px; }
  .modal-foot { flex-direction: column; align-items: stretch; }
  .modal-foot .btn-row { justify-content: flex-end; }
}

.rich-underline { text-decoration: underline; text-underline-offset: 2px; }

/* Document review uses author colour only with a visible author name. */
.review-workspace { display: grid; grid-template-columns: minmax(0, 1fr) 280px; min-height: 0; flex: 1; overflow: hidden; }
.review-workspace.comments-hidden { grid-template-columns: minmax(0, 1fr); }
.review-workspace.changes-open { grid-template-columns: minmax(0, 1fr) 260px; }
.review-main { min-width: 0; overflow-y: auto; position: relative; }
.review-toolbar, .reviewer-filters { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; padding: 7px 12px; border-bottom: 1px solid var(--line-soft); background: var(--rail); font: 500 12.5px var(--sans); color: var(--ink-3); }
.review-toolbar { justify-content: space-between; }
.review-toolbar label, .reviewer-filters label { display: inline-flex; align-items: center; gap: 6px; }
.review-toolbar-actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }
.review-toolbar-secondary { display: contents; }
.review-workspace.changes-open .review-toolbar-secondary,
.review-workspace.changes-open .rich-toolbar { display: none; }
.review-workspace.changes-open .rich-editor-surface { padding-left: 16px; padding-right: 16px; }
.review-workspace.changes-open .rich-content { padding: 24px 20px; }
.redline-toggle.active { border-color: var(--ink); background: var(--ink); color: var(--paper); }
.reviewer-menu { position: relative; }
.reviewer-menu > summary { list-style: none; padding: 5px 8px; border: 1px solid var(--control); border-radius: 6px; background: var(--raised); color: var(--ink-3); cursor: pointer; }
.reviewer-menu > summary::-webkit-details-marker { display: none; }
.reviewer-menu > summary::after { content: " +"; color: var(--ink-5); }
.reviewer-menu[open] > summary::after { content: " −"; }
.reviewer-menu > .reviewer-filters { position: absolute; z-index: 8; top: calc(100% + 6px); right: 0; width: min(520px, calc(100vw - 48px)); padding: 12px; border: 1px solid var(--line); border-radius: 8px; box-shadow: var(--shadow-modal); background: var(--raised); }
.review-modes { display: flex; padding: 2px; border-radius: 7px; background: var(--sunken); }
.review-modes button { border: 0; border-radius: 5px; padding: 5px 9px; background: transparent; color: var(--ink-3); cursor: pointer; }
.review-modes button.active { background: var(--raised); color: var(--ink); box-shadow: 0 1px 2px rgba(27,26,23,.12); }
.author-swatch { width: 9px; height: 9px; border-radius: 50%; border: 1px solid rgba(27,26,23,.2); }
.reviewer-filters select { width: 26px; border: 0; background: transparent; color: transparent; }
.revision-text { color: var(--revision-color); border-radius: 2px; }
.revision-insert { text-decoration: underline 2px; text-underline-offset: 3px; }
.revision-delete { text-decoration: line-through 2px; background: color-mix(in srgb, var(--revision-color) 9%, transparent); }
.revision-comment { color: inherit; background: var(--attention-tint); border-bottom: 2px solid var(--attention); cursor: pointer; }
.revision-insert[data-author="__hidden__"] { display: none; }
.revision-comment::after, .revision-insert[data-author="__hidden__"]::after { content: none; }
.comment-anchor-button { display: block; width: 100%; padding: 0; border: 0; background: transparent; color: inherit; text-align: left; cursor: pointer; }
.author-popover { display: flex; gap: 6px; padding: 6px; border: 1px solid var(--line); border-radius: 7px; background: var(--raised); }
.comment-rail { min-width: 0; overflow-y: auto; border-left: 1px solid var(--line-soft); background: var(--rail); padding: 12px; font: 400 13px/1.45 var(--sans); }
.comment-rail-head, .comment-thread-actions { display: flex; align-items: center; justify-content: space-between; gap: 6px; flex-wrap: wrap; }
.comment-rail-head .pane-collapse { margin-left: auto; }
.comment-thread { margin-top: 10px; padding: 11px; border: 1px solid var(--line); border-radius: 8px; background: var(--raised); }
.comment-thread.resolved { opacity: .76; }
.comment-thread blockquote { margin: 0 0 9px; padding-left: 8px; border-left: 2px solid var(--attention); color: var(--ink-3); }
.comment-entry { padding: 7px 0; border-top: 1px solid var(--line-hair); }
.comment-entry p, .comment-note, .resolved-comments p { margin: 3px 0 7px; }
.comment-reply { display: flex; gap: 5px; margin: 8px 0; }
.comment-popover { position: sticky; bottom: 12px; z-index: 5; width: min(430px, calc(100% - 24px)); margin: 12px auto; padding: 14px; border: 1px solid var(--attention-edge); border-radius: 9px; background: var(--raised); box-shadow: var(--shadow-modal); }
.comment-popover textarea { width: 100%; min-height: 80px; margin: 9px 0; }
.review-list {
  min-width: 0; max-width: none; margin: 0; overflow-y: auto; padding: 12px;
  border-left: 1px solid var(--line-soft); background: var(--rail); font: 400 13px/1.45 var(--sans);
}
.review-list-head {
  position: sticky; z-index: 1; top: 0;
  display: flex; align-items: flex-start; justify-content: space-between; gap: 16px;
  margin: 0 0 8px; padding: 0 0 12px; border-bottom: 1px solid var(--line-soft); background: var(--rail);
}
.review-list-head h3 { margin: 0; }
.review-list-head p { margin: 3px 0 0; font: 400 12.5px var(--sans); color: var(--ink-4); }
.review-card { display: flex; flex-direction: column; align-items: stretch; gap: 10px; padding: 10px 12px; border-top: 1px solid var(--line-hair); }
.review-card > .btn-row { align-self: flex-end; }
.review-change-text { display: flex; gap: 8px; margin-top: 4px; white-space: pre-wrap; }
.review-change-text ins { text-decoration: underline; }
@media (max-width: 1024px) {
  .review-workspace, .review-workspace.changes-open { grid-template-columns: 1fr; overflow: visible; }
  .comment-rail, .review-list { border-left: 0; border-top: 1px solid var(--line-soft); }
}

/* ── Matter tree ─────────────────────────────────────────────────────── */

.tree { padding: 10px; }
.tree-folder-row { display: flex; align-items: center; gap: 4px; }
.tree-folder-row > .tree-row { flex: 1; min-width: 0; }
.tree-add {
  flex: none; display: grid; place-items: center; width: 25px; height: 25px; margin-right: 4px;
  border: 1px solid transparent; border-radius: 6px; background: transparent;
  color: var(--ink-4); cursor: pointer; font: 500 18px/1 var(--sans);
}
.tree-add:hover, .tree-add:focus-visible { border-color: var(--control); background: var(--raised); color: var(--ink); outline: none; }
.tree-empty { padding: 4px 8px 8px 24px; font: 400 12px var(--sans); color: var(--ink-5); }
.tree-group-help { margin: 3px 8px 7px; font: 400 12.5px/1.45 var(--sans); color: var(--ink-4); }
.tree-row {
  display: flex; align-items: center; gap: 8px;
  width: 100%; border: 0; background: transparent; text-align: left;
  min-height: 30px; padding: 5px 8px; border-radius: 7px; cursor: pointer;
  font: 400 13.5px var(--sans); color: var(--ink-3);
}
.tree-row:hover { background: var(--rail); color: var(--ink); }
.tree-row.active { background: var(--line-soft); color: var(--ink); font-weight: 500; }
.tree-row .tree-folder { font: 500 10px var(--mono); letter-spacing: 0.09em; text-transform: uppercase; color: var(--ink-6); }
.tree-indent { margin-left: 12px; padding-left: 6px; border-left: 1px solid var(--line-faint); }
.tree-dot { width: 7px; height: 7px; border-radius: 3px; flex: none; border: 1px solid var(--ink-6); }
.tree-dot.source { border-radius: 50%; background: var(--line-soft); }
.tree-dot.agent { border: 1px dashed var(--agent-dash); background: var(--agent-tint); }
.tree-dot.conversation { border-color: var(--agent); background: var(--agent); border-radius: 50%; }
.field-source { margin-left: 5px; font-weight: 400; color: var(--agent); }
.field-help { margin-top: 6px; font: 400 13px/1.45 var(--sans); color: var(--ink-5); }

.register-row { font-size: 15px; line-height: 1.5; }
.register-title, .register-cell, .register-basis { overflow-wrap: anywhere; }
.drop-zone {
  margin: 10px; padding: 14px; border: 1px dashed var(--control); border-radius: 8px;
  font: 400 13.5px var(--sans); color: var(--ink-5); text-align: center;
}
.drop-zone.active { border-color: var(--attention); color: var(--attention-deep); background: #fffdf4; }

.company-setting-row { align-items: flex-start; }
.company-setting-row .setting-control { width: min(390px, 52%); min-height: 76px; resize: vertical; }
.company-setting-row .setting-control[rows="1"] { min-height: 42px; resize: none; }
.company-interview {
  overflow: hidden; border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised);
}
.company-interview-thread { display: grid; gap: 16px; padding: 20px; }
.company-interview-exchange { display: contents; }
.company-interview .assistant-message { max-width: 94%; }
.company-interview .bubble-you { justify-self: end; }
.company-answer-skipped { color: var(--ink-4); font-style: italic; }
.company-question:not(.current) { opacity: .82; }
.company-question-reason { margin: 8px 0 0; font: 400 13px/1.5 var(--sans); color: var(--ink-4); }
.company-interview-composer { padding: 14px 20px 16px; border-top: 1px solid var(--line-faint); background: var(--raised); }
.company-interview-composer .field-label { margin-bottom: 8px; }
.company-interview-composer-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 8px; font: 400 12.5px var(--sans); color: var(--ink-5); }
.company-interview-status { padding: 18px 20px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--raised); color: var(--ink-4); }
.company-interview-status p { margin-bottom: 12px; }
.company-interview-error { padding: 12px 14px; border: 1px solid var(--failure-edge); border-radius: 8px; background: var(--failure-wash); }
.company-interview-error p { margin: 0 0 10px; }
.company-review-card { border: 1px dashed var(--agent-dash); border-radius: 10px; background: var(--agent-wash); padding: 17px 18px; }
.company-review-card.saved { border-style: solid; border-color: var(--healthy); background: var(--healthy-wash); }
.company-review-card > .agent-label { color: var(--agent); }
.company-review-card.saved > .agent-label { color: var(--healthy); }
.company-review-card h2 { margin-top: 8px; }
.company-review-state { margin: 5px 0 0; font: 400 14px/1.5 var(--sans); color: var(--ink-3); }
.company-review-fields { display: grid; gap: 0; margin: 16px 0 0; }
.company-review-fields > div { display: grid; grid-template-columns: minmax(130px, .34fr) minmax(0, 1fr); gap: 18px; padding: 10px 0; border-top: 1px solid var(--line-faint); }
.company-review-fields dt { font: 600 13px/1.5 var(--sans); color: var(--ink-4); }
.company-review-fields dd { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; font: 400 15px/1.55 var(--serif); color: var(--ink-2); }
.company-review-fields dt label { cursor: pointer; }
.company-review-fields .text-input { width: 100%; font: 400 14.5px/1.5 var(--sans); }
.company-review-fields textarea.text-input { min-height: 82px; resize: vertical; }
.company-interview-warning { margin: 14px 0 0; padding: 10px 12px; border: 1px solid var(--attention-edge); border-radius: 7px; background: var(--attention-wash); font: 400 13.5px/1.5 var(--sans); color: var(--ink-2); }
.company-interview-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.company-manual-editor { margin-top: 22px; border-top: 1px solid var(--line-soft); padding-top: 15px; }
.company-manual-editor > summary { width: fit-content; cursor: pointer; font: 600 14px var(--sans); color: var(--ink-3); }
.company-manual-fields { margin-top: 12px; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--raised); }
@media (max-width: 820px) {
  .company-setting-row .setting-control { width: 100%; }
  .company-interview-thread, .company-interview-composer { padding-left: 14px; padding-right: 14px; }
  .company-interview .assistant-message { max-width: 100%; }
  .company-review-fields > div { grid-template-columns: 1fr; gap: 3px; }
  .company-interview-composer .composer-field { align-items: stretch; flex-direction: column; }
  .company-interview-composer .composer-field .btn { align-self: flex-end; }
}

.memo-body.reading p { margin: 0 0 18px; font-size: 16.5px; line-height: 1.75; }
.memo-body.reading h2 { margin: 26px 0 10px; font-size: 19px; }
.memo-body.reading h3 { margin: 22px 0 8px; font-size: 17px; }
.memo-body.reading ul { margin: 0 0 18px; padding-left: 1.4em; font-size: 16.5px; line-height: 1.75; }

/* ══════════════════════════════════════════════════════════════════════
   Briefing, reader, automations, skills
   Every screen answers: what is this page for, what is here, what do I do.
   ══════════════════════════════════════════════════════════════════════ */

/* ── Page orientation ─────────────────────────────────────────────────── */

.page-lede {
  margin: 10px 0 0; max-width: 78ch;
  font: 400 15.5px/1.65 var(--sans); color: var(--ink-3); text-wrap: pretty;
}
.page-lede strong { font-weight: 600; color: var(--ink-2); }
.page-header-main { flex: 1 1 auto; min-width: 0; }

/* A rail card: one job, named, with a sentence of help under the name. */
.rail-card { min-width: 0; background: var(--raised); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px 17px; overflow-wrap: anywhere; }
.rail-card-title { margin: 0; font: 600 16px var(--serif); color: var(--ink); }
.rail-card-help { margin: 5px 0 0; font: 400 13.5px/1.55 var(--sans); color: var(--ink-4); text-wrap: pretty; }
.rail-card-body { margin-top: 13px; display: grid; gap: 2px; }
.rail-card-empty { margin: 12px 0 0; font: 400 13.5px var(--sans); color: var(--ink-5); }
.rail-entry { padding: 11px 0; border-top: 1px solid var(--line-hair); }
.rail-entry:first-child { border-top: 0; padding-top: 2px; }
.rail-entry-name {
  display: block; width: 100%; text-align: left; border: 0; padding: 0; background: transparent;
  font: 600 15px var(--serif); color: var(--ink); cursor: pointer;
}
.rail-entry-name:hover { color: var(--agent); }
.rail-entry-meta { margin-top: 3px; font: 400 12.5px var(--sans); color: var(--ink-5); }
.rail-entry-actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 9px; }
.rail-entry-actions .btn.tiny { padding: 4px 9px; font-size: 12.5px; }

/* ── Briefing query bar ───────────────────────────────────────────────── */

.query-bar {
  margin-top: 16px; padding: 14px 16px 13px;
  background: var(--raised); border: 1px solid var(--line); border-radius: var(--radius);
}
.query-bar-row { display: flex; align-items: flex-end; gap: 12px; flex-wrap: wrap; }
.query-bar-search { flex: 1 1 300px; min-width: 220px; }
.query-bar-controls { display: flex; align-items: flex-end; gap: 10px; flex-wrap: wrap; }
.query-bar label { display: grid; gap: 5px; min-width: 132px; }
.query-bar label > span { font: 600 12px var(--sans); color: var(--ink-4); letter-spacing: .01em; }
.query-bar .select-input, .query-bar .text-input { font-size: 14px; padding: 8px 11px; }
.query-bar-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.query-more { margin-top: 12px; border-top: 1px solid var(--line-hair); padding-top: 11px; }
.query-more > summary {
  width: fit-content; cursor: pointer; list-style: none;
  font: 600 13px var(--sans); color: var(--ink-3);
}
.query-more > summary::-webkit-details-marker { display: none; }
.query-more > summary::before { content: "+ "; color: var(--ink-5); }
.query-more[open] > summary::before { content: "− "; }
.query-more-help { margin: 10px 0 0; font: 400 13px var(--sans); color: var(--ink-5); }
.query-more-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 12px; margin-top: 12px;
}
.query-summary {
  display: flex; align-items: baseline; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  margin: 0 2px 10px;
}
.query-summary-count { font: 600 14px var(--sans); color: var(--ink-2); }
.query-summary-note { font: 400 13px var(--sans); color: var(--ink-5); }

/* ── Briefing item list ───────────────────────────────────────────────── */

.briefing-group + .briefing-group { margin-top: 22px; }
.briefing-group-head {
  display: flex; align-items: baseline; gap: 10px; margin: 0 2px 8px;
}
.briefing-group-head h2 { margin: 0; font: 600 15px var(--sans); color: var(--ink-3); }
.briefing-group-head span { font: 400 13px var(--sans); color: var(--ink-5); }

.briefing-item {
  display: block; position: relative; padding: 16px 20px 15px 21px;
  border-bottom: 1px solid var(--line-hair); border-left: 3px solid transparent;
  background: var(--raised); text-decoration: none;
}
.briefing-item:last-child { border-bottom: 0; }
.briefing-item:hover { background: var(--hover); }
.briefing-item.unread { border-left-color: var(--ink); }
.briefing-item.review { border-left-color: var(--attention); background: var(--attention-wash); }
.briefing-item.review:hover { background: #fefaea; }
.briefing-item-meta {
  font: 500 10px var(--mono); letter-spacing: .09em; text-transform: uppercase; color: var(--ink-5);
}
.briefing-item-title {
  margin-top: 7px; font: 600 18px/1.35 var(--serif); color: var(--ink); text-wrap: pretty;
}
.briefing-item.unread .briefing-item-title { color: var(--ink); }
.briefing-item.read .briefing-item-title { font-weight: 400; color: var(--ink-2); }
.briefing-item-summary {
  margin: 5px 0 0; max-width: 74ch;
  font: 400 14.5px/1.6 var(--sans); color: var(--ink-3); text-wrap: pretty;
}
.briefing-item-foot { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 11px; }
.briefing-item-foot .state-label { font-size: 11.5px; padding: 3px 8px; }
.briefing-item-status { font: 400 12.5px/1.4 var(--sans); color: var(--ink-5); }
.state-quiet { color: var(--ink-4); background: var(--sunken); border-color: var(--line); }
.state-plain { color: var(--ink-2); background: var(--raised); border-color: var(--control); }

/* ── Briefing reader ──────────────────────────────────────────────────── */

.reader-back { margin-bottom: 14px; }
.reader-back a { font: 500 13.5px var(--sans); color: var(--ink-4); }
.reader-back a:hover { color: var(--ink); }
.reader-head { padding-bottom: 20px; border-bottom: 1px solid var(--line-soft); }
.reader-title {
  margin: 8px 0 0; max-width: 40ch;
  font: 600 34px/1.16 var(--serif); color: var(--ink); letter-spacing: -0.018em; text-wrap: pretty;
}
.reader-summary {
  margin: 12px 0 0; max-width: 76ch;
  font: 400 17px/1.6 var(--serif); color: var(--ink-2); text-wrap: pretty;
}
.reader-states { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.reader-facts {
  display: flex; flex-wrap: wrap; gap: 10px 34px; margin-top: 18px;
}
.reader-fact { display: grid; gap: 3px; }
.reader-fact dt {
  font: 500 10px var(--mono); letter-spacing: .09em; text-transform: uppercase; color: var(--ink-5);
}
.reader-fact dd { margin: 0; font: 500 15px var(--sans); color: var(--ink); }
.reader-fact dd.plain { font-weight: 400; color: var(--ink-2); }

.reader-section { margin-top: 30px; }
.reader-section > h2 { margin: 0 0 10px; font: 600 20px var(--serif); color: var(--ink); }
.reader-section-help { margin: -4px 0 12px; font: 400 13.5px/1.5 var(--sans); color: var(--ink-5); }
.reader-prose { margin: 0; max-width: 68ch; font: 400 16px/1.68 var(--serif); color: var(--ink-2); text-wrap: pretty; }
.reader-grid {
  display: grid; grid-template-columns: minmax(130px, auto) minmax(0, 1fr);
  gap: 10px 20px; margin: 0; font: 400 14.5px/1.55 var(--sans);
}
.reader-grid dt { font-weight: 500; color: var(--ink-4); }
.reader-grid dd { margin: 0; color: var(--ink-2); overflow-wrap: anywhere; }
.reader-details { margin-top: 30px; border-top: 1px solid var(--line-faint); padding-top: 16px; }
.reader-details > summary {
  width: fit-content; cursor: pointer; list-style: none; font: 600 13.5px var(--sans); color: var(--ink-4);
}
.reader-details > summary::-webkit-details-marker { display: none; }
.reader-details > summary::before { content: "+ "; color: var(--ink-5); }
.reader-details[open] > summary::before { content: "− "; }
.reader-details .reader-grid { margin-top: 14px; font-family: var(--sans); }
.reader-details .reader-grid dd { font: 400 13px var(--mono); color: var(--ink-3); }

.source-entry { padding: 14px 0; border-top: 1px solid var(--line-hair); }
.source-entry:first-child { border-top: 0; padding-top: 0; }
.source-entry-title { font: 600 16px/1.4 var(--serif); color: var(--ink); }
.source-entry a:hover .source-entry-title { color: var(--agent); text-decoration: underline; }
.source-entry-meta { display: flex; flex-wrap: wrap; gap: 7px; align-items: center; margin-top: 7px; }
.source-entry-note { margin-top: 6px; font: 400 13px/1.5 var(--sans); color: var(--ink-5); overflow-wrap: anywhere; }
.source-entry-excerpt { margin: 9px 0 0; font: 400 15px/1.65 var(--serif); color: var(--ink-2); }

.action-list { display: grid; gap: 7px; margin-top: 13px; }
.action-list .btn { width: 100%; text-align: center; white-space: normal; }
.ask-panel { border-style: dashed; }
.ask-thread { display: flex; flex-direction: column; gap: 14px; margin: 14px 0; max-height: 52vh; overflow-y: auto; }
.ask-thread > * { min-width: 0; }
.ask-thread .bubble-you { max-width: 100%; }
.ask-thread .assistant-message { padding: 12px 13px; }
.ask-thread .bubble-agent { overflow-wrap: anywhere; }
.ask-thread .bubble-agent p, .ask-thread .bubble-agent ul, .ask-thread .bubble-agent ol { font-size: 15px; line-height: 1.62; }
.ask-thread .bubble-agent pre, .ask-thread .bubble-agent table { display: block; max-width: 100%; overflow-x: auto; }

/* ── Automations ──────────────────────────────────────────────────────── */

.automation-section + .automation-section { margin-top: 26px; }
.automation-section-head { margin: 0 2px 12px; }
.automation-section-head h2 { margin: 0; font: 600 16px var(--serif); color: var(--ink); }
.automation-section-head p { margin: 3px 0 0; font: 400 13.5px var(--sans); color: var(--ink-5); }
.automation-list { display: flex; flex-direction: column; gap: 12px; }

.automation-card { background: var(--raised); border: 1px solid var(--line-soft); border-radius: 9px; border-left: 3px solid var(--line); padding: 17px 20px; }
.automation-card.failing { border-color: var(--failure-edge); border-left-color: var(--failure); background: var(--failure-wash); }
.automation-card.running { border-left-color: var(--healthy); }
.automation-card.paused { border-left-color: var(--line); }
.automation-card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 18px; }
.automation-kicker {
  font: 500 10px var(--mono); letter-spacing: .09em; text-transform: uppercase; color: var(--ink-5);
}
.automation-title { margin: 5px 0 0; font: 600 18px/1.3 var(--serif); color: var(--ink); }
.automation-effect { margin: 10px 0 0; font: 400 16px/1.6 var(--serif); color: var(--ink-2); max-width: 66ch; text-wrap: pretty; }
.automation-facts {
  display: flex; flex-wrap: wrap; gap: 8px 30px; margin: 15px 0 0;
  padding-top: 13px; border-top: 1px solid var(--line-hair);
}
.automation-fact { display: grid; gap: 2px; min-width: 0; }
.automation-fact dt {
  font: 500 10px var(--mono); letter-spacing: .09em; text-transform: uppercase; color: var(--ink-5);
}
.automation-fact dd { margin: 0; font: 400 14px var(--sans); color: var(--ink-2); overflow-wrap: anywhere; }
.automation-actions { display: flex; justify-content: flex-end; gap: 8px; flex-wrap: wrap; margin-top: 14px; }
.automation-failure {
  margin-top: 13px; padding: 11px 13px; border-radius: 8px;
  border: 1px solid var(--failure-edge); background: var(--failure-tint);
  font: 400 14px/1.55 var(--sans); color: #8f2c17;
}
.automation-compose { margin-top: 20px; }
.automation-compose-help { margin: 0 0 10px 2px; font: 400 13.5px var(--sans); color: var(--ink-5); }
.form-help { display: block; margin: 5px 0 0; font: 400 13px/1.5 var(--sans); color: var(--ink-5); }
.form-heading { margin: 0; font: 600 20px var(--serif); color: var(--ink); }
.form-heading-help { margin: 5px 0 0; font: 400 14px/1.55 var(--sans); color: var(--ink-3); max-width: 60ch; }

/* ── Skills ───────────────────────────────────────────────────────────── */

.admin-body.wide { max-width: 1000px; }
.skill-start-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 14px; margin-top: 24px;
}
.skill-start-card {
  display: flex; flex-direction: column; gap: 9px;
  background: var(--raised); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px;
}
.skill-start-card.lead { border-color: var(--control); box-shadow: var(--shadow-card); }
.skill-start-card h2 { margin: 0; font: 600 19px var(--serif); color: var(--ink); }
.skill-start-card p { margin: 0; font: 400 14.5px/1.6 var(--sans); color: var(--ink-3); text-wrap: pretty; }
.skill-start-card .btn-row { margin-top: auto; padding-top: 6px; }
.skill-example {
  margin-top: 22px; padding: 14px 16px; border-radius: 9px;
  border: 1px solid var(--line-faint); background: var(--rail);
  font: 400 14.5px/1.6 var(--sans); color: var(--ink-3);
}
.skill-example .mono { color: var(--ink); font-size: 13.5px; }

.skill-section { margin-top: 34px; }
.skill-section-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; }
.skill-section-head h2 { margin: 0; font: 600 20px var(--serif); color: var(--ink); }
.skill-section-head span { font: 400 13.5px var(--sans); color: var(--ink-5); }
.skill-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(272px, 1fr)); gap: 12px; margin-top: 14px; }
.skill-card {
  display: flex; flex-direction: column; gap: 7px; text-align: left; cursor: pointer;
  background: var(--raised); border: 1px solid var(--line); border-radius: 9px; padding: 16px 17px;
}
.skill-card:hover { border-color: var(--ink-6); }
.skill-card.active { border-color: var(--ink); }
.skill-card-name { font: 600 17px/1.3 var(--serif); color: var(--ink); }
.skill-card-purpose { font: 400 14px/1.55 var(--sans); color: var(--ink-3); }
.skill-card-command {
  margin-top: auto; padding-top: 8px;
  font: 500 12.5px var(--mono); color: var(--agent);
}

.skill-progress { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.skill-progress-track { flex: 1; max-width: 260px; height: 4px; border-radius: 2px; background: var(--sunken); overflow: hidden; }
.skill-progress-fill { display: block; height: 100%; background: var(--ink); border-radius: 2px; transition: width 160ms ease; }
.skill-progress span { font: 500 12px var(--sans); color: var(--ink-4); white-space: nowrap; }
.skill-step-help { margin: 10px 0 0; max-width: 56ch; font: 400 14.5px/1.6 var(--sans); color: var(--ink-3); }
.skill-draft-head { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; }
.skill-field-help { display: block; margin: 5px 0 0; font: 400 13px/1.5 var(--sans); color: var(--ink-5); }
.skill-rail-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding: 0 10px 12px; }
.skill-rail-head span { font: 400 12.5px var(--sans); color: var(--ink-5); }

@media (max-width: 900px) {
  .reader-title { font-size: 27px; max-width: none; }
  .reader-facts { gap: 10px 24px; }
}
@media (max-width: 820px) {
  .query-bar-actions { margin-left: 0; width: 100%; }
  .query-bar-actions > .btn { flex: 1 1 auto; }
  .query-bar label, .query-bar-search { min-width: 0; width: 100%; }
  .query-bar-controls { width: 100%; }
  .query-bar-controls > label { flex: 1 1 45%; }
  .briefing-item { padding: 14px 16px 14px 15px; }
  .reader-grid { grid-template-columns: 1fr; gap: 3px 0; }
  .reader-grid dd { margin-bottom: 9px; }
  .automation-card { padding: 15px 16px; }
  .automation-card-head { flex-direction: column; gap: 10px; }
  .automation-actions { justify-content: flex-start; }
  .automation-actions .btn { flex: 1 1 auto; }
  .skill-grid { grid-template-columns: 1fr; }
}

/*
 * Below this width a rail beside the work leaves neither enough room.
 * The work keeps the page; the rail follows it.
 */
@media (max-width: 900px) {
  .work-rail-layout { display: block; }
  .work-rail { position: static; max-height: none; margin-top: 18px; overflow: visible; }
}

.watch-card-foot {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px 20px;
  flex-wrap: wrap; margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--line-hair);
  font: 400 13.5px var(--sans); color: var(--ink-4);
}

/* ── Today — attention hierarchy (3a revision) ────────────────────────── */

/* The status pill replaces the bare dot. Colour plus the word, in a small
   tinted control — the design language reserves stronger tints for badges. */
.brief-status {
  display: inline-flex; align-items: center;
  border-radius: 5px; padding: 2px 8px;
  font: 600 12.5px/1.35 var(--sans);
}

/* Titles and reasons are capped so a long row cannot out-weigh a higher-ranked
   short one. The full text stays in the DOM. */
.brief-why {
  display: -webkit-box; -webkit-box-orient: vertical; overflow: hidden;
}
.brief-title { overflow-wrap: anywhere; }
.brief-why { -webkit-line-clamp: 2; }

/* Overdue reads hotter than waiting without a heavier wash: a wider spine. */
.brief-row.is-late { border-left-width: 4px; padding-left: 20px; }

.brief-more {
  display: block; width: 100%; text-align: left;
  background: var(--raised); border: 0; border-top: 1px solid var(--line-hair);
  padding: 13px 24px 13px 21px; cursor: pointer;
  font: 500 14px var(--sans); color: var(--ink-3);
}
.brief-more:hover { background: var(--hover); color: var(--ink); }

/* Two-column Today: the ranked list keeps its width, the practice sits beside
   it instead of in a footer nobody reads. */
.today-grid {
  margin-top: 26px;
  display: grid; grid-template-columns: minmax(0, 1000px) 296px;
  gap: 28px; align-items: start;
}
.today-col { min-width: 0; display: flex; flex-direction: column; gap: 22px; }
.today-rail { min-width: 0; position: sticky; top: 75px; }

.rail-head {
  display: flex; align-items: baseline; gap: 10px;
  padding: 14px 18px 12px; border-bottom: 1px solid var(--line-hair);
}
.rail-head-title { flex: 1; font: 600 16px var(--serif); color: var(--ink); }
.rail-head-count { font: 400 13.5px var(--sans); color: var(--ink-5); }

.rail-stage {
  display: flex; align-items: baseline; gap: 12px;
  padding: 9px 18px; border-bottom: 1px solid var(--line-hair);
}
.rail-stage:last-of-type { border-bottom: 0; }
.rail-stage-label { flex: 1; font: 400 14px/1.4 var(--sans); color: var(--ink-2); }
.rail-stage-count {
  flex: none; font: 600 16px var(--serif); color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.rail-stage.is-empty .rail-stage-label { color: var(--ink-6); }
.rail-stage.is-empty .rail-stage-count { color: var(--ink-6); font-weight: 400; }

.rail-note {
  display: flex; align-items: baseline; gap: 9px;
  padding: 11px 18px; border-top: 1px solid var(--line-soft);
  font: 400 13.5px/1.5 var(--sans); color: var(--ink-3);
}
.rail-foot { padding: 12px 18px 14px; border-top: 1px solid var(--line-soft); }

/* "Your other matters" gets a container so it stops reading as a footnote. */
.quiet-head {
  display: flex; align-items: baseline; gap: 12px;
  padding: 12px 20px; border-bottom: 1px solid var(--line-hair);
}
.quiet-head-title { font: 600 16px var(--serif); color: var(--ink); }
.quiet-head-count { flex: 1; font: 400 13.5px var(--sans); color: var(--ink-5); }
.quiet-head-link { font: 500 13.5px var(--sans); color: var(--agent); }
.quiet-head-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.quiet-inset { padding: 2px 20px 6px; }
.quiet-inset .quiet-row:last-child { border-bottom: 0; }

@media (max-width: 1180px) {
  .today-grid { grid-template-columns: minmax(0, 1fr); gap: 22px; }
  .today-rail { position: static; }
}

/* One conversation and editor across the single-lawyer workspace views. */
.workspace-entry-actions { display: flex; flex-wrap: wrap; gap: 8px; padding: 12px 24px; }
.workspace-template-surface, .workspace-exploration, .workspace-reuse, .workspace-existing-controls { padding: 16px; border-top: 1px solid var(--line); min-width: 0; }
.workspace-exploration > summary, .workspace-reuse > summary, .workspace-existing-controls > summary { font-family: var(--sans); font-size: 15px; cursor: pointer; padding: 8px 0; }
.workspace-export-mode { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; padding: 8px 12px; font-family: var(--sans); font-size: 15px; }
.workspace-template-surface pre { white-space: pre-wrap; overflow-wrap: anywhere; }
@media (max-width: 600px) { .workspace-entry-actions { padding: 8px; } .workspace-exploration, .workspace-reuse, .workspace-existing-controls { padding: 10px; } }

/* Workspace columns must fit the available reading width. */
.matter-shell, .matter-shell > *, .draft-workspace__layout > * { min-width: 0; max-width: 100%; }
.matter-shell .draft-workspace { width: 100%; box-sizing: border-box; padding: 16px; }
.draft-workspace :where(article, section, p, h1, h2, h3, a, li, summary) { overflow-wrap: anywhere; }
@media (max-width: 760px) {
  .matter-shell .draft-workspace__conversation { position: static; max-height: none; overflow: visible; }
  .matter-shell .draft-workspace__layout { display: block; }
  .matter-shell .draft-workspace :where(input, textarea, select) { min-width: 0; max-width: 100%; }
  .matter-shell .draft-workspace__understand > section { grid-template-columns: minmax(0, 1fr); }
  .matter-shell .draft-workspace .btn-row { flex-wrap: wrap; }
  .matter-head > *, .matter-facts { min-width: 0; max-width: 100%; flex-wrap: wrap; }
}

.matter-shell .draft-workspace__conversation { overflow: hidden; }
.matter-shell .draft-workspace .conversation-dock { display: flex; flex-direction: column; height: min(780px, calc(100dvh - 100px)); min-height: 420px; overflow: hidden; }
.matter-shell .draft-workspace .conversation-dock__target, .matter-shell .draft-workspace .conversation-dock__receipts { flex: none; }
.matter-shell .draft-workspace .conversation-dock__receipts[open] { max-height: 150px; overflow-y: auto; }
.matter-shell .draft-workspace .conversation-dock__panel { flex: 1; min-height: 0; display: flex; overflow: hidden; max-height: none; }
.matter-shell .draft-workspace .conversation-dock .chat-panel { min-height: 0; width: 100%; }
.matter-shell .draft-workspace .conversation-dock .thread { flex: 1 1 0; overflow-y: auto; }
.matter-shell .draft-workspace .conversation-dock .composer { flex: none; }
.document-editor-reference { min-width: 0; }
.document-editor-reference.has-reference {
  display: grid;
  grid-template-columns: minmax(420px, 1.15fr) minmax(340px, .85fr);
  gap: 16px;
  align-items: start;
}
.document-editor-reference__draft { min-width: 0; }
.document-editor-reference.has-reference > aside { position: sticky; top: 76px; min-width: 0; }
@media (max-width: 900px) {
  .document-editor-reference.has-reference { grid-template-columns: minmax(0, 1fr); }
  .document-editor-reference.has-reference > aside { position: static; top: auto; }
}
@media (max-width: 760px) {
  .matter-shell .draft-workspace .conversation-dock { height: min(720px, 90dvh); min-height: 420px; }
  .matter-shell .draft-workspace .conversation-dock__panel { max-height: none; overflow: hidden; }
}

/* Long question and artifact labels must wrap inside their controls. */
.matter-shell .draft-workspace :where(button, .btn, .text-button, .suggestion) {
  min-width: 0; max-width: 100%; white-space: normal; overflow-wrap: anywhere; box-sizing: border-box;
}
.matter-shell .draft-workspace :where(.btn-row, .chat-card-actions, .composer-suggestions) { min-width: 0; max-width: 100%; flex-wrap: wrap; }
.matter-shell .draft-workspace :where(.thread, .chat-card, .assistant-message, .bubble-agent, .artifact-row) { min-width: 0; max-width: 100%; box-sizing: border-box; }
@media (max-width: 760px) {
  .matter-shell .draft-workspace :where(article, .artifact-list, .draft-tools) { min-width: 0; max-width: 100%; box-sizing: border-box; }
  .matter-shell .draft-workspace .draft-workspace__understand { width: 100%; min-width: 0; }
}

.continuity-surface { margin: 12px 24px; padding: 18px; border: 1px solid var(--line); border-radius: 8px; background: var(--raised); overflow-wrap: anywhere; }
.continuity-surface select, .continuity-surface textarea { max-width: 100%; }
@media (max-width: 600px) { .continuity-surface { margin: 8px; padding: 12px; } }
